--
-- Name: account_deletion_blockers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_blockers(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  out jsonb := '[]'::jsonb;
  r record;
  n bigint;
begin
  if to_regclass('public.founder_accounts') is not null then
    execute format('select count(*) from public.founder_accounts where user_id = %L', _user) into n;
    if n > 0 then
      out := out || jsonb_build_array(jsonb_build_object(
        'code', 'founder_account', 'message', 'Founder accounts cannot be deleted.'));
    end if;
  end if;

  for r in select * from public.account_deletion_orgs(_user) o where o.is_owner and o.other_members > 0 loop
    out := out || jsonb_build_array(jsonb_build_object(
      'code', 'org_has_other_members', 'org_id', r.org_id, 'members', r.other_members,
      'message', 'Your workspace still has other members. Remove them or transfer ownership first.'));
  end loop;

  if to_regclass('public.polar_subscriptions') is not null then
    execute format(
      'select count(*) from public.polar_subscriptions where user_id = %L and status in (''active'',''past_due'',''grace'')',
      _user) into n;
    if n > 0 then
      out := out || jsonb_build_array(jsonb_build_object(
        'code', 'active_subscription',
        'message', 'You still have an active paid plan. It has to be cancelled and ended before the account can be deleted — contact support if you need help.'));
    end if;
  end if;

  return out;
end $$;


--
-- Name: account_deletion_cancel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_cancel(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  n bigint;
begin
  update public.account_deletions
     set state = 'cancelled', cancelled_at = now()
   where user_id = _user and state = 'scheduled';
  get diagnostics n = row_count;
  return jsonb_build_object('ok', true, 'cancelled', n > 0);
end $$;


--
-- Name: account_deletion_orgs(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_orgs(_user uuid) RETURNS TABLE(org_id uuid, is_owner boolean, other_members integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  ids uuid[] := '{}';
  owners uuid[] := '{}';
  one uuid;
  q text;
  st text;
  n int;
begin
  if to_regclass('public.org_members') is not null then
    for r in execute format(
      'select m.org_id as org_ref, (m.role::text = ''owner'') as own from public.org_members m where m.user_id = %L', _user)
    loop
      ids := ids || r.org_ref;
      if r.own then owners := owners || r.org_ref; end if;
    end loop;
  end if;
  if to_regclass('public.organisations') is not null and public._ad_has_col('organisations', 'owner_id') then
    for r in execute format('select o.id as org_ref from public.organisations o where o.owner_id = %L', _user) loop
      ids := ids || r.org_ref;
      owners := owners || r.org_ref;
    end loop;
  end if;
  if to_regclass('public.account_org_members') is not null then
    for r in execute format(
      'select m.org_id as org_ref, (m.role = ''owner'') as own from public.account_org_members m where m.user_id = %L', _user)
    loop
      ids := ids || r.org_ref;
      if r.own then owners := owners || r.org_ref; end if;
    end loop;
  end if;
  if to_regclass('public.account_organisations') is not null then
    for r in execute format('select o.id as org_ref from public.account_organisations o where o.created_by = %L', _user) loop
      ids := ids || r.org_ref;
      owners := owners || r.org_ref;
    end loop;
  end if;

  for one in select distinct x from unnest(ids) as x loop
    q := '';
    if to_regclass('public.org_members') is not null then
      st := case when public._ad_has_col('org_members', 'status')
                 then ' and coalesce(m.status::text, ''active'') not in (''removed'',''revoked'',''inactive'',''disabled'',''declined'')'
                 else '' end;
      q := format('select m.user_id from public.org_members m where m.org_id = %L and m.user_id <> %L', one, _user) || st;
    end if;
    if to_regclass('public.account_org_members') is not null then
      q := case when q = '' then '' else q || ' union ' end
        || format('select m.user_id from public.account_org_members m where m.org_id = %L and m.user_id <> %L', one, _user);
    end if;
    if q = '' then
      n := 0;
    else
      execute 'select count(*) from (' || q || ') s' into n;
    end if;
    org_id := one;
    is_owner := one = any(owners);
    other_members := n;
    return next;
  end loop;
end $$;


--
-- Name: account_deletion_request(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_request(_user uuid, _confirm_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_email text;
  d public.account_deletions;
  b jsonb;
begin
  select u.email into v_email from auth.users u where u.id = _user;
  if v_email is null then
    return jsonb_build_object('ok', false, 'error', 'user_not_found');
  end if;
  if lower(btrim(coalesce(_confirm_email, ''))) <> lower(btrim(v_email)) then
    return jsonb_build_object('ok', false, 'error', 'email_mismatch');
  end if;

  select * into d from public.account_deletions where user_id = _user and state = 'scheduled';
  if d.id is not null then
    return jsonb_build_object('ok', true, 'already_scheduled', true, 'scheduled_for', d.scheduled_for);
  end if;

  b := public.account_deletion_blockers(_user);
  if jsonb_array_length(b) > 0 then
    return jsonb_build_object('ok', false, 'error', 'blocked', 'blockers', b);
  end if;

  insert into public.account_deletions (user_id, email, email_hash, requested_by, scheduled_for)
  values (_user, v_email, encode(sha256(convert_to(lower(v_email), 'UTF8')), 'hex'), 'self', now() + interval '7 days')
  returning * into d;
  return jsonb_build_object('ok', true, 'already_scheduled', false, 'scheduled_for', d.scheduled_for);
exception when unique_violation then
  select * into d from public.account_deletions where user_id = _user and state = 'scheduled';
  return jsonb_build_object('ok', true, 'already_scheduled', true, 'scheduled_for', d.scheduled_for);
end $$;


--
-- Name: account_deletion_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletion_state(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  d public.account_deletions;
  b jsonb;
begin
  b := public.account_deletion_blockers(_user);
  select * into d from public.account_deletions where user_id = _user and state = 'scheduled';
  if d.id is null then
    return jsonb_build_object('scheduled', false, 'blockers', b);
  end if;
  return jsonb_build_object(
    'scheduled', true,
    'requested_at', d.requested_at,
    'scheduled_for', d.scheduled_for,
    'days_left', greatest(0, ceil(extract(epoch from (d.scheduled_for - now())) / 86400)::int),
    'blockers', b);
end $$;


--
-- Name: account_deletions_email_hmac_migrate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_deletions_email_hmac_migrate(_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare n bigint;
begin
  if coalesce(_key, '') = '' then raise exception 'key_required'; end if;
  update public.account_deletions d set email_hmac = public.email_hmac_v1(d.email, _key)
   where d.email_hmac is null and d.email is not null;
  get diagnostics n = row_count;
  return jsonb_build_object('ok', true, 'migrated', n);
end $$;


--
-- Name: account_export_page(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_export_page(_user uuid, _kind text, _after text DEFAULT NULL::text, _limit integer DEFAULT 500) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  sc     jsonb := public.account_export_scope(_user);
  mbx    text[];
  own    uuid[];
  orgs   uuid[];
  lim    int := least(greatest(coalesce(_limit, 500), 1), 2000);
  sqlt   text;
  rows_j jsonb;
  nxt    text;
  after_ text := coalesce(_after, '');
  tid_col text;
begin
  if (sc->>'ok') is distinct from 'true' then return jsonb_build_object('rows', '[]'::jsonb, 'next', null); end if;
  select coalesce(array_agg(x), '{}') into mbx from jsonb_array_elements_text(sc->'mailboxes') x;
  select coalesce(array_agg(x::uuid), '{}') into own from jsonb_array_elements_text(sc->'owner_orgs') x;
  select coalesce(array_agg(x::uuid), '{}') into orgs from jsonb_array_elements_text(sc->'orgs') x;

  if _kind = 'threads' then
    if to_regclass('public.mail_threads') is null then return jsonb_build_object('rows','[]'::jsonb,'next',null); end if;
    sqlt := 'select t.id::text as k, to_jsonb(t) as j from public.mail_threads t where (lower(t.mailbox_address) = any($1)';
    if public._ae_has_col('mail_threads', 'account_id') and to_regclass('public.mail_accounts') is not null then
      sqlt := sqlt || ' or t.account_id in (select a.id from public.mail_accounts a where lower(a.address) = any($1))';
    end if;
    sqlt := sqlt || ') and t.id::text > $2 order by t.id::text limit $3';
    execute format('select coalesce(jsonb_agg(j order by k), ''[]''::jsonb), max(k) from (%s) q', sqlt)
      into rows_j, nxt using mbx, after_, lim;

  elsif _kind = 'messages' then
    if to_regclass('public.mail_messages') is null or to_regclass('public.mail_threads') is null then
      return jsonb_build_object('rows','[]'::jsonb,'next',null); end if;
    sqlt := 'select m.id::text as k, to_jsonb(m) as j from public.mail_messages m where m.thread_id in (select t.id from public.mail_threads t where (lower(t.mailbox_address) = any($1)';
    if public._ae_has_col('mail_threads', 'account_id') and to_regclass('public.mail_accounts') is not null then
      sqlt := sqlt || ' or t.account_id in (select a.id from public.mail_accounts a where lower(a.address) = any($1))';
    end if;
    sqlt := sqlt || ')) and m.id::text > $2 order by m.id::text limit $3';
    execute format('select coalesce(jsonb_agg(j order by k), ''[]''::jsonb), max(k) from (%s) q', sqlt)
      into rows_j, nxt using mbx, after_, lim;

  elsif _kind = 'attachments' then
    if to_regclass('public.mail_attachments') is null or to_regclass('public.mail_messages') is null or to_regclass('public.mail_threads') is null then
      return jsonb_build_object('rows','[]'::jsonb,'next',null); end if;
    sqlt := 'select a.id::text as k, to_jsonb(a) as j from public.mail_attachments a where a.message_id in (select m.id from public.mail_messages m where m.thread_id in (select t.id from public.mail_threads t where (lower(t.mailbox_address) = any($1)';
    if public._ae_has_col('mail_threads', 'account_id') and to_regclass('public.mail_accounts') is not null then
      sqlt := sqlt || ' or t.account_id in (select x.id from public.mail_accounts x where lower(x.address) = any($1))';
    end if;
    sqlt := sqlt || '))) and a.id::text > $2 order by a.id::text limit $3';
    execute format('select coalesce(jsonb_agg(j order by k), ''[]''::jsonb), max(k) from (%s) q', sqlt)
      into rows_j, nxt using mbx, after_, lim;

  elsif _kind = 'contacts' then
    if to_regclass('public.contacts') is null then return jsonb_build_object('rows','[]'::jsonb,'next',null); end if;
    execute 'select coalesce(jsonb_agg(j order by k), ''[]''::jsonb), max(k) from (select c.id::text as k, to_jsonb(c) as j from public.contacts c where c.org_id = any($1) and c.id::text > $2 order by c.id::text limit $3) q'
      into rows_j, nxt using own, after_, lim;

  elsif _kind = 'events' then
    if to_regclass('public.calendar_events') is null then return jsonb_build_object('rows','[]'::jsonb,'next',null); end if;
    execute 'select coalesce(jsonb_agg(j order by k), ''[]''::jsonb), max(k) from (select e.id::text as k, to_jsonb(e) as j from public.calendar_events e where (e.org_id = any($1) or (e.org_id = any($4) and e.created_by = $5)) and e.id::text > $2 order by e.id::text limit $3) q'
      into rows_j, nxt using own, after_, lim, orgs, _user;

  elsif _kind = 'attendees' then
    if to_regclass('public.calendar_attendees') is null or to_regclass('public.calendar_events') is null then
      return jsonb_build_object('rows','[]'::jsonb,'next',null); end if;
    execute 'select coalesce(jsonb_agg(j order by k), ''[]''::jsonb), max(k) from (select a.id::text as k, to_jsonb(a) as j from public.calendar_attendees a where a.event_id in (select e.id from public.calendar_events e where (e.org_id = any($1) or (e.org_id = any($4) and e.created_by = $5))) and a.id::text > $2 order by a.id::text limit $3) q'
      into rows_j, nxt using own, after_, lim, orgs, _user;

  else
    return jsonb_build_object('rows','[]'::jsonb,'next',null,'error','bad_kind');
  end if;

  -- next sirf tab jab poora page aaya (aur rows hain)
  if jsonb_array_length(rows_j) < lim then nxt := null; end if;
  return jsonb_build_object('rows', rows_j, 'next', nxt);
end $_$;


--
-- Name: account_export_scope(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_export_scope(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  em   text;
  orgs uuid[] := '{}';
  own  uuid[] := '{}';
  mbx  text[] := '{}';
begin
  select lower(u.email) into em from auth.users u where u.id = _user;
  if em is null then return jsonb_build_object('ok', false, 'error', 'user_not_found'); end if;

  if to_regclass('public.org_members') is not null then
    select coalesce(array_agg(distinct m.org_id), '{}') into orgs
      from public.org_members m
     where m.user_id = _user and coalesce(m.status::text, 'active') <> 'revoked';
    select coalesce(array_agg(distinct m.org_id), '{}') into own
      from public.org_members m
     where m.user_id = _user and m.role::text = 'owner' and coalesce(m.status::text, 'active') <> 'revoked';
  end if;

  mbx := array[em];
  if to_regclass('public.mail_accounts') is not null then
    select coalesce(array_agg(distinct lower(a.address)), '{}') || mbx into mbx
      from public.mail_accounts a where lower(a.address) = em;
  end if;
  select coalesce(array_agg(distinct x), '{}') into mbx from unnest(mbx) x;

  return jsonb_build_object('ok', true, 'email', em, 'orgs', to_jsonb(orgs),
                            'owner_orgs', to_jsonb(own), 'mailboxes', to_jsonb(mbx));
end $$;


--
-- Name: account_export_ticket_issue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_export_ticket_issue(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  tok text;
  st  text := null;
  eu  timestamptz := null;
begin
  if not exists (select 1 from auth.users where id = _user) then
    return jsonb_build_object('ok', false, 'error', 'user_not_found');
  end if;
  if to_regclass('public.account_integrity') is not null then
    select i.state, i.export_until into st, eu from public.account_integrity i where i.user_id = _user;
    if st = 'purged' then return jsonb_build_object('ok', false, 'error', 'purged'); end if;
    if st = 'blocked' and eu is not null and eu < now() then
      return jsonb_build_object('ok', false, 'error', 'export_window_closed', 'export_until', eu);
    end if;
  end if;
  delete from public.account_export_tickets where expires_at < now() - interval '1 day';
  tok := encode(gen_random_bytes(24), 'hex');
  insert into public.account_export_tickets (token_hash, user_id, expires_at)
  values (encode(digest(tok, 'sha256'), 'hex'), _user, now() + interval '10 minutes');
  if to_regclass('public.account_integrity_log') is not null and st = 'blocked' then
    begin
      insert into public.account_integrity_log (user_id, event, actor, detail)
      values (_user, 'exported', 'user', jsonb_build_object('at', now(), 'via', 'account-export'));
    exception when others then null;
    end;
  end if;
  return jsonb_build_object('ok', true, 'ticket', tok, 'expires_in', 600);
end $$;


--
-- Name: account_export_ticket_use(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_export_ticket_use(_token text) RETURNS jsonb
