    SET search_path TO 'public', 'extensions'
    AS $$
declare r public.account_export_tickets;
begin
  update public.account_export_tickets
     set used_at = now()
   where token_hash = [REDACTED] ''), 'sha256'), 'hex')
     and used_at is null and expires_at > now()
  returning * into r;
  if r.user_id is null then return jsonb_build_object('ok', false, 'error', 'invalid_or_used'); end if;
  return jsonb_build_object('ok', true, 'user_id', r.user_id);
end $$;


--
-- Name: account_integrity_appeal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_appeal(_user uuid, _statement text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare h text; res jsonb; opened int := 0; last_err text; first_id uuid;
begin
  if _user is null then raise exception 'user_required'; end if;
  if not exists (select 1 from public.account_integrity where user_id = _user and state in ('blocked','warned','purged')) then
    return jsonb_build_object('ok', false, 'error', 'nothing_to_appeal');
  end if;
  for h in select distinct v.device_hash from public.device_vault v
             join public.device_bans b on b.device_hash = v.device_hash and b.appealable
            where v.user_id = _user
  loop
    res := public.device_appeal_open(_user, h, _statement);
    if coalesce((res->>'ok')::boolean, false) then
      opened := opened + 1; first_id := coalesce(first_id, (res->>'appeal_id')::uuid);
    else last_err := res->>'error'; if last_err = 'statement_required' then return res; end if;
    end if;
  end loop;
  if opened = 0 then
    return jsonb_build_object('ok', false, 'error', coalesce(last_err, 'no_appealable_ban'),
      'message', case when last_err = 'appeal_already_open' then 'Your appeal is already with a reviewer.' else 'No appealable device block found on this account.' end);
  end if;
  return jsonb_build_object('ok', true, 'appeal_id', first_id, 'devices', opened);
end $$;


--
-- Name: account_integrity_block(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_block(_actor uuid, _user uuid, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_reason text := btrim(coalesce(_reason,''));
  v_row public.account_integrity;
  v_pol public.account_integrity_policy;
  v_until timestamptz;
  v_bans int := 0;
  v_hash text;
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed');
  end if;
  if length(v_reason) < 12 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Block ke liye kam az kam 12 character ki wajah likhni hogi.');
  end if;
  select * into v_pol from public.account_integrity_policy where id = 1;
  select * into v_row from public.account_integrity where user_id = _user;
  if v_row.user_id is null then
    return jsonb_build_object('ok', false, 'error', 'no_record');
  end if;
  if v_pol.warning_required and v_row.state <> 'warned' then
    return jsonb_build_object('ok', false, 'error', 'warning_required_first',
      'message', 'Ladder ka qadam skip nahi hota: pehle ek likhi hui final warning.');
  end if;

  v_until := now() + make_interval(hours => v_pol.export_window_hours);

  update public.account_integrity
     set state = 'blocked', reason = v_reason, blocked_at = now(), blocked_by = _actor,
         export_until = v_until, purge_after = v_until, updated_at = now()
   where user_id = _user;

  -- ban SIRF device hash par (IP / network kabhi nahi), aur appealable
  for v_hash in select distinct device_hash from public.device_vault where user_id = _user loop
    insert into public.device_bans (device_hash, reason, banned_by, appealable)
    values (v_hash, 'account integrity: ' || v_reason, _actor, true)
    on conflict (device_hash) do update
      set reason = excluded.reason, banned_by = excluded.banned_by, appealable = true;
    v_bans := v_bans + 1;
    insert into public.device_trust_events (user_id, device_hash, event, actor, detail)
    values (_user, v_hash, 'banned', 'human', jsonb_build_object('reason', v_reason));
  end loop;

  update public.device_vault set state = 'banned', last_seen_at = last_seen_at
   where user_id = _user;

  insert into public.account_integrity_log (user_id, event, actor, actor_user, reason, detail)
  values (_user, 'blocked', 'human', _actor, v_reason,
          jsonb_build_object('devices_banned', v_bans, 'ban_scope', v_pol.ban_scope));
  insert into public.account_integrity_log (user_id, event, actor, actor_user, detail)
  values (_user, 'export_window_opened', 'engine', _actor,
          jsonb_build_object('export_until', v_until, 'hours', v_pol.export_window_hours));

  return jsonb_build_object('ok', true, 'state', 'blocked', 'devices_banned', v_bans,
    'export_until', v_until, 'export_hours', v_pol.export_window_hours,
    'appealable', true);
end $$;


--
-- Name: account_integrity_evaluate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_evaluate(_user uuid, _device_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_pol    public.account_integrity_policy;
  v_hash   text := nullif(btrim(coalesce(_device_hash,'')), '');
  v_users  int := 1;
  v_signup int := 0;
  v_row    public.account_integrity;
  v_ev     jsonb := '[]'::jsonb;
  v_state  text;
begin
  if _user is null then return jsonb_build_object('ok', false, 'error', 'user_required'); end if;
  select * into v_pol from public.account_integrity_policy where id = 1;

  if v_hash is null then
    select device_hash into v_hash from public.device_vault
     where user_id = _user order by last_seen_at desc limit 1;
  end if;

  if v_hash is not null then
    select count(distinct user_id) into v_users
      from public.device_vault where device_hash = v_hash;
    select count(*) into v_signup
      from public.device_trust_events
     where device_hash = v_hash and event = 'registered'
       and at > now() - make_interval(hours => v_pol.signup_window_hours);
  end if;

  if v_users >= v_pol.max_accounts_per_device then
    v_ev := v_ev || jsonb_build_array(
      format('is device shape par %s accounts mile (had %s)', v_users, v_pol.max_accounts_per_device));
  end if;
  if v_signup >= v_pol.max_signups_in_window then
    v_ev := v_ev || jsonb_build_array(
      format('%s ghante mein %s naye signup isi device se', v_pol.signup_window_hours, v_signup));
  end if;

  insert into public.account_integrity (user_id, accounts_on_device, signups_in_window)
  values (_user, greatest(v_users,1), v_signup)
  on conflict (user_id) do update
    set accounts_on_device = greatest(excluded.accounts_on_device,1),
        signups_in_window  = excluded.signups_in_window,
        updated_at = now()
  returning * into v_row;

  -- ladder aage badh chuki ho to engine peeche nahi le jaati
  if v_row.state in ('clean','suspicious') then
    v_state := case when jsonb_array_length(v_ev) > 0 then 'suspicious' else 'clean' end;
    update public.account_integrity
       set state = v_state,
           evidence = jsonb_build_object('signals', v_ev, 'device_hash_prefix',
                        case when v_hash is null then null else left(v_hash,12) || '…' end),
           reason = case when v_state = 'suspicious'
                        then 'engine ne dohra account pattern dekha' else null end,
           updated_at = now()
     where user_id = _user
     returning * into v_row;
  end if;

  insert into public.account_integrity_log (user_id, device_hash, event, actor, detail)
  values (_user, v_hash,
    case when v_row.state = 'suspicious' then 'suspicious' else 'evaluated' end,
    'engine',
    jsonb_build_object('accounts_on_device', v_users, 'signups_in_window', v_signup,
                       'signals', v_ev));

  return jsonb_build_object('ok', true, 'state', v_row.state,
    'accounts_on_device', v_users, 'signups_in_window', v_signup,
    'signals', v_ev, 'engine_can_block', false);
end $$;


--
-- Name: account_integrity_export_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_export_ready(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.account_integrity;
begin
  select * into v_row from public.account_integrity where user_id = _user;
  if v_row.user_id is null or v_row.state <> 'blocked' then
    return jsonb_build_object('ok', true, 'blocked', false, 'export_open', true);
  end if;
  if v_row.export_until is not null and v_row.export_until < now() then
    return jsonb_build_object('ok', false, 'blocked', true, 'export_open', false,
      'error', 'export_window_closed', 'export_until', v_row.export_until);
  end if;
  insert into public.account_integrity_log (user_id, event, actor, detail)
  values (_user, 'exported', 'user', jsonb_build_object('at', now()));
  return jsonb_build_object('ok', true, 'blocked', true, 'export_open', true,
    'export_until', v_row.export_until,
    'hours_left', greatest(0, round(extract(epoch from (v_row.export_until - now())) / 3600.0, 1)));
end $$;


--
-- Name: account_integrity_log_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_log_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'account_integrity_log is append-only';
end $$;


--
-- Name: account_integrity_notice_claim(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_notice_claim(_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record; out jsonb := '[]'::jsonb; ids bigint[] := '{}';
begin
  -- 24 ghante bache hain: ek hi baar reminder
  for r in
    select i.user_id, i.reason, i.export_until from public.account_integrity i
     where i.state = 'blocked' and i.purged_at is null and i.export_until is not null
       and i.export_until > now() and i.export_until <= now() + interval '24 hours'
       and not exists (select 1 from public.account_integrity_notices n where n.subject_user = i.user_id and n.kind = 'reminder_24h')
  loop
    perform public._ai_notice_enqueue(r.user_id, 'reminder_24h', r.reason, r.export_until);
  end loop;

  for r in
    select n.id from public.account_integrity_notices n
     where n.sent_at is null and n.attempts < 5 and (n.claimed_at is null or n.claimed_at < now() - interval '10 minutes')
     order by n.id limit least(greatest(coalesce(_limit, 20), 1), 100)
     for update skip locked
  loop
    update public.account_integrity_notices set claimed_at = now(), attempts = attempts + 1 where id = r.id;
    ids := ids || r.id;
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'to', to_jsonb(n.to_addrs), 'subject', n.subject, 'body', n.body) order by n.id), '[]'::jsonb)
    into out from public.account_integrity_notices n
   where n.id = any(ids);   -- sirf is call mein claim hue (dobara chalne par double-send nahi)
  return jsonb_build_object('ok', true, 'notices', out);
end $$;


--
-- Name: account_integrity_notice_done(bigint, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_notice_done(_id bigint, _ok boolean, _err text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if _ok then
    -- bhejne ke baad pate mita do (PII nahi rakhni); matn mein sirf wajah hai
    update public.account_integrity_notices set sent_at = now(), to_addrs = '{}', last_error = null where id = _id;
  else
    update public.account_integrity_notices set last_error = left(coalesce(_err, 'unknown'), 300) where id = _id;
  end if;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: account_integrity_purge_due(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_purge_due(_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r public.account_integrity; v_email text; v_rep jsonb; v_tl jsonb; v_done int := 0; v_stuck int := 0;
begin
  for r in
    select * from public.account_integrity
     where state = 'blocked' and purge_after is not null and purge_after < now() and purged_at is null
     order by purge_after limit 25
  loop
    select lower(u.email) into v_email from auth.users u where u.id = r.user_id;
    if v_email is null then
      update public.account_integrity set state = 'purged', purged_at = now(), updated_at = now() where user_id = r.user_id;
      continue;
    end if;
    if to_regclass('public.chat_messages') is not null then delete from public.chat_messages where sender_user_id = r.user_id; end if;
    if to_regclass('public.chat_work_items') is not null then delete from public.chat_work_items where owner_user_id = r.user_id or created_by = r.user_id; end if;

    select coalesce(jsonb_agg(jsonb_build_object('event', l.event, 'at', l.at, 'actor', l.actor, 'reason', l.reason) order by l.id), '[]'::jsonb)
      into v_tl from public.account_integrity_log l where l.user_id = r.user_id;
    begin
      perform public._ai_notice_enqueue(r.user_id, 'purged', r.reason, r.export_until);   -- pate user mitne se pehle utha liye
      alter table public.account_integrity_log disable trigger account_integrity_log_no_change;
      v_rep := public.account_purge(r.user_id, false, true, false);
      alter table public.account_integrity_log enable trigger account_integrity_log_no_change;
      if not coalesce((v_rep->>'ok')::boolean, false) then
        raise exception 'purge_not_ok' using detail = v_rep::text;   -- notice + trigger wapas (rollback)
      end if;
    exception when others then
      if sqlerrm = 'purge_not_ok' then null;
      else v_rep := jsonb_build_object('ok', false, 'error', 'purge_exception', 'detail', sqlerrm); end if;
      if v_rep is null or coalesce((v_rep->>'ok')::boolean, false) then v_rep := jsonb_build_object('ok', false, 'error', 'purge_not_ok'); end if;
    end;
    if coalesce((v_rep->>'ok')::boolean, false) then
      insert into public.account_integrity_tombstones
        (user_id, email_sha256, state_before, reason, warned_at, blocked_at, export_until, purge_report, timeline)
      values (r.user_id, public.email_hmac_v1(v_email, _key), r.state, r.reason, r.warned_at, r.blocked_at, r.export_until,
              jsonb_build_object('anonymised_rows', v_rep->'anonymised_rows', 'ledgers_unlocked', v_rep->'ledgers_unlocked'), v_tl);
      v_done := v_done + 1;
    else
      update public.account_integrity set purge_after = now() + interval '24 hours', updated_at = now() where user_id = r.user_id;
      insert into public.account_integrity_log (user_id, event, actor, detail)
      values (r.user_id, 'purge_blocked', 'engine',
              jsonb_build_object('error', v_rep->>'error', 'blockers', v_rep->'blockers', 'count', v_rep->'count', 'detail', v_rep->>'detail',
                                 'retry_after', now() + interval '24 hours'));
      v_stuck := v_stuck + 1;
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'purged', v_done, 'blocked', v_stuck);
end $$;


--
-- Name: account_integrity_queue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_queue(_actor uuid, _state text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('allowed', false, 'accounts', '[]'::jsonb);
  end if;
  return jsonb_build_object('allowed', true, 'accounts', coalesce((
    select jsonb_agg(jsonb_build_object(
        'user_id', i.user_id, 'state', i.state, 'reason', i.reason,
        'evidence', i.evidence, 'accounts_on_device', i.accounts_on_device,
        'signups_in_window', i.signups_in_window,
        'warned_at', i.warned_at, 'blocked_at', i.blocked_at,
        'export_until', i.export_until, 'purge_after', i.purge_after,
        'updated_at', i.updated_at) order by i.updated_at desc)
      from public.account_integrity i
     where (_state is null and i.state <> 'clean') or i.state = _state), '[]'::jsonb));
end $$;


--
-- Name: account_integrity_release(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_release(_actor uuid, _user uuid, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_reason text := btrim(coalesce(_reason,'')); v_row public.account_integrity;
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed');
  end if;
  if length(v_reason) < 12 then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;
  select * into v_row from public.account_integrity where user_id = _user;
  if v_row.user_id is null then return jsonb_build_object('ok', false, 'error', 'no_record'); end if;
  if v_row.purged_at is not null then
    return jsonb_build_object('ok', false, 'error', 'already_purged',
      'message', 'Data purge ho chuka — release se wapas nahi aata.');
  end if;

  delete from public.device_bans
   where device_hash in (select device_hash from public.device_vault where user_id = _user);
  update public.device_vault set state = 'pending' where user_id = _user and state = 'banned';

  update public.account_integrity
     set state = 'released', reason = v_reason, released_at = now(),
         blocked_at = null, export_until = null, purge_after = null, warned_at = null,
         updated_at = now()
   where user_id = _user;

  insert into public.account_integrity_log (user_id, event, actor, actor_user, reason)
  values (_user, 'released', 'human', _actor, v_reason);

  return jsonb_build_object('ok', true, 'state', 'released');
end $$;


--
-- Name: account_integrity_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_state(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.account_integrity; v_pol public.account_integrity_policy;
begin
  select * into v_pol from public.account_integrity_policy where id = 1;
  select * into v_row from public.account_integrity where user_id = _user;
  return jsonb_build_object(
    'policy', jsonb_build_object(
      'max_accounts_per_device', v_pol.max_accounts_per_device,
      'signup_window_hours', v_pol.signup_window_hours,
      'max_signups_in_window', v_pol.max_signups_in_window,
      'export_window_hours', v_pol.export_window_hours,
      'ban_scope', v_pol.ban_scope,
      'warning_required', v_pol.warning_required),
    'state', coalesce(v_row.state, 'clean'),
    'reason', v_row.reason,
    'evidence', coalesce(v_row.evidence, '{}'::jsonb),
    'accounts_on_device', coalesce(v_row.accounts_on_device, 1),
    'signups_in_window', coalesce(v_row.signups_in_window, 0),
    'warned_at', v_row.warned_at,
    'blocked_at', v_row.blocked_at,
    'export_until', v_row.export_until,
    'export_hours_left', case when v_row.export_until is null then null
      else greatest(0, round(extract(epoch from (v_row.export_until - now())) / 3600.0, 1)) end,
    'purge_after', v_row.purge_after,
    'purged_at', v_row.purged_at,
    'appeal', coalesce((
      select jsonb_build_object('id', a.id, 'state', a.state, 'created_at', a.created_at,
                                'decision_reason', a.decision_reason)
        from public.device_ban_appeals a
       where a.user_id = _user order by a.created_at desc limit 1), 'null'::jsonb),
    'timeline', coalesce((
      select jsonb_agg(jsonb_build_object('event', l.event, 'actor', l.actor,
               'reason', l.reason, 'detail', l.detail, 'at', l.at) order by l.id desc)
        from public.account_integrity_log l where l.user_id = _user limit 50), '[]'::jsonb),
    'append_only', true);
end $$;


--
-- Name: account_integrity_warn(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_integrity_warn(_actor uuid, _user uuid, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_reason text := btrim(coalesce(_reason,'')); v_row public.account_integrity;
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed');
  end if;
  if length(v_reason) < 12 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Warning ke liye kam az kam 12 character ki wajah likhni hogi.');
  end if;
  select * into v_row from public.account_integrity where user_id = _user;
  if v_row.user_id is null then
    perform public.account_integrity_evaluate(_user, null);
    select * into v_row from public.account_integrity where user_id = _user;
  end if;
  if v_row.state = 'warned' then
    return jsonb_build_object('ok', false, 'error', 'already_warned',
      'message', 'Final warning pehle se mojood hai — dobara warning nahi, agla qadam block hai.');
  end if;
  if v_row.state in ('blocked','purged') then
    return jsonb_build_object('ok', false, 'error', 'already_blocked');
  end if;

  update public.account_integrity
     set state = 'warned', reason = v_reason, warned_at = now(), warned_by = _actor,
         released_at = null, updated_at = now()
   where user_id = _user;

  insert into public.account_integrity_log (user_id, event, actor, actor_user, reason)
  values (_user, 'warned', 'human', _actor, v_reason);

  return jsonb_build_object('ok', true, 'state', 'warned', 'next_step', 'block');
end $$;


--
-- Name: account_profile_touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_profile_touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$ begin new.updated_at=now(); return new; end $$;


--
-- Name: account_purge(uuid, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_purge(_user uuid, _dry_run boolean DEFAULT true, _skip_grace boolean DEFAULT false, _release_handle boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_email    text;
  v_hash     text;
  v_d        public.account_deletions;
  v_blockers jsonb;
  v_orgs     uuid[] := '{}';
  r          record;
  w          jsonb;
  v_work     jsonb := '[]'::jsonb;
  v_pending  jsonb;
  v_next     jsonb;
  v_pass     int := 0;
  v_n        bigint;
  key        text;
  v_pre      jsonb := '{}'::jsonb;
  v_expl     jsonb := '{}'::jsonb;
  v_casc     jsonb := '{}'::jsonb;
  v_anon     jsonb := '{}'::jsonb;
  v_ledgers  text[] := '{}';
  v_unlocked jsonb := '[]'::jsonb;
  v_addrs    text[] := '{}';
  v_domains  text[] := '{}';
  v_tmp      text[];
  v_handle   text;
  v_addr0    text;
  v_report   jsonb;
begin
  select u.email into v_email from auth.users u where u.id = _user;
  if v_email is null then
    return jsonb_build_object('ok', false, 'error', 'user_not_found');
  end if;
  v_hash := encode(sha256(convert_to(lower(v_email), 'UTF8')), 'hex');

  v_blockers := public.account_deletion_blockers(_user);
  if jsonb_array_length(v_blockers) > 0 then
    return jsonb_build_object('ok', false, 'error', 'blocked', 'blockers', v_blockers);
  end if;

  select * into v_d from public.account_deletions where user_id = _user and state = 'scheduled';
  if not _dry_run and not _skip_grace then
    if v_d.id is null then
      return jsonb_build_object('ok', false, 'error', 'not_scheduled',
        'hint', 'Pehle user se request karwao, ya test account ke liye _skip_grace => true.');
    end if;
    if v_d.scheduled_for > now() then
      return jsonb_build_object('ok', false, 'error', 'grace_not_over', 'scheduled_for', v_d.scheduled_for);
    end if;
  end if;

  -- Supabase Storage ki files SQL se delete nahi hoti (bucket mein orphan reh jati hain).
  if to_regclass('storage.objects') is not null then
    for r in
      select a.attname::text as col from pg_attribute a
       where a.attrelid = to_regclass('storage.objects') and a.attname in ('owner_id', 'owner')
         and a.attnum > 0 and not a.attisdropped
    loop
      execute format('select count(*) from storage.objects where %I::text = %L', r.col, _user::text) into v_n;
      if v_n > 0 then
        return jsonb_build_object('ok', false, 'error', 'storage_objects_exist', 'count', v_n,
          'hint', 'Pehle Storage mein is user ki files delete karo (Dashboard ya Storage API), phir purge.');
      end if;
    end loop;
  end if;

  -- sirf woh orgs jin mein yeh akela member hai
  select coalesce(array_agg(o.org_id), '{}') into v_orgs
    from public.account_deletion_orgs(_user) o where o.other_members = 0;

  -- delete se PEHLE woh cheezein padh lo jo baad mein server cleanup ke kaam aayengi
  select t.anexomail_handle, t.anexomail_address into v_handle, v_addr0
    from public.trial_accounts t where t.user_id = _user;
  if v_addr0 is not null then v_addrs := array[lower(v_addr0)]; end if;
  if cardinality(v_orgs) > 0 then
    for r in select * from (values ('mail_accounts', 'address'), ('mailboxes', 'address'), ('org_addresses', 'address')) as v(t, c) loop
      if to_regclass('public.' || quote_ident(r.t)) is not null
         and public._ad_has_col(r.t, 'org_id') and public._ad_has_col(r.t, r.c) then
        execute format('select array_agg(distinct lower(%I::text)) from public.%I where org_id = any(%L::uuid[])',
                       r.c, r.t, v_orgs) into v_tmp;
        v_addrs := v_addrs || coalesce(v_tmp, '{}');
      end if;
    end loop;
    if to_regclass('public.org_domains') is not null and public._ad_has_col('org_domains', 'org_id') then
      execute format('select array_agg(distinct lower(domain::text)) from public.org_domains where org_id = any(%L::uuid[])',
                     v_orgs) into v_tmp;
      v_domains := coalesce(v_tmp, '{}');
    end if;
  end if;

  begin  -- ek unit: poora ya kuch nahi (dry-run mein bhi rollback)
    perform set_config('lock_timeout', '5s', true);

    -- A) auth.users par FK wali tables
    for r in
      select n.nspname::text as s, c.relname::text as t, a.attname::text as col, con.confdeltype::text as d
        from pg_constraint con
        join pg_class c on c.oid = con.conrelid
        join pg_namespace n on n.oid = c.relnamespace
        join pg_attribute a on a.attrelid = con.conrelid and a.attnum = con.conkey[1]
       where con.contype = 'f' and con.confrelid = to_regclass('auth.users')
         and cardinality(con.conkey) = 1 and con.conparentid = 0
         and n.nspname not in ('auth', 'pg_catalog', 'information_schema')
         and c.relkind in ('r', 'p')
    loop
      execute format('select count(*) from %I.%I where %I = %L', r.s, r.t, r.col, _user) into v_n;
      if r.s <> 'public' then
        if v_n > 0 then
          raise exception 'foreign_schema_rows: %.% has % row(s) for this user — delete them first', r.s, r.t, v_n;
        end if;
        continue;
      end if;
      key := r.t;
      v_pre := v_pre || jsonb_build_object(key, coalesce((v_pre ->> key)::bigint, 0) + v_n);
      if r.d = 'c' then
        if v_n > 0 then v_casc := v_casc || jsonb_build_object(key, coalesce((v_casc ->> key)::bigint, 0) + v_n); end if;
      elsif r.d in ('n', 'd') then
        if v_n > 0 then v_anon := v_anon || jsonb_build_object(key, coalesce((v_anon ->> key)::bigint, 0) + v_n); end if;
      elsif v_n > 0 then
        v_work := v_work || jsonb_build_array(jsonb_build_object('s', r.s, 't', r.t, 'c', r.col, 'm', 'user'));
      end if;
    end loop;

    -- B) FK ke baghair user_id / owner_id / owner_user_id
    for r in
      select c.relname::text as t, a.attname::text as col
        from pg_attribute a
        join pg_class c on c.oid = a.attrelid
        join pg_namespace n on n.oid = c.relnamespace
       where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relispartition
         and a.attnum > 0 and not a.attisdropped and a.atttypid = 'uuid'::regtype
         and a.attname in ('user_id', 'owner_id', 'owner_user_id')
         and c.relname not in ('account_deletions', 'organisations', 'orgs', 'account_organisations')
         and not exists (
           select 1 from pg_constraint k
            where k.conrelid = c.oid and k.contype = 'f' and k.confrelid = to_regclass('auth.users')
              and cardinality(k.conkey) = 1 and k.conkey[1] = a.attnum)
    loop
      execute format('select count(*) from public.%I where %I = %L', r.t, r.col, _user) into v_n;
      if v_n > 0 then
        key := r.t;
        v_pre := v_pre || jsonb_build_object(key, coalesce((v_pre ->> key)::bigint, 0) + v_n);
        v_work := v_work || jsonb_build_array(jsonb_build_object('s', 'public', 't', r.t, 'c', r.col, 'm', 'user'));
      end if;
    end loop;

    -- C) sole-member orgs: unki org_id wali rows, phir org ki apni row
    if cardinality(v_orgs) > 0 then
      for r in
        select c.relname::text as t
          from pg_attribute a
          join pg_class c on c.oid = a.attrelid
          join pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'public' and c.relkind in ('r', 'p') and not c.relispartition
           and a.attname = 'org_id' and a.attnum > 0 and not a.attisdropped and a.atttypid = 'uuid'::regtype
           and c.relname not in ('account_deletions', 'organisations', 'orgs', 'account_organisations')
      loop
        execute format('select count(*) from public.%I where org_id = any(%L::uuid[])', r.t, v_orgs) into v_n;
        if v_n > 0 then
          key := r.t;
          v_pre := v_pre || jsonb_build_object(key, coalesce((v_pre ->> key)::bigint, 0) + v_n);
          v_work := v_work || jsonb_build_array(jsonb_build_object('s', 'public', 't', r.t, 'c', 'org_id', 'm', 'org'));
        end if;
      end loop;
      for r in select * from (values ('organisations'), ('orgs'), ('account_organisations')) as v(t) loop
        if to_regclass('public.' || quote_ident(r.t)) is not null then
          execute format('select count(*) from public.%I where id = any(%L::uuid[])', r.t, v_orgs) into v_n;
          if v_n > 0 then
            key := r.t;
            v_pre := v_pre || jsonb_build_object(key, v_n);
            v_work := v_work || jsonb_build_array(jsonb_build_object('s', 'public', 't', r.t, 'c', 'id', 'm', 'org'));
          end if;
        end if;
      end loop;
    end if;

    -- D) immutable ledgers: sirf jin mein is user ki rows hon, sirf is transaction ke liye
    for r in
      select n.nspname::text as s, c.relname::text as t, g.tgname::text as trg, g.tgenabled::text as en
        from pg_trigger g
        join pg_class c on c.oid = g.tgrelid
        join pg_namespace n on n.oid = c.relnamespace
       where not g.tgisinternal and n.nspname = 'public' and g.tgenabled <> 'D'
         and (c.relname::text, g.tgname::text) in (
           values ('trial_events', 'trial_events_no_update'),
                  ('billing_event_receipts', 'billing_receipts_immutable'),
                  ('ai_credit_ledger', 'ai_ledger_no_update'),
                  ('movein_audit', 'movein_audit_no_change'),
                  ('mail_inbound_raw', 'mail_inbound_raw_immutable'),
                  ('mail_outbox_log', 'mail_outbox_log_immutable'),
                  ('crm_evidence', 'crm_evidence_no_update'))
    loop
      if coalesce((v_pre ->> r.t)::bigint, 0) > 0 then
        execute format('alter table %I.%I disable trigger %I', r.s, r.t, r.trg);
        v_ledgers := v_ledgers || r.t;
        v_unlocked := v_unlocked || jsonb_build_array(
          jsonb_build_object('s', r.s, 't', r.t, 'trg', r.trg, 'en', r.en));
      end if;
    end loop;

    -- E) explicit deletes; FK ki wajah se rukein to agle pass mein dobara
    v_pending := v_work;
    loop
      exit when jsonb_array_length(v_pending) = 0;
      v_pass :[REDACTED] v_pass + 1;
      v_next := '[]'::jsonb;
      for w in select value from jsonb_array_elements(v_pending) loop
        begin
          if w ->> 'm' = 'user' then
            execute format('delete from %I.%I where %I = %L', w ->> 's', w ->> 't', w ->> 'c', _user);
          else
            execute format('delete from %I.%I where %I = any(%L::uuid[])', w ->> 's', w ->> 't', w ->> 'c', v_orgs);
          end if;
          get diagnostics v_n = row_count;
          if v_n > 0 then
            key := w ->> 't';
            v_expl := v_expl || jsonb_build_object(key, coalesce((v_expl ->> key)::bigint, 0) + v_n);
          end if;
        exception when foreign_key_violation then
          v_next := v_next || jsonb_build_array(w);
        end;
      end loop;
      exit when jsonb_array_length(v_next) = jsonb_array_length(v_pending) or v_pass >= 10;
      v_pending := v_next;
    end loop;
    if jsonb_array_length(v_pending) > 0 then
      raise exception 'purge_blocked: FK ke wajah se in tables se rows nahi hati: %', v_pending::text;
    end if;

    -- F) handle quarantine, phir auth user (baqi cascade/set null DB khud karta hai)
    if v_handle is not null and not _release_handle then
      insert into public.reserved_handles (handle, reason) values (lower(v_handle), 'deleted')
      on conflict (handle) do nothing;
    end if;

    delete from auth.users where id = _user;
    get diagnostics v_n = row_count;
    if v_n <> 1 then
      raise exception 'auth_user_not_deleted';
    end if;

    -- ledgers wapas LOCK (asli run mein yeh commit hota hai — dobara enable zaroori hai)
    for w in select value from jsonb_array_elements(v_unlocked) loop
      execute format('alter table %I.%I %s trigger %I', w ->> 's', w ->> 't',
        case w ->> 'en' when 'A' then 'enable always' when 'R' then 'enable replica' else 'enable' end,
        w ->> 'trg');
    end loop;

    v_report := jsonb_build_object(
      'ok', true,
      'dry_run', _dry_run,
      'user_id', _user,
      'handle', v_handle,
      'handle_quarantined', (v_handle is not null and not _release_handle),
      'orgs_purged', to_jsonb(v_orgs),
      'mail_addresses', to_jsonb(array(select distinct unnest(v_addrs) order by 1)),
      'domains', to_jsonb(array(select distinct unnest(v_domains) order by 1)),
      'deleted_rows', v_expl,
      'cascaded_rows', v_casc,
      'anonymised_rows', v_anon,
      'ledgers_unlocked', to_jsonb(v_ledgers),
      'grace', jsonb_build_object('scheduled_for', v_d.scheduled_for, 'over', v_d.scheduled_for <= now()));

    if _dry_run then
      raise exception 'dry_run' using errcode = 'DR001';
    end if;

    update public.account_deletions
       set email = null, email_hash = v_hash
     where user_id = _user;
    update public.account_deletions
       set state = 'purged', purged_at = now(), purge_report = v_report - 'mail_addresses' - 'handle'
     where user_id = _user and state = 'scheduled';
    get diagnostics v_n = row_count;
    if v_n = 0 then
      insert into public.account_deletions
        (user_id, email_hash, state, requested_by, scheduled_for, purged_at, purge_report)
      values (_user, v_hash, 'purged', 'founder', now(), now(), v_report - 'mail_addresses' - 'handle');
    end if;
    return v_report;
  exception
    when sqlstate 'DR001' then
      return v_report;
    when others then
      return jsonb_build_object('ok', false, 'error', 'purge_failed', 'dry_run', _dry_run,
                                'detail', sqlerrm, 'sqlstate', sqlstate);
  end;
end $$;


--
-- Name: account_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.account_state(_user_id uuid DEFAULT auth.uid()) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.trial_accounts; st text; hrs numeric; res_left numeric;
begin
  select * into a from public.trial_accounts where user_id = _user_id;
  if a.user_id is null then
    return jsonb_build_object(
      'state','none','hours_left',0,'can_social_login',false,'ai_enabled',false,
      'address',null,'needs_claim',true,'needs_passkey',true,'needs_recovery',true,
      'business_data',false,'trial_limited',false,'trial_features','[]'::jsonb,
      'billing_access',true,'recovery_access',true);
  end if;

  st := a.status;
  -- DB decides expiry, not the clock in the browser
  if st = 'trial' and a.trial_ends_at <= now() then st := 'expired'; end if;
  if st = 'expired' and a.expired_at is not null
     and a.expired_at + interval '30 days' <= now() then st := 'released'; end if;

  hrs := greatest(0, round(extract(epoch from (a.trial_ends_at - now())) / 3600.0, 2));
  res_left := case when a.address_reserved_until is null then null
                   else greatest(0, round(extract(epoch from (a.address_reserved_until - now())) / 86400.0, 2)) end;

  return jsonb_build_object(
    'state', st,
    'plan', a.plan,
    'hours_left', case when st = 'trial' then hrs else 0 end,
    'trial_ends_at', a.trial_ends_at,
    -- OAuth permanently band. Passkey primary; password/magic-link recovery khuli.
    'can_social_login', false,
    'recovery_access', true,
    'billing_access', true,
    -- Trial core workspace ka real, limited tour hai: account/address, mail,
    -- people, calendar, search aur security. CRM/org/admin/AI/chat unlock nahi.
    'business_data', st = 'active' or st = 'trial',
    'trial_limited', st = 'trial',
    'trial_features', case when st = 'trial' then
      jsonb_build_array('today','mail','people','calendar','search','account','security','billing')
      else '[]'::jsonb end,
    'ai_enabled', st = 'active',                 -- trial/expired/frozen = HARD ZERO
    'address', a.anexomail_address,
    'address_reserved_days_left', res_left,
    'needs_claim', a.anexomail_address is null,
    'needs_passkey', not a.passkey_set,
    'needs_recovery', not a.recovery_set
  );
end $$;


--
-- Name: activate_paid_account(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_paid_account(_user uuid, _plan text, _ref text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if _user is null or _plan is null then return false; end if;
  if _plan not in ('basic','pro','business','business_pro') then return false; end if;
  if not exists (
    select 1 from public.trial_accounts
     where user_id = _user and status in ('pending_plan','trial')
  ) then
    return false;   -- active / expired / frozen / released ko yahan nahi chheda jata
  end if;
  perform public.trial_subscribe(_user, _plan, _ref);
  return true;
end $$;


--
-- Name: FUNCTION activate_paid_account(_user uuid, _plan text, _ref text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.activate_paid_account(_user uuid, _plan text, _ref text) IS 'E23: verified-payment entitlement -> trial_accounts pending_plan/trial => active (via trial_subscribe). No-op for every other status.';


--
-- Name: add_contact_alias(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_contact_alias(_contact_id uuid, _email text) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result text[];
begin
  update public.contacts
  set addresses = (
    select array_agg(distinct x) from unnest(coalesce(addresses, '{}') || array[lower(_email)]) x
  ),
  updated_at = now()
  where id = _contact_id
  returning addresses into result;
  return result;
end;
$$;


--
-- Name: ai_credits_complimentary(uuid, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_credits_complimentary(_workspace_id uuid, _day smallint) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w public.ai_credit_wallets; before numeric;
begin
  select * into w from public.ai_credit_wallets where workspace_id = _workspace_id for update;
  if w.id is null then raise exception 'wallet not found'; end if;
  begin
    insert into public.ai_credit_grants (workspace_id, cycle_started_at, grant_day, credits)
    values (_workspace_id, w.cycle_started_at, _day, 5);
  exception when unique_violation then
    return w.total_balance; -- already granted this cycle
  end;
  before := w.total_balance;
  update public.ai_credit_wallets
     set complimentary_credits = complimentary_credits + 5, updated_at = now() where id = w.id;
  insert into public.ai_credit_ledger
    (workspace_id, credit_type, entry_type, amount, balance_before, balance_after, reason)
  values (_workspace_id, 'complimentary', 'complimentary_grant', 5, before, before + 5,
          format('complimentary day %s', _day));
  return before + 5;
end $$;


--
-- Name: ai_credits_release(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_credits_release(_workspace_id uuid, _action_id uuid, _reason text DEFAULT 'provider failure'::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w public.ai_credit_wallets; res numeric; before numeric;
begin
  select * into w from public.ai_credit_wallets where workspace_id = _workspace_id for update;
  select reserved_credits into res from public.ai_actions where id = _action_id;
  res := coalesce(res, 0);
  before := w.total_balance;
  update public.ai_credit_wallets
     set reserved_credits = greatest(reserved_credits - res, 0), updated_at = now()
   where id = w.id;
  update public.ai_actions set status = 'failed', completed_at = now() where id = _action_id;
  insert into public.ai_credit_ledger
    (workspace_id, action_id, credit_type, entry_type, amount, balance_before, balance_after, reason)
  values (_workspace_id, _action_id, 'reserved', 'release', res, before, before + res, _reason);
  return before + res;
end $$;


--
-- Name: ai_credits_reserve(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_credits_reserve(_workspace_id uuid, _action_id uuid, _credits numeric, _idem text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w public.ai_credit_wallets; before numeric;
begin
  if exists (select 1 from public.ai_credit_ledger where idempotency_key = _idem) then
    return (select total_balance from public.ai_credit_wallets where workspace_id = _workspace_id);
  end if;
  select * into w from public.ai_credit_wallets where workspace_id = _workspace_id for update;
  if w.id is null then raise exception 'wallet not found'; end if;
  before := w.total_balance;
  if before < _credits then raise exception 'insufficient_credits'; end if;

  update public.ai_credit_wallets
     set reserved_credits = reserved_credits + _credits, updated_at = now()
   where id = w.id;
  update public.ai_actions
     set reserved_credits = _credits, status = 'reserved', approved_at = now()
   where id = _action_id;

  insert into public.ai_credit_ledger
    (workspace_id, action_id, credit_type, entry_type, amount, balance_before, balance_after, reason, idempotency_key)
  values (_workspace_id, _action_id, 'reserved', 'reservation', -_credits, before, before - _credits,
          'pre-flight reservation', _idem);

  return before - _credits;
end $$;


--
-- Name: ai_credits_settle(uuid, uuid, numeric, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_credits_settle(_workspace_id uuid, _action_id uuid, _actual numeric, _model text, _provider_cost numeric DEFAULT 0, _idem text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w public.ai_credit_wallets; res numeric; before numeric; take numeric; from_comp numeric; from_top numeric; from_sub numeric;
begin
  if _idem is not null and exists (select 1 from public.ai_credit_ledger where idempotency_key = _idem) then
    return (select total_balance from public.ai_credit_wallets where workspace_id = _workspace_id);
  end if;
  select * into w from public.ai_credit_wallets where workspace_id = _workspace_id for update;
  select reserved_credits into res from public.ai_actions where id = _action_id;
  res := coalesce(res, 0);
  before := w.total_balance;
  take := least(greatest(_actual, 0), res + w.subscription_credits + w.topup_credits + w.complimentary_credits);

  -- spend order: complimentary -> subscription -> topup
  from_comp := least(w.complimentary_credits, take);
  from_sub  := least(w.subscription_credits, take - from_comp);
  from_top  := take - from_comp - from_sub;

  update public.ai_credit_wallets set
    reserved_credits = greatest(reserved_credits - res, 0),
    complimentary_credits = complimentary_credits - from_comp,
    subscription_credits  = subscription_credits  - from_sub,
    topup_credits         = topup_credits         - from_top,
    updated_at = now()
  where id = w.id;

  update public.ai_actions set
    actual_credits = take, model = coalesce(_model, model), provider_cost = _provider_cost,
    status = 'completed', completed_at = now()
  where id = _action_id;

  insert into public.ai_credit_ledger
    (workspace_id, action_id, credit_type, entry_type, amount, balance_before, balance_after,
     reason, model, estimated_credits, actual_credits, idempotency_key)
  values (_workspace_id, _action_id, 'subscription', 'charge', -take, before,
          (select total_balance from public.ai_credit_wallets where id = w.id),
          'ai action settled', _model, res, take, _idem);

  return (select total_balance from public.ai_credit_wallets where id = w.id);
end $$;


--
-- Name: ai_credits_topup(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_credits_topup(_workspace_id uuid, _product_id text, _idem text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p public.ai_credit_topup_products; w public.ai_credit_wallets; before numeric;
begin
  if exists (select 1 from public.ai_credit_ledger where idempotency_key = _idem) then
    return (select total_balance from public.ai_credit_wallets where workspace_id = _workspace_id);
  end if;
  select * into p from public.ai_credit_topup_products where id = _product_id and active;
  if p.id is null then raise exception 'unknown_topup_product'; end if;
  select * into w from public.ai_credit_wallets where workspace_id = _workspace_id for update;
  before := w.total_balance;
  update public.ai_credit_wallets
     set topup_credits = topup_credits + p.credits, updated_at = now() where id = w.id;
  insert into public.ai_credit_ledger
    (workspace_id, credit_type, entry_type, amount, balance_before, balance_after, reason, idempotency_key)
  values (_workspace_id, 'topup', 'topup_purchase', p.credits, before, before + p.credits,
          format('top-up %s (%s credits)', p.id, p.credits), _idem);
  return before + p.credits;
end $$;


--
-- Name: ai_enabled(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_enabled(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((public.account_state(_user_id) ->> 'ai_enabled')::boolean, false);
$$;


