--
-- Name: billing_apply_entitlement(uuid, text, text, text, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_apply_entitlement(p_user uuid, p_kind text, p_plan text, p_band text, p_seats integer, p_intent uuid, p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_credits int; v_before numeric; v_cycle text; v_active_until timestamptz;
begin
  select billing_cycle into v_cycle from public.billing_intents where id=p_intent;
  v_active_until := case
    when v_cycle='yearly' then now()+interval '1 year'
    when p_kind in ('plan','ai_plan','support') then now()+interval '1 month'
    else null
  end;
  insert into public.entitlement_state
    (user_id,plan,ai_plan,seats,movein_band,support_active,active_until,revision,source_intent,updated_at)
  values (
    p_user,
    case when p_kind='plan' then p_plan end,
    case when p_kind='ai_plan' then p_plan end,
    case when p_kind='plan' then greatest(1,coalesce(p_seats,1)) else 0 end,
    case when p_kind='movein' then p_band end,
    p_kind='support',
    v_active_until,
    1,p_intent,now()
  ) on conflict (user_id) do update set
    plan=coalesce(case when p_kind='plan' then p_plan end,entitlement_state.plan),
    ai_plan=coalesce(case when p_kind='ai_plan' then p_plan end,entitlement_state.ai_plan),
    seats=case when p_kind='plan' then greatest(1,coalesce(p_seats,1)) else entitlement_state.seats end,
    movein_band=coalesce(case when p_kind='movein' then p_band end,entitlement_state.movein_band),
    support_active=entitlement_state.support_active or p_kind='support',
    active_until=coalesce(v_active_until,entitlement_state.active_until),
    revision=entitlement_state.revision+1,source_intent=p_intent,updated_at=now();

  if p_kind='ai_plan' then
    select monthly_credits into v_credits from public.ai_credit_plans where id=p_plan and active;
    if v_credits is null then raise exception 'unknown_ai_plan'; end if;
    select subscription_credits into v_before from public.ai_credit_wallets where owner_id=p_user for update;
    update public.ai_credit_wallets set plan_id=p_plan,subscription_credits=v_credits,
      cycle_started_at=now(),renews_at=now()+interval '1 month',updated_at=now()
    where owner_id=p_user;
    if not found then raise exception 'ai_wallet_missing_for_user'; end if;
    insert into public.ai_credit_ledger
      (workspace_id,user_id,credit_type,entry_type,amount,balance_before,balance_after,reason,idempotency_key)
    select workspace_id,p_user,'subscription','plan_allocation',v_credits,coalesce(v_before,0),v_credits,
           'verified '||p_plan||' subscription payment','billing-intent:'||p_intent
    from public.ai_credit_wallets where owner_id=p_user
    on conflict (idempotency_key) do nothing;
  end if;

  insert into public.billing_state_log (user_id,intent_id,from_state,to_state,reason,source)
  values (p_user,p_intent,'paid','entitled','entitlement applied: '||coalesce(p_kind,'plan'),p_source);
end;
$$;


--
-- Name: billing_guest_intent_claim(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_guest_intent_claim(p_token text, p_user uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  update public.billing_intents
     set user_id = coalesce(user_id, p_user),
         claimed_at = coalesce(claimed_at, now()),
         updated_at = now()
   where guest_token = [REDACTED]
   returning id into v_id;
  if v_id is null then return null; end if;

  -- paid guest checkout: entitlement claim ke waqt lagta hai
  if exists (select 1 from public.billing_intents where id = v_id and state = 'paid') then
    perform public.billing_apply_entitlement(v_id);
  end if;
  return v_id;
end;
$$;


--
-- Name: billing_guest_intent_open(text, text, text, text, text, integer, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_guest_intent_open(p_kind text, p_plan text DEFAULT NULL::text, p_band text DEFAULT NULL::text, p_product_key text DEFAULT NULL::text, p_product_id text DEFAULT NULL::text, p_seats integer DEFAULT 1, p_amount numeric DEFAULT NULL::numeric, p_currency text DEFAULT 'GBP'::text, p_email text DEFAULT NULL::text) RETURNS TABLE(intent_id uuid, guest_token text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_id uuid; v_tok text;
begin
  v_tok := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');

  insert into public.billing_intents
    (user_id, kind, plan, band, product_key, product_id, seats, amount_expected, currency,
     guest_email, guest_token, fsm_state, expires_at)
  values (null, coalesce(p_kind,'plan'), p_plan, p_band, p_product_key, p_product_id,
          greatest(1, coalesce(p_seats,1)), p_amount, coalesce(p_currency,'GBP'),
          nullif(trim(coalesce(p_email,'')),''), v_tok, 'CHECKOUT_OPEN', now() + interval '2 hours')
  returning id into v_id;

  insert into public.billing_state_versions
    (entity_type, entity_id, state_version, state, state_hash, source)
  values ('intent', v_id, 1, 'CHECKOUT_OPEN',
          public.billing_state_hash('intent', v_id, 'CHECKOUT_OPEN', 1), 'app');

  return query select v_id, v_tok;
end;
$$;


--
-- Name: billing_inbox_apply(uuid, text, uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_inbox_apply(p_message uuid, p_entity text, p_entity_id uuid, p_state text, p_version integer, p_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_local int; v_expect text;
begin
  if exists (select 1 from public.billing_inbox where message_id = p_message) then
    return 'DUPLICATE_ACK';
  end if;

  v_expect := public.billing_state_hash(p_entity, p_entity_id, p_state, p_version);
  if v_expect <> p_hash then
    insert into public.billing_failures (scope, intent_id, code, detail)
    values ('quic_inbox', p_entity_id, 'state_hash_mismatch', p_hash);
    return 'HASH_MISMATCH';
  end if;

  select state_version into v_local from public.billing_intents where id = p_entity_id;

  insert into public.billing_inbox (message_id, entity_type, entity_id, state, state_version, state_hash)
  values (p_message, p_entity, p_entity_id, p_state, p_version, p_hash);

  if v_local is null then
    return 'UNKNOWN_ENTITY';
  elsif p_version <= v_local then
    update public.billing_inbox set stale = true where message_id = p_message;
    return 'STALE_IGNORED';
  elsif p_version > v_local + 1 then
    return 'GAP_SNAPSHOT_REQUIRED';
  end if;

  update public.billing_intents
     set fsm_state = p_state, state_version = p_version, state_hash = p_hash, updated_at = now()
   where id = p_entity_id;
  update public.billing_inbox set applied = true, applied_at = now() where message_id = p_message;
  return 'APPLIED';
end;
$$;


--
-- Name: billing_intent_attach_checkout(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_intent_attach_checkout(p_intent uuid, p_checkout_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.billing_intents
     set polar_checkout_id = p_checkout_id, updated_at = now()
   where id = p_intent and polar_checkout_id is null;
end;
$$;


--
-- Name: billing_intent_confirm(uuid, text, text, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_intent_confirm(p_intent uuid DEFAULT NULL::uuid, p_checkout_id text DEFAULT NULL::text, p_order_id text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric, p_source text DEFAULT 'pull'::text, p_currency text DEFAULT 'GBP'::text, p_product_id text DEFAULT NULL::text) RETURNS TABLE(intent_id uuid, state text, already boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.billing_intents;
begin
  select * into r from public.billing_intents
   where (p_intent is not null and id = p_intent)
      or (p_checkout_id is not null and polar_checkout_id = p_checkout_id)
   order by created_at desc limit 1 for update;

  if r.id is null then
    insert into public.payment_alerts (severity,kind,message)
    values ('critical','payment_without_intent','paid signal without matching intent');
    return query select null::uuid,'no_intent'::text,false;
    return;
  end if;
  if r.state = 'entitled' then return query select r.id,r.state,true; return; end if;

  if upper(coalesce(p_currency,'GBP')) <> upper(r.currency) then
    raise exception 'payment_currency_mismatch';
  end if;
  if p_product_id is not null and r.product_id is not null and p_product_id <> r.product_id then
    raise exception 'payment_product_mismatch';
  end if;
  p_amount := coalesce(p_amount,r.amount_paid);
  if p_amount is null or abs(p_amount - r.amount_expected) > 0.01 then
    raise exception 'payment_amount_mismatch expected % received %', r.amount_expected, p_amount;
  end if;

  update public.billing_intents set
    state='paid', paid_at=coalesce(paid_at,now()), polar_order_id=coalesce(p_order_id,polar_order_id),
    amount_paid=p_amount, source=p_source, last_error=null, updated_at=now()
  where id=r.id;

  insert into public.billing_state_log (user_id,intent_id,from_state,to_state,reason,source,payload)
  values (r.user_id,r.id,r.state,'paid','validated payment confirmed',p_source,
          jsonb_build_object('amount',p_amount,'currency',p_currency,'product_id',p_product_id));

  perform public.billing_apply_entitlement(r.user_id,r.kind,r.plan,r.band,r.seats,r.id,p_source);
  update public.billing_intents set state='entitled',resolved_at=now(),
    next_sync_at=now()+interval '100 years',updated_at=now() where id=r.id;
  return query select r.id,'entitled'::text,false;
end;
$$;


--
-- Name: billing_intent_open(uuid, text, text, text, text, text, integer, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_intent_open(p_user uuid, p_kind text, p_plan text DEFAULT NULL::text, p_band text DEFAULT NULL::text, p_product_key text DEFAULT NULL::text, p_product_id text DEFAULT NULL::text, p_seats integer DEFAULT 1, p_amount numeric DEFAULT NULL::numeric, p_currency text DEFAULT 'GBP'::text, p_billing_cycle text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; pb public.billing_price_book; v_seats int; v_amount numeric; v_cycle text;
begin
  if upper(coalesce(p_currency,'GBP')) <> 'GBP' then raise exception 'billing_currency_must_be_gbp'; end if;
  v_seats := greatest(1, coalesce(p_seats,1));

  select * into pb from public.billing_price_book
   where product_key = p_product_key and active;

  if pb.product_key is not null then
    v_cycle  := pb.billing_cycle;
    v_amount := pb.amount_gbp * (case when pb.per_seat then v_seats else 1 end);
    if p_amount is not null and abs(p_amount - v_amount) > 0.01 then
      raise exception 'price_book_mismatch expected % got %', v_amount, p_amount;
    end if;
  else
    v_cycle  := p_billing_cycle;
    v_amount := p_amount;
  end if;

  if v_amount is null or v_amount <= 0 then raise exception 'billing_amount_required'; end if;
  if v_cycle is not null and v_cycle not in ('monthly','yearly') then raise exception 'invalid_billing_cycle'; end if;

  select id into v_id from public.billing_intents
   where user_id = p_user and state = 'open'
     and coalesce(product_id,'') = coalesce(p_product_id,'')
     and coalesce(billing_cycle,'') = coalesce(v_cycle,'')
     and created_at > now() - interval '30 minutes'
   order by created_at desc limit 1;
  if v_id is not null then return v_id; end if;

  insert into public.billing_intents
    (user_id,kind,plan,band,product_key,product_id,seats,amount_expected,currency,billing_cycle)
  values
    (p_user, coalesce(pb.kind,p_kind,'plan'), coalesce(pb.plan,p_plan), coalesce(pb.band,p_band),
     p_product_key, p_product_id, v_seats, v_amount, 'GBP', v_cycle)
  returning id into v_id;

  insert into public.billing_state_log (user_id,intent_id,from_state,to_state,reason,source,payload)
  values (p_user,v_id,null,'open','intent opened before checkout (price from DB price book)','app',
          jsonb_build_object('product_key',p_product_key,'billing_cycle',v_cycle,
                             'seats',v_seats,'amount_expected',v_amount,'currency','GBP'));
  return v_id;
end;
$$;


--
-- Name: billing_outbox_ack(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_outbox_ack(p_message uuid, p_hash text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ok boolean;
begin
  update public.billing_outbox
     set acked_at = now(), delivered_at = coalesce(delivered_at, now())
   where message_id = p_message and state_hash = p_hash
   returning true into v_ok;
  return coalesce(v_ok, false);
end;
$$;


--
-- Name: billing_personal_product_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_personal_product_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  required_kind text;
  actual_kind text;
  expected_product_id text;
begin
  if new.product_key is null
     or new.product_key not like 'POLAR_PRODUCT_PLAN_PERSONAL_%' then
    return new;
  end if;

  select pb.required_account_kind, pb.polar_product_id
    into required_kind, expected_product_id
  from public.billing_price_book pb
  where pb.product_key = new.product_key and pb.active;

  if required_kind is null then
    return new;
  end if;

  -- GUEST checkout (naya user, abhi tak koi account nahi): Business
  -- products ki tarah allow karo. Account-kind check yahan skip hota hai
  -- kyunki abhi koi account_profiles row exist hi nahi karti — kind
  -- signup ke waqt set hoga.
  if new.user_id is not null then
    select lower(nullif(btrim(p.preferences->>'workspace_kind'), ''))
      into actual_kind
    from public.account_profiles p
    where p.user_id = new.user_id;

    if actual_kind is not null and actual_kind is distinct from required_kind then
      raise exception 'product_not_available_for_account_kind';
    end if;
  end if;

  if expected_product_id is null
     or expected_product_id = ''
     or expected_product_id like 'REPLACE_%' then
    raise exception 'personal_polar_product_id_missing';
  end if;

  if new.product_id is distinct from expected_product_id then
    raise exception 'personal_polar_product_id_mismatch';
  end if;

  return new;
end;
$$;


--
-- Name: billing_reconcile_begin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_reconcile_begin(p_scope text DEFAULT 'hot'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  if exists (select 1 from public.billing_reconciliation_runs
              where finished_at is null and lease_until > now()) then
    return null;
  end if;
  insert into public.billing_reconciliation_runs (scope, lease_until)
  values (coalesce(p_scope,'hot'), now() + interval '5 minutes')
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: billing_reconcile_finish(uuid, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_reconcile_finish(p_run uuid, p_checked integer DEFAULT 0, p_repaired integer DEFAULT 0, p_failed integer DEFAULT 0, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.billing_reconciliation_runs
     set finished_at = now(), checked = p_checked, repaired = p_repaired,
         failed = p_failed, note = p_note, lease_until = null
