$$;


--
-- Name: billing_state_apply(uuid, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_state_apply(p_intent uuid, p_state text, p_source text DEFAULT 'reconcile'::text, p_amount numeric DEFAULT NULL::numeric, p_provider_object text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_ver int; v_hash text; v_user uuid; v_trace uuid;
begin
  select state_version, user_id, trace_id into v_ver, v_user, v_trace
    from public.billing_intents where id = p_intent for update;
  if v_ver is null then return null; end if;

  v_ver := v_ver + 1;
  v_hash := public.billing_state_hash('intent', p_intent, p_state, v_ver);

  update public.billing_intents
     set fsm_state = p_state,
         state_version = v_ver,
         state_hash = v_hash,
         amount_paid = coalesce(p_amount, amount_paid),
         updated_at = now()
   where id = p_intent;

  insert into public.billing_state_versions
    (entity_type, entity_id, state_version, state, state_hash, source, trace_id)
  values ('intent', p_intent, v_ver, p_state, v_hash, coalesce(p_source,'reconcile'), v_trace)
  on conflict do nothing;

  insert into public.billing_outbox
    (entity_type, entity_id, state, state_version, state_hash, trace_id, payload)
  values ('intent', p_intent, p_state, v_ver, v_hash, v_trace,
          jsonb_build_object('source', p_source, 'provider_object_id', p_provider_object));

  if p_state in ('PAYMENT_CONFIRMED','SUBSCRIPTION_ACTIVE') then
    insert into public.billing_receipts
      (intent_id, user_id, provider_object_id, amount, currency, state, state_version, state_hash, trace_id)
    select p_intent, v_user, p_provider_object,
           coalesce(p_amount, i.amount_paid, i.amount_expected, 0), i.currency,
           p_state, v_ver, v_hash, v_trace
      from public.billing_intents i where i.id = p_intent
    on conflict (intent_id, state_version) do nothing;
  end if;

  return v_ver;
end;
$$;


--
-- Name: billing_state_hash(text, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_state_hash(p_entity text, p_id uuid, p_state text, p_version integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(extensions.digest(coalesce(p_entity,'')||'|'||coalesce(p_id::text,'')||'|'||
                       coalesce(p_state,'')||'|'||coalesce(p_version::text,''), 'sha256'), 'hex');
$$;


--
-- Name: billing_sync_abandon_stale(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_sync_abandon_stale() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_count int;
begin
  with done as (
    update public.billing_intents
       set state = 'abandoned', resolved_at = now(), updated_at = now()
     where state = 'open'
       and paid_at is null
       and created_at < now() - interval '24 hours'
    returning id, user_id, state
  )
  insert into public.billing_state_log (user_id, intent_id, from_state, to_state, reason, source)
  select user_id, id, 'open', 'abandoned', 'unpaid for 24h', 'sweep' from done;
  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end;
$$;


--
-- Name: billing_sync_claim(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_sync_claim(p_limit integer DEFAULT 25) RETURNS TABLE(id uuid, user_id uuid, kind text, plan text, band text, product_id text, amount_expected numeric, amount_paid numeric, currency text, billing_cycle text, polar_checkout_id text, state text, attempts integer, created_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select i.id,i.user_id,i.kind,i.plan,i.band,i.product_id,i.amount_expected,i.amount_paid,
         i.currency,i.billing_cycle,i.polar_checkout_id,i.state,i.attempts,i.created_at
  from public.billing_intents i
  where i.state in ('open','paid','stuck') and i.next_sync_at<=now()
  order by i.created_at asc limit greatest(1,least(p_limit,100));
$$;


--
-- Name: billing_sync_fail(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_sync_fail(p_intent uuid, p_error text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_attempts int; v_state text;
begin
  update public.billing_intents
     set attempts = attempts + 1,
         last_error = p_error,
         -- backoff 30s, 1m, 2m ... capped 1h
         next_sync_at = now() + least(interval '1 hour', (interval '30 seconds') * power(2, least(attempts, 7))),
         state = case when state = 'paid' and attempts + 1 >= 5 then 'stuck' else state end,
         updated_at = now()
   where id = p_intent
  returning attempts, state into v_attempts, v_state;

  if coalesce(v_attempts,0) >= 3 then
    insert into public.payment_alerts (severity, kind, message)
    values ('critical','state_sync_failed',
            'intent ' || p_intent || ' attempt ' || v_attempts || ': ' || coalesce(p_error,'unknown'));
  end if;
end;
$$;


--
-- Name: billing_sync_touch(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_sync_touch(p_intent uuid, p_delay_seconds integer DEFAULT 60) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.billing_intents
     set next_sync_at = now() + make_interval(secs => greatest(15, p_delay_seconds)),
         updated_at = now()
   where id = p_intent;
$$;


