-- Name: block_billing_receipt_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_billing_receipt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'billing_event_receipts is append-only';
end;
$$;


--
-- Name: calendar_busy(uuid, text[], timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_busy(p_org uuid, p_addresses text[], p_from timestamp with time zone, p_to timestamp with time zone) RETURNS TABLE(address text, starts_at timestamp with time zone, ends_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select lower(a.address), e.starts_at, e.ends_at
    from public.calendar_attendees a
    join public.calendar_events e on e.id = a.event_id
   where e.org_id = p_org
     and lower(a.address) = any (select lower(x) from unnest(p_addresses) x)
     and e.starts_at < p_to and e.ends_at > p_from
     and coalesce(e.status, 'confirmed') <> 'cancelled' and e.cancelled_at is null
     and coalesce(a.response, 'needs_action') <> 'declined'
     and coalesce(e.kind, 'meeting') <> 'hold'
   order by 1, 2
$$;


--
-- Name: calendar_invite_log_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_invite_log_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('anexo.ledger_maintenance', true) = 'on' then
    return coalesce(new, old);
  end if;
  raise exception 'calendar_invite_log append-only hai (% band)', tg_op using errcode = 'AX032';
end $$;


--
-- Name: calendar_rsvp_apply(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_rsvp_apply(p_token uuid, p_response text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_att       uuid;
  v_cancelled boolean;
begin
  -- NULL ya ghalat jawab: refuse (pehle `null not in (...)` guard se nikal jata tha)
  if p_response is null or p_response not in ('accepted', 'tentative', 'declined') then
    return jsonb_build_object('found', false, 'error', 'bad_response');
  end if;

  -- attendee row lock: do jawab ek saath aaye to ek ke baad ek lagte hain
  select a.id, (e.status = 'cancelled' or e.cancelled_at is not null)
    into v_att, v_cancelled
    from public.calendar_attendees a
    join public.calendar_events e on e.id = a.event_id
   where a.rsvp_token = [REDACTED]
     for update of a;

  if v_att is null then
    return jsonb_build_object('found', false, 'error', 'not_found');
  end if;
  if v_cancelled then
    return jsonb_build_object('found', true, 'error', 'cancelled') || public.calendar_rsvp_lookup(p_token);
  end if;

  update public.calendar_attendees
     set response     = p_response,
         rsvp_at      = now(),
         rsvp_comment = nullif(left(btrim(coalesce(p_comment, '')), 500), '')
   where id = v_att;
  return public.calendar_rsvp_lookup(p_token);
end;
$$;


--
-- Name: calendar_rsvp_lookup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calendar_rsvp_lookup(p_token uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(
    (select jsonb_build_object(
        'found',     true,
        'event_id',  e.id,
        'title',     e.title,
        'agenda',    e.agenda,
        'location',  e.location,
        'starts_at', e.starts_at,
        'ends_at',   e.ends_at,
        'organiser', e.organiser,
        'cancelled', (e.status = 'cancelled' or e.cancelled_at is not null),
        'address',   a.address,
        'response',  a.response,
        'rsvp_at',   a.rsvp_at
      )
      from public.calendar_attendees a
      join public.calendar_events e on e.id = a.event_id
     where a.rsvp_token = [REDACTED]
    jsonb_build_object('found', false))
$$;


--
-- Name: call_connect_health(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_connect_health(_user uuid, _days integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d int := greatest(coalesce(_days, 7), 1);
begin
  if not public.chat_feature_ok(_user, 'call_connect_report') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  return (
    select jsonb_build_object('allowed', true, 'window_days', d,
      'samples', count(*),
      'ring_to_frame_p50', percentile_disc(0.5) within group (order by value_ms),
      'ring_to_frame_p95', percentile_disc(0.95) within group (order by value_ms),
      'ring_to_frame_p99', percentile_disc(0.99) within group (order by value_ms),
      'source', 'browser first_remote_frame marks')
      from public.chat_call_connect_marks
     where mark = 'first_remote_frame' and value_ms is not null
       and at > now() - make_interval(days => d));
end $$;


--
-- Name: call_connect_mark(uuid, uuid, text, bigint, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_connect_mark(_session uuid, _user uuid, _mark text, _value_ms bigint, _transport text, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_feature_ok(_user, 'call_connect_report') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  insert into public.chat_call_connect_marks (session_id, user_id, mark, value_ms, transport, at_ms)
  values (_session, _user, _mark, _value_ms, nullif(_transport,''), _at_ms);
  return jsonb_build_object('ok', true, 'measured_not_marketed', true);
end $$;


--
-- Name: call_connect_report(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_connect_report(_session uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m jsonb;
begin
  if not public.chat_feature_ok(_user, 'call_connect_report') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  select coalesce(jsonb_object_agg(mark, value_ms), '{}'::jsonb) into m
    from (select mark, min(value_ms) as value_ms
            from public.chat_call_connect_marks
           where session_id = _session group by mark) t;
  return jsonb_build_object('allowed', true, 'marks', m,
    'signaling_transport', (select transport from public.chat_call_connect_marks
                             where session_id = _session and transport is not null
                             order by id desc limit 1),
    'survival', coalesce((
      select jsonb_agg(jsonb_build_object('state', s.state, 'reason', s.reason,
               'rtt_ms', s.rtt_ms, 'loss_pct', s.loss_pct, 'at_ms', s.at_ms) order by s.id)
        from public.chat_call_survival s where s.session_id = _session), '[]'::jsonb),
    'same_call_record', true,
    'nothing_estimated', true);
end $$;


--
-- Name: call_event_record(uuid, uuid, text, bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_event_record(_session uuid, _user uuid, _event text, _at_ms bigint, _transport text, _path text, _detail jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare new_id bigint;
begin
  if not public.chat_feature_ok(_user, 'call_record') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  insert into public.chat_call_events (session_id, user_id, event, at_ms, transport, path, detail)
  values (_session, _user, _event, _at_ms,
          nullif(_transport,''), nullif(_path,''), coalesce(_detail, '{}'::jsonb))
  returning id into new_id;
  return jsonb_build_object('ok', true, 'event_id', new_id, 'append_only', true);
end $$;


--
-- Name: call_file_share(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_file_share(_session uuid, _version uuid, _user uuid, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_feature_ok(_user, 'call_file') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  insert into public.chat_call_files (session_id, version_id, shared_by, at_ms)
  values (_session, _version, _user, _at_ms)
  on conflict (session_id, version_id) do nothing;
  return jsonb_build_object('ok', true,
    'evidence_chain', coalesce((
      select jsonb_agg(jsonb_build_object('state', e.state, 'at', e.at) order by e.id)
        from public.file_evidence e where e.version_id = _version), '[]'::jsonb),
    'no_delivery_wording', true);
end $$;


--
-- Name: call_record(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_record(_session uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s record; joined_ms bigint; left_ms bigint;
begin
  if not public.chat_feature_ok(_user, 'call_record') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  select * into s from public.chat_call_sessions where id = _session;
  if not found then return jsonb_build_object('allowed', true, 'found', false); end if;

  select min(at_ms) into joined_ms from public.chat_call_events
   where session_id = _session and event in ('joined','rejoined');
  select max(at_ms) into left_ms from public.chat_call_events
   where session_id = _session and event = 'left';

  return jsonb_build_object(
    'allowed', true, 'found', true, 'measured_not_estimated', true,
    'call', jsonb_build_object('id', s.id, 'conversation_id', s.conversation_id,
      'started_by', s.caller_id, 'started_at', s.started_at, 'ended_at', s.ended_at,
      'setup_ms', s.setup_ms, 'signaling', s.signaling, 'path', s.path,
      'video_codec', s.video_codec, 'ice_restarts', s.ice_restarts,
      'end_reason', s.end_reason),
    'duration_ms', case when joined_ms is not null and left_ms is not null
                        then left_ms - joined_ms else null end,
    'duration_source', 'join/leave events',
    'join_truth', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', e.user_id, 'event', e.event,
               'at_ms', e.at_ms, 'transport', e.transport, 'path', e.path) order by e.id)
        from public.chat_call_events e where e.session_id = _session), '[]'::jsonb),
    'never_joined', coalesce((
      select jsonb_agg(distinct e.user_id) from public.chat_call_events e
       where e.session_id = _session and e.event = 'never_joined'), '[]'::jsonb),
    'transport_switches', coalesce((
      select jsonb_agg(jsonb_build_object('path', t.path, 'relay_host', t.relay_host,
               'reason', t.reason, 'at_ms', t.at_ms) order by t.id)
        from public.chat_call_transport_events t where t.session_id = _session), '[]'::jsonb),
    'files', coalesce((
      select jsonb_agg(jsonb_build_object('version_id', cf.version_id, 'shared_by', cf.shared_by,
               'at_ms', cf.at_ms, 'sha256', v.file_sha256, 'bytes', v.bytes,
               'name', f.name,
               'evidence', coalesce((select jsonb_agg(jsonb_build_object('state', e.state, 'at', e.at)
                                       order by e.id)
                                      from public.file_evidence e where e.version_id = cf.version_id),
                                    '[]'::jsonb)))
        from public.chat_call_files cf
        join public.chat_file_versions v on v.id = cf.version_id
        join public.chat_files f on f.id = v.file_id
       where cf.session_id = _session), '[]'::jsonb),
    'work', coalesce((
      select jsonb_agg(jsonb_build_object('object_type', w.object_type, 'object_id', w.object_id,
               'created_by', w.created_by, 'note', w.note, 'at_ms', w.at_ms))
        from public.chat_call_work w where w.session_id = _session), '[]'::jsonb));
end $$;


--
-- Name: call_record_board(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_record_board(_user uuid, _conversation uuid, _limit integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_feature_ok(_user, 'call_record') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  return jsonb_build_object('allowed', true, 'calls', coalesce((
    select jsonb_agg(jsonb_build_object(
             'id', s.id, 'started_at', s.started_at, 'ended_at', s.ended_at,
             'started_by', s.caller_id, 'path', s.path, 'signaling', s.signaling,
             'joins', (select count(*) from public.chat_call_events e
                        where e.session_id = s.id and e.event in ('joined','rejoined')),
             'never_joined', (select count(*) from public.chat_call_events e
                        where e.session_id = s.id and e.event = 'never_joined'),
             'files', (select count(*) from public.chat_call_files cf where cf.session_id = s.id),
             'work', (select count(*) from public.chat_call_work w where w.session_id = s.id))
           order by s.started_at desc)
      from public.chat_call_sessions s
     where (_conversation is null or s.conversation_id = _conversation)
       and (s.caller_id = _user or s.peer_id = _user)
     limit greatest(coalesce(_limit, 50), 1)), '[]'::jsonb));
end $$;


--
-- Name: call_ring_settle(uuid, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_ring_settle(_ring uuid, _user uuid, _action text, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  select * into r from public.chat_call_rings where id = _ring;
  if not found then return jsonb_build_object('ok', false, 'reason', 'ring_not_found'); end if;
  if _user not in (r.from_user, r.to_user) then
    return jsonb_build_object('ok', false, 'reason', 'not_a_participant');
  end if;
  if _action not in ('answered','declined','no_answer') then
    return jsonb_build_object('ok', false, 'reason', 'unknown_action');
  end if;

  update public.chat_call_rings set
    answered_at_ms  = case when _action = 'answered'  then coalesce(answered_at_ms, _at_ms)  else answered_at_ms end,
    declined_at_ms  = case when _action = 'declined'  then coalesce(declined_at_ms, _at_ms)  else declined_at_ms end,
    no_answer_at_ms = case when _action = 'no_answer' then coalesce(no_answer_at_ms, _at_ms) else no_answer_at_ms end
   where id = _ring;

  insert into public.chat_call_ring_log (ring_id, action, actor, at_ms)
  values (_ring, _action, _user, _at_ms);

  return jsonb_build_object('ok', true, 'recorded', _action,
    'ring_to_answer_ms', case when _action = 'answered' then _at_ms - r.rang_at_ms else null end,
    'no_false_missed', true);
end $$;


--
-- Name: call_ring_start(uuid, uuid, uuid, text, boolean, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_ring_start(_session uuid, _from uuid, _to uuid, _tone text, _calm boolean, _trigger text, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare win int; ring_id uuid;
begin
  if not public.chat_feature_ok(_from, 'call_ring') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  win := coalesce((public.chat_feature_allowed(_from, 'call_ring')->>'limit')::int, 45);

  insert into public.chat_call_rings (session_id, from_user, to_user, tone, calm_mode,
                                      trigger_path, window_s, rang_at_ms)
  values (_session, _from, _to, coalesce(nullif(_tone,''),'ringtone'), coalesce(_calm,false),
          coalesce(nullif(_trigger,''),'quic'), win, _at_ms)
  on conflict (session_id, to_user, tone) do update
    set rang_at_ms = excluded.rang_at_ms, calm_mode = excluded.calm_mode,
        trigger_path = excluded.trigger_path
  returning id into ring_id;

  insert into public.chat_call_ring_log (ring_id, action, actor, at_ms)
  values (ring_id, 'rang', _from, _at_ms);
  if coalesce(_calm, false) then
    insert into public.chat_call_ring_log (ring_id, action, actor, at_ms)
    values (ring_id, 'calm_mode', _from, _at_ms);
  end if;

  return jsonb_build_object('ok', true, 'ring_id', ring_id, 'window_s', win,
    'sound', case when coalesce(_calm,false) then 'muted — visual pulse + haptic only'
                  else 'self-made WebAudio chime (no CDN, no library)' end);
end $$;


--
-- Name: call_ring_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_ring_state(_session uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return jsonb_build_object('rings', coalesce((
    select jsonb_agg(jsonb_build_object('ring_id', r.id, 'to_user', r.to_user, 'tone', r.tone,
             'calm_mode', r.calm_mode, 'trigger_path', r.trigger_path, 'window_s', r.window_s,
             'rang_at_ms', r.rang_at_ms, 'answered_at_ms', r.answered_at_ms,
             'declined_at_ms', r.declined_at_ms, 'no_answer_at_ms', r.no_answer_at_ms,
             'state', case when r.answered_at_ms is not null then 'answered'
                           when r.declined_at_ms is not null then 'declined'
                           when r.no_answer_at_ms is not null then 'no answer'
                           else 'ringing' end)
             order by r.at)
      from public.chat_call_rings r
     where r.session_id = _session and (r.from_user = _user or r.to_user = _user)), '[]'::jsonb));
end $$;


--
-- Name: call_sfu_join(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_sfu_join(_room uuid, _user uuid, _layers integer, _codec text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare live int; cap int;
begin
  if not public.chat_feature_ok(_user, 'call_sfu') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  select max_participants into cap from public.chat_call_sfu_rooms where id = _room;
  if cap is null then return jsonb_build_object('ok', false, 'reason', 'room_not_found'); end if;
  select count(*) into live from public.chat_call_sfu_participants
   where room_id = _room and left_at is null;
  if live >= cap then
    return jsonb_build_object('ok', false, 'reason', 'room_full', 'max_participants', cap);
  end if;
  insert into public.chat_call_sfu_participants (room_id, user_id, layers, codec)
  values (_room, _user, coalesce(_layers, 3), nullif(_codec,''));
  return jsonb_build_object('ok', true, 'room_id', _room, 'simulcast_layers', coalesce(_layers, 3));
end $$;


--
-- Name: call_sfu_leave(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_sfu_leave(_room uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.chat_call_sfu_participants set left_at = now()
   where room_id = _room and user_id = _user and left_at is null;
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: call_sfu_room_ensure(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_sfu_room_ensure(_conversation uuid, _user uuid, _participants integer, _engine_host text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cap int; room record; want text; fwd boolean;
begin
  if not public.chat_feature_ok(_user, 'call_sfu') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  cap := coalesce((public.chat_feature_allowed(_user, 'call_sfu')->>'limit')::int, 8);
  if coalesce(_participants, 2) > cap then
    return jsonb_build_object('ok', false, 'reason', 'group_size_over_plan', 'max_participants', cap);
  end if;

  want := case when coalesce(_participants, 2) >= 3 then 'sfu' else 'mesh' end;
  -- media_forwarding SIRF tab true jab engine host asal mein bataya gaya ho
  fwd := want = 'sfu' and coalesce(nullif(_engine_host,''), '') <> '';

  select * into room from public.chat_call_sfu_rooms
   where conversation_id = _conversation and closed_at is null
   order by opened_at desc limit 1;

  if not found then
    insert into public.chat_call_sfu_rooms (conversation_id, opened_by, topology,
                                            media_forwarding, engine_host, max_participants)
    values (_conversation, _user, want, fwd, nullif(_engine_host,''), cap)
    returning * into room;
  else
    update public.chat_call_sfu_rooms
       set topology = want, media_forwarding = fwd,
           engine_host = coalesce(nullif(_engine_host,''), engine_host),
           max_participants = cap
     where id = room.id returning * into room;
  end if;

  return jsonb_build_object('ok', true, 'room_id', room.id, 'topology', room.topology,
    'media_forwarding', room.media_forwarding, 'engine_host', room.engine_host,
    'max_participants', room.max_participants,
    'honest_label', case when room.topology = 'mesh' then 'Direct mesh (1:1 or 2 people)'
                         when room.media_forwarding then 'Our own Rust SFU is forwarding this call'
                         else 'Group room open — SFU forwarding not reported by the engine yet' end,
    'turn_is_not_sfu', true);
end $$;


--
-- Name: call_sfu_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_sfu_state(_conversation uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare room record;
begin
  select * into room from public.chat_call_sfu_rooms
   where conversation_id = _conversation and closed_at is null
   order by opened_at desc limit 1;
  if not found then
    return jsonb_build_object('open', false, 'topology', 'mesh',
      'honest_label', 'No group room open — direct mesh');
  end if;
  return jsonb_build_object('open', true, 'room_id', room.id, 'topology', room.topology,
    'media_forwarding', room.media_forwarding, 'engine_host', room.engine_host,
    'max_participants', room.max_participants,
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', p.user_id, 'layers', p.layers,
               'codec', p.codec, 'joined_at', p.joined_at, 'left_at', p.left_at)
               order by p.joined_at)
        from public.chat_call_sfu_participants p where p.room_id = room.id), '[]'::jsonb));
end $$;


--
-- Name: call_survival_record(uuid, uuid, text, text, integer, numeric, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_survival_record(_session uuid, _user uuid, _state text, _reason text, _rtt integer, _loss numeric, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_feature_ok(_user, 'call_survival') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  if length(btrim(coalesce(_reason,''))) < 3 then
    return jsonb_build_object('ok', false, 'reason', 'reason_required');
  end if;
  insert into public.chat_call_survival (session_id, user_id, state, reason, rtt_ms, loss_pct, at_ms)
  values (_session, _user, _state, btrim(_reason), _rtt, _loss, _at_ms);
  return jsonb_build_object('ok', true, 'same_call_record', true, 'new_call_created', false);
end $$;


