-- Name: call_transport_record(uuid, uuid, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_transport_record(_session uuid, _user uuid, _path text, _relay_host text, _reason text, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_feature_ok(_user, 'call_record') then
