  end if;
  insert into public.chat_call_transport_events (session_id, user_id, path, relay_host, reason, at_ms)
  values (_session, _user, _path, nullif(_relay_host,''), nullif(_reason,''), _at_ms);
  return jsonb_build_object('ok', true, 'honest_label', _path);
end $$;


--
-- Name: call_work_link(uuid, text, uuid, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.call_work_link(_session uuid, _object_type text, _object_id uuid, _note text, _user uuid, _at_ms bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_feature_ok(_user, 'call_work') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  insert into public.chat_call_work (session_id, object_type, object_id, created_by, note, at_ms)
  values (_session, _object_type, _object_id, _user, nullif(btrim(coalesce(_note,'')),''), _at_ms)
  on conflict (session_id, object_type, object_id) do nothing;
  return jsonb_build_object('ok', true, 'provenance',
    jsonb_build_object('call_id', _session, 'at_ms', _at_ms, 'written_by', _user,
                       'engine_invented', false));
end $$;


--
-- Name: chat_access(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_access(_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  ok boolean := false;
  pl text;
  kind text;
  email text;
begin
  if _user_id is null then return false; end if;

  if to_regclass('public.founder_accounts') is not null then
    execute 'select exists(select 1 from public.founder_accounts where user_id = $1)'
      into ok using _user_id;
    if ok then return true; end if;
  end if;

  select u.email into email from auth.users u where u.id = _user_id;

  if email is not null and to_regclass('public.family_accounts') is not null then
    execute $q$
      select plan from public.family_accounts
      where lower(email) = lower($1)
      limit 1
    $q$ into pl using email;
  end if;

  if (pl is null or btrim(pl) = '')
     and to_regclass('public.entitlement_state') is not null then
    execute $q$
      select plan from public.entitlement_state
      where user_id = $1
        and (active_until is null or active_until > now())
      order by updated_at desc nulls last
      limit 1
    $q$ into pl using _user_id;
  end if;

  pl := replace(lower(coalesce(nullif(btrim(pl), ''), '')), '-', '_');
  if pl = 'businesspro' then pl := 'business_pro'; end if;

  -- Canonical Pro entitlement (Personal Pro+) · Business · Business Pro · AI grants
  if pl in ('pro', 'business', 'business_pro', 'ai_pro', 'ai_business', 'ai_executive') then
    return true;
  end if;

  if to_regclass('public.account_profiles') is not null then
    select lower(nullif(btrim(p.preferences->>'workspace_kind'), ''))
      into kind
    from public.account_profiles p
    where p.user_id = _user_id;
  end if;

  if kind = 'personal' and pl is not null and pl <> '' and pl <> 'basic' then
    return true;
  end if;

  return false;
end;
$_$;


--
-- Name: chat_attachment_attach(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_attachment_attach(_user uuid, _message uuid, _ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_count int;
begin
  update public.chat_attachments
     set message_id = _message
   where id = any(_ids)
     and uploader_id = _user
     and message_id is null;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: chat_attachment_commit(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_attachment_commit(_user uuid, _attachment uuid, _width integer, _height integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.chat_attachments
     set state = 'ready',
         committed_at = now(),
         width = coalesce(_width, width),
         height = coalesce(_height, height)
   where id = _attachment
     and uploader_id = _user;
  return found;
end $$;


--
-- Name: chat_attachment_new(uuid, uuid, text, text, bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_attachment_new(_user uuid, _conv uuid, _filename text, _content_type text, _bytes bigint, _width integer, _height integer) RETURNS TABLE(attachment_id uuid, storage_path text, thumb_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid := gen_random_uuid();
  v_path text;
  v_thumb text;
begin
  if not exists (
    select 1 from public.chat_participants p
    where p.conversation_id = _conv and p.user_id = _user
  ) then
    raise exception 'not_a_participant';
  end if;

  v_path  := _conv || '/' || v_id || '/original';
  v_thumb := _conv || '/' || v_id || '/thumb.webp';

  insert into public.chat_attachments (
    id, conversation_id, uploader_id, filename, content_type,
    bytes, width, height, storage_path, thumb_path, state
  ) values (
    v_id, _conv, _user, _filename, _content_type,
    coalesce(_bytes, 0), _width, _height, v_path, v_thumb, 'pending'
  );

  return query select v_id, v_path, v_thumb;
end $$;


