--
-- Name: chat_call_start(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_call_start(_conv uuid, _user uuid, _peer uuid, _role text, _signaling text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare sid uuid; ws uuid;
begin
  if not public.chat_video_allowed(_user) then raise exception 'video_not_entitled'; end if;
  select workspace_id into ws from public.chat_conversations where id = _conv;
  if ws is null then raise exception 'conversation_not_found'; end if;
  insert into public.chat_call_sessions
    (conversation_id, workspace_id, caller_id, peer_id, role, signaling)
  values (_conv, ws, _user, nullif(_peer, _user),
          coalesce(nullif(_role,''), 'caller'),
          nullif(_signaling,''))
  returning id into sid;
  perform public.chat_log(ws, _user, 'call.start', sid::text,
    jsonb_build_object('conversation', _conv, 'signaling', _signaling));
  return sid;
end $$;


--
-- Name: chat_call_stat(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_call_stat(_session uuid, _user uuid, _sample jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare owns boolean;
begin
  select true into owns from public.chat_call_sessions
   where id = _session and (caller_id = _user or peer_id = _user);
  if owns is not true then raise exception 'not_your_call'; end if;

  insert into public.chat_call_stats (
    session_id, rtt_ms, jitter_ms, loss_pct, bitrate_kbps, fps, width, height,
    path, video_codec, audio_codec, quality,
    capture_width, capture_height, encoded_width, encoded_height,
    decoded_width, decoded_height, rung, quality_limitation,
    available_out_kbps, frames_dropped, power_efficient
  ) values (
    _session,
    nullif((_sample->>'rtt_ms'),'')::int,
    nullif((_sample->>'jitter_ms'),'')::int,
    nullif((_sample->>'loss_pct'),'')::numeric,
    nullif((_sample->>'bitrate_kbps'),'')::int,
    nullif((_sample->>'fps'),'')::int,
    nullif((_sample->>'width'),'')::int,
    nullif((_sample->>'height'),'')::int,
    nullif((_sample->>'path'),''),
    nullif((_sample->>'video_codec'),''),
    nullif((_sample->>'audio_codec'),''),
    nullif((_sample->>'quality'),''),
    nullif((_sample->>'capture_width'),'')::int,
    nullif((_sample->>'capture_height'),'')::int,
    nullif((_sample->>'encoded_width'),'')::int,
    nullif((_sample->>'encoded_height'),'')::int,
    nullif((_sample->>'decoded_width'),'')::int,
    nullif((_sample->>'decoded_height'),'')::int,
    nullif((_sample->>'rung'),''),
    nullif((_sample->>'quality_limitation'),''),
    nullif((_sample->>'available_out_kbps'),'')::int,
    nullif((_sample->>'frames_dropped'),'')::int,
    case when _sample ? 'power_efficient' then (_sample->>'power_efficient')::boolean end
  );

  update public.chat_call_sessions s set
    capture_width      = coalesce(nullif((_sample->>'capture_width'),'')::int, s.capture_width),
    capture_height     = coalesce(nullif((_sample->>'capture_height'),'')::int, s.capture_height),
    capture_native_8k  = s.capture_native_8k
                          or coalesce(nullif((_sample->>'capture_width'),'')::int, 0) >= 7680,
    max_encoded_width  = greatest(coalesce(s.max_encoded_width, 0),
                                  coalesce(nullif((_sample->>'encoded_width'),'')::int, 0)),
    max_encoded_height = greatest(coalesce(s.max_encoded_height, 0),
                                  coalesce(nullif((_sample->>'encoded_height'),'')::int, 0)),
    max_decoded_width  = greatest(coalesce(s.max_decoded_width, 0),
                                  coalesce(nullif((_sample->>'decoded_width'),'')::int, 0)),
    max_decoded_height = greatest(coalesce(s.max_decoded_height, 0),
                                  coalesce(nullif((_sample->>'decoded_height'),'')::int, 0)),
    top_rung           = coalesce(nullif((_sample->>'rung'),''), s.top_rung),
    video_codec        = coalesce(nullif((_sample->>'video_codec'),''), s.video_codec),
    hw_accelerated     = coalesce(
                           case when _sample ? 'power_efficient'
                                then (_sample->>'power_efficient')::boolean end,
                           s.hw_accelerated),
    downgrades         = s.downgrades + coalesce(nullif((_sample->>'downgrade'),'')::int, 0),
    upgrades           = s.upgrades   + coalesce(nullif((_sample->>'upgrade'),'')::int, 0)
  where s.id = _session;

  return true;
end $$;


--
-- Name: chat_continuity(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_continuity(_user uuid, _device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'devices', coalesce((
      select jsonb_agg(jsonb_build_object(
               'device_id', d.device_id, 'device_label', d.device_label, 'kind', d.kind,
               'platform', d.platform, 'installed', d.installed,
               'last_seen_at', d.last_seen_at,
               'this_device', (_device_id is not null and d.device_id = _device_id))
               order by d.last_seen_at desc)
        from public.chat_devices d where d.user_id = _user), '[]'::jsonb),
    'drafts', coalesce((
      select jsonb_agg(jsonb_build_object(
               'conversation_id', dr.conversation_id, 'body', dr.body,
               'reply_to_id', dr.reply_to_id, 'caret', dr.caret,
               'attachment_ids', dr.attachment_ids, 'rev', dr.rev,
               'device_label', dr.device_label,
               'from_other_device', (_device_id is null or coalesce(dr.device_id,'') <> _device_id),
               'updated_at', dr.updated_at)
               order by dr.updated_at desc)
        from public.chat_drafts dr where dr.user_id = _user), '[]'::jsonb),
    'positions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'conversation_id', p.conversation_id, 'anchor_seq', p.anchor_seq,
               'at_bottom', p.at_bottom, 'rev', p.rev, 'device_label', p.device_label,
               'from_other_device', (_device_id is null or coalesce(p.device_id,'') <> _device_id),
               'updated_at', p.updated_at)
               order by p.updated_at desc)
        from public.chat_positions p where p.user_id = _user), '[]'::jsonb),
    'server_time', now()
  )
  where public.chat_access(_user);
$$;


--
-- Name: chat_conversation_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_conversation_list(_ws uuid, _me uuid) RETURNS TABLE(conversation_id uuid, kind text, subject text, other_user_id uuid, other_name text, last_body text, last_seq bigint, last_at timestamp with time zone, last_mine boolean, unread bigint, other_read_seq bigint, health text, health_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with mine as (
    select p.conversation_id, p.last_read_seq
      from public.chat_participants p where p.user_id = _me
  ),
  conv as (
    select c.* from public.chat_conversations c
     join mine on mine.conversation_id = c.id
     where c.workspace_id = _ws
  ),
  other as (
    select p.conversation_id, p.user_id, p.last_read_seq,
           coalesce(m.display_name, 'Teammate') as name
      from public.chat_participants p
      join conv on conv.id = p.conversation_id
      left join public.chat_members m
        on m.workspace_id = conv.workspace_id and m.user_id = p.user_id
     where p.user_id <> _me
  ),
  last_msg as (
    select distinct on (x.conversation_id) x.conversation_id, x.body, x.seq, x.created_at,
           x.sender_user_id
      from public.chat_messages x
      join conv on conv.id = x.conversation_id
     where x.deleted_at is null
     order by x.conversation_id, x.seq desc
  )
  select conv.id, conv.kind, conv.subject,
         other.user_id, other.name,
         last_msg.body, last_msg.seq, last_msg.created_at,
         (last_msg.sender_user_id = _me) as last_mine,
         (select count(*) from public.chat_messages z
            where z.conversation_id = conv.id and z.sender_user_id <> _me
              and z.seq > mine.last_read_seq and z.deleted_at is null) as unread,
         other.last_read_seq,
         case
           when last_msg.seq is null then 'green'
           when last_msg.sender_user_id = _me
                and coalesce(other.last_read_seq,0) < last_msg.seq
                and last_msg.created_at < now() - interval '24 hours' then 'red'
           when last_msg.sender_user_id = _me
                and coalesce(other.last_read_seq,0) < last_msg.seq then 'amber'
           when last_msg.sender_user_id <> _me and last_msg.seq > mine.last_read_seq then 'amber'
           else 'green'
         end as health,
         case
           when last_msg.seq is null then 'Nothing waiting'
           when last_msg.sender_user_id = _me
                and coalesce(other.last_read_seq,0) < last_msg.seq
                and last_msg.created_at < now() - interval '24 hours'
             then 'No reply for over 24 hours: ' || coalesce(other.name,'teammate')
           when last_msg.sender_user_id = _me
                and coalesce(other.last_read_seq,0) < last_msg.seq
             then 'Waiting: ' || coalesce(other.name,'teammate')
           when last_msg.sender_user_id <> _me and last_msg.seq > mine.last_read_seq
             then 'Waiting on you'
           else 'Nothing waiting'
         end as health_reason
    from conv
    join mine on mine.conversation_id = conv.id
    left join other on other.conversation_id = conv.id
    left join last_msg on last_msg.conversation_id = conv.id
   order by coalesce(last_msg.created_at, conv.created_at) desc
$$;


--
-- Name: chat_conversation_prefs(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_conversation_prefs(_conv uuid, _user uuid, _mute_minutes integer DEFAULT NULL::integer, _archived boolean DEFAULT NULL::boolean) RETURNS TABLE(muted_until timestamp with time zone, archived_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_in_conversation(_conv, _user) then raise exception 'not_participant'; end if;
  update public.chat_participants p
     set muted_until = case
           when _mute_minutes is null then p.muted_until
           when _mute_minutes <= 0 then null
           else now() + make_interval(mins => _mute_minutes) end,
         archived_at = case
           when _archived is null then p.archived_at
           when _archived then now() else null end
   where p.conversation_id = _conv and p.user_id = _user;
  return query select p.muted_until, p.archived_at from public.chat_participants p
    where p.conversation_id = _conv and p.user_id = _user;
end $$;


--
-- Name: chat_conversation_set_state(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_conversation_set_state(_conv uuid, _user uuid, _state text, _note text DEFAULT NULL::text) RETURNS TABLE(state text, note text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ws uuid;
begin
  if not public.chat_in_conversation(_conv, _user) then raise exception 'not_participant'; end if;
  if _state not in ('active','waiting','blocked','closed') then raise exception 'bad_state'; end if;
  select c.workspace_id into ws from public.chat_conversations c where c.id = _conv;
  insert into public.chat_conversation_state (conversation_id, workspace_id, state, note, set_by, updated_at)
    values (_conv, ws, _state, _note, _user, now())
  on conflict (conversation_id) do update
    set state = excluded.state, note = excluded.note, set_by = excluded.set_by, updated_at = now();
  perform public.chat_log(ws, _user, 'conversation.state', _conv::text, jsonb_build_object('state', _state));
  return query select s.state, s.note, s.updated_at
    from public.chat_conversation_state s where s.conversation_id = _conv;
end $$;


