--
-- Name: chat_delete_message(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_delete_message(_msg uuid, _user uuid) RETURNS TABLE(id uuid, deleted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m record;
begin
  select * into m from public.chat_messages where chat_messages.id = _msg;
  if m.id is null then raise exception 'message_not_found'; end if;
  if m.sender_user_id <> _user then raise exception 'only_sender_can_delete'; end if;
  if m.created_at < now() - interval '1 hour' then raise exception 'delete_window_closed'; end if;
  update public.chat_messages
     set deleted_at = now(), body = 'Message deleted by sender'
   where chat_messages.id = _msg;
  perform public.chat_log(m.workspace_id, _user, 'message.delete', _msg::text, jsonb_build_object('seq', m.seq));
  return query select mm.id, mm.deleted_at from public.chat_messages mm where mm.id = _msg;
end $$;


--
-- Name: chat_delete_message_48h(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_delete_message_48h(_msg uuid, _user uuid) RETURNS TABLE(id uuid, deleted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  m record;
  user_plan text;
begin
  -- ── message ──────────────────────────────────────────────────────────────
  select * into m from public.chat_messages where chat_messages.id = _msg;
  if m.id is null then
    raise exception 'message_not_found';
  end if;

  -- ── sirf sender ──────────────────────────────────────────────────────────
  if m.sender_user_id <> _user then
    raise exception 'only_sender_can_delete';
  end if;

  -- ── entitlement gate (canonical plan, Phase 36) ──────────────────────────
  select lower(nullif(btrim(es.plan), ''))
    into user_plan
  from public.entitlement_state es
  where es.user_id = _user
  limit 1;

  if user_plan is null or user_plan not in ('business', 'business_pro') then
    raise exception 'business_required';
  end if;

  -- ── window: Business = 48h, Business Pro = no limit ──────────────────────
  if user_plan = 'business'
     and m.created_at < now() - interval '48 hours' then
    raise exception 'delete_window_closed_48h';
  end if;

  -- ── delete ───────────────────────────────────────────────────────────────
  update public.chat_messages
     set deleted_at = now(),
         body = 'Message deleted by sender'
   where chat_messages.id = _msg
     and chat_messages.deleted_at is null;

  -- ── audit record ─────────────────────────────────────────────────────────
  perform public.chat_log(
    m.workspace_id,
    _user,
    'message.delete_48h',
    _msg::text,
    jsonb_build_object(
      'seq', m.seq,
      'plan', user_plan,
      'window', case when user_plan = 'business_pro' then 'none' else '48h' end
    )
  );

  return query
    select mm.id, mm.deleted_at
    from public.chat_messages mm
    where mm.id = _msg;
end $$;


--
-- Name: chat_delete_message_anytime(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_delete_message_anytime(_msg uuid, _user uuid) RETURNS TABLE(id uuid, deleted_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  m record;
  user_plan text;
begin
  -- ── message ──────────────────────────────────────────────────────────────
  select * into m from public.chat_messages where chat_messages.id = _msg;
  if m.id is null then
    raise exception 'message_not_found';
  end if;

  -- ── sirf sender apna message delete kar sakta hai ────────────────────────
  if m.sender_user_id <> _user then
    raise exception 'only_sender_can_delete';
  end if;

  -- ── Business Pro entitlement gate (canonical plan, Phase 36) ────────────
  select lower(nullif(btrim(es.plan), ''))
    into user_plan
  from public.entitlement_state es
  where es.user_id = _user
  limit 1;

  if user_plan is distinct from 'business_pro' then
    -- 1-hour window wala normal rule lagao — Business Pro ke baghair
    -- anytime delete nahi. Purana function wahi kaam karta hai.
    raise exception 'business_pro_required';
  end if;

  -- ── delete — koi time window nahi (Business Pro card) ───────────────────
  update public.chat_messages
     set deleted_at = now(),
         body = 'Message deleted by sender'
   where chat_messages.id = _msg
     and chat_messages.deleted_at is null;

  -- ── audit record — card: "with audit record" ─────────────────────────────
  perform public.chat_log(
    m.workspace_id,
    _user,
    'message.delete_anytime',
    _msg::text,
    jsonb_build_object('seq', m.seq, 'plan', user_plan, 'window', 'none')
  );

  return query
    select mm.id, mm.deleted_at
    from public.chat_messages mm
    where mm.id = _msg;
end $$;


--
-- Name: chat_device_seen(uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_device_seen(_user uuid, _device_id text, _label text DEFAULT NULL::text, _kind text DEFAULT 'unknown'::text, _platform text DEFAULT NULL::text, _installed boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_access(_user) then raise exception 'chat_not_entitled'; end if;
  insert into public.chat_devices (user_id, device_id, device_label, kind, platform, installed, last_seen_at)
  values (
    _user, _device_id, coalesce(nullif(btrim(_label), ''), 'Unknown device'),
    case when _kind in ('desktop','laptop','tablet','phone','pwa') then _kind else 'unknown' end,
    _platform, coalesce(_installed, false), now()
  )
  on conflict (user_id, device_id) do update
     set device_label = excluded.device_label,
         kind         = excluded.kind,
         platform     = excluded.platform,
         installed    = excluded.installed,
         last_seen_at = now();
end $$;


--
-- Name: chat_direct_conversation(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_direct_conversation(_ws uuid, _me uuid, _other uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare k text; c uuid;
begin
  if not public.chat_is_member(_ws, _me) then raise exception 'not_workspace_member'; end if;
  if not public.chat_is_member(_ws, _other) then raise exception 'other_not_member'; end if;
  k := least(_me::text, _other::text) || ':' || greatest(_me::text, _other::text);
  select id into c from public.chat_conversations where workspace_id = _ws and direct_key = k;
  if c is not null then return c; end if;
  insert into public.chat_conversations (workspace_id, kind, created_by, direct_key)
    values (_ws, 'direct', _me, k) returning id into c;
  insert into public.chat_participants (conversation_id, user_id) values (c, _me), (c, _other)
    on conflict do nothing;
  return c;
end $$;


--
-- Name: chat_draft_save(uuid, uuid, text, uuid, integer, uuid[], bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_draft_save(_user uuid, _conv uuid, _body text, _reply_to uuid DEFAULT NULL::uuid, _caret integer DEFAULT 0, _attachment_ids uuid[] DEFAULT '{}'::uuid[], _rev bigint DEFAULT 0, _device_id text DEFAULT NULL::text, _device_label text DEFAULT NULL::text) RETURNS TABLE(accepted boolean, conversation_id uuid, body text, reply_to_id uuid, caret integer, attachment_ids uuid[], rev bigint, device_label text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cur public.chat_drafts;
  next_rev bigint;
begin
  if not public.chat_access(_user) then raise exception 'chat_not_entitled'; end if;
  if not exists (select 1 from public.chat_participants p
                  where p.conversation_id = _conv and p.user_id = _user) then
    raise exception 'not_a_participant';
  end if;

  select * into cur from public.chat_drafts d
   where d.user_id = _user and d.conversation_id = _conv for update;

  -- purani rev nayi state ko kabhi overwrite nahi karti
  if cur.id is not null and coalesce(_rev, 0) < cur.rev then
    return query
      select false, cur.conversation_id, cur.body, cur.reply_to_id, cur.caret,
             cur.attachment_ids, cur.rev, cur.device_label, cur.updated_at;
    return;
  end if;

  next_rev := greatest(coalesce(cur.rev, 0), coalesce(_rev, 0)) + 1;

  if coalesce(btrim(_body), '') = '' and coalesce(array_length(_attachment_ids, 1), 0) = 0 then
    delete from public.chat_drafts where user_id = _user and conversation_id = _conv;
    return query select true, _conv, ''::text, null::uuid, 0, '{}'::uuid[], next_rev,
                        _device_label, now();
    return;
  end if;

  insert into public.chat_drafts (
    user_id, conversation_id, body, reply_to_id, caret, attachment_ids, rev,
    device_id, device_label, updated_at
  ) values (
    _user, _conv, _body, _reply_to, greatest(coalesce(_caret, 0), 0),
    coalesce(_attachment_ids, '{}'), next_rev, _device_id, _device_label, now()
  )
  on conflict (user_id, conversation_id) do update
     set body = excluded.body, reply_to_id = excluded.reply_to_id, caret = excluded.caret,
         attachment_ids = excluded.attachment_ids, rev = excluded.rev,
         device_id = excluded.device_id, device_label = excluded.device_label,
         updated_at = now();

  return query
    select true, d.conversation_id, d.body, d.reply_to_id, d.caret, d.attachment_ids,
           d.rev, d.device_label, d.updated_at
      from public.chat_drafts d
     where d.user_id = _user and d.conversation_id = _conv;
end $$;


--
-- Name: chat_edit_message(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_edit_message(_msg uuid, _user uuid, _body text) RETURNS TABLE(id uuid, body text, edited_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m record;
begin
  select * into m from public.chat_messages where chat_messages.id = _msg;
  if m.id is null then raise exception 'message_not_found'; end if;
  if m.sender_user_id <> _user then raise exception 'only_sender_can_edit'; end if;
  if m.deleted_at is not null then raise exception 'message_deleted'; end if;
  if m.created_at < now() - interval '5 minutes' then raise exception 'edit_window_closed'; end if;
  if coalesce(btrim(_body),'') = '' then raise exception 'empty_body'; end if;

  insert into public.chat_message_edits (message_id, editor_id, old_body, new_body)
    values (_msg, _user, m.body, _body);
  update public.chat_messages set body = _body, edited_at = now() where chat_messages.id = _msg;
  perform public.chat_log(m.workspace_id, _user, 'message.edit', _msg::text, jsonb_build_object('seq', m.seq));
  return query select mm.id, mm.body, mm.edited_at from public.chat_messages mm where mm.id = _msg;
end $$;


