-- Name: chat_email_quotes_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_email_quotes_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'chat_email_quotes is append-only';
