--
-- Name: chat_ensure_workspace(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_ensure_workspace(_user uuid, _name text DEFAULT 'Workspace'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ws uuid;
begin
  if not public.chat_access(_user) then raise exception 'chat_not_entitled'; end if;
  select m.workspace_id into ws
    from public.chat_members m
    join public.chat_workspaces w on w.id = m.workspace_id
   where m.user_id = _user
   order by (w.name = 'ANEXOMAIL Family') desc, m.created_at
   limit 1;
  if ws is not null then return ws; end if;
  insert into public.chat_workspaces (name, owner_user_id)
  values (coalesce(_name,'Workspace'), _user)
  returning id into ws;
  insert into public.chat_members (workspace_id, user_id, role)
  values (ws, _user, 'owner') on conflict do nothing;
  return ws;
end $$;


--
-- Name: chat_feature_allowed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_feature_allowed(_user uuid, _feature text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_plan text; v_row public.chat_phase_entitlements;
begin
  v_plan := (public.file_plan_for(_user)).plan;
  select * into v_row from public.chat_phase_entitlements
   where plan = v_plan and feature = _feature;
  if not found then
    return jsonb_build_object('plan', v_plan, 'feature', _feature, 'allowed', false, 'limit', null);
  end if;
  return jsonb_build_object(
    'plan', v_plan, 'feature', _feature,
    'allowed', v_row.allowed, 'limit', v_row.limit_value, 'note', v_row.note);
end $$;


