--
-- Name: chat_in_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_in_conversation(_conv uuid, _user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.chat_participants p
    where p.conversation_id = _conv and p.user_id = _user
  )
$$;


--
-- Name: chat_is_founder(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_is_founder(_user uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare found boolean := false;
begin
  if _user is null then return false; end if;
  if to_regclass('public.founder_accounts') is not null then
    execute 'select exists(select 1 from public.founder_accounts where user_id = $1)'
      into found using _user;
  end if;
  return coalesce(found, false);
end $_$;


