$$;


--
-- Name: chat_mark(uuid, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_mark(_conv uuid, _user uuid, _state text, _upto bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n bigint := 0;
begin
  if not public.chat_in_conversation(_conv, _user) then raise exception 'not_participant'; end if;
  if _state not in ('delivered','read') then raise exception 'bad_state'; end if;

  insert into public.chat_message_receipts (message_id, user_id, state)
  select m.id, _user, _state from public.chat_messages m
   where m.conversation_id = _conv and m.seq <= _upto and m.sender_user_id <> _user
  on conflict do nothing;
  get diagnostics n = row_count;

  if _state = 'read' then
    update public.chat_participants p
       set last_read_seq = greatest(p.last_read_seq, _upto),
           last_delivered_seq = greatest(p.last_delivered_seq, _upto)
     where p.conversation_id = _conv and p.user_id = _user;
  else
    update public.chat_participants p
       set last_delivered_seq = greatest(p.last_delivered_seq, _upto)
     where p.conversation_id = _conv and p.user_id = _user;
  end if;
  return n;
end $$;


--
-- Name: chat_message_forward(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_message_forward(_msg uuid, _to_conv uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_from uuid; v_body text; v_new jsonb;
begin
  select conversation_id, body into v_from, v_body from public.chat_messages where id = _msg;
  if v_from is null then raise exception 'message_not_found'; end if;
  if not public.chat_in_conversation(v_from, _user) then raise exception 'not_participant_source'; end if;
  if not public.chat_in_conversation(_to_conv, _user) then raise exception 'not_participant_target'; end if;

  select to_jsonb(t) into v_new from public.chat_send(
    _to_conv, _user, gen_random_uuid()::text, v_body, 'forward') t;

  insert into public.chat_work_events (item_id, actor_id, action, detail)
  select w.id, _user, 'forwarded', jsonb_build_object('to_conversation', _to_conv)
    from public.chat_work_items w where w.message_id = _msg;

  return jsonb_build_object('ok', true, 'forwarded_from', _msg, 'to_conversation', _to_conv, 'message', v_new);
end $$;


--
-- Name: chat_message_hide(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_message_hide(_msg uuid, _user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c uuid;
begin
  select conversation_id into c from public.chat_messages where id = _msg;
  if c is null then raise exception 'message_not_found'; end if;
  if not public.chat_in_conversation(c, _user) then raise exception 'not_participant'; end if;
  insert into public.chat_message_hidden (message_id, user_id) values (_msg, _user)
    on conflict do nothing;
  return true;
end $$;


--
-- Name: chat_message_star(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_message_star(_msg uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_conv uuid; v_starred boolean;
begin
  select conversation_id into v_conv from public.chat_messages where id = _msg;
  if v_conv is null then raise exception 'message_not_found'; end if;
  if not public.chat_in_conversation(v_conv, _user) then raise exception 'not_participant'; end if;
  if exists (select 1 from public.chat_message_stars where message_id = _msg and user_id = _user) then
    delete from public.chat_message_stars where message_id = _msg and user_id = _user;
    v_starred := false;
  else
    insert into public.chat_message_stars (message_id, user_id) values (_msg, _user);
    v_starred := true;
  end if;
  return jsonb_build_object('ok', true, 'message_id', _msg, 'starred', v_starred);
end $$;


--
-- Name: chat_messages_page(uuid, uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_messages_page(_conv uuid, _me uuid, _before_seq bigint DEFAULT NULL::bigint, _limit integer DEFAULT 80) RETURNS TABLE(id uuid, seq bigint, body text, sender_user_id uuid, sender_name text, mine boolean, device_label text, transport text, created_at timestamp with time zone, edited_at timestamp with time zone, delivered_at timestamp with time zone, read_at timestamp with time zone, reply_to_id uuid, reply_to_body text, reply_to_sender text, pinned_at timestamp with time zone, reactions jsonb, attachment_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.id, m.seq, m.body, m.sender_user_id,
         coalesce(mem.display_name, 'Teammate') as sender_name,
         (m.sender_user_id = _me) as mine,
         m.device_label, m.transport, m.created_at, m.edited_at,
         (select min(r.at) from public.chat_message_receipts r
           where r.message_id = m.id and r.state = 'delivered') as delivered_at,
         (select min(r.at) from public.chat_message_receipts r
           where r.message_id = m.id and r.state = 'read') as read_at,
         m.reply_to_id,
         (select left(p.body, 160) from public.chat_messages p where p.id = m.reply_to_id) as reply_to_body,
         (select coalesce(pm.display_name, 'Teammate') from public.chat_messages p
            left join public.chat_members pm
              on pm.workspace_id = p.workspace_id and pm.user_id = p.sender_user_id
           where p.id = m.reply_to_id) as reply_to_sender,
         m.pinned_at,
         coalesce((
           select jsonb_agg(x order by x->>'emoji')
             from (
               select jsonb_build_object(
                        'emoji', r.emoji,
                        'count', count(*),
                        'mine', bool_or(r.user_id = _me)) as x
                 from public.chat_reactions r
                where r.message_id = m.id
                group by r.emoji) g
         ), '[]'::jsonb) as reactions,
         (select count(*) from public.chat_attachments a
           where a.message_id = m.id and a.state = 'ready') as attachment_count
    from public.chat_messages m
    left join public.chat_members mem
      on mem.workspace_id = m.workspace_id and mem.user_id = m.sender_user_id
   where m.conversation_id = _conv
     and public.chat_in_conversation(_conv, _me)
     and m.deleted_at is null
     and (_before_seq is null or m.seq < _before_seq)
   order by m.seq desc
   limit greatest(1, least(coalesce(_limit,80), 300))
$$;


--
-- Name: chat_pin_message(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_pin_message(_msg uuid, _user uuid, _pin boolean) RETURNS TABLE(id uuid, pinned_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m record;
begin
  select * into m from public.chat_messages where chat_messages.id = _msg;
  if m.id is null then raise exception 'message_not_found'; end if;
  if not public.chat_in_conversation(m.conversation_id, _user) then raise exception 'not_participant'; end if;
  update public.chat_messages
     set pinned_at = case when _pin then now() else null end,
         pinned_by = case when _pin then _user else null end
   where chat_messages.id = _msg;
  return query select mm.id, mm.pinned_at from public.chat_messages mm where mm.id = _msg;
end $$;


--
-- Name: chat_position_save(uuid, uuid, bigint, boolean, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_position_save(_user uuid, _conv uuid, _anchor_seq bigint, _at_bottom boolean DEFAULT true, _rev bigint DEFAULT 0, _device_id text DEFAULT NULL::text, _device_label text DEFAULT NULL::text) RETURNS TABLE(accepted boolean, anchor_seq bigint, at_bottom boolean, rev bigint, device_label text, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cur public.chat_positions;
  next_rev bigint;
begin
  if not public.chat_access(_user) then raise exception 'chat_not_entitled'; end if;
  if not exists (select 1 from public.chat_participants p
                  where p.conversation_id = _conv and p.user_id = _user) then
    raise exception 'not_a_participant';
  end if;

  select * into cur from public.chat_positions p
   where p.user_id = _user and p.conversation_id = _conv for update;

  if cur.id is not null and coalesce(_rev, 0) < cur.rev then
    return query select false, cur.anchor_seq, cur.at_bottom, cur.rev, cur.device_label, cur.updated_at;
    return;
  end if;

  next_rev := greatest(coalesce(cur.rev, 0), coalesce(_rev, 0)) + 1;

  insert into public.chat_positions (
    user_id, conversation_id, anchor_seq, at_bottom, rev, device_id, device_label, updated_at
  ) values (
    _user, _conv, greatest(coalesce(_anchor_seq, 0), 0), coalesce(_at_bottom, true),
    next_rev, _device_id, _device_label, now()
  )
  on conflict (user_id, conversation_id) do update
     set anchor_seq = excluded.anchor_seq, at_bottom = excluded.at_bottom,
         rev = excluded.rev, device_id = excluded.device_id,
         device_label = excluded.device_label, updated_at = now();

  return query select true, p.anchor_seq, p.at_bottom, p.rev, p.device_label, p.updated_at
    from public.chat_positions p
   where p.user_id = _user and p.conversation_id = _conv;
end $$;


--
-- Name: chat_presence_ping(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_presence_ping(_ws uuid, _user uuid, _device text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.chat_presence (workspace_id, user_id, device_label, last_seen_at)
  values (_ws, _user, _device, now())
  on conflict (workspace_id, user_id)
    do update set last_seen_at = now(), device_label = coalesce(excluded.device_label, chat_presence.device_label)
$$;


--
-- Name: chat_provenance_backfill(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_provenance_backfill(_conversation uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record; n int := 0;
begin
  for r in
    select m.id from public.chat_messages m
     where (_conversation is null or m.conversation_id = _conversation)
       and not exists (select 1 from public.chat_message_provenance p where p.message_id = m.id)
     order by m.conversation_id, m.seq
  loop
    perform public.chat_provenance_seal(r.id);
    n := n + 1;
  end loop;
  return jsonb_build_object('ok', true, 'sealed', n);
end $$;


--
-- Name: chat_provenance_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_provenance_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'provenance_is_sealed';
end $$;


--
-- Name: chat_provenance_on_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_provenance_on_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  perform public.chat_provenance_seal(new.id);
  return new;
end $$;


--
-- Name: chat_provenance_seal(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_provenance_seal(_message uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare m record; v_prev text; v_body text; v_chain text;
begin
  select * into m from public.chat_messages where id = _message;
  if m.id is null then return jsonb_build_object('ok', false, 'error', 'message_not_found'); end if;
  if exists (select 1 from public.chat_message_provenance where message_id = _message) then
    return jsonb_build_object('ok', true, 'already_sealed', true);
  end if;

  select p.chain_hash into v_prev
    from public.chat_message_provenance p
   where p.conversation_id = m.conversation_id and p.seq < m.seq
   order by p.seq desc limit 1;

  v_body  := encode(digest(coalesce(m.body, ''), 'sha256'), 'hex');
  v_chain := encode(digest(coalesce(v_prev, '') || v_body || m.seq::text, 'sha256'), 'hex');

  insert into public.chat_message_provenance
    (message_id, conversation_id, workspace_id, seq, sender_user_id, sent_at,
     transport, device_label, body_hash, prev_hash, chain_hash)
  values (m.id, m.conversation_id, m.workspace_id, m.seq, m.sender_user_id, m.created_at,
          coalesce(m.transport, 'bun'), m.device_label, v_body, v_prev, v_chain)
  on conflict (message_id) do nothing;

  return jsonb_build_object('ok', true, 'body_hash', v_body, 'chain_hash', v_chain);
end $$;


--
-- Name: chat_react(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_react(_msg uuid, _user uuid, _emoji text) RETURNS TABLE(emoji text, count bigint, mine boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare conv uuid; ws uuid;
begin
  select m.conversation_id, m.workspace_id into conv, ws from public.chat_messages m where m.id = _msg;
  if conv is null then raise exception 'message_not_found'; end if;
  if not public.chat_in_conversation(conv, _user) then raise exception 'not_participant'; end if;
  if coalesce(btrim(_emoji),'') = '' then raise exception 'emoji_required'; end if;

  if exists (select 1 from public.chat_reactions r
             where r.message_id = _msg and r.user_id = _user and r.emoji = _emoji) then
    delete from public.chat_reactions r
     where r.message_id = _msg and r.user_id = _user and r.emoji = _emoji;
  else
    insert into public.chat_reactions (message_id, user_id, emoji) values (_msg, _user, _emoji);
  end if;

  return query
    select r.emoji, count(*)::bigint, bool_or(r.user_id = _user)
      from public.chat_reactions r where r.message_id = _msg
     group by r.emoji order by 2 desc, 1;
end $$;


