--
-- Name: chat_search_deep(uuid, text, uuid, uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_search_deep(_user uuid, _q text, _conv uuid DEFAULT NULL::uuid, _sender uuid DEFAULT NULL::uuid, _before timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 40) RETURNS TABLE(id uuid, conversation_id uuid, seq bigint, body text, sender_user_id uuid, sender_name text, created_at timestamp with time zone, mine boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.id, m.conversation_id, m.seq, m.body, m.sender_user_id,
         coalesce(mem.display_name, 'Teammate'), m.created_at,
         (m.sender_user_id = _user)
    from public.chat_messages m
    join public.chat_participants p
      on p.conversation_id = m.conversation_id and p.user_id = _user
    left join public.chat_members mem
      on mem.workspace_id = m.workspace_id and mem.user_id = m.sender_user_id
   where public.chat_access(_user)
     and m.deleted_at is null
     and coalesce(btrim(_q), '') <> ''
     and m.body ilike '%' || btrim(_q) || '%'
     and (_conv is null or m.conversation_id = _conv)
     and (_sender is null or m.sender_user_id = _sender)
     and (_before is null or m.created_at < _before)
   order by m.created_at desc
   limit greatest(1, least(coalesce(_limit, 40), 100));
$$;


--
-- Name: chat_search_messages(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_search_messages(_user uuid, _q text, _limit integer DEFAULT 40) RETURNS TABLE(id uuid, conversation_id uuid, seq bigint, body text, sender_name text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.id, m.conversation_id, m.seq, m.body,
         coalesce(mem.display_name, 'Teammate'), m.created_at
    from public.chat_messages m
    join public.chat_participants p
      on p.conversation_id = m.conversation_id and p.user_id = _user
    left join public.chat_members mem
      on mem.workspace_id = m.workspace_id and mem.user_id = m.sender_user_id
   where public.chat_access(_user)
     and m.deleted_at is null
     and coalesce(btrim(_q),'') <> ''
     and m.body ilike '%' || btrim(_q) || '%'
     and not exists (select 1 from public.chat_message_hidden h
                      where h.message_id = m.id and h.user_id = _user)
   order by m.created_at desc
   limit greatest(1, least(coalesce(_limit,40), 200))
$$;


--
-- Name: chat_send(uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_send(_conv uuid, _sender uuid, _client_msg_id text, _body text, _device text DEFAULT NULL::text, _reply_to uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, seq bigint, created_at timestamp with time zone, duplicate boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ws uuid; s bigint; m record;
begin
  if not public.chat_in_conversation(_conv, _sender) then raise exception 'not_participant'; end if;
  if coalesce(btrim(_body),'') = '' then raise exception 'empty_body'; end if;
  if coalesce(btrim(_client_msg_id),'') = '' then raise exception 'client_msg_id_required'; end if;

  select mm.id, mm.seq, mm.created_at into m from public.chat_messages mm
   where mm.conversation_id = _conv and mm.client_msg_id = _client_msg_id;
  if m.id is not null then
    return query select m.id, m.seq, m.created_at, true;
    return;
  end if;

  update public.chat_conversations c set next_seq = c.next_seq + 1, last_message_at = now()
    where c.id = _conv returning c.next_seq - 1, c.workspace_id into s, ws;

  insert into public.chat_messages (conversation_id, workspace_id, sender_user_id,
      client_msg_id, seq, body, device_label, reply_to_id)
    values (_conv, ws, _sender, _client_msg_id, s, _body, _device, _reply_to)
    returning chat_messages.id, chat_messages.seq, chat_messages.created_at
    into m;

  update public.chat_participants p
     set last_read_seq = greatest(p.last_read_seq, s),
         last_delivered_seq = greatest(p.last_delivered_seq, s)
   where p.conversation_id = _conv and p.user_id = _sender;

  return query select m.id, m.seq, m.created_at, false;
end $$;


--
-- Name: chat_signal_poll(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_signal_poll(_conv uuid, _user uuid) RETURNS TABLE(id uuid, from_user uuid, kind text, payload jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_video_allowed(_user) then raise exception 'video_not_entitled'; end if;
  return query
    update public.chat_signals s set consumed_at = now()
     where s.to_user = _user and s.consumed_at is null
       and (_conv is null or s.conversation_id = _conv)
       and s.created_at > now() - interval '2 minutes'
    returning s.id, s.from_user, s.kind, s.payload, s.created_at;
end $$;


--
-- Name: chat_signal_send(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_signal_send(_conv uuid, _from uuid, _to uuid, _kind text, _payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ws uuid; sid uuid;
begin
  if not public.chat_video_allowed(_from) then raise exception 'video_not_entitled'; end if;
  if not public.chat_in_conversation(_conv, _from) then raise exception 'not_participant'; end if;
  if not public.chat_in_conversation(_conv, _to) then raise exception 'peer_not_participant'; end if;
  select c.workspace_id into ws from public.chat_conversations c where c.id = _conv;
  insert into public.chat_signals (conversation_id, from_user, to_user, kind, payload)
    values (_conv, _from, _to, _kind, coalesce(_payload, '{}'::jsonb)) returning id into sid;
  perform public.chat_log(ws, _from, 'video.' || _kind, _conv::text, jsonb_build_object('to', _to));
  return sid;
end $$;


--
-- Name: chat_typing_ping(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_typing_ping(_conv uuid, _user uuid, _typing boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_in_conversation(_conv, _user) then raise exception 'not_participant'; end if;
  if _typing then
    insert into public.chat_typing (conversation_id, user_id, until)
    values (_conv, _user, now() + interval '6 seconds')
    on conflict (conversation_id, user_id) do update set until = now() + interval '6 seconds';
  else
    delete from public.chat_typing where conversation_id = _conv and user_id = _user;
  end if;
end $$;


--
-- Name: chat_unread_total(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_unread_total(_user uuid) RETURNS TABLE(unread bigint, conversations bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with mine as (
    select p.conversation_id, p.last_read_seq
      from public.chat_participants p
     where p.user_id = _user
  ), counted as (
    select mine.conversation_id,
           count(m.id) filter (
             where m.seq > mine.last_read_seq
               and m.sender_user_id <> _user
               and m.deleted_at is null
           ) as n
      from mine
      left join public.chat_messages m on m.conversation_id = mine.conversation_id
     group by mine.conversation_id
  )
  select coalesce(sum(n),0)::bigint, count(*) filter (where n > 0)::bigint from counted;
$$;


--
-- Name: chat_video_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_video_allowed(_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  ok boolean := false;
  billed text := 'basic';
  email text;
begin
  if _user_id is null then return false; end if;

  if to_regclass('public.founder_accounts') is not null then
    execute 'select exists(select 1 from public.founder_accounts where user_id = $1)'
      into ok using _user_id;
    if ok then return true; end if;
  end if;

  select u.email into email from auth.users u where u.id = _user_id;

  if to_regclass('public.family_accounts') is not null and email is not null then
    execute $q$
      select plan from public.family_accounts
      where lower(email) = lower($1)
      limit 1
    $q$ into billed using email;
  end if;

  if (billed is null or btrim(billed) = '')
     and to_regclass('public.trial_accounts') is not null then
    execute 'select plan from public.trial_accounts where user_id = $1 limit 1'
      into billed using _user_id;
  end if;

  if (billed is null or btrim(billed) = '')
     and to_regclass('public.entitlement_state') is not null then
    execute $q$
      select plan from public.entitlement_state
      where user_id = $1
      order by updated_at desc nulls last
      limit 1
    $q$ into billed using _user_id;
  end if;

  billed := replace(lower(coalesce(nullif(btrim(billed), ''), 'basic')), '-', '_');
  if billed in ('pro', 'business', 'business_pro', 'businesspro') then
    return true;
  end if;
  return false;
end;
$_$;


--
-- Name: chat_work_board(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_board(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then return jsonb_build_object('items', '[]'::jsonb); end if;
  return jsonb_build_object(
    'plan', public.chat_feature_allowed(_user, 'work_chain'),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'id', w.id, 'kind', w.kind, 'title', w.title, 'state', w.state,
        'owner_user_id', w.owner_user_id, 'due_at', w.due_at,
        'depends_on', w.depends_on, 'conversation_id', w.conversation_id,
        'message_id', w.message_id, 'completed_at', w.completed_at,
        'overdue', w.due_at is not null and w.state in ('open','blocked') and w.due_at < now(),
        'evidence_count', (select count(*) from public.chat_work_evidence e
                            where e.item_id = w.id and e.kind <> 'message'))
      order by (w.due_at is null), w.due_at)
      from public.chat_work_items w
     where w.workspace_id = v_ws and w.state in ('open','blocked')), '[]'::jsonb));
end $$;


--
-- Name: chat_work_chain(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_chain(_item uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.chat_work_items; v_msg jsonb;
begin
  select * into v_row from public.chat_work_items where id = _item;
  if not found then raise exception 'item_not_found'; end if;
  if not public.chat_in_conversation(v_row.conversation_id, _user) then raise exception 'not_participant'; end if;

  select jsonb_build_object(
      'id', m.id, 'seq', m.seq, 'sender_id', m.sender_user_id, 'sent_at', m.created_at,
      'visible', m.deleted_at is null,
      'body', case when m.deleted_at is null then m.body else null end)
    into v_msg
    from public.chat_messages m where m.id = v_row.message_id;

  return jsonb_build_object(
    'item', jsonb_build_object(
      'id', v_row.id, 'kind', v_row.kind, 'title', v_row.title, 'state', v_row.state,
      'owner_user_id', v_row.owner_user_id, 'created_by', v_row.created_by,
      'created_at', v_row.created_at, 'due_at', v_row.due_at,
      'depends_on', v_row.depends_on,
      'completed_by', v_row.completed_by, 'completed_at', v_row.completed_at,
      'retention_class', v_row.retention_class),
    'source_message', coalesce(v_msg, jsonb_build_object('visible', false, 'body', null)),
    'provenance', v_row.provenance,
    'parsed', v_row.parsed,
    'dependency', (select jsonb_build_object('id', d.id, 'title', d.title, 'state', d.state)
                     from public.chat_work_items d where d.id = v_row.depends_on),
    'evidence', coalesce((select jsonb_agg(jsonb_build_object(
        'kind', e.kind, 'ref', e.ref, 'sha256', e.sha256, 'at', e.at) order by e.id)
      from public.chat_work_evidence e where e.item_id = _item), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(jsonb_build_object(
        'action', ev.action, 'from_state', ev.from_state, 'to_state', ev.to_state, 'at', ev.at) order by ev.id)
      from public.chat_work_events ev where ev.item_id = _item), '[]'::jsonb),
    'chain_intact', v_row.provenance ? 'body_hash');
end $$;


--
-- Name: chat_work_complete(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_complete(_item uuid, _user uuid, _evidence jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.chat_work_items; v_have int; v_kind text; v_ref text;
begin
  select * into v_row from public.chat_work_items where id = _item;
  if not found then raise exception 'item_not_found'; end if;
  if not public.chat_in_conversation(v_row.conversation_id, _user) then raise exception 'not_participant'; end if;
  if v_row.depends_on is not null
     and exists (select 1 from public.chat_work_items d where d.id = v_row.depends_on and d.state <> 'done') then
    return jsonb_build_object('ok', false, 'error', 'blocked_by_dependency', 'depends_on', v_row.depends_on);
  end if;

  if _evidence is not null and coalesce(_evidence->>'ref','') <> '' then
    v_kind := coalesce(_evidence->>'kind', 'note');
    v_ref  := _evidence->>'ref';
    insert into public.chat_work_evidence (item_id, kind, ref, sha256, added_by)
    values (_item, v_kind, v_ref, encode(digest(v_ref, 'sha256'), 'hex'), _user);
  end if;

  select count(*) into v_have from public.chat_work_evidence
   where item_id = _item and kind <> 'message';
  if v_have = 0 then
    return jsonb_build_object('ok', false, 'error', 'evidence_required',
      'message', 'Completion needs evidence: a file, a link, a message or a written note.');
  end if;

  update public.chat_work_items
     set state = 'done', completed_by = _user, completed_at = now(), closed_at = now()
   where id = _item;

  update public.chat_work_items
     set state = 'open'
   where depends_on = _item and state = 'blocked';

  insert into public.chat_work_events (item_id, actor_id, from_state, to_state, action, detail)
  values (_item, _user, v_row.state, 'done', 'completed', jsonb_build_object('evidence_count', v_have));

  return jsonb_build_object('ok', true, 'item_id', _item, 'state', 'done', 'evidence_count', v_have);
end $$;


--
-- Name: chat_work_create(uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_create(_conv uuid, _user uuid, _msg uuid, _kind text, _title text, _due timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ws uuid; id uuid;
begin
  if not public.chat_in_conversation(_conv, _user) then raise exception 'not_participant'; end if;
  if _kind not in ('task','promise','decision') then raise exception 'bad_kind'; end if;
  if coalesce(btrim(_title),'') = '' then raise exception 'title_required'; end if;
  select c.workspace_id into ws from public.chat_conversations c where c.id = _conv;
  insert into public.chat_work_items (workspace_id, conversation_id, message_id, kind, title, owner_user_id, due_at, created_by)
    values (ws, _conv, _msg, _kind, _title, _user, _due, _user)
    returning chat_work_items.id into id;
  perform public.chat_log(ws, _user, 'work.create', id::text, jsonb_build_object('kind', _kind));
  return id;
end $$;


--
-- Name: chat_work_depend(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_depend(_item uuid, _depends_on uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_conv uuid; v_cursor uuid; v_hops int := 0;
begin
  if _item = _depends_on then raise exception 'self_dependency'; end if;
  if not coalesce((public.chat_feature_allowed(_user,'work_dependency')->>'allowed')::boolean,false) then
    return jsonb_build_object('ok', false, 'error', 'not_entitled');
  end if;
  select conversation_id into v_conv from public.chat_work_items where id = _item;
  if v_conv is null then raise exception 'item_not_found'; end if;
  if not public.chat_in_conversation(v_conv, _user) then raise exception 'not_participant'; end if;

  v_cursor := _depends_on;
  while v_cursor is not null and v_hops < 32 loop
    if v_cursor = _item then raise exception 'dependency_cycle'; end if;
    select depends_on into v_cursor from public.chat_work_items where id = v_cursor;
    v_hops := v_hops + 1;
  end loop;

  update public.chat_work_items
     set depends_on = _depends_on,
         state = case when state = 'open'
                       and exists (select 1 from public.chat_work_items d
                                    where d.id = _depends_on and d.state <> 'done')
                      then 'blocked' else state end
   where id = _item;

  insert into public.chat_work_events (item_id, actor_id, action, detail)
  values (_item, _user, 'dependency_set', jsonb_build_object('depends_on', _depends_on));

  return jsonb_build_object('ok', true, 'item_id', _item, 'depends_on', _depends_on);
end $$;


--
-- Name: chat_work_from_message(uuid, uuid, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_from_message(_msg uuid, _user uuid, _kind text DEFAULT NULL::text, _title text DEFAULT NULL::text, _owner uuid DEFAULT NULL::uuid, _due timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_s jsonb; v_conv uuid; v_ws uuid; v_id uuid; v_body text; v_seq bigint;
  v_sender uuid; v_sent timestamptz; v_gate jsonb; v_open int;
begin
  v_gate := public.chat_feature_allowed(_user, 'work_chain');
  if not coalesce((v_gate->>'allowed')::boolean, false) then
    return jsonb_build_object('ok', false, 'error', 'not_entitled', 'plan', v_gate->>'plan');
  end if;

  v_s := public.chat_work_suggest(_msg, _user);
  v_conv := (v_s->>'conversation_id')::uuid;

  select m.body, m.seq, m.sender_user_id, m.created_at, c.workspace_id
    into v_body, v_seq, v_sender, v_sent, v_ws
    from public.chat_messages m join public.chat_conversations c on c.id = m.conversation_id
   where m.id = _msg;

  select count(*) into v_open from public.chat_work_items
   where workspace_id = v_ws and state in ('open','blocked');
  if (v_gate->>'limit') is not null and v_open >= (v_gate->>'limit')::int then
    return jsonb_build_object('ok', false, 'error', 'work_limit_reached', 'limit', (v_gate->>'limit')::int);
  end if;

  insert into public.chat_work_items (
    workspace_id, conversation_id, message_id, kind, title, owner_user_id,
    due_at, created_by, source_seq, parsed, provenance)
  values (
    v_ws, v_conv, _msg,
    coalesce(_kind, v_s->>'kind'),
    coalesce(nullif(trim(coalesce(_title,'')),''), v_s->>'title'),
    coalesce(_owner, (v_s->>'owner_user_id')::uuid),
    coalesce(_due, nullif(v_s->>'due_at','')::timestamptz),
    _user, v_seq, v_s,
    jsonb_build_object(
      'conversation_id', v_conv, 'message_id', _msg, 'message_seq', v_seq,
      'sender_id', v_sender, 'sent_at', v_sent,
      'body_hash', encode(digest(coalesce(v_body,''), 'sha256'), 'hex'),
      'source', 'ANEXOChat', 'captured_at', now()))
  returning id into v_id;

  insert into public.chat_work_evidence (item_id, kind, ref, sha256, added_by)
  values (v_id, 'message', _msg::text, encode(digest(coalesce(v_body,''),'sha256'),'hex'), _user);

  insert into public.chat_work_events (item_id, actor_id, from_state, to_state, action, detail)
  values (v_id, _user, null, 'open', 'created_from_message', v_s);

  perform public.chat_log(v_ws, _user, 'work.from_message', v_id::text, v_s);

  return jsonb_build_object('ok', true, 'item_id', v_id, 'parsed', v_s);
end $$;


--
-- Name: chat_work_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_list(_conv uuid, _user uuid) RETURNS TABLE(id uuid, kind text, title text, state text, due_at timestamp with time zone, owner_user_id uuid, message_id uuid, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.chat_in_conversation(_conv, _user) then raise exception 'not_participant'; end if;
  return query
    select w.id, w.kind, w.title, w.state, w.due_at, w.owner_user_id, w.message_id, w.created_at
      from public.chat_work_items w
     where w.conversation_id = _conv
     order by (w.state = 'open') desc, w.created_at desc;
end $$;


--
-- Name: chat_work_parse_due(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_parse_due(_body text, _now timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare b text := lower(coalesce(_body,'')); n int; dow int; target date;
begin
  if b ~ 'tomorrow|kal' then
    return jsonb_build_object('due', (date_trunc('day', _now) + interval '1 day 17 hours'), 'phrase', 'tomorrow');
  end if;
  if b ~ 'today|aaj|tonight' then
    return jsonb_build_object('due', (date_trunc('day', _now) + interval '18 hours'), 'phrase', 'today');
  end if;
  if b ~ 'next week' then
    return jsonb_build_object('due', (date_trunc('week', _now) + interval '1 week 4 days 17 hours'), 'phrase', 'next week');
  end if;
  n := nullif(substring(b from 'in ([0-9]{1,2}) day'), '')::int;
  if n is not null then
    return jsonb_build_object('due', _now + make_interval(days => n), 'phrase', 'in ' || n || ' days');
  end if;
  n := nullif(substring(b from 'in ([0-9]{1,2}) hour'), '')::int;
  if n is not null then
    return jsonb_build_object('due', _now + make_interval(hours => n), 'phrase', 'in ' || n || ' hours');
  end if;
  dow := case
    when b ~ 'monday'    then 1 when b ~ 'tuesday'  then 2
    when b ~ 'wednesday' then 3 when b ~ 'thursday' then 4
    when b ~ 'friday'    then 5 when b ~ 'saturday' then 6
    when b ~ 'sunday'    then 7 else null end;
  if dow is not null then
    target := (_now)::date + ((dow - extract(isodow from _now)::int + 7) % 7);
    if target = _now::date then target := target + 1; end if;
    return jsonb_build_object('due', target::timestamptz + interval '17 hours', 'phrase', 'weekday');
  end if;
  return jsonb_build_object('due', null, 'phrase', null);
end $$;


--
-- Name: chat_work_set_state(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_set_state(_item uuid, _user uuid, _state text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare w record;
begin
  select * into w from public.chat_work_items where chat_work_items.id = _item;
  if w.id is null then raise exception 'item_not_found'; end if;
  if not public.chat_in_conversation(w.conversation_id, _user) then raise exception 'not_participant'; end if;
  if _state not in ('open','done','cancelled') then raise exception 'bad_state'; end if;
  update public.chat_work_items
     set state = _state, closed_at = case when _state = 'open' then null else now() end
   where chat_work_items.id = _item;
  perform public.chat_log(w.workspace_id, _user, 'work.state', _item::text, jsonb_build_object('state', _state));
  return true;
end $$;


--
-- Name: chat_work_suggest(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_work_suggest(_msg uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_conv uuid; v_body text; v_sender uuid; v_due jsonb; v_owner uuid; v_owner_name text;
  v_title text; r record;
begin
  select m.conversation_id, m.body, m.sender_user_id into v_conv, v_body, v_sender
    from public.chat_messages m where m.id = _msg;
  if v_conv is null then raise exception 'message_not_found'; end if;
  if not public.chat_in_conversation(v_conv, _user) then raise exception 'not_participant'; end if;

  v_due := public.chat_work_parse_due(v_body);

  -- owner = conversation participant jiska naam message mein literal aaya
  for r in
    select cm.user_id, coalesce(mem.display_name, '') as name
      from public.chat_participants cm
      left join public.chat_members mem on mem.user_id = cm.user_id
     where cm.conversation_id = v_conv
  loop
    if coalesce(r.name,'') <> '' and lower(v_body) like '%' || lower(split_part(r.name,' ',1)) || '%' then
      v_owner := r.user_id; v_owner_name := r.name; exit;
    end if;
  end loop;

  v_title := trim(regexp_replace(left(coalesce(v_body,''), 120), '^[^a-zA-Z0-9]*', ''));
  if position(',' in v_title) > 0 and v_owner is not null then
    v_title := trim(substring(v_title from position(',' in v_title) + 1));
  end if;
  v_title := left(initcap(left(v_title,1)) || substring(v_title from 2), 120);

  return jsonb_build_object(
    'message_id', _msg, 'conversation_id', v_conv,
    'kind', case when lower(coalesce(v_body,'')) ~ 'i will|main karunga|promise' then 'promise'
                 when lower(coalesce(v_body,'')) ~ 'decided|decision|final' then 'decision'
                 else 'task' end,
    'title', v_title,
    'owner_user_id', coalesce(v_owner, v_sender),
    'owner_name', v_owner_name,
    'due_at', v_due->'due',
    'due_phrase', v_due->>'phrase',
    'source', 'ANEXOChat',
    'deterministic', true);
end $$;


--
-- Name: cleanup_old_memories(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_memories() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  agent_rec RECORD;
  current_count BIGINT;
  delete_count BIGINT;
BEGIN
  FOR agent_rec IN SELECT agent, max_memories FROM agent_memory_config LOOP
    SELECT COUNT(*) INTO current_count 
    FROM ai_memory_vectors 
    WHERE agent = agent_rec.agent;
    IF current_count > agent_rec.max_memories THEN
      delete_count := current_count - agent_rec.max_memories;
      DELETE FROM ai_memory_vectors
      WHERE id IN (
        SELECT id FROM ai_memory_vectors
        WHERE agent = agent_rec.agent
        ORDER BY importance ASC, access_count ASC, created_at ASC
        LIMIT delete_count
      );
    END IF;
  END LOOP;
END;
$$;


--
-- Name: cleanup_password_reset_tokens(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_password_reset_tokens() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  delete from public.account_recovery_tokens
   where expires_at < now() - interval '1 day';
$$;


--
-- Name: close_founder_reply_clock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_founder_reply_clock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  j jsonb := to_jsonb(new);
  v_thread_id uuid;
  v_sent_at timestamptz;
begin
  if coalesce(j->>'direction', '') not in ('out','outbound') then return new; end if;
  begin v_thread_id := nullif(j->>'thread_id','')::uuid; exception when others then v_thread_id := null; end;
  if v_thread_id is null then return new; end if;
  begin v_sent_at := coalesce(nullif(j->>'sent_at','')::timestamptz, now()); exception when others then v_sent_at := now(); end;

  update public.founder_reply_queue
  set state = 'replied', replied_at = v_sent_at
  where thread_id = v_thread_id and state = 'awaiting_reply';
  return new;
exception when others then
  raise warning 'close_founder_reply_clock skipped: %', sqlerrm;
  return new;
end;
$$;


