--
-- Name: commitment_collision_act(uuid, uuid, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commitment_collision_act(_collision uuid, _user uuid, _action text, _reason text, _new_due timestamp with time zone DEFAULT NULL::timestamp with time zone, _new_owner uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare x record; w record; v_res jsonb;
begin
  if not public.chat_feature_ok(_user, 'commitment_collision') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;
  if _action not in ('resolve_dependency','change_deadline','reassign','dismiss','viewed_source') then
    return jsonb_build_object('ok', false, 'error', 'bad_action');
  end if;
  select * into x from public.commitment_collisions where id = _collision;
  if x.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  select * into w from public.chat_work_items where id = x.item_id;
  if not public.chat_in_conversation(w.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;

  if _action = 'viewed_source' then
    insert into public.commitment_collision_events (collision_id, actor_id, action)
    values (_collision, _user, 'viewed_source');
    return jsonb_build_object('ok', true, 'message_id', w.message_id,
      'conversation_id', w.conversation_id);
  end if;

  if _reason is null or length(btrim(_reason)) < 8 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Har amal 8+ character wajah ke saath likha jata hai.');
  end if;

  if _action = 'change_deadline' then
    if _new_due is null then return jsonb_build_object('ok', false, 'error', 'due_required'); end if;
    v_res := public.promise_recover(x.item_id, _user, 'deadline', btrim(_reason), _new_due, null);
    if coalesce((v_res->>'ok')::boolean, false) is not true then return v_res; end if;
  elsif _action = 'reassign' then
    if _new_owner is null then return jsonb_build_object('ok', false, 'error', 'owner_required'); end if;
    v_res := public.promise_recover(x.item_id, _user, 'reassign', btrim(_reason), null, _new_owner);
    if coalesce((v_res->>'ok')::boolean, false) is not true then return v_res; end if;
  elsif _action = 'resolve_dependency' then
    -- rishta khatam karna bhi insaani faisla hai; kaam ki tareekh nahi badalti
    update public.chat_work_items
       set depends_on = null,
           state = case when state = 'blocked' then 'open' else state end
     where id = x.item_id;
  end if;

  update public.commitment_collisions
     set state = case _action when 'dismiss' then 'dismissed' else 'resolved' end,
         closed_at = now(), closed_by = _user, close_reason = btrim(_reason)
   where id = _collision;

  insert into public.commitment_collision_events (collision_id, actor_id, action, reason, detail)
  values (_collision, _user, _action, btrim(_reason),
    jsonb_build_object('new_due', _new_due, 'new_owner', _new_owner, 'result', v_res));

  return jsonb_build_object('ok', true, 'collision_id', _collision, 'action', _action,
    'result', v_res);
end $$;


--
-- Name: commitment_collision_scan(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commitment_collision_scan(_user uuid, _conversation uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid; r record; n int := 0; v_id uuid;
begin
  if not public.chat_feature_ok(_user, 'commitment_collision') then
    return jsonb_build_object('plan', false, 'collisions', '[]'::jsonb);
  end if;
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then
    return jsonb_build_object('plan', true, 'collisions', '[]'::jsonb);
  end if;

  for r in
    select w.id as item_id, w.title as item_title, w.due_at as item_due,
           w.owner_user_id as item_owner, w.conversation_id,
           b.id as blocker_id, b.title as blocker_title, b.due_at as blocker_due,
           b.owner_user_id as blocker_owner, b.state as blocker_state,
           b.kind as blocker_kind, b.original_due_at as blocker_original_due
      from public.chat_work_items w
      join public.chat_work_items b on b.id = w.depends_on
     where w.workspace_id = v_ws
       and w.state in ('open','blocked')
       and b.state in ('open','blocked')
       and (_conversation is null or w.conversation_id = _conversation)
       and public.chat_in_conversation(w.conversation_id, _user)
       and (
         (b.due_at is not null and b.due_at < now())                       -- blocker overdue
         or (w.due_at is not null and b.due_at is not null and b.due_at >= w.due_at)
         or (w.due_at is not null and b.due_at is null)                    -- blocker bina deadline
       )
  loop
    insert into public.commitment_collisions
      (workspace_id, item_id, blocker_id, relation, severity, downstream, evidence)
    values (v_ws, r.item_id, r.blocker_id, 'depends_on',
      case when r.blocker_due is not null and r.blocker_due < now() then 'critical' else 'warning' end,
      r.item_title,
      jsonb_build_object(
        'link', 'human_recorded_dependency',
        'item', jsonb_build_object('id', r.item_id, 'title', r.item_title, 'due_at', r.item_due,
          'owner', (select u.email from auth.users u where u.id = r.item_owner)),
        'blocker', jsonb_build_object('id', r.blocker_id, 'title', r.blocker_title,
          'kind', r.blocker_kind, 'state', r.blocker_state, 'due_at', r.blocker_due,
          'original_due_at', r.blocker_original_due,
          'owner', (select u.email from auth.users u where u.id = r.blocker_owner)),
        'why', case
          when r.blocker_due is not null and r.blocker_due < now()
            then 'The commitment this one depends on is already past its deadline.'
          when r.blocker_due is null
            then 'The commitment this one depends on has no deadline at all.'
          else 'The commitment this one depends on is due at or after this deadline.' end))
    on conflict (item_id, blocker_id, relation) do update
      set severity = excluded.severity,
          evidence = excluded.evidence,
          state = case when commitment_collisions.state = 'dismissed'
                       then 'dismissed' else 'open' end
    returning id into v_id;

    if v_id is not null then
      n := n + 1;
      insert into public.commitment_collision_events (collision_id, actor_id, action, detail)
      select v_id, null, 'detected', jsonb_build_object('scanned_by', _user)
       where not exists (select 1 from public.commitment_collision_events
                          where collision_id = v_id and action = 'detected');
    end if;
  end loop;

  return jsonb_build_object(
    'plan', true,
    'engine_invents_dependencies', false,
    'scanned', n,
    'collisions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', x.id, 'state', x.state, 'severity', x.severity, 'relation', x.relation,
        'downstream', x.downstream, 'evidence', x.evidence, 'detected_at', x.detected_at,
        'item_id', x.item_id, 'blocker_id', x.blocker_id,
        'conversation_id', (select w.conversation_id from public.chat_work_items w where w.id = x.item_id),
        'source_message', (select w.message_id from public.chat_work_items w where w.id = x.blocker_id),
        'log', coalesce((select jsonb_agg(jsonb_build_object('action', e.action, 'reason', e.reason,
                  'at', e.at) order by e.id desc)
                  from public.commitment_collision_events e where e.collision_id = x.id), '[]'::jsonb))
        order by case x.severity when 'critical' then 0 else 1 end, x.detected_at desc)
        from public.commitment_collisions x
        join public.chat_work_items w on w.id = x.item_id
       where x.workspace_id = v_ws
         and x.state <> 'resolved'
         and (_conversation is null or w.conversation_id = _conversation)
         and public.chat_in_conversation(w.conversation_id, _user)), '[]'::jsonb));
end $$;


--
-- Name: consume_password_reset_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_password_reset_token(_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_user_id uuid;
begin
  update public.account_recovery_tokens
     set used_at = now()
   where token_hash = [REDACTED]
     and used_at is null
     and expires_at > now()
   returning user_id into v_user_id;

  if v_user_id is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_or_expired');
  end if;
  return jsonb_build_object('ok', true, 'user_id', v_user_id);
end $$;


--
-- Name: conversation_chain_verify(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conversation_chain_verify(_conversation uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare r record; v_prev text; v_expect text; v_break jsonb := null; n int := 0; v_edited int := 0;
begin
  if not public.chat_in_conversation(_conversation, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'provenance_chain') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;

  for r in
    select p.*, m.body, m.edited_at from public.chat_message_provenance p
      join public.chat_messages m on m.id = p.message_id
     where p.conversation_id = _conversation
     order by p.seq
  loop
    n := n + 1;
    if r.edited_at is not null then v_edited := v_edited + 1; end if;
    v_expect := encode(digest(coalesce(v_prev, '') || r.body_hash || r.seq::text, 'sha256'), 'hex');
    if v_break is null and (v_expect <> r.chain_hash or coalesce(r.prev_hash,'') <> coalesce(v_prev,'')) then
      v_break := jsonb_build_object('message_id', r.message_id, 'seq', r.seq,
        'expected', v_expect, 'sealed', r.chain_hash);
    end if;
    v_prev := r.chain_hash;
  end loop;

  return jsonb_build_object(
    'conversation_id', _conversation,
    'sealed_messages', n,
    'unsealed_messages', (select count(*) from public.chat_messages m
                           where m.conversation_id = _conversation
                             and not exists (select 1 from public.chat_message_provenance p
                                              where p.message_id = m.id)),
    'edited_after_sealing', v_edited,
    'chain_intact', v_break is null,
    'first_break', v_break,
    'head_hash', v_prev);
end $$;


--
-- Name: conversation_health(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conversation_health(_conversation uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare c record; last_msg record; v_open int; v_blocked int; v_overdue int; v_total int;
        v_owner text; v_due timestamptz; v_state text; v_reasons jsonb := '[]'::jsonb;
        v_waiting boolean := false;
begin
  if not public.chat_in_conversation(_conversation, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'conversation_health') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;

  select * into c from public.chat_conversations where id = _conversation;

  select m.* into last_msg from public.chat_messages m
   where m.conversation_id = _conversation and m.deleted_at is null
   order by m.seq desc limit 1;

  select count(*) filter (where w.state in ('open','blocked')),
         count(*) filter (where w.state = 'blocked'),
         count(*) filter (where w.state in ('open','blocked')
                            and w.due_at is not null and w.due_at < now()),
         count(*)
    into v_open, v_blocked, v_overdue, v_total
    from public.chat_work_items w where w.conversation_id = _conversation;

  -- next commitment = sabse pehli khuli deadline
  select (select u.email from auth.users u where u.id = w.owner_user_id), w.due_at
    into v_owner, v_due
    from public.chat_work_items w
   where w.conversation_id = _conversation and w.state in ('open','blocked')
   order by (w.due_at is null), w.due_at
   limit 1;

  -- jawab ka intezar: aakhri message mera tha aur doosre ne padha nahi
  if last_msg.id is not null then
    v_waiting := exists (
      select 1 from public.chat_participants p
       where p.conversation_id = _conversation
         and p.user_id <> last_msg.sender_user_id
         and coalesce(p.last_read_seq, 0) < last_msg.seq);
  end if;

  if v_blocked > 0 or v_overdue > 0 then
    v_state := 'blocked';
  elsif v_open > 0 and v_waiting then
    v_state := 'waiting';
  elsif v_open > 0 then
    v_state := 'healthy';
  elsif v_total > 0 then
    v_state := 'completed';
  elsif v_waiting then
    v_state := 'waiting';
  else
    v_state := 'healthy';
  end if;

  if v_blocked > 0 then
    v_reasons := v_reasons || jsonb_build_array(jsonb_build_object(
      'reason', v_blocked || ' item(s) blocked by a dependency someone recorded',
      'evidence', 'chat_work_items.depends_on'));
  end if;
  if v_overdue > 0 then
    v_reasons := v_reasons || jsonb_build_array(jsonb_build_object(
      'reason', v_overdue || ' commitment(s) past their deadline',
      'evidence', 'chat_work_items.due_at'));
  end if;
  if v_waiting then
    v_reasons := v_reasons || jsonb_build_array(jsonb_build_object(
      'reason', 'The last message has not been read by everyone yet',
      'evidence', 'chat_participants.last_read_seq'));
  end if;
  if v_state = 'completed' then
    v_reasons := v_reasons || jsonb_build_array(jsonb_build_object(
      'reason', 'Every recorded commitment here closed with evidence',
      'evidence', 'chat_work_evidence'));
  end if;

  return jsonb_build_object(
    'conversation_id', _conversation,
    'title', coalesce(c.subject, 'Conversation'),
    'state', v_state,                       -- healthy | waiting | blocked | completed
    'owner', v_owner,
    'due_at', v_due,
    'open_items', v_open,
    'blocked_items', v_blocked,
    'overdue_items', v_overdue,
    'total_items', v_total,
    'last_message_at', last_msg.created_at,
    'reasons', v_reasons,
    'chain', case when public.chat_feature_ok(_user,'provenance_chain')
                  then public.conversation_chain_verify(_conversation, _user)
                  else null end);
end $$;


--
-- Name: conversation_health_board(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conversation_health_board(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null or not public.chat_feature_ok(_user, 'conversation_health') then
    return jsonb_build_object('plan', public.chat_feature_ok(_user,'conversation_health'),
      'timeline', public.chat_feature_ok(_user,'conversation_timeline'),
      'collision', public.chat_feature_ok(_user,'commitment_collision'),
      'conversations', '[]'::jsonb);
  end if;

  return jsonb_build_object(
    'plan', true,
    'timeline', public.chat_feature_ok(_user,'conversation_timeline'),
    'collision', public.chat_feature_ok(_user,'commitment_collision'),
    'conversations', coalesce((
      select jsonb_agg(h order by
               case h->>'state' when 'blocked' then 0 when 'waiting' then 1
                                when 'healthy' then 2 else 3 end,
               h->>'due_at')
        from (
          select public.conversation_health(c.id, _user) as h
            from public.chat_conversations c
           where c.workspace_id = v_ws
             and public.chat_in_conversation(c.id, _user)
           order by c.created_at desc
           limit 100) t), '[]'::jsonb));
end $$;


--
-- Name: conversation_timeline(uuid, uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.conversation_timeline(_conversation uuid, _user uuid, _lens text DEFAULT 'all'::text, _limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_cap int; v_lens text := coalesce(nullif(btrim(coalesce(_lens,'')),''), 'all');
begin
  if not public.chat_in_conversation(_conversation, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'conversation_timeline') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;

  v_cap := least(
    coalesce(_limit, 300),
    coalesce((public.chat_feature_allowed(_user,'conversation_timeline')->>'limit')::int, 300));

  return jsonb_build_object(
    'conversation_id', _conversation,
    'title', (select coalesce(c.subject, 'Conversation') from public.chat_conversations c
               where c.id = _conversation),
    'lens', v_lens,
    'events', coalesce((
      select jsonb_agg(e order by e->>'at')
        from (
          select to_jsonb(x) as e from (

            -- COMMUNICATION: messages (important hamesha; lens='messages' par sab)
            select m.created_at as at, 'communication' as lane, 'message' as kind,
                   case when i.id is not null then 'Important message' else 'Message' end as label,
                   left(regexp_replace(coalesce(m.body,''), '\s+', ' ', 'g'), 200) as detail,
                   (select u.email from auth.users u where u.id = m.sender_user_id) as actor,
                   m.id as object_id, 'message' as object_type,
                   (i.id is not null) as important,
                   jsonb_build_object('seq', m.seq, 'sealed',
                     exists (select 1 from public.chat_message_provenance p where p.message_id = m.id),
                     'transport', m.transport) as evidence
              from public.chat_messages m
              left join public.chat_message_important i
                on i.message_id = m.id and i.removed_at is null
             where m.conversation_id = _conversation
               and m.deleted_at is null
               and (v_lens in ('all','messages')
                    or (v_lens = 'important' and i.id is not null))
               and (v_lens <> 'all' or i.id is not null
                    or exists (select 1 from public.chat_work_items w where w.message_id = m.id)
                    or exists (select 1 from public.chat_decisions d where d.message_id = m.id)
                    or m.seq = (select min(z.seq) from public.chat_messages z
                                 where z.conversation_id = _conversation and z.deleted_at is null)
                    or m.seq = (select max(z.seq) from public.chat_messages z
                                 where z.conversation_id = _conversation and z.deleted_at is null))

            union all

            -- OUTCOME: file received (evidence chain se sabit)
            select ev.at, 'outcome', 'file',
                   case ev.state when 'available' then 'File received and verified'
                                 when 'verified'  then 'File verified'
                                 when 'uploaded'  then 'File received'
                                 when 'blocked'   then 'File blocked by safety'
                                 else 'File ' || ev.state end,
                   f.name, (select u.email from auth.users u where u.id = ev.user_id),
                   f.id, 'file', false,
                   jsonb_build_object('state', ev.state, 'actor', ev.actor,
                                      'version', fv.version, 'bytes', fv.bytes,
                                      'sha256', fv.file_sha256)
              from public.file_evidence ev
              join public.chat_file_versions fv on fv.id = ev.version_id
              join public.chat_files f on f.id = fv.file_id
             where f.conversation_id = _conversation
               and ev.state in ('uploaded','verified','available','blocked')
               and v_lens in ('all','files','outcome')

            union all

            -- OUTCOME: task / promise created
            select w.created_at, 'outcome',
                   w.kind,
                   case w.kind when 'promise' then 'Promise made'
                               when 'task' then 'Task created'
                               else 'Decision recorded' end,
                   w.title, (select u.email from auth.users u where u.id = w.created_by),
                   w.id, w.kind, false,
                   jsonb_build_object('owner', (select u.email from auth.users u where u.id = w.owner_user_id),
                     'due_at', w.due_at, 'state', w.state, 'depends_on', w.depends_on,
                     'from_message', w.message_id, 'body_hash', w.provenance->>'body_hash')
              from public.chat_work_items w
             where w.conversation_id = _conversation
               and (v_lens in ('all','outcome')
                    or (v_lens = 'tasks' and w.kind = 'task')
                    or (v_lens = 'promises' and w.kind = 'promise')
                    or (v_lens = 'decisions' and w.kind = 'decision'))

            union all

            -- OUTCOME: work completed (evidence ke saath — warna band hi nahi hota)
            select w.completed_at, 'outcome', 'completed',
                   case w.kind when 'promise' then 'Promise kept' else 'Completed' end,
                   w.title, (select u.email from auth.users u where u.id = w.completed_by),
                   w.id, w.kind, false,
                   jsonb_build_object('evidence_count',
                     (select count(*) from public.chat_work_evidence e where e.item_id = w.id),
                     'due_at', w.due_at, 'original_due_at', w.original_due_at)
              from public.chat_work_items w
             where w.conversation_id = _conversation
               and w.state = 'done' and w.completed_at is not null
               and v_lens in ('all','outcome','tasks','promises')

            union all

            -- OUTCOME: decision recorded / changed (versions se, kabhi overwrite nahi)
            select v.at, 'outcome', 'decision',
                   case v.change when 'recorded' then 'Decision recorded'
                                 when 'amended' then 'Decision changed (new version)'
                                 when 'superseded' then 'Decision replaced'
                                 else 'Decision reversed' end,
                   v.title, (select u.email from auth.users u where u.id = v.changed_by),
                   d.id, 'decision', false,
                   jsonb_build_object('version', v.version, 'reason', v.reason,
                     'decided_at', v.decided_at, 'body_hash', d.body_hash,
                     'from_message', d.message_id)
              from public.chat_decision_versions v
              join public.chat_decisions d on d.id = v.decision_id
             where d.conversation_id = _conversation
               and v_lens in ('all','outcome','decisions')

          ) x
          order by (x.at) asc
          limit v_cap
        ) y), '[]'::jsonb),
    'lanes', jsonb_build_object(
      'communication', 'What was said',
      'outcome', 'What actually resulted'),
    'engine_invents_nothing', true);
end $$;


--
-- Name: crm_capture_suggestions(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_capture_suggestions(_org_id uuid, _own_addrs text[]) RETURNS TABLE(email text, message_count integer, first_mail_at timestamp with time zone, last_mail_at timestamp with time zone, confidence numeric, suggested_company text, source text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with recent as (
    select from_address, sent_at, subject, body_text
    from public.mail_messages
    where org_id = _org_id
      and direction = 'in'
      and sent_at >= now() - interval '30 days'
  ),
  cleaned as (
    select lower(from_address) as addr, sent_at, subject, body_text
    from recent
    where from_address is not null and from_address like '%@%'
  ),
  filtered as (
    select * from cleaned
    where addr <> all(coalesce(_own_addrs, array[]::text[]))
      and addr !~ '^(no-?reply|noreply|mailer-daemon|postmaster|notifications?|bounce|newsletter|do-?not-?reply|support|billing|marketing|info|admin)@'
  ),
  agg as (
    select
      addr as email,
      count(*)::int as message_count,
      min(sent_at) as first_mail_at,
      max(sent_at) as last_mail_at,
      bool_or(
        coalesce(subject, '') ~* '(pricing|quote|proposal|demo|interested|budget|purchase|contract|meeting|call|partner|collaborat)'
        or coalesce(body_text, '') ~* '(pricing|quote|proposal|demo|interested|budget|purchase|contract)'
      ) as has_intent_signal,
      split_part(addr, '@', 2) as domain
    from filtered
    group by addr
  ),
  scored as (
    select
      a.*,
      least(
        1.0,
        0.25
        + least(a.message_count, 5) * 0.1
        + case when a.has_intent_signal then 0.35 else 0 end
      )::numeric(3,2) as confidence
    from agg a
  )
  select
    s.email,
    s.message_count,
    s.first_mail_at,
    s.last_mail_at,
    s.confidence,
    initcap(split_part(s.domain, '.', 1)) as suggested_company,
    'inbound_email'::text as source
  from scored s
  where not exists (
    select 1 from public.crm_leads l
    where l.org_id = _org_id and lower(l.email) = s.email
  )
  and not exists (
    select 1 from public.crm_lead_dismissals d
    where d.org_id = _org_id and lower(d.email) = s.email
  )
  and not exists (
    select 1 from public.crm_leads l2
    where l2.org_id = _org_id and split_part(lower(l2.email), '@', 2) = s.domain
  )
  order by s.confidence desc, s.message_count desc
  limit 30;
$$;


--
-- Name: crm_evidence_no_mutate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_evidence_no_mutate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'crm_evidence is append-only';
end;
$$;


--
-- Name: crm_extract_signature(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_extract_signature(_org_id uuid, _contact_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  primary_addr text;
  latest_body text;
  found_phone text;
  found_title text;
begin
  select lower(primary_address) into primary_addr
  from public.contacts where id = _contact_id and org_id = _org_id;

  if primary_addr is null then
    return jsonb_build_object('ok', false, 'reason', 'contact_not_found');
  end if;

  select body_text into latest_body
  from public.mail_messages
  where org_id = _org_id and lower(from_address) = primary_addr and direction = 'in'
  order by sent_at desc
  limit 1;

  if latest_body is null then
    return jsonb_build_object('ok', false, 'reason', 'no_mail');
  end if;

  found_phone := (regexp_match(right(latest_body, 400), '(\+?\d[\d\s\-\(\)]{7,}\d)'))[1];
  found_title := (regexp_match(right(latest_body, 400), '([A-Z][a-zA-Z& ]{2,40}\s(?:at|@)\s[A-Z][a-zA-Z0-9& ]{2,40})'))[1];

  update public.contacts
  set phone = coalesce(phone, trim(found_phone)),
      title = coalesce(title, found_title),
      updated_at = now()
  where id = _contact_id;

  return jsonb_build_object('ok', true, 'phone', found_phone, 'title', found_title);
end;
$$;


--
-- Name: crm_followups(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_followups(_org_id uuid, _days integer) RETURNS TABLE(thread_id uuid, subject text, mailbox_address text, last_message_at timestamp with time zone, days_waiting integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select t.id, t.subject, t.mailbox_address, m.sent_at,
    floor(extract(epoch from (now() - m.sent_at)) / 86400)::int as days_waiting
  from public.mail_threads t
  join lateral (
    select direction, sent_at
    from public.mail_messages
    where thread_id = t.id
    order by sent_at desc
    limit 1
  ) m on true
  where t.org_id = _org_id
    and t.folder not in ('trash', 'spam', 'archive')
    and t.status <> 'done'
    and m.direction = 'out'
    and m.sent_at < now() - (_days || ' days')::interval
  order by m.sent_at asc
  limit 200;
$$;


--
-- Name: crm_graph(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_graph(_org_id uuid, _limit integer DEFAULT 60) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  with free(d) as (values ('gmail.com'),('googlemail.com'),('yahoo.com'),('outlook.com'),
                          ('hotmail.com'),('live.com'),('icloud.com'),('proton.me'),
                          ('protonmail.com'),('aol.com')),
  ppl as (
    select c.id, lower(c.primary_address) as email, c.display_name as name,
           lower(coalesce(nullif(c.company_domain, ''), split_part(c.primary_address, '@', 2))) as dom
      from public.contacts c
     where c.org_id = _org_id
  ),
  ppl2 as (
    select p.*,
           case when p.dom = '' or p.dom in (select d from free) then null else p.dom end as grp
      from ppl p
  ),
  dls as (
    select d.id, d.title, d.stage::text as stage, d.value, d.currency,
           lower(d.contact_email) as contact_email,
           coalesce(p.grp, nullif(lower(d.company), '')) as grp
      from public.crm_deals d
      left join ppl2 p on p.email = lower(d.contact_email)
     where d.org_id = _org_id
  ),
  groups as (
    select grp from ppl2 where grp is not null
    union
    select grp from dls where grp is not null
  )
  select jsonb_build_object(
    'companies', coalesce((
      select jsonb_agg(x.g order by x.company)
        from (
          select gr.grp as company,
                 jsonb_build_object(
                   'company', gr.grp,
                   'people', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'email', p.email, 'name', p.name) order by p.email)
                                         from ppl2 p where p.grp = gr.grp), '[]'::jsonb),
                   'deals', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'title', d.title, 'stage', d.stage,
                                                                          'value', d.value, 'currency', d.currency,
                                                                          'contact_email', d.contact_email) order by d.title)
                                        from dls d where d.grp = gr.grp), '[]'::jsonb)
                 ) as g
            from (select grp from groups order by grp
                   limit least(greatest(coalesce(_limit, 60), 1), 200)) gr
        ) x
    ), '[]'::jsonb),
    'individuals', coalesce((select jsonb_agg(jsonb_build_object('id', p.id, 'email', p.email, 'name', p.name) order by p.email)
                               from ppl2 p where p.grp is null), '[]'::jsonb),
    'loose_deals', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'title', d.title, 'stage', d.stage,
                                                                 'value', d.value, 'currency', d.currency,
                                                                 'contact_email', d.contact_email) order by d.title)
                               from dls d where d.grp is null), '[]'::jsonb)
  )
$$;


--
-- Name: crm_health(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_health(_org_id uuid, _limit integer DEFAULT 100) RETURNS TABLE(contact_id uuid, email text, name text, company text, last_contact_at timestamp with time zone, days_since integer, relationship text, last_direction text, waiting_on_me boolean, messages_in integer, messages_out integer, rank_group integer)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  with people as (
    select c.id, lower(c.primary_address) as email, c.display_name, c.company_domain,
           array_append(
             array(select lower(a) from unnest(coalesce(c.addresses, '{}'::text[])) a),
             lower(c.primary_address)) as addrs
      from public.contacts c
     where c.org_id = _org_id
  ),
  msgs as (
    select p.id as pid, m.sent_at, m.direction::text as dir
      from people p
      join public.mail_messages m
        on m.org_id = _org_id
       and m.sent_at is not null
       and (lower(m.from_address) = any(p.addrs)
            or exists (select 1 from unnest(m.to_addrs) t where lower(t) = any(p.addrs)))
  ),
  agg as (
    select pid,
           max(sent_at) as last_at,
           (array_agg(dir order by sent_at desc))[1] as last_dir,
           (count(*) filter (where dir = 'in'))::int as mi,
           (count(*) filter (where dir = 'out'))::int as mo
      from msgs
     group by pid
  ),
  scored as (
    select p.id, p.email, p.display_name, p.company_domain, a.last_at, a.last_dir, a.mi, a.mo,
           floor(extract(epoch from (now() - a.last_at)) / 86400)::int as days,
           case
             when extract(epoch from (now() - a.last_at)) / 86400 <= 14 then 'active'
             when extract(epoch from (now() - a.last_at)) / 86400 <= 45 then 'cooling'
             else 'cold'
           end as rel
      from people p
      join agg a on a.pid = p.id
  )
  select q.* from (
    select s.id as contact_id, s.email, s.display_name as name, s.company_domain as company,
           s.last_at as last_contact_at, s.days as days_since, s.rel as relationship,
           s.last_dir as last_direction, (s.last_dir = 'in') as waiting_on_me,
           s.mi as messages_in, s.mo as messages_out,
           case when s.last_dir = 'in' then 1
                when s.rel = 'cooling' then 2
                when s.rel = 'cold' then 3
                else 4 end as rank_group
      from scored s
  ) q
  order by q.rank_group, q.days_since desc
  limit least(greatest(coalesce(_limit, 100), 1), 300)
$$;


--
-- Name: crm_is_promise(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_is_promise(frag text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select (
    frag ~* '\m(i[''’]?ll|i will|we[''’]?ll|we will|let me)\M'
    and frag ~* '\m(send|share|get back|revert|call|reply|confirm|deliver|finish|complete|update|follow up|check)\M'
    and frag !~* '\m(not|never|won[''’]t)\M'
  )
  or frag ~* '\m(bhej|kar|de) (dunga|dungi|denge|karunga|karungi|karenge)\M'
$$;


--
-- Name: crm_next(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_next(_org_id uuid, _limit integer DEFAULT 20) RETURNS TABLE(source text, title text, reason text, person_email text, at timestamp with time zone, href text, priority integer)
    LANGUAGE sql STABLE
    AS $$
  with rk as (select * from public.crm_risk(_org_id, 100)),
  pr as (
    select * from public.crm_promises_board(_org_id, null, 300)
     where phase in ('suggested', 'pending')
       and due_at is not null
       and due_at <= now() + interval '7 days'
  ),
  hl as (
    select * from public.crm_health(_org_id, 300)
     where relationship = 'cooling' and not waiting_on_me
  ),
  items as (
    select 'risk'::text as source, r.title, r.reason, r.person_email, r.at, r.href,
           r.severity as priority
      from rk r
    union all
    select 'promises', p.title,
           'Due ' || to_char(p.due_at, 'YYYY-MM-DD'),
           case when p.side = 'mine' then lower(p.promised_to) else lower(p.promised_by) end,
           p.due_at, '/app/crm/promises', 4
      from pr p
    union all
    select 'health', coalesce(h.name, h.email),
           'You wrote last ' || h.days_since::text || ' days ago, time to follow up',
           h.email, h.last_contact_at, '/app/crm/health', 5
      from hl h
  ),
  dedup as (
    select i.*,
           row_number() over (partition by coalesce(i.person_email, i.title) order by i.priority) as rn
      from items i
  )
  select d.source, d.title, d.reason, d.person_email, d.at, d.href, d.priority
    from dedup d
   where d.rn = 1
   order by d.priority, d.at asc nulls last
   limit least(greatest(coalesce(_limit, 20), 1), 100)
$$;


--
-- Name: crm_person_timeline(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_person_timeline(_org_id uuid, _contact_id uuid) RETURNS TABLE(at timestamp with time zone, kind text, title text, href text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  primary_addr text;
  extra_addrs text[];
  all_addrs text[];
begin
  select lower(c.primary_address), array(select lower(a) from unnest(coalesce(c.addresses, '{}')) a)
  into primary_addr, extra_addrs
  from public.contacts c
  where c.id = _contact_id and c.org_id = _org_id;

  if primary_addr is null then
    return;
  end if;

  all_addrs := array_append(extra_addrs, primary_addr);

  return query
  select m.sent_at as at,
         case when m.direction = 'out' then 'email_out' else 'email_in' end as kind,
         coalesce(m.subject, '(no subject)') as title,
         case when m.thread_id is not null then '/app/mail/inbox/' || m.thread_id::text else '/app/mail/inbox' end as href
  from public.mail_messages m
  where m.org_id = _org_id and lower(m.from_address) = any(all_addrs)
  union all
  select e.starts_at as at, 'meeting'::text as kind, e.title as title, '/app/calendar'::text as href
  from public.calendar_events e
  where e.org_id = _org_id and lower(coalesce(e.organiser, '')) = any(all_addrs)
  union all
  select t.created_at as at, 'task'::text as kind, t.title as title, '/app/work'::text as href
  from public.work_tasks t
  where t.org_id = _org_id and lower(coalesce(t.owner, '')) = any(all_addrs)
  union all
  select d.created_at as at, 'deal'::text as kind, d.title as title, '/app/crm/pipeline'::text as href
  from public.crm_deals d
  where d.org_id = _org_id and lower(coalesce(d.contact_email, '')) = any(all_addrs)
  order by at desc
  limit 60;
end;
$$;


--
-- Name: crm_promise_candidates(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_promise_candidates(_org_id uuid, _days integer DEFAULT 30) RETURNS TABLE(message_id uuid, thread_id uuid, promised_by text, promised_to text, quote text, due_at timestamp with time zone, detected_at timestamp with time zone, direction text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select distinct on (x.id)
         x.id, x.thread_id, x.from_address, x.first_to, x.frag,
         public.crm_promise_due(x.frag, x.sent_at), x.sent_at, x.dir
    from (
      select m.id, m.thread_id, m.from_address, lower(m.to_addrs[1]) as first_to,
             m.sent_at, m.direction::text as dir, btrim(f.frag) as frag, f.n
        from public.mail_messages m
       cross join lateral regexp_split_to_table(coalesce(m.body_text, ''), E'(?<=[.!?])\\s+|\\n+')
             with ordinality as f(frag, n)
       where m.org_id = _org_id
         and m.sent_at >= now() - make_interval(days => least(greatest(coalesce(_days, 30), 1), 365))
         and not exists (select 1 from public.work_promises w
                          where w.org_id = _org_id and w.message_id = m.id)
    ) x
   where length(x.frag) between 12 and 240
     and x.frag !~ '^\s*>'
     and public.crm_is_promise(x.frag)
   order by x.id, x.n
$$;


--
-- Name: crm_promise_due(text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_promise_due(frag text, sent timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select ((case
    when frag ~* '\m(today|tonight|eod|end of day|aaj)\M' then (sent at time zone 'UTC')::date
    when frag ~* '\m(tomorrow|kal)\M' then (sent at time zone 'UTC')::date + 1
    when frag ~* '\mnext week\M' then (sent at time zone 'UTC')::date + 7
    else (
      select (sent at time zone 'UTC')::date
             + ((d.dow - extract(dow from (sent at time zone 'UTC'))::int + 6) % 7 + 1)
        from (values ('sunday',0),('monday',1),('tuesday',2),('wednesday',3),
                     ('thursday',4),('friday',5),('saturday',6)) d(name, dow)
       where frag ~* ('\m' || d.name || '\M')
       limit 1)
  end)::timestamp + interval '17 hours') at time zone 'UTC'
$$;


--
-- Name: crm_promises_board(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_promises_board(_org_id uuid, _side text DEFAULT NULL::text, _limit integer DEFAULT 100) RETURNS TABLE(id uuid, quote text, title text, due_at timestamp with time zone, thread_id uuid, promised_by text, promised_to text, side text, phase text, task_id uuid, completed_at timestamp with time zone, detected_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select * from (
    select p.id, p.quote, p.suggested_title as title,
           coalesce(t.due_at, p.suggested_due_at) as due_at,
           p.thread_id, p.promised_by, p.promised_to,
           case when m.direction::text = 'in' then 'theirs' else 'mine' end as side,
           case
             when coalesce(p.status, case p.state when 'committed' then 'committed'
                                                   when 'dismissed' then 'dismissed'
                                                   else 'suggested' end) = 'suggested' then 'suggested'
             when t.completed_at is not null then
               case when coalesce(t.due_at, p.suggested_due_at) is null
                         or t.completed_at <= coalesce(t.due_at, p.suggested_due_at)
                    then 'kept' else 'late' end
             when coalesce(t.due_at, p.suggested_due_at) is not null
                  and coalesce(t.due_at, p.suggested_due_at) < now() then 'broken'
             else 'pending'
           end as phase,
           p.task_id, t.completed_at, p.detected_at
      from public.work_promises p
      left join public.work_tasks t on t.id = p.task_id
      left join public.mail_messages m on m.id = p.message_id
     where p.org_id = _org_id
       and coalesce(p.status, case p.state when 'committed' then 'committed'
                                           when 'dismissed' then 'dismissed'
                                           else 'suggested' end) <> 'dismissed'
  ) q
  where _side is null or q.side = _side
  order by q.due_at asc nulls last, q.detected_at desc
  limit least(greatest(coalesce(_limit, 100), 1), 300)
$$;


--
-- Name: crm_promises_open(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_promises_open(_org_id uuid) RETURNS TABLE(id uuid, quote text, suggested_title text, suggested_due_at timestamp with time zone, status text, thread_id uuid)
    LANGUAGE sql STABLE
    AS $$
  select b.id, b.quote, b.title, b.due_at, b.phase, b.thread_id
    from public.crm_promises_board(_org_id, null, 200) b
   where b.phase in ('suggested', 'pending', 'broken')
$$;


--
-- Name: crm_promises_scan(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_promises_scan(_org_id uuid, _days integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare n integer;
begin
  insert into public.work_promises
    (org_id, quote, suggested_title, suggested_due_at, thread_id, message_id,
     promised_by, promised_to, confidence, state, status, detected_at)
  select _org_id, c.quote, left(c.quote, 120), c.due_at, c.thread_id, c.message_id,
         c.promised_by, c.promised_to, 0.6, 'open', 'suggested', c.detected_at
    from public.crm_promise_candidates(_org_id, _days) c;
  get diagnostics n = row_count;
  return n;
end;
$$;


--
-- Name: crm_risk(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_risk(_org_id uuid, _limit integer DEFAULT 50) RETURNS TABLE(kind text, title text, reason text, person_email text, at timestamp with time zone, severity integer, href text)
    LANGUAGE sql STABLE
    AS $$
  with h as (select * from public.crm_health(_org_id, 300)),
  deals as (
    select d.title, d.value, d.currency, lower(d.contact_email) as em,
           h.days_since, h.last_contact_at
      from public.crm_deals d
      join h on h.email = lower(d.contact_email)
     where d.org_id = _org_id
       and d.stage::text not in ('won', 'lost')
       and h.relationship = 'cold'
  ),
  broken as (
    select * from public.crm_promises_board(_org_id, null, 300) where phase = 'broken'
  )
  select r.kind, r.title, r.reason, r.person_email, r.at, r.severity, r.href
    from (
      select 'deal_cold'::text as kind, d.title as title,
             'Open deal worth ' || d.value::text || ' ' || d.currency
               || ' - no contact for ' || d.days_since::text || ' days' as reason,
             d.em as person_email, d.last_contact_at as at, 1 as severity,
             '/app/crm/pipeline'::text as href, d.value as sortkey
        from deals d
      union all
      select 'promise_overdue', b.title,
             'Promise overdue since ' || to_char(b.due_at, 'YYYY-MM-DD'),
             case when b.side = 'mine' then lower(b.promised_to) else lower(b.promised_by) end,
             b.due_at, 2, '/app/crm/promises', 0::numeric
        from broken b
      union all
      select 'reply_waiting', coalesce(x.name, x.email),
             'They wrote ' || x.days_since::text || ' days ago and you have not replied',
             x.email, x.last_contact_at, 3, '/app/crm/health', x.days_since::numeric
        from h x
       where x.waiting_on_me and x.days_since >= 3
    ) r
   order by r.severity, r.sortkey desc nulls last, r.at asc
   limit least(greatest(coalesce(_limit, 50), 1), 200)
$$;


--
-- Name: crm_team_graph(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_team_graph(_org_id uuid, _limit integer DEFAULT 100) RETURNS TABLE(member_email text, member_role text, mailbox text, person_email text, messages integer, last_at timestamp with time zone, teammates_on_person integer)
    LANGUAGE sql STABLE
    AS $$
  with mb as (
    select lower(a.address) as addr, a.owner_id
      from public.mail_accounts a
     where a.org_id = _org_id
  ),
  ex as (
    select mb.addr as mailbox, mb.owner_id, lower(t) as person, m.sent_at
      from mb
      join public.mail_messages m
        on m.org_id = _org_id and m.direction::text = 'out' and lower(m.from_address) = mb.addr
      cross join lateral unnest(coalesce(m.to_addrs, m.to_addresses)::text[]) as t
    union all
    select mb.addr, mb.owner_id, lower(m.from_address), m.sent_at
      from mb
      join public.mail_messages m
        on m.org_id = _org_id and m.direction::text = 'in'
       and exists (select 1 from unnest(coalesce(m.to_addrs, m.to_addresses)::text[]) as x
                    where lower(x) = mb.addr)
  ),
  ext as (
    select * from ex
     where person is not null and person <> ''
       and person not in (select addr from mb)
  ),
  agg as (
    select e.mailbox, e.owner_id, e.person,
           count(*)::integer as messages, max(e.sent_at) as last_at
      from ext e
     group by e.mailbox, e.owner_id, e.person
  )
  select coalesce(om.email, a.mailbox) as member_email,
         coalesce(om.role::text, 'member') as member_role,
         a.mailbox, a.person as person_email, a.messages, a.last_at,
         (count(*) over (partition by a.person))::integer as teammates_on_person
    from agg a
    left join public.org_members om on om.org_id = _org_id and om.user_id = a.owner_id
   order by a.messages desc, a.last_at desc nulls last
   limit least(greatest(coalesce(_limit, 100), 1), 500)
$$;


--
-- Name: crm_timeline(uuid, uuid, text[], timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_timeline(_org_id uuid, _contact_id uuid DEFAULT NULL::uuid, _kinds text[] DEFAULT NULL::text[], _before timestamp with time zone DEFAULT NULL::timestamp with time zone, _limit integer DEFAULT 50) RETURNS TABLE(at timestamp with time zone, kind text, title text, person_email text, person_name text, href text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  addrs text[];
  lim integer := least(greatest(coalesce(_limit, 50), 1), 200);
begin
  if _contact_id is not null then
    select array_append(
             array(select lower(a) from unnest(coalesce(c.addresses, '{}'::text[])) a),
             lower(c.primary_address))
      into addrs
      from public.contacts c
     where c.id = _contact_id and c.org_id = _org_id;
    if addrs is null then
      return;
    end if;
  end if;

  return query
  with feed as (
    select m.sent_at as at,
           case when m.direction::text = 'out' then 'email_out' else 'email_in' end as kind,
           coalesce(m.subject, '(no subject)') as title,
           case when m.direction::text = 'out' then lower(m.to_addrs[1]) else lower(m.from_address) end as person_email,
           '/app/mail/inbox/' || m.thread_id::text as href
      from public.mail_messages m
     where m.org_id = _org_id
       and m.sent_at is not null
       and (addrs is null
            or lower(m.from_address) = any(addrs)
            or exists (select 1 from unnest(m.to_addrs) t where lower(t) = any(addrs)))
    union all
    select e.starts_at, 'meeting', e.title, lower(e.organiser), '/app/calendar'
      from public.calendar_events e
     where e.org_id = _org_id
       and (addrs is null
            or lower(coalesce(e.organiser, '')) = any(addrs)
            or exists (select 1 from public.calendar_attendees a
                        where a.event_id = e.id and lower(a.address) = any(addrs)))
    union all
    select coalesce(t.created_at, t.due_at), 'task', t.title, lower(t.owner), '/app/work'
      from public.work_tasks t
     where t.org_id = _org_id
       and (addrs is null or lower(coalesce(t.owner, '')) = any(addrs))
    union all
    select d.created_at, 'deal', d.title, lower(d.contact_email), '/app/crm/pipeline'
      from public.crm_deals d
     where d.org_id = _org_id
       and (addrs is null or lower(coalesce(d.contact_email, '')) = any(addrs))
    union all
    select p.detected_at, 'promise', p.suggested_title,
           lower(coalesce(p.promised_to, p.promised_by)), '/app/work'
      from public.work_promises p
     where p.org_id = _org_id
       and (addrs is null
            or lower(coalesce(p.promised_to, '')) = any(addrs)
            or lower(coalesce(p.promised_by, '')) = any(addrs))
  )
  select f.at, f.kind, f.title, f.person_email, c.display_name, f.href
    from feed f
    left join public.contacts c
           on c.org_id = _org_id and lower(c.primary_address) = f.person_email
   where f.at is not null
     and (_kinds is null or f.kind = any(_kinds))
     and (_before is null or f.at < _before)
   order by f.at desc
   limit lim;
end;
$$;


--
-- Name: dashboard_analytics(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_analytics(_org uuid, _days integer DEFAULT 14) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _d        integer := least(greatest(coalesce(_days, 14), 1), 90);
  _today    timestamptz := date_trunc('day', now() at time zone 'utc') at time zone 'utc';
  _from     timestamptz;
  _series   jsonb;
  _recv     bigint := 0;
  _sent     bigint := 0;
  _ok       bigint := 0;
  _fail     bigint := 0;
  _reply    numeric;
begin
  if _org is null then
    raise exception 'org_required';
  end if;
  _from := _today - make_interval(days => _d - 1);

  with days as (
    select ((_from at time zone 'utc')::date + g) as d
      from generate_series(0, _d - 1) g
  ), m as (
    select (created_at at time zone 'utc')::date as d,
           count(*) filter (where direction = 'in')  as r,
           count(*) filter (where direction = 'out') as s
      from public.mail_messages
     where org_id = _org and created_at >= _from
     group by 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'date', to_char(days.d, 'YYYY-MM-DD'),
           'received', coalesce(m.r, 0),
           'sent', coalesce(m.s, 0)
         ) order by days.d), '[]'::jsonb),
         coalesce(sum(m.r), 0),
         coalesce(sum(m.s), 0)
    into _series, _recv, _sent
    from days left join m using (d);

  -- Delivered: sirf asli send-queue ke natije (mail_scheduled sent / failed).
  -- Koi row nahi -> NULL (UI "—" dikhata hai, jhoota 100% nahi).
  if to_regclass('public.mail_scheduled') is not null then
    select count(*) filter (where status = 'sent'),
           count(*) filter (where status = 'failed')
      into _ok, _fail
      from public.mail_scheduled
     where org_id = _org and send_at >= _from;
  end if;

  -- Pehla jawab: thread ki pehli aane wali mail -> uske baad pehli bheji hui mail.
  select avg(extract(epoch from (o.t - i.t)))
    into _reply
    from (
      select thread_id, min(created_at) as t
        from public.mail_messages
       where org_id = _org and direction = 'in' and created_at >= _from
       group by thread_id
    ) i
    join lateral (
      select min(m2.created_at) as t
        from public.mail_messages m2
       where m2.thread_id = i.thread_id
         and m2.direction = 'out'
         and m2.created_at > i.t
    ) o on o.t is not null;

  return jsonb_build_object(
    'range_days', _d,
    'received', _recv,
    'sent', _sent,
    'avg_first_reply_seconds', case when _reply is null then null else round(_reply)::bigint end,
    'delivery_rate', case when (_ok + _fail) = 0 then null else round(_ok::numeric / (_ok + _fail), 4) end,
    'series', _series
  );
end
$$;


--
-- Name: dashboard_summary(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dashboard_summary(_org uuid, _user uuid, _email text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _plan      text;
  _splan     text;
  _sp        record;
  _unread    bigint := 0;
  _waiting   bigint := 0;
  _assigned  bigint := 0;
  _sent_today bigint := 0;
  _today     timestamptz := date_trunc('day', now() at time zone 'utc') at time zone 'utc';
  _msg_bytes bigint := 0;
  _att_bytes bigint := 0;
  _limit     bigint;
  _model     text;
  _org_domain text;
  _dr_domain text;
  _dr_status text;
  _custom    boolean := false;
  _dom_name  text;
  _dom_status text := 'none';
begin
  if _org is null then
    raise exception 'org_required';
  end if;

  -- Plan resolver Rust jaisa hi (named args _user_id/_email); literal se call taake arg types par na atke.
  execute format('select public.resolve_plan(_user_id => %L, _email => %L)', _user, _email) into _plan;
  _plan := coalesce(nullif(_plan, ''), 'basic');

  -- ---- KPI: folder badges ke wahi numbers (mail.counts se mel khate hain) ----
  select count(*) filter (where folder = 'inbox' and unread is true),
         count(*) filter (where folder = 'waiting'),
         count(*) filter (
           where assignee is not null
             and coalesce(folder, 'inbox') not in ('trash', 'spam', 'archive')
             and assignee = _user   -- live: mail_threads.assignee uuid hai (user id)
         )
    into _unread, _waiting, _assigned
    from public.mail_threads
   where org_id = _org;

  select count(*) into _sent_today
    from public.mail_messages
   where org_id = _org and direction = 'out' and created_at >= _today;

  -- ---- storage: plan table se limit, message content se used ----
  _splan := case when _plan like 'ai\_%' then 'business_pro' else _plan end;
  select * into _sp from public.storage_plans where plan_id = _splan;
  if _sp.plan_id is null then
    select * into _sp from public.storage_plans where plan_id = 'trial';
  end if;

  select coalesce(sum(
           octet_length(coalesce(subject, '')) +
           octet_length(coalesce(body_text, '')) +
           octet_length(coalesce(body_html, ''))
         ), 0)
    into _msg_bytes
    from public.mail_messages
   where org_id = _org;

  begin
    select coalesce(sum(a.size_bytes), 0)
      into _att_bytes
      from public.mail_attachments a
      join public.mail_messages m on m.id = a.message_id
     where m.org_id = _org;
  exception when others then
    _att_bytes := 0;
  end;

  if _sp.pooled_bytes is not null then
    _model := 'pooled';
    _limit := _sp.pooled_bytes;
  else
    _model := 'per_mailbox';
    _limit := coalesce(_sp.per_mailbox_bytes, 0) * coalesce(_sp.mailbox_limit, 1);
  end if;

  -- ---- domain: org_domains (E15) + organisations.domain ----
  select domain into _org_domain from public.organisations where id = _org;
  if to_regclass('public.org_domains') is not null then
    select domain, status
      into _dr_domain, _dr_status
      from public.org_domains
     where org_id = _org and status <> 'removed'
     order by (status = 'verified') desc, created_at
     limit 1;
  end if;

  if _dr_domain is not null then
    _custom := true;
    _dom_name := _dr_domain;
    _dom_status := case when _dr_status = 'verified' then 'verified' else 'pending' end;
  elsif _org_domain is not null and lower(_org_domain) <> 'anexomail.com'
        and lower(_org_domain) not like '%.anexomail.com' then
    _custom := true;
    _dom_name := _org_domain;
    _dom_status := 'pending';
  end if;

  return jsonb_build_object(
    'plan', _plan,
    'unread', _unread,
    'assigned_to_me', _assigned,
    'waiting', _waiting,
    'sent_today', _sent_today,
    'done_today', _sent_today,            -- purana naam, wahi qeemat (purane client ke liye)
    'storage_used_bytes', _msg_bytes + _att_bytes,
    'storage_limit_bytes', _limit,
    'storage_model', _model,
    'storage_per_mailbox_bytes', _sp.per_mailbox_bytes,
    'storage_mailbox_limit', _sp.mailbox_limit,
    'domain', _dom_name,
    'domain_status', _dom_status,
    'domain_verified', (_dom_status = 'verified'),
    'domain_hosted', (not _custom)
  );
end
$$;


--
-- Name: decision_amend(uuid, uuid, text, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_amend(_decision uuid, _user uuid, _reason text, _change text DEFAULT 'amended'::text, _title text DEFAULT NULL::text, _detail text DEFAULT NULL::text, _decided_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _superseded_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare d record; v_new int; v_title text; v_detail text; v_when timestamptz; v_state text;
begin
  if not public.chat_feature_ok(_user, 'decision_ledger') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;
  if _change not in ('amended','superseded','reversed') then
    return jsonb_build_object('ok', false, 'error', 'bad_change');
  end if;
  if _reason is null or length(btrim(_reason)) < 12 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Har tabdeeli 12+ character wajah ke saath likhi jati hai.');
  end if;

  select * into d from public.chat_decisions where id = _decision;
  if d.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public.chat_in_conversation(d.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;

  v_title  := coalesce(nullif(btrim(coalesce(_title, '')), ''), d.title);
  v_detail := coalesce(nullif(btrim(coalesce(_detail, '')), ''), d.detail);
  v_when   := coalesce(_decided_at, d.decided_at);
  v_state  := case _change when 'amended' then 'active'
                           when 'superseded' then 'superseded'
                           else 'reversed' end;
  v_new    := d.version + 1;

  -- history: NAYA row (purana version kabhi overwrite nahi hota)
  insert into public.chat_decision_versions
    (decision_id, version, title, detail, decided_at, state, changed_by, change, reason)
  values (_decision, v_new, v_title, v_detail, v_when, v_state, _user, _change, btrim(_reason));

  update public.chat_decisions
     set title = v_title, detail = v_detail, decided_at = v_when,
         state = v_state, version = v_new,
         superseded_by = coalesce(_superseded_by, superseded_by),
         updated_at = now()
   where id = _decision;

  insert into public.chat_decision_impact_log (decision_id, actor_id, event, reason, prev, next)
  values (_decision, _user, _change, btrim(_reason),
    jsonb_build_object('version', d.version, 'title', d.title, 'detail', d.detail,
                       'decided_at', d.decided_at, 'state', d.state),
    jsonb_build_object('version', v_new, 'title', v_title, 'detail', v_detail,
                       'decided_at', v_when, 'state', v_state));

  return jsonb_build_object('ok', true, 'decision_id', _decision, 'version', v_new,
    'state', v_state, 'previous_version', d.version);
end $$;


--
-- Name: decision_board(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_board(_user uuid, _conversation uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then
    return jsonb_build_object('plan', public.chat_feature_ok(_user,'decision_ledger'),
      'impact', public.chat_feature_ok(_user,'decision_impact'),
      'decisions', '[]'::jsonb, 'summary', '{}'::jsonb);
  end if;

  return jsonb_build_object(
    'plan',   public.chat_feature_ok(_user, 'decision_ledger'),
    'impact', public.chat_feature_ok(_user, 'decision_impact'),
    'summary', (
      select jsonb_build_object(
        'total',      count(*),
        'active',     count(*) filter (where d.state = 'active'),
        'superseded', count(*) filter (where d.state = 'superseded'),
        'reversed',   count(*) filter (where d.state = 'reversed'),
        'amended',    count(*) filter (where d.version > 1))
        from public.chat_decisions d
       where d.workspace_id = v_ws
         and (_conversation is null or d.conversation_id = _conversation)),
    'decisions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', d.id, 'title', d.title, 'detail', d.detail, 'state', d.state,
        'version', d.version, 'decided_at', d.decided_at,
        'made_by', d.made_by,
        'made_by_email', (select u.email from auth.users u where u.id = d.made_by),
        'recorded_at', d.created_at, 'source', d.source,
        'conversation_id', d.conversation_id, 'message_id', d.message_id,
        'body_hash', d.body_hash,
        'affects_count', (select count(*) from public.chat_decision_links l
                           where l.decision_id = d.id and l.removed_at is null),
        'open_affected', (select count(*) from public.chat_decision_links l
                           join public.chat_work_items w on w.id = l.object_id
                          where l.decision_id = d.id and l.removed_at is null
                            and l.object_type in ('task','promise')
                            and w.state not in ('done','cancelled')))
        order by d.decided_at desc)
        from public.chat_decisions d
       where d.workspace_id = v_ws
         and public.chat_in_conversation(d.conversation_id, _user)
         and (_conversation is null or d.conversation_id = _conversation)
       limit 200), '[]'::jsonb));
end $$;


--
-- Name: decision_impact(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_impact(_decision uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare d record; v_allowed boolean;
begin
  select * into d from public.chat_decisions where id = _decision;
  if d.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if not public.chat_in_conversation(d.conversation_id, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  v_allowed := public.chat_feature_ok(_user, 'decision_impact');

  return jsonb_build_object(
    'decision_id', d.id,
    'title', d.title,
    'state', d.state,
    'version', d.version,
    'decided_at', d.decided_at,
    'impact_allowed', v_allowed,
    'engine_invents_links', false,
    -- ASLI links: kisi insaan ne reason ke saath banaye
    'affects', case when not v_allowed then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'link_id', l.id, 'object_type', l.object_type, 'object_id', l.object_id,
        'relation', l.relation, 'note', l.note,
        'link_reason', l.link_reason, 'linked_at', l.created_at,
        'label', case l.object_type
          when 'task'     then (select w.title from public.chat_work_items w where w.id = l.object_id)
          when 'promise'  then (select w.title from public.chat_work_items w where w.id = l.object_id)
          when 'decision' then (select x.title from public.chat_decisions x where x.id = l.object_id)
          when 'file'     then (select f.name from public.chat_files f where f.id = l.object_id)
          when 'conversation' then (select c.title from public.chat_conversations c where c.id = l.object_id)
          else (select left(g.body, 120) from public.chat_messages g where g.id = l.object_id)
        end,
        'object_state', case l.object_type
          when 'task'    then (select w.state from public.chat_work_items w where w.id = l.object_id)
          when 'promise' then (select public.promise_state_of(w.state, w.due_at, w.completed_at, w.original_due_at)
                                 from public.chat_work_items w where w.id = l.object_id)
          when 'decision' then (select x.state from public.chat_decisions x where x.id = l.object_id)
          when 'file'    then (select v.state from public.chat_file_versions v where v.file_id = l.object_id order by v.version desc limit 1)
          else null end,
        'due_at', case when l.object_type in ('task','promise')
          then (select w.due_at from public.chat_work_items w where w.id = l.object_id) else null end)
        order by l.created_at)
        from public.chat_decision_links l
       where l.decision_id = _decision and l.removed_at is null), '[]'::jsonb) end,
    -- POTENTIALLY affected: sirf isi conversation ke khule kaam, koi link nahi bana
    'potentially_affected', case when not v_allowed then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object(
        'object_type', w.kind, 'object_id', w.id, 'label', w.title,
        'object_state', w.state, 'due_at', w.due_at,
        'derived_from', 'same_conversation', 'linked', false)
        order by (w.due_at is null), w.due_at)
        from public.chat_work_items w
       where w.conversation_id = d.conversation_id
         and w.kind in ('task','promise')
         and w.state not in ('done','cancelled')
         and not exists (select 1 from public.chat_decision_links l
                          where l.decision_id = _decision and l.removed_at is null
                            and l.object_id = w.id)), '[]'::jsonb) end,
    'removed_links', coalesce((
      select jsonb_agg(jsonb_build_object('object_type', l.object_type, 'object_id', l.object_id,
        'remove_reason', l.remove_reason, 'removed_at', l.removed_at) order by l.removed_at desc)
        from public.chat_decision_links l
       where l.decision_id = _decision and l.removed_at is not null), '[]'::jsonb));
end $$;


--
-- Name: decision_link(uuid, uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_link(_decision uuid, _user uuid, _object_type text, _object_id uuid, _reason text, _relation text DEFAULT 'affects'::text, _note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare d record; v_id uuid;
begin
  if not public.chat_feature_ok(_user, 'decision_impact') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;
  if _object_type not in ('task','promise','decision','conversation','file','message') then
    return jsonb_build_object('ok', false, 'error', 'bad_object_type');
  end if;
  if _reason is null or length(btrim(_reason)) < 8 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'Link bina 8+ character wajah ke nahi banta.');
  end if;

  select * into d from public.chat_decisions where id = _decision;
  if d.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if not public.chat_in_conversation(d.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;

  -- object asli hona chahiye
  if _object_type in ('task','promise') then
    if not exists (select 1 from public.chat_work_items w
                    where w.id = _object_id and w.kind = _object_type) then
      return jsonb_build_object('ok', false, 'error', 'object_not_found');
    end if;
  elsif _object_type = 'decision' then
    if not exists (select 1 from public.chat_decisions x where x.id = _object_id) then
      return jsonb_build_object('ok', false, 'error', 'object_not_found');
    end if;
  elsif _object_type = 'conversation' then
    if not exists (select 1 from public.chat_conversations c where c.id = _object_id) then
      return jsonb_build_object('ok', false, 'error', 'object_not_found');
    end if;
  elsif _object_type = 'file' then
    if not exists (select 1 from public.chat_files f where f.id = _object_id) then
      return jsonb_build_object('ok', false, 'error', 'object_not_found');
    end if;
  else
    if not exists (select 1 from public.chat_messages g where g.id = _object_id) then
      return jsonb_build_object('ok', false, 'error', 'object_not_found');
    end if;
  end if;

  insert into public.chat_decision_links
    (decision_id, object_type, object_id, relation, note, linked_by, link_reason)
  values (_decision, _object_type, _object_id, coalesce(_relation, 'affects'),
          nullif(btrim(coalesce(_note, '')), ''), _user, btrim(_reason))
  on conflict do nothing
  returning id into v_id;

  if v_id is null then
    return jsonb_build_object('ok', false, 'error', 'already_linked');
  end if;

  insert into public.chat_decision_impact_log (decision_id, actor_id, event, reason, next)
  values (_decision, _user, 'link_added', btrim(_reason),
    jsonb_build_object('object_type', _object_type, 'object_id', _object_id,
                       'relation', coalesce(_relation, 'affects')));

  return jsonb_build_object('ok', true, 'link_id', v_id);
end $$;


--
-- Name: decision_mark(uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_mark(_user uuid, _message uuid, _title text DEFAULT NULL::text, _detail text DEFAULT NULL::text, _decided_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  m record; v_id uuid; v_hash text; v_title text; v_when timestamptz; v_work uuid;
begin
  if not public.chat_feature_ok(_user, 'decision_ledger') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;
  if _message is null then
    return jsonb_build_object('ok', false, 'error', 'message_required',
      'message', 'Ek decision hamesha ek asli message se banti hai.');
  end if;

  select id, conversation_id, workspace_id, sender_user_id, body, created_at
    into m from public.chat_messages where id = _message;
  if m.id is null then
    return jsonb_build_object('ok', false, 'error', 'message_not_found');
  end if;
  if not public.chat_in_conversation(m.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;

  select id into v_id from public.chat_decisions where message_id = _message;
  if v_id is not null then
    return jsonb_build_object('ok', false, 'error', 'already_a_decision', 'decision_id', v_id);
  end if;

  v_title := nullif(btrim(coalesce(_title, '')), '');
  if v_title is null then
    v_title := left(regexp_replace(m.body, '\s+', ' ', 'g'), 180);
  end if;
  v_when := coalesce(_decided_at, m.created_at);
  v_hash := encode(digest(m.body, 'sha256'), 'hex');

  -- Phase 3 work item (kind='decision') bhi banao — no duplicate, sirf link
  begin
    insert into public.chat_work_items
      (workspace_id, conversation_id, message_id, kind, title, owner_user_id, created_by)
    values (m.workspace_id, m.conversation_id, m.id, 'decision', v_title,
            m.sender_user_id, _user)
    returning id into v_work;
  exception when others then v_work := null;
  end;

  insert into public.chat_decisions
    (workspace_id, conversation_id, message_id, work_item_id, title, detail,
     decided_at, made_by, recorded_by, body_hash)
  values (m.workspace_id, m.conversation_id, m.id, v_work, v_title,
          nullif(btrim(coalesce(_detail, '')), ''), v_when, m.sender_user_id, _user, v_hash)
  returning id into v_id;

  insert into public.chat_decision_versions
    (decision_id, version, title, detail, decided_at, state, changed_by, change, reason)
  values (v_id, 1, v_title, nullif(btrim(coalesce(_detail, '')), ''), v_when,
          'active', _user, 'recorded', null);

  insert into public.chat_decision_impact_log (decision_id, actor_id, event, next)
  values (v_id, _user, 'recorded', jsonb_build_object(
    'title', v_title, 'decided_at', v_when, 'made_by', m.sender_user_id,
    'source', 'anexochat', 'body_hash', v_hash));

  return jsonb_build_object('ok', true, 'decision_id', v_id, 'work_item_id', v_work,
    'title', v_title, 'decided_at', v_when, 'made_by', m.sender_user_id, 'body_hash', v_hash);
end $$;


--
-- Name: decision_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_state(_decision uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare d record;
begin
  select * into d from public.chat_decisions where id = _decision;
  if d.id is null then return jsonb_build_object('error', 'not_found'); end if;
  if not public.chat_in_conversation(d.conversation_id, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;

  return jsonb_build_object(
    'decision', jsonb_build_object(
      'id', d.id, 'title', d.title, 'detail', d.detail, 'state', d.state,
      'version', d.version, 'decided_at', d.decided_at,
      'made_by', d.made_by,
      'made_by_email', (select u.email from auth.users u where u.id = d.made_by),
      'recorded_by', d.recorded_by, 'recorded_at', d.created_at,
      'source', d.source, 'conversation_id', d.conversation_id,
      'message_id', d.message_id, 'work_item_id', d.work_item_id,
      'body_hash', d.body_hash,
      'message_visible', exists (select 1 from public.chat_messages g
                                  where g.id = d.message_id and g.deleted_at is null),
      'superseded_by', d.superseded_by),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object(
        'version', v.version, 'title', v.title, 'detail', v.detail,
        'decided_at', v.decided_at, 'state', v.state, 'change', v.change,
        'reason', v.reason, 'changed_by', v.changed_by, 'at', v.at)
        order by v.version desc)
        from public.chat_decision_versions v where v.decision_id = _decision), '[]'::jsonb),
    'impact', public.decision_impact(_decision, _user),
    'ledger', coalesce((
      select jsonb_agg(jsonb_build_object('event', l.event, 'reason', l.reason,
        'prev', l.prev, 'next', l.next, 'actor_id', l.actor_id, 'at', l.at)
        order by l.id desc)
        from (select * from public.chat_decision_impact_log
               where decision_id = _decision order by id desc limit 50) l), '[]'::jsonb));
end $$;


--
-- Name: decision_to_email(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_to_email(_user uuid, _decision uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare d record; v_draft uuid; v_body text; v_ws uuid; v_maker text; v_line int := 1;
begin
  select dd.*, u.email as maker_email into d
    from public.chat_decisions dd join auth.users u on u.id = dd.made_by
   where dd.id = _decision;
  if not found then return jsonb_build_object('ok', false, 'error', 'decision_not_found'); end if;
  if not public.chat_in_conversation(d.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'chat_to_email') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;

  v_maker := d.maker_email;
  v_body :=
    'DECISION: ' || d.title || E'\n' ||
    coalesce('Detail: ' || d.detail || E'\n', '') ||
    'Decided: ' || to_char(d.decided_at at time zone 'utc', 'YYYY-MM-DD HH24:MI:SS') || ' UTC' || E'\n' ||
    'Made by: ' || v_maker || E'\n' ||
    'Source: ' || d.source || E'\n' ||
    'Version: ' || d.version || ' · State: ' || d.state || E'\n' ||
    'Record hash: ' || substring(d.body_hash, 1, 16) || E'\n\n' ||
    '---' || E'\n' ||
    'Formal record: ANEXOMAIL. This decision was recorded in ANEXOChat from a real message; ' ||
    'its history is versioned and never overwritten.';

  select workspace_id into v_ws from public.chat_conversations where id = d.conversation_id;

  insert into public.chat_email_drafts (workspace_id, conversation_id, created_by,
    subject, recipients, body, decision_id, state)
  values (v_ws, d.conversation_id, _user,
    'Decision: ' || d.title || ' (v' || d.version || ')', '{}'::text[], v_body, d.id, 'draft')
  returning id into v_draft;

  insert into public.chat_email_draft_citations (draft_id, line_no, message_id,
    sender_id, sender, sent_at_ms, body_hash, seal_source)
  select v_draft, v_line, d.message_id, d.made_by, v_maker,
         to_char(d.decided_at at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
         d.body_hash, 'chat_decisions.body_hash'
  on conflict (draft_id, message_id) do nothing;

  insert into public.chat_message_escalations (message_id, draft_id, by_user)
  values (d.message_id, v_draft, _user) on conflict do nothing;

  return jsonb_build_object('ok', true, 'draft_id', v_draft, 'decision_id', d.id,
    'version', d.version, 'state', 'draft', 'formal_record', 'ANEXOMAIL',
    'recipients_required_before_send', true);
end $$;


--
-- Name: decision_unlink(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decision_unlink(_link uuid, _user uuid, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare l record; d record;
begin
  if _reason is null or length(btrim(_reason)) < 8 then
    return jsonb_build_object('ok', false, 'error', 'reason_required');
  end if;
  select * into l from public.chat_decision_links where id = _link;
  if l.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if l.removed_at is not null then
    return jsonb_build_object('ok', false, 'error', 'already_removed');
  end if;
  select * into d from public.chat_decisions where id = l.decision_id;
  if not public.chat_in_conversation(d.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;

  -- link row rehta hai (record kabhi delete nahi) — sirf removed mark hota hai
  update public.chat_decision_links
     set removed_at = now(), removed_by = _user, remove_reason = btrim(_reason)
   where id = _link;

  insert into public.chat_decision_impact_log (decision_id, actor_id, event, reason, prev)
  values (l.decision_id, _user, 'link_removed', btrim(_reason),
    jsonb_build_object('object_type', l.object_type, 'object_id', l.object_id,
                       'relation', l.relation));

  return jsonb_build_object('ok', true, 'link_id', _link);
end $$;


--
-- Name: device_appeal_decide(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_appeal_decide(_actor uuid, _appeal uuid, _decision text, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.device_ban_appeals; v_reason text := btrim(coalesce(_reason,''));
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed');
  end if;
  if _decision not in ('reviewing','granted','denied') then
    return jsonb_build_object('ok', false, 'error', 'bad_decision');
  end if;
  if _decision in ('granted','denied') and length(v_reason) < 12 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'A decision on someone’s access needs at least 12 characters of reason.');
  end if;

  select * into v_row from public.device_ban_appeals where id = _appeal;
  if not found then raise exception 'appeal_not_found'; end if;
  if v_row.state in ('granted','denied') then
    return jsonb_build_object('ok', false, 'error', 'already_decided', 'state', v_row.state);
  end if;

  update public.device_ban_appeals
     set state = _decision,
         decided_by = case when _decision = 'reviewing' then null else _actor end,
         decision_reason = nullif(v_reason,''),
         decided_at = case when _decision = 'reviewing' then null else now() end
   where id = _appeal;

  if _decision = 'granted' then
    delete from public.device_bans where device_hash = v_row.device_hash;
    update public.device_vault
       set state = 'pending', reasons = '[]'::jsonb
     where device_hash = v_row.device_hash and state = 'banned';
    insert into public.device_trust_events (user_id, device_hash, event, actor, detail)
    values (v_row.user_id, v_row.device_hash, 'unbanned', 'reviewer',
            jsonb_build_object('appeal_id', _appeal, 'reason', v_reason));
  elsif _decision = 'denied' then
    insert into public.device_trust_events (user_id, device_hash, event, actor, detail)
    values (v_row.user_id, v_row.device_hash, 'appeal_denied', 'reviewer',
            jsonb_build_object('appeal_id', _appeal, 'reason', v_reason));
  end if;

  return jsonb_build_object('ok', true, 'appeal_id', _appeal, 'state', _decision);
end $$;


--
-- Name: device_appeal_open(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_appeal_open(_user uuid, _device_hash text, _statement text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_id uuid; v_txt text := btrim(coalesce(_statement,''));
begin
  if _user is null or coalesce(_device_hash,'') = '' then raise exception 'user_device_required'; end if;
  if length(v_txt) < 20 then
    return jsonb_build_object('ok', false, 'error', 'statement_required',
      'message', 'Tell us in at least 20 characters why this block is wrong.');
  end if;
  if not exists (select 1 from public.device_bans b
                  where b.device_hash = _device_hash and b.appealable) then
    return jsonb_build_object('ok', false, 'error', 'no_appealable_ban');
  end if;
  if exists (select 1 from public.device_ban_appeals a
              where a.device_hash = _device_hash and a.user_id = _user and a.state in ('new','reviewing')) then
    return jsonb_build_object('ok', false, 'error', 'appeal_already_open');
  end if;

  insert into public.device_ban_appeals (device_hash, user_id, statement)
  values (_device_hash, _user, v_txt) returning id into v_id;

  insert into public.device_trust_events (user_id, device_hash, event, actor, detail)
  values (_user, _device_hash, 'appealed', 'user', jsonb_build_object('appeal_id', v_id));

  return jsonb_build_object('ok', true, 'appeal_id', v_id, 'state', 'new');
end $$;


--
-- Name: device_appeal_queue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_appeal_queue(_actor uuid, _state text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('allowed', false, 'appeals', '[]'::jsonb);
  end if;
  return jsonb_build_object('allowed', true, 'appeals', coalesce((
    select jsonb_agg(jsonb_build_object(
        'id', a.id, 'device_hash', left(a.device_hash, 12) || '…', 'user_id', a.user_id,
        'statement', a.statement, 'state', a.state, 'created_at', a.created_at,
        'decision_reason', a.decision_reason, 'decided_at', a.decided_at)
      order by a.created_at desc)
      from public.device_ban_appeals a
     where _state is null or a.state = _state), '[]'::jsonb));
end $$;


--
-- Name: device_hash_migrate_v2(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_hash_migrate_v2(_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  r        record;
  s        jsonb;
  canon    text;
  h2       text;
  n_vault  int := 0;
  n_bans   int := 0;
  n_events int := 0;
  n_skip   int := 0;
begin
  if _key is null or _key = '' then raise exception 'key_required'; end if;

  for r in select d.id, d.user_id, d.device_hash, d.sealed_signals from public.device_vault d
            where d.sealed_signals is not null
  loop
    begin
      s := pgp_sym_decrypt(r.sealed_signals::bytea, _key)::jsonb;
      canon := concat_ws('|', s->>'platform_class', s->>'browser_class', s->>'timezone_bucket', s->>'screen_bucket', s->>'language');
      -- sirf woh record jinka hash sach mein v1 se milta hai (naye v2 ko chhedna nahi)
      if public.device_hash_v1(canon, _key) <> r.device_hash then n_skip := n_skip + 1; continue; end if;
      h2 := public.device_hash_v2(canon, _key);

      -- ban: purane hash par ban tha to v2 par bhi lagao (v1 wali row wahin rehti hai)
      if to_regclass('public.device_bans') is not null then
        insert into public.device_bans (device_hash, reason, banned_by, banned_at, expires_at)
        select h2, b.reason, b.banned_by, b.banned_at, b.expires_at
          from public.device_bans b where b.device_hash = r.device_hash
        on conflict (device_hash) do nothing;
        get diagnostics n_events = row_count;
        n_bans := n_bans + n_events;
      end if;

      if exists (select 1 from public.device_vault x where x.user_id = r.user_id and x.device_hash = h2) then
        n_skip := n_skip + 1; continue;   -- is user ke paas v2 pehle se hai
      end if;
      update public.device_vault set device_hash = h2 where id = r.id;
      update public.device_trust_events set device_hash = h2 where user_id = r.user_id and device_hash = r.device_hash;
      n_vault := n_vault + 1;
    exception when others then
      n_skip := n_skip + 1;   -- kisi aur key se seal hua tha / kharab record: chhod do, kuch nahi bigarta
    end;
  end loop;

  select count(*) into n_events from public.device_vault d
   where d.sealed_signals is not null;
  return jsonb_build_object('ok', true, 'vault_rows_moved_to_v2', n_vault, 'bans_copied_to_v2', n_bans,
                            'skipped', n_skip, 'vault_rows_total', n_events);
end $$;


--
-- Name: device_hash_v1(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_hash_v1(_canon text, _key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(digest(_canon || '|' || coalesce(_key, 'no-pepper'), 'sha256'), 'hex')
$$;


--
-- Name: device_hash_v2(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_hash_v2(_canon text, _key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select encode(
    hmac(convert_to(_canon, 'UTF8'),
         hmac(convert_to('anexomail/device-hash/v2', 'UTF8'),
              convert_to(coalesce(nullif(_key, ''), 'no-pepper'), 'UTF8'), 'sha256'),
         'sha256'),
    'hex')
$$;


--
-- Name: device_session_link(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_session_link(_user uuid, _device_hash text, _session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if _user is null or _session is null or coalesce(_device_hash, '') = '' then return jsonb_build_object('ok', false, 'error', 'bad_input'); end if;
  -- sirf us user ki apni, maujooda session link ho sakti hai
  if not exists (select 1 from auth.sessions s where s.id = _session and s.user_id = _user) then
    return jsonb_build_object('ok', false, 'error', 'session_not_found');
  end if;
  if not exists (select 1 from public.device_vault v where v.user_id = _user and v.device_hash = _device_hash) then
    return jsonb_build_object('ok', false, 'error', 'device_not_found');
  end if;
  insert into public.device_session_links (session_id, user_id, device_hash) values (_session, _user, _device_hash)
  on conflict (session_id) do update set device_hash = excluded.device_hash, linked_at = now();
  delete from public.device_session_links l where l.user_id = _user and not exists (select 1 from auth.sessions s where s.id = l.session_id);  -- purani/khatam links saaf
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: device_signal_class(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_signal_class(_ua text, _kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case when _kind = 'platform' then
      case when _ua ilike '%iphone%' then 'iPhone'
           when _ua ilike '%ipad%' then 'iPad'
           when _ua ilike '%android%' then 'Android'
           when _ua ilike '%windows%' then 'Windows'
           when _ua ilike '%mac os%' or _ua ilike '%macintosh%' then 'macOS'
           when _ua ilike '%linux%' then 'Linux'
           else 'Unknown' end
    else
      case when _ua ilike '%edg/%' then 'Edge'
           when _ua ilike '%chrome%' and _ua not ilike '%edg/%' then 'Chrome'
           when _ua ilike '%safari%' and _ua not ilike '%chrome%' then 'Safari'
           when _ua ilike '%firefox%' then 'Firefox'
           else 'Other' end
    end
$$;


--
-- Name: device_trust_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_trust_list(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_devices jsonb; v_policy public.device_vault_policy;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
      'device_hash', d.device_hash,
      'label', d.label,
      'platform_class', d.platform_class,
      'browser_class', d.browser_class,
      'state', d.state,
      'reasons', d.reasons,
      'registrations', d.registrations,
      'first_seen_at', d.first_seen_at,
      'last_seen_at', d.last_seen_at,
      'retain_until', d.retain_until
    ) order by d.last_seen_at desc), '[]'::jsonb)
    into v_devices
    from public.device_vault d where d.user_id = _user;

  select * into v_policy from public.device_vault_policy where id = 1;

  return jsonb_build_object(
    'devices', v_devices,
    'policy', jsonb_build_object(
      'retain_days', v_policy.retain_days,
      'signals_collected', v_policy.signals_collected,
      'legal_basis', v_policy.legal_basis,
      'purpose', v_policy.purpose,
      'biometric', false,
      'purged_at', v_policy.purged_at));
end $$;


--
-- Name: device_trust_set(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_trust_set(_user uuid, _device_hash text, _state text, _actor text DEFAULT 'user'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare v_row public.device_vault; v_killed int := 0; v_n int := 0; v_method text := null;
begin
  if _state not in ('trusted','suspicious','revoked') then raise exception 'bad_state'; end if;

  update public.device_vault set state = _state, last_seen_at = last_seen_at
   where user_id = _user and device_hash = _device_hash
   returning * into v_row;
  if not found then raise exception 'device_not_found'; end if;

  -- Revoke = access marta hai: asli login sessions (auth.sessions) bhi
  if _state = 'revoked' then
    -- 1) is device se linked sessions
    if to_regclass('auth.sessions') is not null then
      delete from auth.sessions s
       where s.user_id = _user
         and s.id in (select l.session_id from public.device_session_links l where l.user_id = _user and l.device_hash = _device_hash);
      get diagnostics v_n = row_count; v_killed := v_killed + v_n;
      if v_n > 0 then v_method := 'linked'; end if;
      -- 2) jin sessions ka kisi device se link nahi: browser+platform jaisa is device ka hai
      if to_regprocedure('public.device_signal_class(text,text)') is not null then
        delete from auth.sessions s
         where s.user_id = _user
           and not exists (select 1 from public.device_session_links l where l.session_id = s.id)
           and public.device_signal_class(coalesce(s.user_agent, ''), 'platform') = v_row.platform_class
           and public.device_signal_class(coalesce(s.user_agent, ''), 'browser')  = v_row.browser_class;
        get diagnostics v_n = row_count; v_killed := v_killed + v_n;
        if v_n > 0 then v_method := coalesce(v_method || '+', '') || 'user_agent'; end if;
      end if;
    end if;
    -- 3) purani app-side list (jaisa pehle)
    if to_regclass('public.security_sessions') is not null then
      execute 'delete from public.security_sessions where user_id = $1 and device_label = $2' using _user, v_row.label;
    end if;
    if to_regclass('public.security_devices') is not null then
      execute 'update public.security_devices set state = ''blocked'' where user_id = $1 and label = $2' using _user, v_row.label;
    end if;
  end if;

  insert into public.device_trust_events (user_id, device_hash, event, actor, detail)
  values (_user, _device_hash,
          case _state when 'trusted' then 'trusted' when 'revoked' then 'revoked' else 'suspicious' end,
          _actor, jsonb_build_object('sessions_killed', v_killed, 'method', v_method));

  return jsonb_build_object('ok', true, 'device_hash', _device_hash, 'state', _state,
                            'sessions_killed', v_killed, 'method', v_method);
end $_$;


--
-- Name: device_vault_purge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_vault_purge() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_gone int;
begin
  delete from public.device_vault where retain_until < now() and state <> 'banned';
  get diagnostics v_gone = row_count;
  delete from public.device_trust_events where at < now() - interval '400 days';
  update public.device_vault_policy set purged_at = now() where id = 1;
  return jsonb_build_object('purged', v_gone, 'at', now());
end $$;


--
-- Name: device_vault_register(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.device_vault_register(_user uuid, _signals jsonb, _key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_ua        text := coalesce(_signals->>'ua', '');
  v_platform  text := coalesce(nullif(_signals->>'platform_class',''), public.device_signal_class(v_ua,'platform'));
  v_browser   text := coalesce(nullif(_signals->>'browser_class',''), public.device_signal_class(v_ua,'browser'));
  v_tz        int  := coalesce((_signals->>'tz_offset_minutes')::int, 0) / 60;   -- hour bucket
  v_screen    text := coalesce(_signals->>'screen_bucket', 'unknown');
  v_lang      text := lower(left(coalesce(_signals->>'language','xx'), 2));
  v_minimized jsonb;
  v_canon     text;
  v_h1        text;
  v_hash      text;      -- v2
  v_row       public.device_vault;
  v_reasons   jsonb := '[]'::jsonb;
  v_state     text := 'pending';
  v_users     int;
  v_recent    int;
  v_retain    int;
  v_limit     jsonb;
  v_count     int;
begin
  if _user is null then raise exception 'user_required'; end if;

  -- MINIMIZATION: sirf yeh 5 coarse signals, koi canvas/audio/font fingerprint nahi
  v_minimized := jsonb_build_object(
    'platform_class', v_platform, 'browser_class', v_browser,
    'timezone_bucket', v_tz, 'screen_bucket', v_screen, 'language', v_lang);

  v_canon := concat_ws('|', v_platform, v_browser, v_tz::text, v_screen, v_lang);
  v_h1    := public.device_hash_v1(v_canon, _key);
  v_hash  := public.device_hash_v2(v_canon, _key);

  -- is user ka purana v1 record: us ko ab v2 bana do (naya v2 record pehle se nahi hai to)
  if not exists (select 1 from public.device_vault where user_id = _user and device_hash = v_hash)
     and exists (select 1 from public.device_vault where user_id = _user and device_hash = v_h1) then
    update public.device_vault set device_hash = v_hash where user_id = _user and device_hash = v_h1;
    update public.device_trust_events set device_hash = v_hash where user_id = _user and device_hash = v_h1;
  end if;

  select retain_days into v_retain from public.device_vault_policy where id = 1;

  -- banned device? (dono hash)
  if exists (select 1 from public.device_bans b
              where b.device_hash in (v_hash, v_h1) and (b.expires_at is null or b.expires_at > now())) then
    v_state := 'banned';
    v_reasons := v_reasons || jsonb_build_array('device is on the banned list');
  end if;

  -- same hash multiple accounts = suspicious registration
  select count(distinct user_id) into v_users from public.device_vault where device_hash in (v_hash, v_h1);
  if v_users >= 3 and v_state <> 'banned' then
    v_state := 'suspicious';
    v_reasons := v_reasons || jsonb_build_array('this device shape registered on ' || v_users || ' accounts');
  end if;

  -- burst registrations from one device in 24h
  select count(*) into v_recent from public.device_trust_events
   where device_hash in (v_hash, v_h1) and event = 'registered' and at > now() - interval '24 hours';
  if v_recent >= 3 and v_state = 'pending' then
    v_state := 'suspicious';
    v_reasons := v_reasons || jsonb_build_array(v_recent || ' registrations from this device in 24h');
  end if;

  -- plan cap on vault size (naya device add karne se pehle)
  v_limit := public.chat_feature_allowed(_user, 'device_vault');
  select count(*) into v_count from public.device_vault where user_id = _user;
  if not exists (select 1 from public.device_vault where user_id = _user and device_hash = v_hash)
     and (v_limit->>'limit') is not null and v_count >= (v_limit->>'limit')::int then
    return jsonb_build_object('ok', false, 'error', 'device_limit_reached',
      'plan', v_limit->>'plan', 'limit', (v_limit->>'limit')::int);
  end if;

  insert into public.device_vault as d (
    user_id, device_hash, label, platform_class, browser_class, signal_count,
    sealed_signals, state, reasons, retain_until)
  values (
    _user, v_hash, v_browser || ' · ' || v_platform, v_platform, v_browser,
    5, pgp_sym_encrypt(v_minimized::text, coalesce(_key, 'no-pepper')),
    v_state, v_reasons, now() + make_interval(days => coalesce(v_retain, 180)))
  on conflict (user_id, device_hash) do update
    set last_seen_at = now(),
        registrations = d.registrations + 1,
        label = excluded.label,
        state = case when d.state = 'revoked' then 'revoked'
                     when excluded.state in ('banned','suspicious') then excluded.state
                     else d.state end,
        reasons = excluded.reasons,
        retain_until = now() + make_interval(days => coalesce(v_retain, 180))
  returning * into v_row;

  insert into public.device_trust_events (user_id, device_hash, event, actor, detail)
  values (_user, v_hash,
          case when v_row.registrations = 1 then 'registered' else 'seen' end,
          'engine', jsonb_build_object('state', v_row.state, 'reasons', v_row.reasons));

  return jsonb_build_object(
    'ok', v_row.state not in ('banned','revoked'),
    'device_hash', v_hash,
    'label', v_row.label,
    'state', v_row.state,
    'reasons', v_row.reasons,
    'signals_collected', 5,
    'retain_until', v_row.retain_until,
    'legal_basis', v_row.legal_basis);
end $$;


--
-- Name: email_chat_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_chat_context(_conversation uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_links jsonb; v_quotes jsonb;
begin
  if not public.chat_in_conversation(_conversation, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'link_id', l.id, 'mail_thread_id', l.mail_thread_id,
           'mail_message_id', l.mail_message_id, 'origin', l.origin,
           'subject', coalesce(public.mail_thread_subject_safe(l.mail_thread_id), l.subject_snapshot),
           'subject_source', case when public.mail_thread_subject_safe(l.mail_thread_id) is null
                                  then 'snapshot at link time' else 'live mail record' end,
           'work_item_id', l.work_item_id,
           'created_at', l.created_at) order by l.created_at), '[]'::jsonb)
    into v_links from public.chat_email_links l
   where l.conversation_id = _conversation and l.removed_at is null;

  select coalesce(jsonb_agg(jsonb_build_object(
           'quote_id', q.id, 'message_id', q.message_id,
           'mail_message_id', q.mail_message_id, 'quoted_hash', q.quoted_hash,
           'at', q.at) order by q.at desc), '[]'::jsonb)
    into v_quotes from public.chat_email_quotes q
    join public.chat_messages m on m.id = q.message_id
   where m.conversation_id = _conversation;

  return jsonb_build_object(
    'conversation_id', _conversation,
    'links', v_links,
    'quotes', v_quotes,
    'formal_record', 'ANEXOMAIL',
    'badge', 'Formal record lives in ANEXOMAIL',
    'chat_is_formal_record', false);
end $$;


--
-- Name: email_discuss_in_chat(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_discuss_in_chat(_user uuid, _mail_thread uuid, _mail_message uuid DEFAULT NULL::uuid, _conversation uuid DEFAULT NULL::uuid, _subject text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid; v_link record; v_conv uuid; v_subject text; v_created boolean := false;
begin
  if not public.chat_feature_ok(_user, 'email_chat_bridge') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;
  if _mail_thread is null then
    return jsonb_build_object('ok', false, 'error', 'mail_thread_required');
  end if;
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then return jsonb_build_object('ok', false, 'error', 'no_workspace'); end if;

  -- pehle se link hai? duplicate kabhi nahi
  select * into v_link from public.chat_email_links
   where mail_thread_id = _mail_thread and removed_at is null
   order by created_at limit 1;

  if found then
    v_conv := v_link.conversation_id;
  else
    v_subject := coalesce(nullif(trim(coalesce(_subject, '')), ''),
                          public.mail_thread_subject_safe(_mail_thread),
                          'Email discussion');
    if _conversation is not null then
      if not public.chat_in_conversation(_conversation, _user) then
        return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
      end if;
      v_conv := _conversation;
    else
      insert into public.chat_conversations (workspace_id, kind, subject, created_by)
      values (v_ws, 'group', v_subject, _user)
      returning id into v_conv;
      insert into public.chat_participants (conversation_id, user_id)
      values (v_conv, _user) on conflict do nothing;
      v_created := true;
    end if;

    insert into public.chat_email_links (workspace_id, conversation_id, mail_thread_id,
      mail_message_id, origin, subject_snapshot, created_by)
    values (v_ws, v_conv, _mail_thread, _mail_message, 'email_to_chat', v_subject, _user)
    on conflict do nothing;

    select * into v_link from public.chat_email_links
     where mail_thread_id = _mail_thread and conversation_id = v_conv and removed_at is null
     limit 1;
  end if;

  return jsonb_build_object('ok', true,
    'conversation_id', v_conv,
    'conversation_created', v_created,
    'link_id', v_link.id,
    'mail_thread_id', _mail_thread,
    'mail_message_id', coalesce(_mail_message, v_link.mail_message_id),
    'formal_record', 'ANEXOMAIL',
    'badge', 'Formal record lives in ANEXOMAIL',
    'chat_role', 'instant communication layer');
end $$;


--
-- Name: email_discuss_presence(uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_discuss_presence(_user uuid, _emails text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid; v_rows jsonb;
begin
  if not public.chat_feature_ok(_user, 'email_chat_bridge') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then return jsonb_build_object('error', 'no_workspace'); end if;

  select coalesce(jsonb_agg(x order by x->>'email'), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
             'email', e.email,
             'user_id', u.id,
             'has_anexochat_account', u.id is not null,
             'in_workspace', m.user_id is not null,
             'last_seen_at', pr.last_seen_at,
             'presence', case
               when u.id is null then 'no ANEXOChat account on record'
               when m.user_id is null then 'not a member of this workspace'
               when pr.last_seen_at is null then 'no presence recorded'
               when pr.last_seen_at > now() - interval '2 minutes' then 'online'
               else 'last seen ' || to_char(pr.last_seen_at at time zone 'utc', 'HH24:MI') || ' UTC'
             end) as x
      from unnest(coalesce(_emails, '{}'::text[])) as e(email)
      left join auth.users u on lower(u.email) = lower(e.email)
      left join public.chat_members m on m.user_id = u.id and m.workspace_id = v_ws
      left join public.chat_presence pr on pr.user_id = u.id and pr.workspace_id = v_ws) t;

  return jsonb_build_object('people', v_rows, 'invites_guessed', false);
end $$;


--
-- Name: email_hmac_v1(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_hmac_v1(_email text, _key text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select case when coalesce(_key, '') = '' or coalesce(_email, '') = '' then null
    else encode(hmac(convert_to(lower(btrim(_email)), 'UTF8'),
           hmac(convert_to('anexomail/email-hash/v1', 'UTF8'), convert_to(_key, 'UTF8'), 'sha256'), 'sha256'), 'hex') end
$$;


--
-- Name: email_quote_to_chat(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_quote_to_chat(_user uuid, _message uuid, _mail_thread uuid, _quoted_text text, _mail_message uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_conv uuid; v_hash text; v_id uuid;
begin
  select conversation_id into v_conv from public.chat_messages where id = _message;
  if v_conv is null then return jsonb_build_object('ok', false, 'error', 'message_not_found'); end if;
  if not public.chat_in_conversation(v_conv, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;
  if coalesce(length(trim(coalesce(_quoted_text, ''))), 0) = 0 then
    return jsonb_build_object('ok', false, 'error', 'quoted_text_required');
  end if;

  v_hash := encode(digest(_quoted_text, 'sha256'), 'hex');
  insert into public.chat_email_quotes (message_id, mail_thread_id, mail_message_id,
    quoted_text, quoted_hash, quoted_by)
  values (_message, _mail_thread, _mail_message, _quoted_text, v_hash, _user)
  returning id into v_id;

  return jsonb_build_object('ok', true, 'quote_id', v_id, 'quoted_hash', v_hash,
    'formal_record', 'ANEXOMAIL', 'mail_message_id', _mail_message);
end $$;


--
-- Name: email_quote_verify(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_quote_verify(_quote uuid, _current_text text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare q record; v_now text;
begin
  select * into q from public.chat_email_quotes where id = _quote;
  if not found then return jsonb_build_object('error', 'quote_not_found'); end if;
  if _current_text is null then
    return jsonb_build_object('quote_id', _quote, 'quoted_hash', q.quoted_hash,
      'match', null, 'note', 'No current text supplied to compare.');
  end if;
  v_now := encode(digest(_current_text, 'sha256'), 'hex');
  return jsonb_build_object('quote_id', _quote, 'quoted_hash', q.quoted_hash,
    'current_hash', v_now, 'match', v_now = q.quoted_hash,
    'note', case when v_now = q.quoted_hash
                 then 'Quote still matches the recorded email text.'
                 else 'The email text no longer matches what was quoted here.' end);
end $$;


--
-- Name: email_thread_conversation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_thread_conversation(_user uuid, _mail_thread uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare l record;
begin
  select * into l from public.chat_email_links
   where mail_thread_id = _mail_thread and removed_at is null
   order by created_at limit 1;
  if not found then
    return jsonb_build_object('linked', false, 'mail_thread_id', _mail_thread,
      'note', 'No ANEXOChat conversation is linked to this email thread yet.');
  end if;
  return jsonb_build_object('linked', true, 'conversation_id', l.conversation_id,
    'link_id', l.id, 'work_item_id', l.work_item_id,
    'may_open', public.chat_in_conversation(l.conversation_id, _user),
    'formal_record', 'ANEXOMAIL');
end $$;


--
-- Name: enqueue_founder_reply(uuid, text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_founder_reply(p_user_id uuid, p_customer_email text, p_subject text, p_thread_id uuid DEFAULT NULL::uuid, p_received_at timestamp with time zone DEFAULT now()) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_user_id uuid;
  v_plan text;
  v_hours integer;
  v_id uuid;
begin
  select user_id, lower(coalesce(plan, 'basic')) into v_user_id, v_plan
  from public.workspace_subscriptions
  where state in ('active', 'trialing')
    and (lower(customer_email) = lower(p_customer_email) or user_id = p_user_id)
  order by (lower(customer_email) = lower(p_customer_email)) desc
  limit 1;

  v_user_id := coalesce(v_user_id, p_user_id);
  v_plan := coalesce(v_plan, 'basic');
  if v_plan not in ('basic', 'pro', 'business', 'business_pro') then v_plan := 'basic'; end if;
  v_hours := case v_plan when 'business_pro' then 12 when 'business' then 24 when 'pro' then 48 else 72 end;

  insert into public.founder_reply_queue (
    user_id, thread_id, customer_email, subject, plan,
    response_due_hours, received_at, respond_by
  ) values (
    v_user_id, p_thread_id, p_customer_email, coalesce(p_subject, ''), v_plan,
    v_hours, p_received_at, p_received_at + make_interval(hours => v_hours)
  ) returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: ensure_trial_account_row(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_trial_account_row(_user_id uuid, _social_email text, _provider text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.trial_accounts;
begin
  insert into public.trial_accounts (user_id, social_email, social_provider, status)
  values (_user_id, _social_email, _provider, 'pending_plan')
  on conflict (user_id) do update set social_email = coalesce(excluded.social_email, trial_accounts.social_email),
                                      updated_at = now()
  returning * into a;
  insert into public.trial_events (user_id, event_type, detail)
  values (_user_id, 'signup', jsonb_build_object('provider', _provider, 'email', _social_email))
  on conflict do nothing;
  -- Funnel audit (hardening #6): 'signup' event pehle se tha, lekin woh
  -- generic hai (business+personal dono, trial_start() ke zamane se).
  -- 'pending_plan_entered' specifically batata hai "yeh account ab plan
  -- choose karne ka intezaar kar raha hai" — v_signup_plan_funnel aur
  -- pending_plan_stale() isi par query karte hain.
  insert into public.trial_events (user_id, event_type, detail)
  values (_user_id, 'pending_plan_entered', jsonb_build_object('provider', _provider))
  on conflict do nothing;
  return public.account_state(_user_id);
end $$;


--
-- Name: FUNCTION ensure_trial_account_row(_user_id uuid, _social_email text, _provider text); Type: COMMENT; Schema: public; Owner: -
--

