--
-- Name: entitled_full(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entitled_full(_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((public.account_state(_user_id) ->> 'business_data')::boolean, false);
$$;


--
-- Name: family_chat_workspace_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.family_chat_workspace_apply() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  founder_id uuid;
  humza_id uuid;
  raana_id uuid;
  ws uuid;
  founder_humza uuid;
  founder_raana uuid;
begin
  select id into founder_id from auth.users
   where lower(email) = 'naumansherwani.founder@anexomail.com' limit 1;
  select id into humza_id from auth.users
   where lower(email) = 'humzasherwani@anexomail.com' limit 1;
  select id into raana_id from auth.users
   where lower(email) = 'raanasherwani@anexomail.com' limit 1;

  if founder_id is null or humza_id is null or raana_id is null then
    return jsonb_build_object('ok', false, 'reason', 'founder_family_auth_users_missing');
  end if;
  if not public.chat_access(founder_id)
     or not public.chat_access(humza_id)
     or not public.chat_access(raana_id) then
    return jsonb_build_object('ok', false, 'reason', 'founder_family_chat_access_missing');
  end if;

  select w.id into ws
    from public.chat_workspaces w
   where w.owner_user_id = founder_id and w.name = 'ANEXOMAIL Family'
   order by w.created_at
   limit 1;
  if ws is null then
    insert into public.chat_workspaces (name, owner_user_id)
    values ('ANEXOMAIL Family', founder_id)
    returning id into ws;
  end if;

  insert into public.chat_members (workspace_id, user_id, display_name, role) values
    (ws, founder_id, 'Muhammad Nauman Sherwani', 'owner'),
    (ws, humza_id, 'Humza Sherwani', 'member'),
    (ws, raana_id, 'Raana Sherwani', 'member')
  on conflict (workspace_id, user_id) do update
    set display_name = excluded.display_name,
        role = excluded.role;

  founder_humza := public.chat_direct_conversation(ws, founder_id, humza_id);
  founder_raana := public.chat_direct_conversation(ws, founder_id, raana_id);

  return jsonb_build_object(
    'ok', true,
    'workspace_id', ws,
    'members', 3,
    'founder_humza_conversation_id', founder_humza,
    'founder_raana_conversation_id', founder_raana
  );
end $$;


--
-- Name: family_grants_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.family_grants_apply() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare r record; n integer := 0; has_ai_plan boolean;
begin
  select exists (select 1 from information_schema.columns
                  where table_schema='public' and table_name='entitlement_state'
                    and column_name='ai_plan') into has_ai_plan;

  for r in select f.*, u.id as uid
             from public.family_accounts f
             join auth.users u on lower(u.email) = lower(f.email)
  loop
    if to_regclass('public.entitlement_state') is not null then
      insert into public.entitlement_state (user_id, plan, seats, support_active, active_until)
      values (r.uid, r.plan, 1, true, now() + interval '10 years')
      on conflict (user_id) do update
        set plan = r.plan, seats = greatest(1, entitlement_state.seats),
            support_active = true,
            active_until = greatest(coalesce(entitlement_state.active_until, now()), now() + interval '10 years'),
            revision = entitlement_state.revision + 1,
            updated_at = now();
      if has_ai_plan then
        if r.ai_plan is null or btrim(r.ai_plan) = '' then
          execute 'update public.entitlement_state set ai_plan = null where user_id = $1'
            using r.uid;
        else
          execute 'update public.entitlement_state set ai_plan = $2 where user_id = $1'
            using r.uid, r.ai_plan;
        end if;
      end if;
    end if;

    if to_regclass('public.ai_credit_wallets') is not null
       and r.ai_plan is not null and btrim(r.ai_plan) <> '' then
      insert into public.ai_credit_wallets (workspace_id, owner_id, plan_id, subscription_credits, renews_at)
      values (r.uid, r.uid, r.ai_plan, r.ai_credits, now() + interval '1 month')
      on conflict (workspace_id) do update
        set owner_id = r.uid, plan_id = r.ai_plan,
            subscription_credits = greatest(ai_credit_wallets.subscription_credits, r.ai_credits),
            updated_at = now();
    end if;

    if to_regclass('public.trial_accounts') is not null then
      insert into public.trial_accounts (user_id, social_email, social_provider, status, plan, trial_ends_at, passkey_set, recovery_set)
      values (r.uid, r.email, 'email', 'active', r.plan, now() + interval '10 years', false, true)
      on conflict (user_id) do update
        set status = 'active',
            plan = r.plan,
            trial_ends_at = greatest(trial_accounts.trial_ends_at, now() + interval '10 years'),
            recovery_set = true,
            updated_at = now();
    end if;

    n := n + 1;
  end loop;
  return n;
end $_$;


--
-- Name: family_workspaces_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.family_workspaces_apply() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  r record;
  n int := 0;
  oid uuid;
  role_udt text;
  parent_table text;
  has_status boolean;
  has_slug boolean := false;
  has_owner_id boolean := false;
  has_created_by boolean := false;
  has_member_email boolean := false;
  domain_nullable boolean := true;
  v_slug text;
  v_name text;
  v_domain text;
  cols text;
  vals text;
  member_exists boolean;
  mail_exists boolean;
begin
  if to_regclass('public.org_members') is null then
    return 0;
  end if;

  if to_regclass('public.organisations') is not null then
    parent_table := 'organisations';
  elsif to_regclass('public.orgs') is not null then
    parent_table := 'orgs';
  else
    return 0;
  end if;

  select c.udt_name into role_udt
    from information_schema.columns c
   where c.table_schema = 'public' and c.table_name = 'org_members' and c.column_name = 'role';

  select exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'org_members' and column_name = 'status'
  ) into has_status;
  select exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'org_members' and column_name = 'email'
  ) into has_member_email;

  select exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = parent_table and column_name = 'slug'
  ) into has_slug;
  select exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = parent_table and column_name = 'owner_id'
  ) into has_owner_id;
  select exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = parent_table and column_name = 'created_by'
  ) into has_created_by;

  -- domain column: only fill if NOT NULL (then unique per user — never shared anexomail.com)
  select coalesce(
    (select c.is_nullable = 'YES'
       from information_schema.columns c
      where c.table_schema = 'public' and c.table_name = parent_table and c.column_name = 'domain'),
    true
  ) into domain_nullable;

  for r in
    select f.email, f.display_name, u.id as uid
      from public.family_accounts f
      join auth.users u on lower(u.email) = lower(f.email)
  loop
    oid := null;
    v_slug := 'family-' || substr(replace(r.uid::text, '-', ''), 1, 12);
    v_name := r.display_name || ' workspace';
    -- unique per mailbox local-part — NOT anexomail.com (organisations_domain_key)
    v_domain := lower(split_part(r.email, '@', 1)) || '.family.anexomail.com';

    if has_slug then
      execute format(
        'select id from public.%I where slug = $1 limit 1',
        parent_table)
        into oid
        using v_slug;
    end if;

    if oid is null and to_regclass('public.mail_accounts') is not null then
      execute format(
        $q$
        select m.org_id
          from public.mail_accounts m
          join public.%I p on p.id = m.org_id
         where lower(m.address) = lower($1)
         limit 1
        $q$, parent_table)
        into oid
        using r.email;
    end if;

    if oid is null then
      execute format(
        $q$
        select m.org_id
          from public.org_members m
          join public.%I p on p.id = m.org_id
         where m.user_id = $1
         limit 1
        $q$, parent_table)
        into oid
        using r.uid;
    end if;

    if oid is null then
      if parent_table = 'organisations' then
        cols := 'name';
        vals := quote_literal(v_name);
        if has_slug then
          cols := cols || ', slug';
          vals := vals || ', ' || quote_literal(v_slug);
        end if;
        -- domain: sirf jab NOT NULL — warna chhodo (null). Kabhi shared anexomail.com nahi.
        if not domain_nullable then
          cols := cols || ', domain';
          vals := vals || ', ' || quote_literal(v_domain);
        end if;
        if has_owner_id then
          cols := cols || ', owner_id';
          vals := vals || ', ' || quote_literal(r.uid::text) || '::uuid';
        elsif has_created_by then
          cols := cols || ', created_by';
          vals := vals || ', ' || quote_literal(r.uid::text) || '::uuid';
        end if;

        begin
          execute format(
            'insert into public.organisations (%s) values (%s) returning id',
            cols, vals)
            into oid;
        exception
          when unique_violation then
            if has_slug then
              select id into oid from public.organisations where slug = v_slug limit 1;
            end if;
            if oid is null and has_owner_id then
              select id into oid from public.organisations where owner_id = r.uid limit 1;
            end if;
            if oid is null then
              -- domain unique collide: retry without domain
              begin
                cols := 'name';
                vals := quote_literal(v_name);
                if has_slug then
                  cols := cols || ', slug';
                  vals := vals || ', ' || quote_literal(v_slug);
                end if;
                if has_owner_id then
                  cols := cols || ', owner_id';
                  vals := vals || ', ' || quote_literal(r.uid::text) || '::uuid';
                elsif has_created_by then
                  cols := cols || ', created_by';
                  vals := vals || ', ' || quote_literal(r.uid::text) || '::uuid';
                end if;
                execute format(
                  'insert into public.organisations (%s) values (%s) returning id',
                  cols, vals)
                  into oid;
              exception
                when unique_violation then
                  if has_slug then
                    select id into oid from public.organisations where slug = v_slug limit 1;
                  end if;
                  if oid is null then
                    raise;
                  end if;
              end;
            end if;
        end;
      else
        insert into public.orgs (name)
        values (v_name)
        returning id into oid;
      end if;
    end if;

    if oid is null then
      raise exception 'family_workspaces_apply: no org id for %', r.email;
    end if;

    select exists (
      select 1 from public.org_members m
       where m.org_id = oid and m.user_id = r.uid
    ) into member_exists;

    if member_exists then
      if has_status and has_member_email then
        update public.org_members
           set email = r.email, status = 'active'
         where org_id = oid and user_id = r.uid;
      elsif has_member_email then
        update public.org_members
           set email = r.email
         where org_id = oid and user_id = r.uid;
      elsif has_status then
        update public.org_members
           set status = 'active'
         where org_id = oid and user_id = r.uid;
      end if;
    else
      if role_udt = 'org_role' then
        if has_status and has_member_email then
          insert into public.org_members (org_id, user_id, email, role, status)
          values (oid, r.uid, r.email, 'owner'::public.org_role, 'active');
        elsif has_member_email then
          insert into public.org_members (org_id, user_id, email, role)
          values (oid, r.uid, r.email, 'owner'::public.org_role);
        elsif has_status then
          insert into public.org_members (org_id, user_id, role, status)
          values (oid, r.uid, 'owner'::public.org_role, 'active');
        else
          insert into public.org_members (org_id, user_id, role)
          values (oid, r.uid, 'owner'::public.org_role);
        end if;
      else
        if has_status and has_member_email then
          insert into public.org_members (org_id, user_id, email, role, status)
          values (oid, r.uid, r.email, 'owner', 'active');
        elsif has_member_email then
          insert into public.org_members (org_id, user_id, email, role)
          values (oid, r.uid, r.email, 'owner');
        elsif has_status then
          insert into public.org_members (org_id, user_id, role, status)
          values (oid, r.uid, 'owner', 'active');
        else
          insert into public.org_members (org_id, user_id, role)
          values (oid, r.uid, 'owner');
        end if;
      end if;
    end if;

    if to_regclass('public.mail_accounts') is not null then
      select exists (
        select 1 from public.mail_accounts m
         where lower(m.address) = lower(r.email)
      ) into mail_exists;

      if mail_exists then
        update public.mail_accounts
           set org_id = oid
         where lower(address) = lower(r.email);
      else
        insert into public.mail_accounts (org_id, address)
        values (oid, r.email);
      end if;
    end if;

    if to_regclass('public.account_organisations') is not null then
      if not exists (
        select 1 from public.account_organisations a where a.slug = v_slug
      ) then
        insert into public.account_organisations (name, slug, domain, created_by)
        values (v_name, v_slug, 'anexomail.com', r.uid);
      end if;

      if to_regclass('public.account_org_members') is not null then
        insert into public.account_org_members (org_id, user_id, role)
        select a.id, r.uid, 'owner'
          from public.account_organisations a
         where a.slug = v_slug
           and not exists (
             select 1 from public.account_org_members m
              where m.org_id = a.id and m.user_id = r.uid
           );
      end if;
    end if;

    n := n + 1;
  end loop;
  return n;
end $_$;


--
-- Name: file_chunk_ack(uuid, uuid, integer, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_chunk_ack(_user uuid, _transfer uuid, _idx integer, _bytes bigint, _sha256 text, _server_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_t public.chat_transfers;
  v_state text;
  v_done bigint;
begin
  select * into v_t from public.chat_transfers where id = _transfer and user_id = _user;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'transfer_not_found');
  end if;

  v_state := case
    when _server_sha256 is null or _sha256 is null then 'stored'
    when lower(_server_sha256) = lower(_sha256) then 'verified'
    else 'corrupt'
  end;

  update public.chat_file_chunks
     set bytes = coalesce(nullif(_bytes, 0), bytes),
         sha256 = coalesce(_sha256, sha256),
         state = v_state,
         attempts = attempts + 1,
         updated_at = now()
   where version_id = v_t.version_id and idx = _idx;

  update public.chat_transfers
     set last_seen_at = now(), state = case when state = 'paused' then 'active' else state end
   where id = _transfer;

  if v_state = 'verified' then
    insert into public.chat_transfer_ledger (workspace_id, user_id, transfer_id, direction, bytes)
    values (v_t.workspace_id, _user, _transfer, 'upload', coalesce(_bytes, 0));
  end if;

  select coalesce(sum(bytes), 0) into v_done
    from public.chat_file_chunks where version_id = v_t.version_id and state = 'verified';

  return jsonb_build_object(
    'ok', v_state <> 'corrupt',
    'chunk_state', v_state,
    'bytes_done', v_done,
    'bytes_total', v_t.bytes_total,
    'percent', case when v_t.bytes_total > 0
                    then round((v_done::numeric / v_t.bytes_total) * 100, 2) else 0 end
  );
end $$;


--
-- Name: file_commit(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_commit(_user uuid, _transfer uuid, _file_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_t public.chat_transfers;
  v_v public.chat_file_versions;
  v_f public.chat_files;
  v_missing jsonb;
  v_corrupt jsonb;
  v_keep int;
  v_type jsonb;
begin
  select * into v_t from public.chat_transfers where id = _transfer and user_id = _user;
  if not found then return jsonb_build_object('ok', false, 'reason', 'transfer_not_found'); end if;
  select * into v_v from public.chat_file_versions where id = v_t.version_id;
  select * into v_f from public.chat_files where id = v_v.file_id;

  select coalesce(jsonb_agg(idx order by idx), '[]'::jsonb) into v_missing
    from public.chat_file_chunks
   where version_id = v_v.id and state in ('pending','stored');
  select coalesce(jsonb_agg(idx order by idx), '[]'::jsonb) into v_corrupt
    from public.chat_file_chunks where version_id = v_v.id and state = 'corrupt';

  if jsonb_array_length(v_missing) > 0 or jsonb_array_length(v_corrupt) > 0 then
    if jsonb_array_length(v_corrupt) > 0 then
      update public.chat_file_versions set state = 'corrupt' where id = v_v.id;
    end if;
    return jsonb_build_object('ok', false, 'reason', 'incomplete',
                              'missing', v_missing, 'corrupt', v_corrupt);
  end if;

  update public.chat_file_versions
     set state = 'ready', ready_at = now(),
         file_sha256 = coalesce(_file_sha256, file_sha256),
         safety = case when safety in ('clean','flagged','blocked') then safety else 'pending' end,
         available_at = case when safety = 'clean' then coalesce(available_at, now()) else null end
   where id = v_v.id;

  update public.chat_files
     set current_version = v_v.version,
         latest_bytes = v_v.bytes,
         content_type = coalesce(v_v.content_type, content_type),
         updated_at = now()
   where id = v_v.file_id;

  update public.chat_transfers
     set state = 'complete', finished_at = now(), last_seen_at = now()
   where id = _transfer;

  select versions_kept into v_keep from public.file_plan_limits
   where plan = (public.file_plan_for(_user)).plan;
  update public.chat_file_versions v
     set state = 'abandoned'
   where v.file_id = v_v.file_id
     and v.state = 'ready'
     and v.version <= v_v.version - coalesce(v_keep, 10);

  -- PHASE 16 evidence: bytes pohonch gayi, magar available nahi.
  perform public.file_evidence_mark(_user, v_v.id, 'uploading', 'engine',
            jsonb_build_object('transfer_id', _transfer));
  perform public.file_evidence_mark(_user, v_v.id, 'uploaded', 'engine',
            jsonb_build_object('bytes', v_v.bytes, 'chunks', v_v.chunk_count));

  -- PHASE 17: deterministic pre-verdict (naam + declared type) queue se pehle.
  v_type := public.file_type_verdict(v_f.name, v_v.content_type, null);

  insert into public.file_scan_jobs
    (version_id, user_id, workspace_id, name, bytes, content_type,
     storage_prefix, chunk_count, state, findings)
  values (v_v.id, _user, v_f.workspace_id, v_f.name, v_v.bytes, v_v.content_type,
          v_v.storage_prefix, v_v.chunk_count, 'pending',
          coalesce(v_type->'reasons', '[]'::jsonb))
  on conflict (version_id) do update
    set state = 'pending', claimed_at = null, finished_at = null, verdict = null;

  perform public.file_evidence_mark(_user, v_v.id, 'scanning', 'engine',
            jsonb_build_object('pre_verdict', v_type));

  -- Saaf block: yahin fasla, worker ka intezaar nahi.
  if v_type->>'decision' = 'block' then
    perform public.file_scan_report(v_v.id,
      jsonb_build_array('type-policy'), 'dangerous', 'block', v_type->'reasons');
    return jsonb_build_object('ok', true, 'file_id', v_v.file_id, 'version', v_v.version,
                              'bytes', v_v.bytes, 'safety', 'blocked',
                              'available', false, 'reason', 'blocked_by_policy');
  end if;

  return jsonb_build_object('ok', true, 'file_id', v_v.file_id, 'version', v_v.version,
                            'bytes', v_v.bytes, 'storage_prefix', v_v.storage_prefix,
                            'version_id', v_v.id, 'safety', 'pending', 'available', false);
end $$;


--
-- Name: file_context_card(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_context_card(_file uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare f record; v record; out jsonb;
begin
  if not public.chat_feature_ok(_user, 'file_context') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;

  select * into f from public.chat_files where id = _file and deleted_at is null;
  if not found then return jsonb_build_object('allowed', true, 'found', false); end if;

  select * into v from public.chat_file_versions
   where file_id = _file order by version desc limit 1;

  out := jsonb_build_object(
    'allowed', true,
    'found', true,
    'engine_invents_nothing', true,
    'file', jsonb_build_object(
      'id', f.id, 'name', f.name, 'content_type', f.content_type,
      'current_version', f.current_version, 'latest_bytes', f.latest_bytes,
      'updated_at', f.updated_at),
    'uploader', (
      select jsonb_build_object('user_id', v.created_by, 'at', v.created_at,
                                'version', v.version, 'sha256', v.file_sha256)
      where v.id is not null),
    'conversation', (
      select jsonb_build_object('id', c.id, 'title', c.title)
        from public.chat_conversations c where c.id = f.conversation_id),
    'evidence', coalesce((
      select jsonb_agg(jsonb_build_object('state', e.state, 'actor', e.actor, 'at', e.at)
                       order by e.id)
        from public.file_evidence e where e.version_id = v.id), '[]'::jsonb),
    'links', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', l.id, 'object_type', l.object_type, 'object_id', l.object_id,
               'label', l.label, 'reason', l.reason, 'linked_by', l.linked_by,
               'linked_at', l.linked_at) order by l.linked_at desc)
        from public.chat_file_links l
       where l.file_id = _file and l.removed_at is null), '[]'::jsonb)
  );

  -- related work status (sirf recorded links se)
  out := out || jsonb_build_object('related_work', coalesce((
    select jsonb_agg(jsonb_build_object(
             'work_id', w.id, 'kind', w.kind, 'title', w.title,
             'status', w.status, 'owner_id', w.owner_id, 'due_at', w.due_at))
      from public.chat_file_links l
      join public.chat_work_items w on w.id::text = l.object_id
     where l.file_id = _file and l.removed_at is null and l.object_type = 'work_item'
  ), '[]'::jsonb));

  return out;
end $$;


--
-- Name: file_download_ack(uuid, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_download_ack(_user uuid, _version uuid, _bytes bigint DEFAULT 0, _device text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_v public.chat_file_versions;
begin
  select * into v_v from public.chat_file_versions where id = _version;
  if not found then return jsonb_build_object('ok', false, 'reason', 'not_found'); end if;
  if v_v.available_at is null or v_v.safety <> 'clean' then
    return jsonb_build_object('ok', false, 'reason', 'not_available', 'safety', v_v.safety);
  end if;
  insert into public.file_downloads(version_id, user_id, bytes, device)
  values (_version, _user, greatest(coalesce(_bytes,0), 0), _device);
  perform public.file_evidence_mark(_user, _version, 'downloaded', 'user',
            jsonb_build_object('device', _device));
  return jsonb_build_object('ok', true);
end $$;


--
-- Name: file_download_manifest(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_download_manifest(_user uuid, _version uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_v     public.chat_file_versions;
  v_f     public.chat_files;
  v_ok    boolean;
  v_chunks jsonb;
begin
  select * into v_v from public.chat_file_versions where id = _version;
  if not found then return jsonb_build_object('found', false, 'ok', false, 'reason', 'not_found'); end if;
  select * into v_f from public.chat_files where id = v_v.file_id;
  if not found or v_f.deleted_at is not null then
    return jsonb_build_object('found', false, 'ok', false, 'reason', 'not_found');
  end if;

  select (v_f.owner_id = _user
          or exists (select 1 from public.chat_participants p
                      where p.conversation_id = v_f.conversation_id and p.user_id = _user))
    into v_ok;
  if not v_ok then return jsonb_build_object('found', false, 'ok', false, 'reason', 'not_found'); end if;

  if v_v.state <> 'ready' then
    return jsonb_build_object('found', true, 'ok', false, 'reason', 'not_ready', 'state', v_v.state);
  end if;
  if v_v.available_at is null or v_v.safety <> 'clean' then
    return jsonb_build_object('found', true, 'ok', false, 'reason', 'not_available',
                              'safety', v_v.safety);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('idx', c.idx, 'bytes', c.bytes, 'sha256', c.sha256)
                            order by c.idx), '[]'::jsonb)
    into v_chunks
    from public.chat_file_chunks c
   where c.version_id = _version and c.state = 'verified';

  if jsonb_array_length(v_chunks) <> v_v.chunk_count then
    return jsonb_build_object('found', true, 'ok', false, 'reason', 'chunks_incomplete',
                              'verified', jsonb_array_length(v_chunks), 'expected', v_v.chunk_count);
  end if;

  return jsonb_build_object(
    'found', true, 'ok', true,
    'version_id', v_v.id, 'file_id', v_f.id, 'version', v_v.version,
    'name', v_f.name, 'content_type', coalesce(v_v.content_type, v_f.content_type, 'application/octet-stream'),
    'bytes', v_v.bytes, 'file_sha256', v_v.file_sha256,
    'chunk_size', v_v.chunk_size, 'chunk_count', v_v.chunk_count,
    'storage_prefix', v_v.storage_prefix,
    'chunks', v_chunks
  );
end $$;


--
-- Name: file_duplicates(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_duplicates(_file uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare f record; v record;
begin
  if not public.chat_feature_ok(_user, 'file_dedupe') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  select * into f from public.chat_files where id = _file and deleted_at is null;
  if not found then return jsonb_build_object('allowed', true, 'found', false); end if;
  select * into v from public.chat_file_versions
   where file_id = _file and state = 'ready' order by version desc limit 1;
  if v.file_sha256 is null then
    return jsonb_build_object('allowed', true, 'found', true, 'sha256', null,
      'reason', 'no sealed hash for the current version', 'duplicates', '[]'::jsonb);
  end if;

  return jsonb_build_object(
    'allowed', true, 'found', true, 'sha256', v.file_sha256, 'match_basis', 'sha256',
    'duplicates', coalesce((
      select jsonb_agg(jsonb_build_object(
               'file_id', o.id, 'name', o.name, 'conversation_id', o.conversation_id,
               'version', ov.version, 'bytes', ov.bytes, 'uploaded_by', ov.created_by,
               'uploaded_at', ov.created_at))
        from public.chat_file_versions ov
        join public.chat_files o on o.id = ov.file_id
       where ov.file_sha256 = v.file_sha256 and ov.state = 'ready'
         and o.workspace_id = f.workspace_id and o.id <> f.id and o.deleted_at is null
    ), '[]'::jsonb),
    'pool_saving_bytes', coalesce((
      select sum(ov.bytes) from public.chat_file_versions ov
        join public.chat_files o on o.id = ov.file_id
       where ov.file_sha256 = v.file_sha256 and ov.state = 'ready'
         and o.workspace_id = f.workspace_id and o.id <> f.id and o.deleted_at is null), 0));
end $$;


--
-- Name: file_engine_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_engine_state(_user uuid, _workspace uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  return jsonb_build_object(
    'pool', public.file_pool_state(_user, _workspace),
    'files', coalesce((
      select jsonb_agg(jsonb_build_object(
        'file_id', f.id, 'name', f.name, 'bytes', f.latest_bytes,
        'content_type', f.content_type, 'version', f.current_version,
        'updated_at', f.updated_at,
        'versions', (select count(*) from public.chat_file_versions v
                      where v.file_id = f.id and v.state = 'ready')
      ) order by f.updated_at desc)
      from public.chat_files f
      where f.workspace_id = _workspace and f.deleted_at is null
        and f.current_version > 0
      limit 100), '[]'::jsonb),
    'transfers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'transfer_id', t.id, 'state', t.state, 'transport', t.transport,
        'bytes_total', t.bytes_total,
        'bytes_done', (select coalesce(sum(c.bytes), 0) from public.chat_file_chunks c
                        where c.version_id = t.version_id and c.state = 'verified'),
        'name', (select f.name from public.chat_files f
                  join public.chat_file_versions v on v.file_id = f.id
                 where v.id = t.version_id),
        'started_at', t.started_at, 'last_seen_at', t.last_seen_at, 'error', t.error
      ) order by t.last_seen_at desc)
      from public.chat_transfers t
      where t.workspace_id = _workspace and t.user_id = _user
        and t.state in ('active','paused','failed')
      limit 20), '[]'::jsonb)
  );
end $$;


--
-- Name: file_evidence_for_transfer(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_evidence_for_transfer(_user uuid, _transfer uuid, _state text, _actor text DEFAULT 'engine'::text, _detail jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_version uuid;
begin
  select version_id into v_version from public.chat_transfers
   where id = _transfer and user_id = _user;
  if v_version is null then return jsonb_build_object('ok', false, 'reason', 'transfer_not_found'); end if;
  return public.file_evidence_mark(_user, v_version, _state, _actor, _detail);
end $$;


--
-- Name: file_evidence_mark(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_evidence_mark(_user uuid, _version uuid, _state text, _actor text DEFAULT 'engine'::text, _detail jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_order  text[] := array['selected','uploading','uploaded','scanning','verified','available','downloaded'];
  v_want   int;
  v_have   int;
begin
  if _state = 'blocked' then
    insert into public.file_evidence(version_id, user_id, state, actor, detail)
    values (_version, _user, 'blocked', _actor, _detail)
    on conflict do nothing;
    return jsonb_build_object('ok', true, 'state', 'blocked');
  end if;

  v_want := array_position(v_order, _state);
  if v_want is null then
    return jsonb_build_object('ok', false, 'reason', 'unknown_state');
  end if;

  select coalesce(max(array_position(v_order, state)), 0) into v_have
    from public.file_evidence where version_id = _version and state <> 'blocked';

  if v_want > v_have + 1 then
    return jsonb_build_object('ok', false, 'reason', 'step_skipped',
                              'have', v_order[greatest(v_have,1)], 'want', _state);
  end if;

  insert into public.file_evidence(version_id, user_id, state, actor, detail)
  values (_version, _user, _state, _actor, _detail)
  on conflict do nothing;

  return jsonb_build_object('ok', true, 'state', _state);
end $$;


--
-- Name: file_link(uuid, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_link(_file uuid, _object_type text, _object_id text, _label text, _reason text, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare new_id uuid;
begin
  if not public.chat_feature_ok(_user, 'file_context') then
    return jsonb_build_object('ok', false, 'reason', 'plan_not_entitled');
  end if;
  if char_length(btrim(coalesce(_reason,''))) < 8 then
    return jsonb_build_object('ok', false, 'reason', 'reason_min_8_chars');
  end if;

  insert into public.chat_file_links (file_id, object_type, object_id, label, reason, linked_by)
  values (_file, _object_type, _object_id, nullif(btrim(coalesce(_label,'')), ''), btrim(_reason), _user)
  on conflict do nothing
  returning id into new_id;

  if new_id is null then
    return jsonb_build_object('ok', false, 'reason', 'already_linked');
  end if;

  insert into public.chat_file_link_log (file_id, link_id, action, actor_id, reason,
    detail) values (_file, new_id, 'linked', _user, btrim(_reason),
    jsonb_build_object('object_type', _object_type, 'object_id', _object_id));

  return jsonb_build_object('ok', true, 'link_id', new_id);
end $$;


--
-- Name: file_plan_limits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.file_plan_limits (
    plan text NOT NULL,
    max_file_bytes bigint NOT NULL,
    pool_bytes bigint NOT NULL,
    transfer_unlimited boolean DEFAULT false NOT NULL,
    monthly_transfer_bytes bigint,
    max_concurrent integer DEFAULT 3 NOT NULL,
    versions_kept integer DEFAULT 10 NOT NULL
);


--
-- Name: file_plan_for(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_plan_for(_user uuid) RETURNS public.file_plan_limits
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_plan text := 'basic';
  v_row public.file_plan_limits;
begin
  if to_regclass('public.founder_accounts') is not null then
    if exists (select 1 from public.founder_accounts fa where fa.user_id = _user) then
      v_plan := 'founder';
    end if;
  end if;

  if v_plan = 'basic' and to_regclass('public.account_state') is null then
    null;
  end if;

  if v_plan = 'basic' then
    begin
      select coalesce(nullif(lower((public.account_state(_user)->>'plan')), ''), 'basic')
        into v_plan;
    exception when others then v_plan := 'basic';
    end;
  end if;

  select * into v_row from public.file_plan_limits where plan = v_plan;
  if not found then
    select * into v_row from public.file_plan_limits where plan = 'basic';
  end if;
  return v_row;
end $$;


--
-- Name: file_pool_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_pool_state(_user uuid, _workspace uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_lim public.file_plan_limits;
  v_stored bigint;
  v_month bigint;
  v_active int;
begin
  v_lim := public.file_plan_for(_user);

  select coalesce(sum(v.bytes), 0) into v_stored
  from public.chat_file_versions v
  join public.chat_files f on f.id = v.file_id
  where f.workspace_id = _workspace and v.state = 'ready' and f.deleted_at is null;

  select coalesce(sum(bytes), 0) into v_month
  from public.chat_transfer_ledger
  where workspace_id = _workspace
    and day >= date_trunc('month', (now() at time zone 'utc'))::date;

  select count(*) into v_active
  from public.chat_transfers
  where workspace_id = _workspace and state = 'active';

  return jsonb_build_object(
    'plan', v_lim.plan,
    'entitled', v_lim.max_file_bytes > 0,
    'max_file_bytes', v_lim.max_file_bytes,
    'pool_bytes', v_lim.pool_bytes,
    'stored_bytes', v_stored,
    'remaining_bytes', greatest(v_lim.pool_bytes - v_stored, 0),
    'percent', case when v_lim.pool_bytes > 0
                    then round((v_stored::numeric / v_lim.pool_bytes) * 100, 1) else 0 end,
    'transfer_unlimited', v_lim.transfer_unlimited,
    'transfer_month_bytes', v_month,
    'transfer_month_limit', v_lim.monthly_transfer_bytes,
    'max_concurrent', v_lim.max_concurrent,
    'active_transfers', v_active,
    'versions_kept', v_lim.versions_kept
  );
end $$;


--
-- Name: file_relationship_graph(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_relationship_graph(_file uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare f record; v record; nodes jsonb := '[]'::jsonb; edges jsonb := '[]'::jsonb;
begin
  if not public.chat_feature_ok(_user, 'relationship_graph') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  select * into f from public.chat_files where id = _file and deleted_at is null;
  if not found then return jsonb_build_object('allowed', true, 'found', false); end if;
  select * into v from public.chat_file_versions where file_id = _file order by version desc limit 1;

  nodes := jsonb_build_array(jsonb_build_object('type','file','id',f.id,'label',f.name));
  if v.created_by is not null then
    nodes := nodes || jsonb_build_array(
      jsonb_build_object('type','person','id',v.created_by,'label','uploader'));
    edges := edges || jsonb_build_array(jsonb_build_object(
      'from', f.id, 'to', v.created_by, 'kind', 'uploaded_by',
      'source', 'chat_file_versions.created_by', 'recorded', true));
  end if;

  nodes := nodes || coalesce((
    select jsonb_agg(distinct jsonb_build_object(
             'type', l.object_type, 'id', l.object_id, 'label', coalesce(l.label, l.object_type)))
      from public.chat_file_links l where l.file_id = _file and l.removed_at is null), '[]'::jsonb);
  edges := edges || coalesce((
    select jsonb_agg(jsonb_build_object(
             'from', f.id, 'to', l.object_id, 'kind', l.object_type,
             'reason', l.reason, 'linked_by', l.linked_by, 'recorded', true))
      from public.chat_file_links l where l.file_id = _file and l.removed_at is null), '[]'::jsonb);

  return jsonb_build_object('allowed', true, 'found', true,
    'engine_invents_edges', false, 'nodes', nodes, 'edges', edges);
end $$;


--
-- Name: file_safety_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_safety_state(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  return jsonb_build_object(
    'enforcement', coalesce((
      select jsonb_build_object('strikes', strikes, 'action', action, 'last_event', last_event)
      from public.file_enforcement where user_id = _user),
      jsonb_build_object('strikes', 0, 'action', 'none', 'last_event', null)),
    'queue', jsonb_build_object(
      'pending', (select count(*) from public.file_scan_jobs where state = 'pending'),
      'scanning', (select count(*) from public.file_scan_jobs where state = 'scanning')),
    'events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'name', s.name, 'classification', s.classification,
        'decision', s.decision, 'reasons', s.reasons, 'engines', s.engines,
        'review_state', s.review_state, 'created_at', s.created_at)
        order by s.created_at desc)
      from public.file_safety_events s where s.user_id = _user limit 25), '[]'::jsonb),
    'engines', jsonb_build_array('type-policy','clamd-local','entropy','archive-ratio','local-classifier'),
    'external_api', false
  );
end $$;


--
-- Name: file_scan_claim(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_scan_claim(_limit integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  -- 10 min se atki scanning jobs wapas pending (self-heal)
  update public.file_scan_jobs
     set state = 'pending', claimed_at = null
   where state = 'scanning' and claimed_at < now() - interval '10 minutes';

  with picked as (
    select version_id from public.file_scan_jobs
     where state = 'pending' and attempts < 5
     order by created_at
     limit greatest(1, least(coalesce(_limit,2), 8))
     for update skip locked
  )
  update public.file_scan_jobs j
     set state = 'scanning', claimed_at = now(), attempts = j.attempts + 1
   where j.version_id in (select version_id from picked);

  return jsonb_build_object('jobs', coalesce((
    select jsonb_agg(jsonb_build_object(
      'version_id', j.version_id, 'user_id', j.user_id, 'name', j.name,
      'bytes', j.bytes, 'content_type', j.content_type,
      'storage_prefix', j.storage_prefix, 'chunk_count', j.chunk_count,
      'attempts', j.attempts))
    from public.file_scan_jobs j
    where j.state = 'scanning' and j.claimed_at >= now() - interval '30 seconds'
  ), '[]'::jsonb));
end $$;


--
-- Name: file_scan_report(uuid, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_scan_report(_version uuid, _engines jsonb, _classification text, _decision text, _findings jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_job  public.file_scan_jobs;
  v_v    public.chat_file_versions;
  v_bad  text;
  v_safety text;
  v_strikes int;
  v_action text;
begin
  select * into v_job from public.file_scan_jobs where version_id = _version;
  if not found then return jsonb_build_object('ok', false, 'reason', 'job_not_found'); end if;
  select * into v_v from public.chat_file_versions where id = _version;

  -- API-FREE LOCK: koi external engine naam aaya to verdict reject.
  select e into v_bad from jsonb_array_elements_text(coalesce(_engines,'[]'::jsonb)) e
   where e ~* '(deepinfra|openrouter|openai|anthropic|google|azure|http)';
  if v_bad is not null then
    return jsonb_build_object('ok', false, 'reason', 'external_engine_forbidden', 'engine', v_bad);
  end if;

  if _decision not in ('allow','quarantine','block') then
    return jsonb_build_object('ok', false, 'reason', 'bad_decision');
  end if;

  v_safety := case _decision when 'allow' then 'clean'
                             when 'quarantine' then 'flagged'
                             else 'blocked' end;

  update public.file_scan_jobs
     set state = 'done', finished_at = now(), engines = coalesce(_engines,'[]'::jsonb),
         findings = coalesce(_findings,'[]'::jsonb), verdict = _decision
   where version_id = _version;

  update public.chat_file_versions
     set safety = v_safety,
         safety_reason = case when _decision = 'allow' then null
                              else coalesce(_findings->0->>'detail', _classification) end,
         scanned_at = now(),
         available_at = case when _decision = 'allow' then now() else null end
   where id = _version;

  perform public.file_evidence_mark(v_job.user_id, _version, 'verified', 'rust',
            jsonb_build_object('engines', _engines, 'classification', _classification));

  if _decision = 'allow' then
    perform public.file_evidence_mark(v_job.user_id, _version, 'available', 'rust',
              jsonb_build_object('bytes', v_job.bytes));
  else
    perform public.file_evidence_mark(v_job.user_id, _version, 'blocked', 'rust',
              jsonb_build_object('classification', _classification, 'findings', _findings));

    insert into public.file_safety_events
      (version_id, user_id, workspace_id, name, classification, decision, reasons, engines)
    values (_version, v_job.user_id, v_job.workspace_id, v_job.name,
            _classification, _decision, coalesce(_findings,'[]'::jsonb), coalesce(_engines,'[]'::jsonb));

    if _decision = 'block' then
      insert into public.file_enforcement(user_id, strikes, action, last_event)
      values (v_job.user_id, 1, 'warned', now())
      on conflict (user_id) do update
        set strikes = file_enforcement.strikes + 1, last_event = now();
      select strikes into v_strikes from public.file_enforcement where user_id = v_job.user_id;
      v_action := case when v_strikes >= 5 then 'account_review'
                       when v_strikes >= 3 then 'uploads_paused'
                       else 'warned' end;
      update public.file_enforcement set action = v_action where user_id = v_job.user_id;
    end if;
  end if;

  return jsonb_build_object('ok', true, 'safety', v_safety, 'decision', _decision);
end $$;


--
-- Name: file_stale_check(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_stale_check(_file uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare f record; v record;
begin
  if not public.chat_feature_ok(_user, 'file_context') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  select * into f from public.chat_files where id = _file and deleted_at is null;
  if not found then return jsonb_build_object('allowed', true, 'found', false); end if;
  select * into v from public.chat_file_versions
   where file_id = _file order by version desc limit 1;

  return jsonb_build_object(
    'allowed', true, 'found', true,
    'current_version', f.current_version,
    'current_version_at', v.created_at,
    'flags', coalesce((
      select jsonb_agg(jsonb_build_object(
               'decision_id', d.id, 'decision_title', d.title,
               'decision_version', d.version, 'decided_at', d.decided_at,
               'file_version', f.current_version, 'file_version_at', v.created_at,
               'stale', d.decided_at > v.created_at,
               'evidence', jsonb_build_object(
                 'link_reason', l.reason, 'linked_by', l.linked_by, 'linked_at', l.linked_at,
                 'decision_body_hash', d.body_hash)))
        from public.chat_file_links l
        join public.chat_decisions d on d.id::text = l.object_id
       where l.file_id = _file and l.removed_at is null and l.object_type = 'decision'
         and d.decided_at > v.created_at
    ), '[]'::jsonb));
end $$;


--
-- Name: file_transfer_begin(uuid, uuid, uuid, text, text, bigint, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_transfer_begin(_user uuid, _workspace uuid, _conv uuid, _name text, _content_type text, _bytes bigint, _file_sha256 text, _chunk_size bigint, _device text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_lim public.file_plan_limits;
  v_pool jsonb;
  v_file uuid;
  v_ver public.chat_file_versions;
  v_next int;
  v_count int;
  v_transfer uuid;
  v_chunk bigint := greatest(coalesce(_chunk_size, 8388608), 1048576);
begin
  v_lim := public.file_plan_for(_user);
  if v_lim.max_file_bytes <= 0 then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled', 'plan', v_lim.plan);
  end if;
  if _bytes > v_lim.max_file_bytes then
    return jsonb_build_object('allowed', false, 'reason', 'file_too_large',
                              'max_file_bytes', v_lim.max_file_bytes);
  end if;

  v_pool := public.file_pool_state(_user, _workspace);
  if (v_pool->>'remaining_bytes')::bigint < _bytes then
    return jsonb_build_object('allowed', false, 'reason', 'pool_full', 'pool', v_pool);
  end if;
  if not (v_pool->>'transfer_unlimited')::boolean
     and v_lim.monthly_transfer_bytes is not null
     and (v_pool->>'transfer_month_bytes')::bigint + _bytes > v_lim.monthly_transfer_bytes then
    return jsonb_build_object('allowed', false, 'reason', 'transfer_quota', 'pool', v_pool);
  end if;

  -- file identity (naam per workspace/conversation)
  select id into v_file from public.chat_files
   where workspace_id = _workspace
     and coalesce(conversation_id, '00000000-0000-0000-0000-000000000000'::uuid)
         = coalesce(_conv, '00000000-0000-0000-0000-000000000000'::uuid)
     and lower(name) = lower(_name)
     and deleted_at is null;

  if v_file is null then
    insert into public.chat_files (workspace_id, conversation_id, owner_id, name, content_type)
    values (_workspace, _conv, _user, _name, _content_type)
    returning id into v_file;
  end if;

  -- PHASE 15: resume identity — same (file, bytes, sha) = same version wapis
  select * into v_ver from public.chat_file_versions
   where file_id = v_file
     and bytes = _bytes
     and coalesce(file_sha256, '') = coalesce(_file_sha256, '')
     and state in ('transferring','corrupt')
   order by version desc limit 1;

  if v_ver.id is null then
    select coalesce(max(version), 0) + 1 into v_next
      from public.chat_file_versions where file_id = v_file;
    v_count := greatest(ceil(_bytes::numeric / v_chunk)::int, 1);
    insert into public.chat_file_versions (
      file_id, version, bytes, content_type, file_sha256,
      chunk_size, chunk_count, storage_prefix, created_by
    ) values (
      v_file, v_next, _bytes, _content_type, _file_sha256,
      v_chunk, v_count, _workspace || '/' || v_file || '/v' || v_next, _user
    ) returning * into v_ver;

    insert into public.chat_file_chunks (version_id, idx, bytes)
    select v_ver.id, g - 1,
           least(v_chunk, _bytes - (g - 1) * v_chunk)
    from generate_series(1, v_count) g
    on conflict do nothing;
  else
    update public.chat_file_versions set state = 'transferring' where id = v_ver.id;
  end if;

  insert into public.chat_transfers (
    version_id, workspace_id, user_id, device_id, bytes_total, concurrency
  ) values (
    v_ver.id, _workspace, _user, _device, _bytes, v_lim.max_concurrent
  ) returning id into v_transfer;

  return jsonb_build_object(
    'allowed', true,
    'transfer_id', v_transfer,
    'file_id', v_file,
    'version_id', v_ver.id,
    'version', v_ver.version,
    'chunk_size', v_ver.chunk_size,
    'chunk_count', v_ver.chunk_count,
    'storage_prefix', v_ver.storage_prefix,
    'resumed', (select count(*) from public.chat_file_chunks
                 where version_id = v_ver.id and state = 'verified') > 0,
    'missing', coalesce((select jsonb_agg(idx order by idx) from public.chat_file_chunks
                          where version_id = v_ver.id and state <> 'verified'), '[]'::jsonb),
    'verified_bytes', coalesce((select sum(bytes) from public.chat_file_chunks
                                 where version_id = v_ver.id and state = 'verified'), 0),
    'max_concurrent', v_lim.max_concurrent,
    'pool', v_pool
  );
end $$;


--
-- Name: file_transfer_mark(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_transfer_mark(_user uuid, _transfer uuid, _state text, _transport text, _error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if _state not in ('active','paused','failed') then
    return jsonb_build_object('ok', false, 'reason', 'bad_state');
  end if;
  update public.chat_transfers
     set state = _state,
         transport = coalesce(nullif(_transport, ''), transport),
         error = _error,
         last_seen_at = now()
   where id = _transfer and user_id = _user;
  return jsonb_build_object('ok', found, 'state', _state);
end $$;


--
-- Name: file_transfer_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_transfer_state(_user uuid, _transfer uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_t public.chat_transfers;
  v_v public.chat_file_versions;
  v_done bigint;
begin
  select * into v_t from public.chat_transfers where id = _transfer and user_id = _user;
  if not found then return jsonb_build_object('found', false); end if;
  select * into v_v from public.chat_file_versions where id = v_t.version_id;
  select coalesce(sum(bytes), 0) into v_done
    from public.chat_file_chunks where version_id = v_t.version_id and state = 'verified';

  return jsonb_build_object(
    'found', true,
    'transfer_id', v_t.id,
    'state', v_t.state,
    'transport', v_t.transport,
    'version_id', v_v.id,
    'version', v_v.version,
    'chunk_size', v_v.chunk_size,
    'chunk_count', v_v.chunk_count,
    'storage_prefix', v_v.storage_prefix,
    'bytes_total', v_t.bytes_total,
    'bytes_done', v_done,
    'percent', case when v_t.bytes_total > 0
                    then round((v_done::numeric / v_t.bytes_total) * 100, 2) else 0 end,
    'missing', coalesce((select jsonb_agg(idx order by idx) from public.chat_file_chunks
                          where version_id = v_t.version_id and state in ('pending','stored')), '[]'::jsonb),
    'corrupt', coalesce((select jsonb_agg(idx order by idx) from public.chat_file_chunks
                          where version_id = v_t.version_id and state = 'corrupt'), '[]'::jsonb)
  );
end $$;


--
-- Name: file_truth(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_truth(_user uuid, _version uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_v      public.chat_file_versions;
  v_owner  boolean;
  v_rows   jsonb;
  v_job    public.file_scan_jobs;
begin
  select * into v_v from public.chat_file_versions where id = _version;
  if not found then return jsonb_build_object('found', false); end if;

  select exists (
    select 1 from public.chat_files f
     where f.id = v_v.file_id
       and (f.owner_id = _user
            or exists (select 1 from public.chat_participants p
                        where p.conversation_id = f.conversation_id and p.user_id = _user))
  ) into v_owner;
  if not v_owner then return jsonb_build_object('found', false); end if;

  select coalesce(jsonb_agg(jsonb_build_object('state', e.state, 'at', e.at,
                                               'actor', e.actor, 'detail', e.detail)
                            order by e.id), '[]'::jsonb) into v_rows
    from public.file_evidence e where e.version_id = _version;

  select * into v_job from public.file_scan_jobs where version_id = _version;

  return jsonb_build_object(
    'found', true,
    'version_id', _version,
    'bytes', v_v.bytes,
    'version', v_v.version,
    'safety', v_v.safety,
    'safety_reason', v_v.safety_reason,
    'available', v_v.available_at is not null,
    'blocked', v_v.safety = 'blocked',
    'chain', v_rows,
    'scan', case when v_job.version_id is null then null else jsonb_build_object(
      'state', v_job.state, 'engines', v_job.engines,
      'findings', v_job.findings, 'verdict', v_job.verdict,
      'attempts', v_job.attempts, 'finished_at', v_job.finished_at) end,
    'downloads', (select count(*) from public.file_downloads d where d.version_id = _version)
  );
end $$;


--
-- Name: file_type_verdict(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_type_verdict(_name text, _content_type text, _magic_hex text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_ext   text := lower(coalesce(nullif(regexp_replace(_name, '^.*\.', ''), _name), ''));
  v_p     public.file_type_policy;
  v_magic text := lower(coalesce(_magic_hex, ''));
  v_reasons jsonb := '[]'::jsonb;
  v_decision text := 'allow';
  v_label text := 'unclassified';
begin
  -- 1) extension policy
  select * into v_p from public.file_type_policy
   where v_ext <> '' and v_ext = any(extensions)
   order by case decision when 'block' then 0 when 'quarantine' then 1 else 2 end
   limit 1;
  if found then
    v_label := v_p.label;
    v_decision := v_p.decision;
    if v_p.decision <> 'allow' then
      v_reasons := v_reasons || jsonb_build_object('code', 'extension_policy', 'detail', v_p.reason);
    end if;
  end if;

  -- 2) magic bytes: executable signature chahe naam kuch bhi ho
  if v_magic like '4d5a%' or v_magic like '7f454c46%' then
    v_decision := 'block';
    v_label := 'executable-magic';
    v_reasons := v_reasons || jsonb_build_object('code', 'executable_magic',
                   'detail', 'Leading bytes identify an executable binary');
  end if;

  -- 3) ext/mime mismatch (masquerading)
  if v_p.label is not null and v_p.mime_prefix is not null
     and coalesce(_content_type,'') not like v_p.mime_prefix || '%' then
    if v_decision = 'allow' then v_decision := 'quarantine'; end if;
    v_reasons := v_reasons || jsonb_build_object('code', 'mime_mismatch',
                   'detail', 'Declared type does not match the file extension');
  end if;

  -- 4) double extension trick
  if _name ~* '\.(pdf|jpg|png|docx|mp4)\.(exe|js|scr|bat|cmd|vbs)$' then
    v_decision := 'block';
    v_reasons := v_reasons || jsonb_build_object('code', 'double_extension',
                   'detail', 'Disguised double extension');
  end if;

  return jsonb_build_object('label', v_label, 'decision', v_decision, 'reasons', v_reasons);
end $_$;


--
-- Name: file_unlink(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_unlink(_link uuid, _reason text, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare l record;
begin
  if char_length(btrim(coalesce(_reason,''))) < 8 then
    return jsonb_build_object('ok', false, 'reason', 'reason_min_8_chars');
  end if;
  select * into l from public.chat_file_links where id = _link and removed_at is null;
  if not found then return jsonb_build_object('ok', false, 'reason', 'link_not_found'); end if;

  update public.chat_file_links
     set removed_at = now(), removed_by = _user, remove_reason = btrim(_reason)
   where id = _link;

  insert into public.chat_file_link_log (file_id, link_id, action, actor_id, reason)
  values (l.file_id, _link, 'unlinked', _user, btrim(_reason));

  return jsonb_build_object('ok', true, 'removed', true);
end $$;


--
-- Name: file_version_diff(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_version_diff(_file uuid, _from integer, _to integer, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a record; b record; cap int; added text[]; removed text[]; kept int := 0;
begin
  if not public.chat_feature_ok(_user, 'file_version_diff') then
    return jsonb_build_object('allowed', false, 'reason', 'plan_not_entitled');
  end if;
  cap := coalesce((select limit_value from public.chat_phase_entitlements e
                    where e.feature = 'file_version_diff'
                      and e.plan = (public.chat_feature_allowed(_user, 'file_version_diff')->>'plan')
                  ), 200);

  select t.* into a from public.chat_file_version_text t
    join public.chat_file_versions v on v.id = t.version_id
   where t.file_id = _file and v.version = _from;
  select t.* into b from public.chat_file_version_text t
    join public.chat_file_versions v on v.id = t.version_id
   where t.file_id = _file and v.version = _to;

  if a.version_id is null or b.version_id is null then
    return jsonb_build_object('allowed', true, 'diff_available', false,
      'reason', 'text not captured for one or both versions',
      'diff_method', 'line_presence');
  end if;

  select array(select l from unnest(b.lines) l except select l from unnest(a.lines) l) into added;
  select array(select l from unnest(a.lines) l except select l from unnest(b.lines) l) into removed;
  select count(*) into kept from (
    select l from unnest(a.lines) l intersect select l from unnest(b.lines) l) k;

  return jsonb_build_object(
    'allowed', true, 'diff_available', true, 'diff_method', 'line_presence',
    'ai_used', false,
    'from', jsonb_build_object('version', _from, 'lines', a.line_count,
                               'sha256', a.text_sha256, 'sent_in_message', a.message_id),
    'to',   jsonb_build_object('version', _to, 'lines', b.line_count,
                               'sha256', b.text_sha256, 'sent_in_message', b.message_id),
    'unchanged_lines', kept,
    'added',   to_jsonb((select array_agg(x) from (select unnest(added) x limit cap) s)),
    'removed', to_jsonb((select array_agg(x) from (select unnest(removed) x limit cap) s)),
    'truncated', (coalesce(array_length(added,1),0) + coalesce(array_length(removed,1),0)) > cap,
    'line_cap', cap);
end $$;


--
-- Name: file_versions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_versions(_user uuid, _file uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_rows jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
           'version_id', v.id, 'version', v.version, 'bytes', v.bytes,
           'state', v.state, 'file_sha256', v.file_sha256,
           'chunk_count', v.chunk_count, 'storage_prefix', v.storage_prefix,
           'created_at', v.created_at, 'ready_at', v.ready_at
         ) order by v.version desc), '[]'::jsonb) into v_rows
    from public.chat_file_versions v
    join public.chat_files f on f.id = v.file_id
   where v.file_id = _file
     and (f.owner_id = _user
          or exists (select 1 from public.chat_participants p
                     where p.conversation_id = f.conversation_id and p.user_id = _user));
  return jsonb_build_object('file_id', _file, 'versions', v_rows);
end $$;


--
-- Name: founder_admin_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.founder_admin_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'tenants', (select count(distinct user_id) from public.admin_health_checks),
    'failing_checks', coalesce((select count(*) from public.admin_health_checks where status = 'fail'), 0),
    'self_heals_24h', coalesce((select sum(heals_24h) from public.admin_health_checks), 0),
    'open_incidents', coalesce((select count(*) from public.admin_incidents where status <> 'resolved'), 0),
    'deferred_1h', coalesce((
      select count(*) from public.admin_delivery_events
      where state in ('deferred','bounced','rejected') and at > now() - interval '1 hour'
    ), 0),
    'errors_1h', coalesce((
      select count(*) from public.admin_logs where level = 'error' and at > now() - interval '1 hour'
    ), 0),
    'storage_used_bytes', coalesce((
      select sum(used_bytes) from public.admin_storage_snapshots
      where day = (select max(day) from public.admin_storage_snapshots)
    ), 0),
    'worst_tenants', coalesce((
      select jsonb_agg(x) from (
        select user_id::text as tenant,
               count(*) filter (where status = 'fail') as failing,
               count(*) as checks
        from public.admin_health_checks
        group by user_id
        order by failing desc limit 10
      ) x
    ), '[]'::jsonb)
  );
$$;


--
-- Name: founder_analytics_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.founder_analytics_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'tenants', (select count(distinct user_id) from public.analytics_debt_daily),
    'currency', 'GBP',
    'total_debt_cost', coalesce((
      select sum(cost_of_delay) from public.analytics_debt_daily
      where day = (select max(day) from public.analytics_debt_daily)
    ), 0),
    'threads_30d', coalesce((
      select count(*) from public.analytics_thread_cost where computed_at > now() - interval '30 days'
    ), 0),
    'platform_keep_rate', coalesce((
      select round(100.0 * count(*) filter (where state = 'kept') / greatest(count(*), 1), 1)
      from public.analytics_promises where created_at > now() - interval '30 days'
    ), 0),
    'worst_tenants', coalesce((
      select jsonb_agg(x) from (
        select user_id::text as tenant, cost_of_delay as debt, waiting_people as waiting
        from public.analytics_debt_daily
        where day = (select max(day) from public.analytics_debt_daily)
        order by cost_of_delay desc limit 10
      ) x
    ), '[]'::jsonb)
  );
$$;


--
-- Name: founder_integrations_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.founder_integrations_overview() RETURNS json
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select json_build_object(
    'connections', (select count(*) from public.integration_connections),
    'needs_reauth', (select count(*) from public.integration_connections where state = 'needs_reauth'),
    'migrations_running', (select count(*) from public.integration_migrations where state = 'running'),
    'migrations_failed', (select count(*) from public.integration_migrations where state = 'failed'),
    'threads_migrated_30d', coalesce((select sum(done) from public.integration_migrations where created_at > now() - interval '30 days'), 0),
    'by_provider', coalesce((
      select json_agg(row_to_json(p)) from (
        select c.provider,
               count(*) as connections,
               count(*) filter (where c.state in ('error','needs_reauth')) as failures
        from public.integration_connections c
        group by c.provider
        order by count(*) desc
      ) p
    ), '[]'::json),
    'worst_delivery', coalesce((
      select json_agg(row_to_json(d)) from (
        select domain,
               round(100.0 * count(*) filter (where state = 'ok') / greatest(count(*), 1)) as score
        from public.delivery_checks
        group by domain
        order by 2 asc
        limit 5
      ) d
    ), '[]'::json)
  );
$$;


--
-- Name: founder_perf_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.founder_perf_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with s as (
    select user_id, duration_ms from public.perf_samples where at > now() - interval '24 hours'
  ),
  per_tenant as (
    select user_id,
           percentile_disc(0.95) within group (order by duration_ms) as p95
    from s group by user_id
  )
  select jsonb_build_object(
    'tenants', (select count(distinct user_id) from public.perf_budgets),
    'p95_ms', (select percentile_disc(0.95) within group (order by duration_ms) from s),
    'budgets_failing', (
      select count(*) from public.perf_budgets b
      where (select percentile_disc(0.95) within group (order by sm.duration_ms)
             from public.perf_samples sm
             where sm.user_id = b.user_id and sm.action = b.action
               and sm.at > now() - interval '24 hours') > b.budget_ms
    ),
    'open_regressions', (select count(*) from public.perf_regressions where state = 'open'),
    'cold_starts_24h', (select count(*) from public.perf_surface_starts
                        where cold and at > now() - interval '24 hours'),
    'ms_saved_24h', (select coalesce(sum(saved_ms), 0) from public.perf_prefetch_events
                     where outcome = 'hit' and at > now() - interval '24 hours'),
    'worst_tenants', coalesce((
      select jsonb_agg(x) from (
        select coalesce(u.email, t.user_id::text) as tenant,
               t.p95 as p95_ms,
               (select count(*) from public.perf_budgets b
                where b.user_id = t.user_id
                  and (select percentile_disc(0.95) within group (order by sm.duration_ms)
                       from public.perf_samples sm
                       where sm.user_id = b.user_id and sm.action = b.action
                         and sm.at > now() - interval '24 hours') > b.budget_ms) as failing
        from per_tenant t
        left join auth.users u on u.id = t.user_id
        order by t.p95 desc nulls last
        limit 10
      ) x), '[]'::jsonb)
  );
$$;


--
-- Name: founder_security_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.founder_security_overview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'tenants', (select count(distinct user_id) from security_devices),
    'devices_blocked', (select count(*) from security_devices where state = 'blocked'),
    'open_anomalies', (select count(*) from security_anomalies where state = 'open'),
    'frozen_accounts', (select count(distinct user_id) from security_anomalies where state = 'frozen'),
    'failed_logins_24h', (select count(*) from security_login_events
                          where outcome in ('failed','blocked') and at > now() - interval '24 hours'),
    'kill_switches_30d', (select count(*) from security_kill_switches
                          where created_at > now() - interval '30 days'),
    'worst_tenants', coalesce((
      select jsonb_agg(x) from (
        select a.user_id::text as tenant,
               count(*) filter (where a.state <> 'cleared') as anomalies,
               (select count(*) from security_login_events e
                where e.user_id = a.user_id and e.outcome in ('failed','blocked')
                  and e.at > now() - interval '24 hours') as failed_logins
        from security_anomalies a
        group by a.user_id
        order by anomalies desc
        limit 8
      ) x), '[]'::jsonb)
  );
$$;


--
-- Name: get_billing_invoices(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_invoices(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare rows jsonb;
begin
  -- ── SECURITY ───────────────────────────────────────────────────────────────
  if auth.uid() is distinct from p_user_id
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'forbidden';
  end if;

  if p_user_id is null then
    return jsonb_build_object('invoices', '[]'::jsonb);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id',           wi.id,
        'number',       coalesce(wi.number, 'INV-' || to_char(wi.issued_at, 'YYYYMMDD')),
        'state',        wi.status,
        'subtotal',     wi.subtotal,
        'tax',          wi.tax,
        'total',        wi.total,
        'currency',     wi.currency,
        'period_start', wi.period_start,
        'period_end',   wi.period_end,
        'issued_at',    wi.issued_at,
        'paid_at',      wi.paid_at,
        'pdf_url',      wi.pdf_url
      )
      order by wi.issued_at desc
    ),
    '[]'::jsonb
  )
  into rows
  from public.workspace_invoices wi
  where wi.user_id = p_user_id;

  return jsonb_build_object('invoices', rows);
end;
$$;


--
-- Name: get_billing_subscription(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_subscription(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  raw          jsonb;
  -- polar_billing_state() returns key 'plan' whose value is the product_key
  -- e.g. "POLAR_PRODUCT_PLAN_PRO_MONTHLY" — NOT a clean plan_id.
  product_key_raw text;
  plan_id      text;   -- clean: basic | pro | business | business_pro
  kind         text;   -- personal | business (from account_profiles)
  intv         text;   -- month | year
  price        integer;
  storage      integer;
  display_name text;
  st           text;
  seats        integer;
  renews_at    timestamptz;
  cancel_at    timestamptz;
  lifetime     boolean := false;
begin
  -- ── SECURITY: only own row or service_role ────────────────────────────────
  if auth.uid() is distinct from p_user_id
     and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'forbidden';
  end if;

  if p_user_id is null then return null; end if;

  -- Family accounts (founder ka parivar) = asli buyer jaisa SAB KUCH, farq sirf itna ke unka plan muft aur umar bhar ka hai.
  -- Billing page "£/month" ki jagah "Lifetime access" dikhata hai. Koi alag code path nahi.
  select exists (
    select 1 from auth.users u
    join public.family_accounts f on lower(f.email) = lower(u.email)
    where u.id = p_user_id
  ) into lifetime;

  -- ── Step 1: account_kind — personal vs business [Phase 65] ───────────────
  select lower(nullif(btrim(coalesce(
    p.preferences->>'workspace_kind',
    ''
  )), ''))
  into kind
  from public.account_profiles p
  where p.user_id = p_user_id;

  -- ── Step 2: canonical plan_id from entitlement_state [Phase 36] ──────────
  select lower(nullif(btrim(es.plan), ''))
  into plan_id
  from public.entitlement_state es
  where es.user_id = p_user_id
  limit 1;

  -- ── Step 3: polar_billing_state() — Phase 50, no-touch ───────────────────
  --    Returns: { "plan": "<product_key_string>", "status": ..., "seats": ... }
  --    NOTE: key is literally "plan" even though value is a product_key.
  raw := public.polar_billing_state(p_user_id);
  product_key_raw := lower(coalesce(raw ->> 'plan', ''));
  st              := coalesce(raw ->> 'status', 'none');
  seats           := coalesce((raw ->> 'seats')::integer, 1);
  renews_at       := (raw ->> 'current_period_end')::timestamptz;

  -- ── Step 4: parse product_key → plan_id (fallback if entitlement empty) ───
  if plan_id is null or plan_id = '' then
    plan_id := case
      when product_key_raw ilike '%business_pro%'
        or product_key_raw ilike '%businesspro%'  then 'business_pro'
      when product_key_raw ilike '%business%'     then 'business'
      when product_key_raw ilike '%pro%'          then 'pro'
      when product_key_raw ilike '%basic%'        then 'basic'
      else null
    end;
  end if;

  -- ── Step 5: default kind from plan if still unknown ──────────────────────
  if kind is null or kind = '' then
    kind := case
      when plan_id in ('basic', 'pro') then 'personal'
      when plan_id in ('business', 'business_pro') then 'business'
      else 'personal'
    end;
  end if;

  -- ── Step 6: billing interval from product_key ────────────────────────────
  intv := case when product_key_raw ilike '%yearly%' then 'year' else 'month' end;

  -- ── Step 7: kind-aware display name + price + storage ────────────────────
  --    Billing display only. Feature power is plan-surface.ts featurePlan().
  --    Personal Pro = same POWER as Business Pro, but kind stays personal.
  if kind = 'personal' then
    case plan_id
      when 'basic' then
        display_name := 'Personal Basic';
        price        := 23;
        storage      := 5;
      when 'pro' then
        display_name := 'Personal Pro';
        price        := 46;
        storage      := 10;
      when 'business' then
        -- Personal account on Business SKU → treated as Personal Pro
        display_name := 'Personal Pro';
        price        := 46;
        storage      := 10;
      when 'business_pro' then
        display_name := 'Personal Premium';
        price        := 2850;
        storage      := null;  -- 1TB pooled
      else
        display_name := 'Personal Basic';
        price        := 23;
        storage      := 5;
    end case;
  else
    -- business kind
    case plan_id
      when 'business' then
        display_name := 'Business';
        price        := 97;
        storage      := 25;
      when 'business_pro' then
        display_name := 'Business Pro';
        price        := 2850;
        storage      := null;  -- 1TB pooled
      when 'pro' then
        display_name := 'Pro';
        price        := 46;
        storage      := 10;
      else
        -- E40: Business account par Basic ab Basic hi dikhta hai (pehle £97 / 25 GB likha aata tha)
        display_name := 'Basic';
        price        := 23;
        storage      := 5;
    end case;
  end if;

  -- ── Step 7b (E40): saalana plan => saal ki asli raqam (plans.ts), "£23 / year" jaisi galti nahi ──────────
  if intv = 'year' and price is not null then
    price := case price when 23 then 253 when 46 then 506 when 97 then 970 when 2850 then 28500 else price * 12 end;
  end if;

  -- ── Step 8: map Rust :3400 status → UI state ─────────────────────────────
  st := case st
    when 'active'   then 'active'
    when 'past_due' then 'past_due'
    when 'grace'    then 'past_due'
    when 'canceled' then 'cancelled'
    when 'revoked'  then 'cancelled'
    else 'none'
  end;

  cancel_at := case when st = 'cancelled' then renews_at else null end;

  -- No subscription at all
  if plan_id is null then
    return jsonb_build_object(
      'plan',                   null,
      'kind',                   coalesce(kind, 'personal'),
      'display_name',           null,
      'state',                  'none',
      'price_per_seat',         0,
      'currency',               'GBP',
      'interval',               'month',
      'seats',                  0,
      'seats_used',             0,
      'storage_per_mailbox_gb', null,
      'renews_at',              null,
      'cancel_at',              null,
      'lifetime',               lifetime
    );
  end if;

  return jsonb_build_object(
    'plan',                   plan_id,
    'kind',                   kind,
    'display_name',           display_name,
    'state',                  st,
    'price_per_seat',         price,
    'currency',               'GBP',
    'interval',               intv,
    'seats',                  seats,
    'seats_used',             1,
    'storage_per_mailbox_gb', storage,
    'renews_at',              renews_at,
    'cancel_at',              cancel_at,
    'lifetime',               lifetime
  );
end;
$$;


--
-- Name: glitch_alerts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.glitch_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    fingerprint text NOT NULL,
    summary text NOT NULL,
    severity text DEFAULT 'error'::text NOT NULL,
    route text,
    first_seen timestamp with time zone DEFAULT now() NOT NULL,
    last_seen timestamp with time zone DEFAULT now() NOT NULL,
    occurrences integer DEFAULT 1 NOT NULL,
    sessions integer DEFAULT 1 NOT NULL,
    recording_url text,
    status text DEFAULT 'pending'::text NOT NULL,
    sent_at timestamp with time zone,
    channel_ref text,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: glitch_alert_due(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.glitch_alert_due(p_limit integer DEFAULT 10) RETURNS SETOF public.glitch_alerts
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select * from public.glitch_alerts
  where status = 'pending' and last_seen < now() - interval '20 seconds'
  order by severity desc, last_seen asc
  limit greatest(coalesce(p_limit,10), 1)
$$;


--
-- Name: glitch_alert_mark(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.glitch_alert_mark(p_id uuid, p_status text, p_ref text DEFAULT NULL::text, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.glitch_alerts
  set status = case when p_status in ('sent','failed','muted') then p_status else 'pending' end,
      sent_at = case when p_status = 'sent' then now() else sent_at end,
      channel_ref = coalesce(p_ref, channel_ref),
      last_error = p_error
  where id = p_id
$$;


--
-- Name: glitch_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.glitch_health() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'logs_24h', (select count(*) from public.customer_glitch_logs where occurred_at > now() - interval '24 hours'),
    'triggers_24h', (select count(*) from public.feedback_user_triggers where occurred_at > now() - interval '24 hours'),
    'alerts_pending', (select count(*) from public.glitch_alerts where status = 'pending'),
    'alerts_sent_24h', (select count(*) from public.glitch_alerts where status = 'sent' and sent_at > now() - interval '24 hours'),
    'alerts_muted_24h', (select count(*) from public.glitch_alerts where status = 'muted' and created_at > now() - interval '24 hours'),
    'top_24h', (select coalesce(jsonb_agg(t), '[]'::jsonb) from (
        select fingerprint, count(*) as hits, max(occurred_at) as last_seen
        from public.customer_glitch_logs
        where occurred_at > now() - interval '24 hours'
        group by fingerprint order by hits desc limit 10) t)
  )
$$;


--
-- Name: glitch_is_noise(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.glitch_is_noise(p_kind text, p_message text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.glitch_noise_rules r
    where r.active
      and r.action = 'ignore'
      and (r.kind is null or r.kind = p_kind)
      and coalesce(p_message,'') ilike r.message_like
  )
$$;


--
-- Name: glitch_log(text, text, text, text, text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.glitch_log(p_kind text, p_message text, p_severity text DEFAULT 'error'::text, p_route text DEFAULT NULL::text, p_fingerprint text DEFAULT NULL::text, p_stack text DEFAULT NULL::text, p_session_id text DEFAULT NULL::text, p_recording_url text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_fp text := coalesce(nullif(p_fingerprint,''), p_kind || '|' || left(coalesce(p_message,'unknown'), 120));
  v_sev text := case when p_severity in ('info','warning','error','critical') then p_severity else 'error' end;
  v_recent int;
  v_alert uuid;
  v_id uuid;
begin
  if public.glitch_is_noise(p_kind, p_message) then
    return jsonb_build_object('stored', false, 'alert', false, 'reason', 'noise_rule');
  end if;

  insert into public.customer_glitch_logs
    (kind, severity, route, message, fingerprint, stack, user_id, session_id, recording_url, meta)
  values (p_kind, v_sev, p_route, left(coalesce(p_message,'unknown'), 2000), v_fp,
          left(coalesce(p_stack,''), 6000), p_user_id, p_session_id, p_recording_url,
          coalesce(p_meta, '{}'::jsonb))
  returning id into v_id;

  -- alert sirf error/critical par
  if v_sev not in ('error','critical') then
    return jsonb_build_object('stored', true, 'id', v_id, 'alert', false, 'reason', 'severity_below_alert');
  end if;

  -- rate cap: pichle 1 ghante mein 12 se zyada alert nahi
  select count(*) into v_recent
  from public.glitch_alerts
  where created_at > now() - interval '1 hour' and status in ('pending','sent');
  if v_recent >= 12 then
    insert into public.glitch_alerts (fingerprint, summary, severity, route, recording_url, status)
    values (v_fp, left(coalesce(p_message,'unknown'), 300), v_sev, p_route, p_recording_url, 'muted')
    on conflict do nothing;
    return jsonb_build_object('stored', true, 'id', v_id, 'alert', false, 'reason', 'hourly_cap');
  end if;

  -- same fingerprint = ek hi alert, sirf counter barhta hai
  insert into public.glitch_alerts (fingerprint, summary, severity, route, recording_url)
  values (v_fp, left(coalesce(p_message,'unknown'), 300), v_sev, p_route, p_recording_url)
  on conflict (fingerprint) where status = 'pending'
  do update set occurrences = public.glitch_alerts.occurrences + 1,
                last_seen = now(),
                sessions = public.glitch_alerts.sessions
                  + case when p_session_id is null then 0 else 1 end,
                severity = greatest_severity(public.glitch_alerts.severity, v_sev)
  returning id into v_alert;

  update public.customer_glitch_logs set alerted = true where id = v_id;
  return jsonb_build_object('stored', true, 'id', v_id, 'alert', true, 'alert_id', v_alert);
end $$;


--
-- Name: glitch_trigger_log(text, text, text, integer, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.glitch_trigger_log(p_trigger_type text, p_route text DEFAULT NULL::text, p_target_label text DEFAULT NULL::text, p_hit_count integer DEFAULT 1, p_session_id text DEFAULT NULL::text, p_recording_url text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_sessions int;
  v_res jsonb;
begin
  insert into public.feedback_user_triggers
    (trigger_type, route, target_label, hit_count, user_id, session_id, recording_url, meta)
  values (p_trigger_type, p_route, left(coalesce(p_target_label,'unknown'), 200),
          greatest(coalesce(p_hit_count,1),1), p_user_id, p_session_id, p_recording_url,
          coalesce(p_meta,'{}'::jsonb));

  select count(distinct coalesce(session_id, id::text)) into v_sessions
  from public.feedback_user_triggers
  where trigger_type = p_trigger_type
    and coalesce(target_label,'') = coalesce(left(coalesce(p_target_label,'unknown'),200),'')
    and occurred_at > now() - interval '15 minutes';

  if v_sessions < 3 then
    return jsonb_build_object('stored', true, 'alert', false, 'reason', 'below_threshold',
                              'sessions', v_sessions);
  end if;

  v_res := public.glitch_log(
    p_kind => p_trigger_type,
    p_message => format('%s x%s on "%s" (%s sessions / 15 min)',
                        p_trigger_type, p_hit_count, coalesce(p_target_label,'unknown'), v_sessions),
    p_severity => 'error',
    p_route => p_route,
    p_fingerprint => p_trigger_type || '|' || coalesce(p_target_label,'unknown'),
    p_session_id => p_session_id,
    p_recording_url => p_recording_url,
    p_user_id => p_user_id,
    p_meta => coalesce(p_meta,'{}'::jsonb) || jsonb_build_object('sessions_15m', v_sessions)
  );
  return v_res || jsonb_build_object('sessions', v_sessions);
end $$;


--
-- Name: greatest_severity(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.greatest_severity(a text, b text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select case when 'critical' in (a,b) then 'critical'
              when 'error' in (a,b) then 'error'
              when 'warning' in (a,b) then 'warning'
              else 'info' end
$$;


--
-- Name: handover_assign(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_assign(_actor uuid, _pack uuid, _incoming uuid, _reason text, _item uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare p record;
begin
  select * into p from public.chat_handover_packs where id = _pack;
  if not found then return jsonb_build_object('ok', false, 'error', 'pack_not_found'); end if;
  if coalesce(length(trim(_reason)), 0) < 8 then
    return jsonb_build_object('ok', false, 'error', '8_char_reason_required');
  end if;
  if not exists (select 1 from public.chat_members
                  where user_id = _incoming and workspace_id = p.workspace_id) then
    return jsonb_build_object('ok', false, 'error', 'incoming_user_not_in_workspace');
  end if;

  if _item is null then
    update public.chat_handover_packs
       set incoming_user = _incoming, state = 'assigned' where id = _pack;
    update public.chat_handover_items set assigned_to = _incoming where pack_id = _pack;
  else
    update public.chat_handover_items set assigned_to = _incoming
     where id = _item and pack_id = _pack;
  end if;

  insert into public.chat_handover_log (pack_id, item_id, action, actor_id, reason)
  values (_pack, _item, 'assigned', _actor, _reason);

  return jsonb_build_object('ok', true, 'pack_id', _pack, 'incoming_user', _incoming);
end $$;


--
-- Name: handover_complete(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_complete(_actor uuid, _pack uuid, _reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare p record; v_unassigned int;
begin
  select * into p from public.chat_handover_packs where id = _pack;
  if not found then return jsonb_build_object('ok', false, 'error', 'pack_not_found'); end if;
  if coalesce(length(trim(_reason)), 0) < 8 then
    return jsonb_build_object('ok', false, 'error', '8_char_reason_required');
  end if;
  select count(*) into v_unassigned from public.chat_handover_items
   where pack_id = _pack and assigned_to is null;
  if v_unassigned > 0 then
    return jsonb_build_object('ok', false, 'error', 'items_without_owner', 'count', v_unassigned);
  end if;

  update public.chat_handover_packs
     set state = 'completed', completed_at = now() where id = _pack;
  update public.chat_handover_items set accepted_at = coalesce(accepted_at, now())
   where pack_id = _pack;
  insert into public.chat_handover_log (pack_id, action, actor_id, reason)
  values (_pack, 'completed', _actor, _reason);

  return jsonb_build_object('ok', true, 'pack_id', _pack, 'state', 'completed');
end $$;


--
-- Name: handover_pack_board(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_pack_board(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid; v_rows jsonb;
begin
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then return jsonb_build_object('packs', '[]'::jsonb, 'error', 'no_workspace'); end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'pack_id', p.id, 'state', p.state, 'scope', p.scope,
           'outgoing', uo.email, 'incoming', ui.email, 'built_at', p.built_at,
           'items', (select count(*) from public.chat_handover_items i where i.pack_id = p.id),
           'overdue', (select count(*) from public.chat_handover_items i
                        where i.pack_id = p.id and i.status = 'overdue'))
           order by p.built_at desc), '[]'::jsonb)
    into v_rows
    from public.chat_handover_packs p
    join auth.users uo on uo.id = p.outgoing_user
    left join auth.users ui on ui.id = p.incoming_user
   where p.workspace_id = v_ws
     and (p.built_by = _user or p.outgoing_user = _user or p.incoming_user = _user);

  return jsonb_build_object('packs', v_rows,
    'allowed', public.chat_feature_ok(_user, 'handover_pack'));
end $$;


--
-- Name: handover_pack_build(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_pack_build(_actor uuid, _outgoing uuid, _scope text DEFAULT 'workspace'::text, _scope_ref uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid; v_pack uuid; r record; v_count int := 0;
begin
  if not public.chat_feature_ok(_actor, 'handover_pack') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;
  select workspace_id into v_ws from public.chat_members where user_id = _actor limit 1;
  if v_ws is null then return jsonb_build_object('ok', false, 'error', 'no_workspace'); end if;
  if not exists (select 1 from public.chat_members where user_id = _outgoing and workspace_id = v_ws) then
    return jsonb_build_object('ok', false, 'error', 'outgoing_user_not_in_workspace');
  end if;

  insert into public.chat_handover_packs (workspace_id, outgoing_user, scope, scope_ref, built_by)
  values (v_ws, _outgoing, coalesce(_scope, 'workspace'), _scope_ref, _actor)
  returning id into v_pack;

  -- open conversations (jahan outgoing user participant hai)
  for r in
    select c.id, coalesce(c.subject, 'Direct conversation') as title, c.last_message_at
      from public.chat_conversations c
      join public.chat_participants p on p.conversation_id = c.id and p.user_id = _outgoing
     where c.workspace_id = v_ws
       and (_scope <> 'conversation' or c.id = _scope_ref)
  loop
    insert into public.chat_handover_items (pack_id, category, status, object_type, object_id,
      title, detail, source, evidence)
    values (v_pack, 'conversation', 'pending', 'conversation', r.id, r.title,
      'Active conversation with the outgoing person.', 'chat_conversations',
      jsonb_build_object('last_message_at', r.last_message_at))
    on conflict do nothing;
    v_count := v_count + 1;
  end loop;

  -- open tasks / promises (owner = outgoing)
  for r in
    select w.id, w.kind, w.title, w.due_at, w.conversation_id, w.state
      from public.chat_work_items w
     where w.workspace_id = v_ws and w.owner_user_id = _outgoing and w.state = 'open'
  loop
    insert into public.chat_handover_items (pack_id, category, status, object_type, object_id,
      title, detail, source, evidence, due_at)
    values (v_pack,
      case when r.kind = 'promise' then 'promise' else 'task' end,
      case when r.due_at is not null and r.due_at < now() then 'overdue' else 'pending' end,
      'work_item', r.id, r.title,
      case when r.due_at is null then 'No deadline recorded.' else null end,
      'chat_work_items',
      jsonb_build_object('conversation_id', r.conversation_id, 'kind', r.kind, 'state', r.state),
      r.due_at)
    on conflict do nothing;
    v_count := v_count + 1;
  end loop;

  -- open dependencies (sirf insaani depends_on)
  for r in
    select w.id, w.title, b.id as blocker_id, b.title as blocker_title, b.state as blocker_state
      from public.chat_work_items w
      join public.chat_work_items b on b.id = w.depends_on
     where w.workspace_id = v_ws and w.owner_user_id = _outgoing
       and w.state = 'open' and b.state = 'open'
  loop
    insert into public.chat_handover_items (pack_id, category, status, object_type, object_id,
      title, detail, source, evidence)
    values (v_pack, 'dependency', 'open_dependency', 'work_item', r.id, r.title,
      'Blocked by: ' || r.blocker_title, 'chat_work_items.depends_on',
      jsonb_build_object('blocker_id', r.blocker_id, 'blocker_state', r.blocker_state))
    on conflict do nothing;
    v_count := v_count + 1;
  end loop;

  -- historical decisions (maker = outgoing)
  for r in
    select d.id, d.title, d.decided_at, d.version, d.state, d.conversation_id
      from public.chat_decisions d
     where d.workspace_id = v_ws and d.made_by = _outgoing
  loop
    insert into public.chat_handover_items (pack_id, category, status, object_type, object_id,
      title, detail, source, evidence)
    values (v_pack, 'decision', 'historical_decision', 'decision', r.id, r.title,
      'Version ' || r.version || ' · ' || r.state, 'chat_decisions',
      jsonb_build_object('decided_at', r.decided_at, 'conversation_id', r.conversation_id,
                         'version', r.version, 'state', r.state))
    on conflict do nothing;
    v_count := v_count + 1;
  end loop;

  -- files (uploaded by outgoing, ready version = confirmed fact)
  for r in
    select f.id, f.name, v.id as version_id, v.state, v.ready_at
      from public.chat_files f
      join public.chat_file_versions v on v.file_id = f.id and v.version = f.current_version
     where f.workspace_id = v_ws and f.owner_id = _outgoing and f.deleted_at is null
  loop
    insert into public.chat_handover_items (pack_id, category, status, object_type, object_id,
      title, detail, source, evidence)
    values (v_pack, 'file',
      case when r.state = 'ready' then 'confirmed_fact' else 'pending' end,
      'file', r.id, r.name, 'Version state: ' || r.state, 'chat_file_versions',
      jsonb_build_object('version_id', r.version_id, 'ready_at', r.ready_at))
    on conflict do nothing;
    v_count := v_count + 1;
  end loop;

  insert into public.chat_handover_log (pack_id, action, actor_id, reason)
  values (v_pack, 'built', _actor, 'items: ' || v_count);

  return jsonb_build_object('ok', true, 'pack_id', v_pack, 'items', v_count,
    'fabricates_missing_context', false);
end $$;


--
-- Name: handover_pack_get(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handover_pack_get(_pack uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare p record; v_items jsonb; v_log jsonb;
begin
  select * into p from public.chat_handover_packs where id = _pack;
  if not found then return jsonb_build_object('error', 'pack_not_found'); end if;
  if _user not in (p.built_by, p.outgoing_user, coalesce(p.incoming_user, p.built_by))
     and not public.chat_feature_ok(_user, 'handover_pack') then
    return jsonb_build_object('error', 'not_authorized');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', i.id, 'category', i.category, 'status', i.status,
           'object_type', i.object_type, 'object_id', i.object_id,
           'title', i.title, 'detail', i.detail, 'source', i.source,
           'evidence', i.evidence, 'due_at', i.due_at,
           'assigned_to', i.assigned_to, 'accepted_at', i.accepted_at)
           order by i.category, i.due_at nulls last), '[]'::jsonb)
    into v_items from public.chat_handover_items i where i.pack_id = _pack;

  select coalesce(jsonb_agg(jsonb_build_object('action', l.action, 'at', l.at,
           'reason', l.reason) order by l.id desc), '[]'::jsonb)
    into v_log from public.chat_handover_log l where l.pack_id = _pack;

  return jsonb_build_object('pack_id', p.id, 'state', p.state, 'scope', p.scope,
    'outgoing_user', p.outgoing_user, 'incoming_user', p.incoming_user,
    'built_at', p.built_at, 'completed_at', p.completed_at,
    'items', v_items, 'log', v_log,
    'statuses', jsonb_build_array('confirmed_fact','pending','overdue',
                                  'historical_decision','open_dependency'),
    'fabricates_missing_context', false);
end $$;


