--
-- Name: knowledge_recall(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.knowledge_recall(_user_id uuid, _query text, _scope text DEFAULT NULL::text, _limit integer DEFAULT 8) RETURNS TABLE(chunk_id uuid, document_id uuid, doc_title text, scope text, excerpt text, score real)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id,
         d.id,
         d.title,
         c.scope,
         left(c.content, 320),
         (similarity(c.content, _query)
           + case when d.pinned then 0.15 else 0 end
           + greatest(0, 0.1 - (extract(epoch from (now() - d.updated_at)) / 2592000.0) * 0.1)
         )::real as score
  from public.knowledge_chunks c
  join public.knowledge_documents d on d.id = c.document_id
  where c.user_id = _user_id
    and (_scope is null or c.scope = _scope)
    and (c.content ilike '%' || _query || '%' or similarity(c.content, _query) > 0.08)
  order by score desc, d.updated_at desc
  limit greatest(1, least(_limit, 25));
$$;


--
-- Name: leo_memory_prune(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leo_memory_prune() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cap    bigint;
  killed integer := 0;
begin
  select max_memories into cap from public.agent_memory_config where agent = 'leo';
  if cap is null then cap := 3000000; end if;

  with ranked as (
    select id, row_number() over (
             order by pinned desc, importance desc, access_count desc, created_at desc
           ) as rn
      from public.leo_memory_vectors
  )
  delete from public.leo_memory_vectors m
   using ranked r
   where m.id = r.id and r.rn > cap and m.pinned = false;

  get diagnostics killed = row_count;
  return killed;
end $$;


--
-- Name: leo_recall(uuid, extensions.vector, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leo_recall(p_user_id uuid, p_embedding extensions.vector, p_limit integer DEFAULT 12) RETURNS TABLE(id uuid, content text, summary text, layer text, importance double precision, created_at timestamp with time zone, score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.id, m.content, m.summary, m.layer, m.importance, m.created_at,
         1 - (m.embedding <=> p_embedding) as score
    from public.leo_memory_vectors m
   where m.user_id = p_user_id
     and m.embedding is not null
   order by m.embedding <=> p_embedding
   limit p_limit
$$;


