--
-- Name: mail_attach_commit(uuid, uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_commit(_user uuid, _org uuid, _ids uuid[], _message uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare n int := 0;
begin
  if to_regclass('public.mail_attachments') is null or to_regclass('public.mail_messages') is null then
    return jsonb_build_object('ok', false, 'error', 'no_mail_tables');
  end if;
  if not exists (select 1 from public.mail_messages m where m.id = _message and m.org_id = _org) then
    return jsonb_build_object('ok', false, 'error', 'message_not_in_org');
  end if;
  insert into public.mail_attachments (message_id, org_id, filename, mime_type, size_bytes, disk_path, sha256, scan)
  select _message, a.org_id, a.filename, a.mime_type, a.size_bytes, b.rel_path, a.sha256, b.scan
    from public.mail_outbound_attachments a
    join public.org_attachment_blobs b on b.org_id = a.org_id and b.sha256 = a.sha256
   where a.id = any(coalesce(_ids, '{}')) and a.user_id = _user and a.org_id = _org
   order by a.created_at;
  get diagnostics n = row_count;
  delete from public.mail_outbound_attachments a
   where a.id = any(coalesce(_ids, '{}')) and a.user_id = _user and a.org_id = _org;
  update public.org_attachment_blobs b set touched_at = now()
   where b.org_id = _org and b.sha256 in (select x.sha256 from public.mail_attachments x where x.message_id = _message and x.sha256 is not null);
  return jsonb_build_object('ok', true, 'attached', n);
end $$;


--
-- Name: mail_attach_ctx(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_ctx(_user uuid, _org uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  org    uuid;
  plan   text := 'basic';
  sp     record;
  st     text := null;
  maxsend bigint := 26214400;
  ceil_  bigint := public._ma_limit('server_ceiling_bytes', 7000000);
  lim    bigint := 5368709120;
  used   bigint := 0;
  isf    boolean := false;
begin
  if _user is null or not exists (select 1 from auth.users where id = _user) then
    return jsonb_build_object('ok', false, 'error', 'unauthorized');
  end if;

  if to_regclass('public.account_integrity') is not null then
    select i.state into st from public.account_integrity i where i.user_id = _user;
    if st in ('blocked', 'purged') then return jsonb_build_object('ok', false, 'error', 'account_blocked'); end if;
  end if;

  if to_regclass('public.org_members') is null then
    return jsonb_build_object('ok', false, 'error', 'no_workspace');
  end if;
  if _org is not null and exists (select 1 from public.org_members m
                                   where m.user_id = _user and m.org_id = _org
                                     and coalesce(m.status::text, 'active') <> 'revoked') then
    org := _org;
  else
    select m.org_id into org from public.org_members m
     where m.user_id = _user and coalesce(m.status::text, 'active') <> 'revoked'
     order by m.org_id limit 1;
  end if;
  if org is null then return jsonb_build_object('ok', false, 'error', 'no_workspace'); end if;

  if to_regprocedure('public.org_plan_of(uuid)') is not null then
    plan := coalesce(public.org_plan_of(org), 'basic');
  end if;
  if to_regclass('public.founder_accounts') is not null then
    select exists (select 1 from public.org_members m join public.founder_accounts f on f.user_id = m.user_id
                    where m.org_id = org) into isf;
    if isf then plan := 'business_pro'; end if;
  end if;

  if to_regclass('public.storage_plans') is not null then
    select * into sp from public.storage_plans where plan_id = plan;
    if sp.plan_id is null then select * into sp from public.storage_plans where plan_id = 'basic'; end if;
    if sp.plan_id is not null then
      maxsend := sp.max_send_bytes;
      lim := coalesce(sp.pooled_bytes, sp.per_mailbox_bytes * greatest(coalesce(sp.mailbox_limit, 1), 1), lim);
    end if;
  end if;

  select coalesce(sum(b.size_bytes), 0) into used from public.org_attachment_blobs b where b.org_id = org;

  return jsonb_build_object(
    'ok', true, 'org_id', org, 'plan', plan,
    'message_cap_bytes', least(maxsend, ceil_),
    'plan_max_send_bytes', maxsend,
    'server_ceiling_bytes', ceil_,
    'max_files', public._ma_limit('max_files', 10),
    'org_limit_bytes', lim,
    'org_used_bytes', used);
end $$;


--
-- Name: mail_attach_gc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_gc() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  ttl   int := public._ma_limit('staged_ttl_hours', 24);
  grace int := public._ma_limit('blob_grace_days', 2);
  ns    int := 0;
  paths text[] := '{}';
begin
  if to_regclass('public.mail_scheduled') is not null
     and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'mail_scheduled' and column_name = 'attachment_ids') then
    delete from public.mail_outbound_attachments a
     where a.created_at < now() - make_interval(hours => ttl)
       and not exists (select 1 from public.mail_scheduled s
                        where s.attachment_ids @> array[a.id] and s.status in ('holding', 'queued'));
  else
    delete from public.mail_outbound_attachments a where a.created_at < now() - make_interval(hours => ttl);
  end if;
  get diagnostics ns = row_count;

  with gone as (
    delete from public.org_attachment_blobs b
     where b.touched_at < now() - make_interval(days => grace)
       and not exists (select 1 from public.mail_outbound_attachments a where a.org_id = b.org_id and a.sha256 = b.sha256)
       and (to_regclass('public.mail_attachments') is null
            or not exists (select 1 from public.mail_attachments m where m.org_id = b.org_id and m.sha256 = b.sha256))
    returning b.rel_path
  )
  select coalesce(array_agg(rel_path), '{}') into paths from gone;

  return jsonb_build_object('ok', true, 'staged_removed', ns, 'paths', to_jsonb(paths));
end $$;


--
-- Name: mail_attach_inbound_register(uuid, uuid, integer, text, text, bigint, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_inbound_register(_org uuid, _message uuid, _ordinal integer, _filename text, _mime text, _size bigint, _sha256 text, _rel_path text, _scan jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  fname    text := left(coalesce(nullif(btrim(_filename), ''), 'file'), 255);
  mime     text := left(coalesce(nullif(btrim(_mime), ''), 'application/octet-stream'), 120);
  scan     jsonb := coalesce(_scan, '{}'::jsonb);
  blob     public.org_attachment_blobs;
  inserted boolean := false;
  used     bigint;
  rid      uuid;
  stored   boolean := false;
  why      text := null;
begin
  if _org is null or _message is null then return jsonb_build_object('ok', false, 'error', 'bad_args'); end if;
  if to_regclass('public.mail_attachments') is null or to_regclass('public.mail_messages') is null then
    return jsonb_build_object('ok', false, 'error', 'no_mail_tables');
  end if;
  if not exists (select 1 from public.mail_messages m where m.id = _message and m.org_id = _org) then
    return jsonb_build_object('ok', false, 'error', 'message_not_in_org');
  end if;
  if _size is null or _size < 0 then return jsonb_build_object('ok', false, 'error', 'bad_size'); end if;
  if _rel_path is not null then
    if _sha256 is null or _sha256 !~ '^[0-9a-f]{64}$' then return jsonb_build_object('ok', false, 'error', 'bad_hash'); end if;
    if _rel_path !~ '^[0-9a-f-]{36}/[0-9a-f]{2}/[0-9a-f]{64}-[0-9a-f]{8}$' or split_part(_rel_path, '/', 1) <> _org::text then
      return jsonb_build_object('ok', false, 'error', 'bad_path');
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtext('mail_attach:' || _org::text));

  if _rel_path is null then
    why := coalesce(nullif(scan->>'reason', ''), case when scan->>'clamd' = 'found' then 'infected' else 'not_stored' end);
  else
    select * into blob from public.org_attachment_blobs where org_id = _org and sha256 = _sha256;
    if blob.sha256 is null then
      select coalesce(sum(b.size_bytes), 0) into used from public.org_attachment_blobs b where b.org_id = _org;
      if used + _size > public.mail_attach_org_limit(_org) then
        why := 'org_quota_full';
      else
        insert into public.org_attachment_blobs (org_id, sha256, size_bytes, rel_path, scan)
        values (_org, _sha256, _size, _rel_path, scan) returning * into blob;
        inserted := true;
        stored := true;
      end if;
    else
      update public.org_attachment_blobs set touched_at = now() where org_id = _org and sha256 = _sha256;
      stored := true;
    end if;
  end if;

  if not stored then scan := scan || jsonb_build_object('stored', false, 'reason', why); end if;

  -- mojooda row (ingest ne naam/size se banayi) — usi naam ki ordinal-wi row; na mile to nayi
  select x.id into rid from (
    select a.id, row_number() over (order by a.created_at, a.id) - 1 as rn
      from public.mail_attachments a where a.message_id = _message and a.filename = fname) x
   where x.rn = _ordinal;
  if rid is null then
    insert into public.mail_attachments (message_id, org_id, filename, mime_type, size_bytes, disk_path, sha256, scan)
    values (_message, _org, fname, mime, _size, case when stored then blob.rel_path end, case when stored then blob.sha256 end, scan);
  else
    update public.mail_attachments
       set org_id = _org, size_bytes = _size, mime_type = coalesce(mime_type, mime),
           disk_path = case when stored then blob.rel_path end,
           sha256 = case when stored then blob.sha256 end,
           scan = scan_new
      from (select scan as scan_new) s
     where id = rid;
  end if;

  return jsonb_build_object('ok', true, 'stored', stored, 'deduped', stored and not inserted,
                            'rel_path', case when stored then blob.rel_path end, 'reason', why);
end $_$;


--
-- Name: mail_attach_org_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_org_limit(_org uuid) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  plan text := 'basic';
  sp   record;
  lim  bigint := 5368709120;
  isf  boolean := false;
begin
  if to_regprocedure('public.org_plan_of(uuid)') is not null then
    plan := coalesce(public.org_plan_of(_org), 'basic');
  end if;
  if to_regclass('public.founder_accounts') is not null and to_regclass('public.org_members') is not null then
    select exists (select 1 from public.org_members m join public.founder_accounts f on f.user_id = m.user_id where m.org_id = _org) into isf;
    if isf then plan := 'business_pro'; end if;
  end if;
  if to_regclass('public.storage_plans') is not null then
    select * into sp from public.storage_plans where plan_id = plan;
    if sp.plan_id is null then select * into sp from public.storage_plans where plan_id = 'basic'; end if;
    if sp.plan_id is not null then
      lim := coalesce(sp.pooled_bytes, sp.per_mailbox_bytes * greatest(coalesce(sp.mailbox_limit, 1), 1), lim);
    end if;
  end if;
  return lim;
end $$;


--
-- Name: mail_attach_register(uuid, uuid, text, bigint, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_register(_user uuid, _org uuid, _sha256 text, _size bigint, _filename text, _mime text, _rel_path text, _scan jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  c        jsonb := public.mail_attach_ctx(_user, _org);
  org      uuid;
  blob     public.org_attachment_blobs;
  inserted boolean := false;
  newid    uuid;
  nstaged  bigint;
  fname    text := left(coalesce(nullif(btrim(_filename), ''), 'file'), 255);
begin
  if (c->>'ok') is distinct from 'true' then return c; end if;
  org := (c->>'org_id')::uuid;
  if org is distinct from _org then
    return jsonb_build_object('ok', false, 'error', 'wrong_org');
  end if;
  if _sha256 is null or _sha256 !~ '^[0-9a-f]{64}$' then return jsonb_build_object('ok', false, 'error', 'bad_hash'); end if;
  if _size is null or _size < 0 then return jsonb_build_object('ok', false, 'error', 'bad_size'); end if;
  if _size > (c->>'message_cap_bytes')::bigint then
    return jsonb_build_object('ok', false, 'error', 'file_too_large', 'limit_bytes', (c->>'message_cap_bytes')::bigint);
  end if;
  if _rel_path is null or _rel_path !~ '^[0-9a-f-]{36}/[0-9a-f]{2}/[0-9a-f]{64}-[0-9a-f]{8}$' then
    return jsonb_build_object('ok', false, 'error', 'bad_path');
  end if;

  perform pg_advisory_xact_lock(hashtext('mail_attach:' || org::text));

  select count(*) into nstaged from public.mail_outbound_attachments where user_id = _user;
  if nstaged >= public._ma_limit('max_staged_per_user', 50) then
    return jsonb_build_object('ok', false, 'error', 'too_many_staged');
  end if;

  select * into blob from public.org_attachment_blobs where org_id = org and sha256 = _sha256;
  if blob.sha256 is null then
    if (c->>'org_used_bytes')::bigint + _size > (c->>'org_limit_bytes')::bigint then
      return jsonb_build_object('ok', false, 'error', 'org_quota_full',
        'used_bytes', (c->>'org_used_bytes')::bigint, 'limit_bytes', (c->>'org_limit_bytes')::bigint);
    end if;
    insert into public.org_attachment_blobs (org_id, sha256, size_bytes, rel_path, scan)
    values (org, _sha256, _size, _rel_path, coalesce(_scan, '{}'::jsonb))
    returning * into blob;
    inserted := true;
  else
    update public.org_attachment_blobs set touched_at = now() where org_id = org and sha256 = _sha256;
  end if;

  insert into public.mail_outbound_attachments (org_id, user_id, sha256, filename, mime_type, size_bytes)
  values (org, _user, _sha256, fname, left(coalesce(_mime, 'application/octet-stream'), 120), blob.size_bytes)
  returning id into newid;

  return jsonb_build_object('ok', true, 'id', newid, 'deduped', not inserted, 'rel_path', blob.rel_path,
                            'size_bytes', blob.size_bytes, 'filename', fname, 'scan', blob.scan);
end $_$;


--
-- Name: mail_attach_remove(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_remove(_user uuid, _id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare n int;
begin
  delete from public.mail_outbound_attachments where id = _id and user_id = _user;
  get diagnostics n = row_count;
  return jsonb_build_object('ok', true, 'removed', n);
end $$;


--
-- Name: mail_attach_resolve(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_resolve(_user uuid, _id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  st text := null;
  r  record;
begin
  if to_regclass('public.account_integrity') is not null then
    select i.state into st from public.account_integrity i where i.user_id = _user;
    if st in ('blocked', 'purged') then return jsonb_build_object('ok', false, 'error', 'account_blocked'); end if;
  end if;

  select a.filename, a.mime_type, a.size_bytes, a.sha256, b.rel_path into r
    from public.mail_outbound_attachments a
    join public.org_attachment_blobs b on b.org_id = a.org_id and b.sha256 = a.sha256
   where a.id = _id and a.user_id = _user;
  if found then
    return jsonb_build_object('ok', true, 'rel_path', r.rel_path, 'filename', r.filename, 'mime_type', r.mime_type,
                              'size_bytes', r.size_bytes, 'sha256', r.sha256);
  end if;

  if to_regclass('public.mail_attachments') is not null and to_regclass('public.org_members') is not null then
    select x.filename, x.mime_type, x.size_bytes, x.sha256, b.rel_path into r
      from public.mail_attachments x
      join public.org_attachment_blobs b on b.org_id = x.org_id and b.sha256 = x.sha256
     where x.id = _id and x.sha256 is not null
       and exists (select 1 from public.org_members m
                    where m.user_id = _user and m.org_id = x.org_id and coalesce(m.status::text, 'active') <> 'revoked');
    if found then
      return jsonb_build_object('ok', true, 'rel_path', r.rel_path, 'filename', r.filename, 'mime_type', r.mime_type,
                                'size_bytes', r.size_bytes, 'sha256', r.sha256);
    end if;
  end if;
  return jsonb_build_object('ok', false, 'error', 'not_found');
end $$;


--
-- Name: mail_attach_stage_check(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_attach_stage_check(_user uuid, _org uuid, _ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  c    jsonb := public.mail_attach_ctx(_user, _org);
  ids  uuid[] := coalesce((select array_agg(distinct x) from unnest(_ids) x), '{}');
  rows_j jsonb;
  total  bigint;
  n      int;
begin
  if (c->>'ok') is distinct from 'true' then return c; end if;
  if cardinality(ids) = 0 then return jsonb_build_object('ok', true, 'files', '[]'::jsonb, 'total_bytes', 0); end if;
  if cardinality(ids) > (c->>'max_files')::int then
    return jsonb_build_object('ok', false, 'error', 'too_many_attachments', 'limit', (c->>'max_files')::int);
  end if;
  select count(*), coalesce(sum(a.size_bytes), 0),
         coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'filename', a.filename, 'mime_type', a.mime_type,
                  'size_bytes', a.size_bytes, 'sha256', a.sha256, 'rel_path', b.rel_path) order by a.created_at), '[]'::jsonb)
    into n, total, rows_j
    from public.mail_outbound_attachments a
    join public.org_attachment_blobs b on b.org_id = a.org_id and b.sha256 = a.sha256
   where a.id = any(ids) and a.user_id = _user and a.org_id = (c->>'org_id')::uuid;
  if n <> cardinality(ids) then return jsonb_build_object('ok', false, 'error', 'attachment_not_found'); end if;
  if total > (c->>'message_cap_bytes')::bigint then
    return jsonb_build_object('ok', false, 'error', 'attachments_too_large', 'limit_bytes', (c->>'message_cap_bytes')::bigint, 'total_bytes', total);
  end if;
  return jsonb_build_object('ok', true, 'files', rows_j, 'total_bytes', total, 'org_id', (c->>'org_id')::uuid);
end $$;


--
-- Name: mail_ingest(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_ingest(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
-- E37 gate: koi bhi mail kisi aur customer ki org mein nahi. Andar wahi purana raasta (mail_ingest_core) chalta hai.
declare
  v_to      text := lower(btrim(coalesce(payload->>'envelope_to', '')));
  v_ops     text := 'resolved@anexomail.com';
  v_payload jsonb := payload;
begin
  if v_to = '' then
    raise exception 'mail_ingest_missing_envelope_to';
  end if;

  -- a) system pata -> ops inbox (agar woh maujood ho)
  if public.mail_system_local_part(v_to) and public.mail_recipient_known(v_ops) then
    v_payload := jsonb_set(v_payload, '{envelope_to}', to_jsonb(v_ops))
                 || jsonb_build_object('original_envelope_to', v_to);
    return public.mail_ingest_core(v_payload) || jsonb_build_object('rerouted_from', v_to);
  end if;

  -- b) jaana pehchana pata -> purana raasta
  if public.mail_recipient_known(v_to) then
    return public.mail_ingest_core(v_payload);
  end if;

  -- c) anjaan pata -> quarantine. Kisi org ko nahi. Postfix ko "ok" taake woh baar baar na bheje.
  insert into public.mail_quarantine
    (reason, envelope_from, envelope_to, from_address, subject, message_id, raw_size, raw_sha256, payload)
  values
    (case when public.mail_system_local_part(v_to) then 'system_address_no_ops_inbox' else 'unknown_recipient' end,
     payload->>'envelope_from', v_to, payload->>'from_address', left(payload->>'subject', 500), payload->>'message_id',
     nullif(payload->>'raw_size', '')::integer, payload->>'raw_sha256', payload);
  return jsonb_build_object('ok', true, 'quarantined', true, 'reason', 'unknown_recipient');
end $$;


--
-- Name: mail_ingest_core(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_ingest_core(payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_box    text := lower(coalesce(payload->>'envelope_to',''));
  v_subj   text := coalesce(nullif(trim(payload->>'subject'),''), '(no subject)');
  v_msgid  text := nullif(payload->>'message_id','');
  v_reply  text := nullif(payload->>'in_reply_to','');
  v_sent   timestamptz := coalesce(nullif(payload->>'sent_at','')::timestamptz, now());
  v_org    uuid;
  v_acct   uuid;
  v_thread uuid;
  v_msg    uuid;
  v_to     text[];
  v_cc     text[];
begin
  if v_box = '' then
    raise exception 'mail_ingest_missing_envelope_to';
  end if;

  insert into public.mail_inbound_raw
    (envelope_from, envelope_to, raw_size, raw_sha256, headers)
  values
    (payload->>'envelope_from', v_box,
     coalesce(nullif(payload->>'raw_size','')::integer, 0), payload->>'raw_sha256',
     coalesce(payload->'headers','{}'::jsonb));

  if v_msgid is not null then
    select id, thread_id into v_msg, v_thread
      from public.mail_messages where message_id = v_msgid limit 1;
    if v_msg is not null then
      return jsonb_build_object('ok', true, 'duplicate', true,
                                'thread_id', v_thread, 'message_id', v_msg);
    end if;
  end if;

  -- Owner resolution: account row -> mailbox row -> same mailbox thread -> any
  -- existing workspace org. Har query schema-safe hai; purana column na ho to skip.
  if to_regclass('public.mail_accounts') is not null
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='mail_accounts' and column_name='address')
     and exists (select 1 from information_schema.columns where table_schema='public' and table_name='mail_accounts' and column_name='org_id') then
    execute 'select id, org_id from public.mail_accounts where lower(address)=$1 limit 1'
      into v_acct, v_org using v_box;
  end if;

  if v_org is null then
    select mb.account_id, mb.org_id into v_acct, v_org
      from public.mailboxes mb where lower(mb.address)=v_box limit 1;
  end if;
  if v_org is null then
    select mt.account_id, mt.org_id into v_acct, v_org
      from public.mail_threads mt
     where lower(mt.mailbox_address)=v_box and mt.org_id is not null
     order by mt.last_message_at desc limit 1;
  end if;
  if v_org is null then
    select mt.org_id into v_org from public.mail_threads mt
     where mt.org_id is not null order by mt.last_message_at desc limit 1;
  end if;
  if v_org is null and to_regclass('public.orgs') is not null then
    execute 'select id from public.orgs limit 1' into v_org;
  end if;
  if v_org is null then
    v_org := 'dbd5aef3-8d6d-415f-9b5b-8d32f0adce3a';
  end if;

  update public.mailboxes
     set org_id=coalesce(org_id,v_org), account_id=coalesce(account_id,v_acct)
   where lower(address)=v_box;

  if v_reply is not null then
    select thread_id into v_thread from public.mail_messages
     where message_id=v_reply limit 1;
  end if;
  if v_thread is null then
    select id into v_thread from public.mail_threads
     where lower(mailbox_address)=v_box
       and subject=regexp_replace(v_subj, '^((re|fwd|fw)\s*:\s*)+', '', 'i')
       and last_message_at > now()-interval '30 days'
     order by last_message_at desc limit 1;
  end if;
  if v_thread is null then
    insert into public.mail_threads
      (org_id, account_id, mailbox_address, subject, snippet, from_name,
       from_address, message_count, unread, last_message_at)
    values
      (v_org, v_acct, v_box,
       regexp_replace(v_subj, '^((re|fwd|fw)\s*:\s*)+', '', 'i'),
       left(coalesce(payload->>'body_text',''),180), payload->>'from_name',
       lower(coalesce(payload->>'from_address','unknown')), 0, true, v_sent)
    returning id into v_thread;
  end if;

  select coalesce(array_agg(value), array[v_box]) into v_to
    from jsonb_array_elements_text(coalesce(payload->'to','[]'::jsonb));
  select coalesce(array_agg(value), '{}'::text[]) into v_cc
    from jsonb_array_elements_text(coalesce(payload->'cc','[]'::jsonb));

  insert into public.mail_messages
    (org_id, thread_id, direction, message_id, in_reply_to, from_name,
     from_address, to_addresses, cc_addresses, to_addrs, cc_addrs,
     subject, body_text, body_html, spf_result, dkim_result, sent_at)
  values
    (v_org, v_thread, 'in', v_msgid, v_reply, payload->>'from_name',
     lower(coalesce(payload->>'from_address','unknown')),
     v_to, v_cc, v_to, v_cc, v_subj, payload->>'body_text', payload->>'body_html',
     payload->>'spf', payload->>'dkim', v_sent)
  returning id into v_msg;

  update public.mail_threads
     set message_count=message_count+1, unread=true,
         org_id=coalesce(org_id,v_org), account_id=coalesce(account_id,v_acct),
         snippet=left(coalesce(payload->>'body_text',snippet,''),180),
         last_message_at=greatest(last_message_at,v_sent)
   where id=v_thread;

  return jsonb_build_object('ok',true,'thread_id',v_thread,'message_id',v_msg,'org_id',v_org);
end $_$;


--
-- Name: FUNCTION mail_ingest_core(payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.mail_ingest_core(payload jsonb) IS 'anexomail-mail-contract-v59';


--
-- Name: mail_message_address_compat(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_message_address_compat() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if cardinality(new.to_addresses) = 0 and cardinality(new.to_addrs) > 0 then
    new.to_addresses := new.to_addrs;
  elsif cardinality(new.to_addrs) = 0 and cardinality(new.to_addresses) > 0 then
    new.to_addrs := new.to_addresses;
  end if;
  if cardinality(new.cc_addresses) = 0 and cardinality(new.cc_addrs) > 0 then
    new.cc_addresses := new.cc_addrs;
  elsif cardinality(new.cc_addrs) = 0 and cardinality(new.cc_addresses) > 0 then
    new.cc_addrs := new.cc_addresses;
  end if;
  if cardinality(new.bcc_addresses) = 0 and cardinality(new.bcc_addrs) > 0 then
    new.bcc_addresses := new.bcc_addrs;
  elsif cardinality(new.bcc_addrs) = 0 and cardinality(new.bcc_addresses) > 0 then
    new.bcc_addrs := new.bcc_addresses;
  end if;
  return new;
end $$;


--
-- Name: mail_messages_mig_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_messages_mig_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.mig_session_id is null then
    return new;                                   -- normal mail: kuch nahi badla
  end if;
  if coalesce(current_setting('anexomail.mig_gate', true), '') is distinct from new.mig_session_id::text
     or not exists (select 1 from public.mig_sessions s
                     where s.id = new.mig_session_id and s.locked = false and s.status in ('verified', 'running')) then
    raise exception 'migration walled garden band hai: yeh row is raaste se nahi likhi ja sakti' using errcode = 'AX050';
  end if;
  return new;
end $$;


--
-- Name: mail_outbox_record(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_outbox_record(payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_id uuid;
begin
  insert into public.mail_outbox_log (from_address, to_addresses, subject, message_id, smtp_response, ok, error)
  values (lower(payload->>'from_address'),
          coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(payload->'to','[]'::jsonb)) x), '{}'),
          payload->>'subject', nullif(payload->>'message_id',''),
          payload->>'smtp_response', coalesce((payload->>'ok')::boolean, false), payload->>'error')
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: mail_predict(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_predict(_user uuid, _prefix text, _formality text DEFAULT 'any'::text, _limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with tail as (
    select btrim(regexp_replace(lower(coalesce(_prefix, '')), '\s+', ' ', 'g')) as t
  ),
  words as (
    select case when t = '' then '{}'::text[] else string_to_array(t, ' ') end as w from tail
  ),
  cands as (
    select p.next_text,
           array_length(string_to_array(p.prefix, ' '), 1) as depth,
           p.weight,
           (p.user_id is not null) as mine
      from public.mail_predict_phrases p, words
     where array_length(words.w, 1) is not null
       and p.prefix = array_to_string(words.w[greatest(array_length(words.w,1) - array_length(string_to_array(p.prefix,' '),1) + 1, 1):array_length(words.w,1)], ' ')
       and (p.user_id is null or p.user_id = _user)
       and (p.formality = 'any' or _formality = 'any' or p.formality = _formality)
  )
  select coalesce(jsonb_agg(x order by x.rank), '[]'::jsonb)
    from (
      select next_text as text,
             case when mine then 'you' else 'business' end as source,
             least(0.99, (weight::numeric / 100) + depth * 0.1 + case when mine then 0.15 else 0 end) as confidence,
             row_number() over (order by depth desc, mine desc, weight desc) as rank
        from cands
       limit greatest(coalesce(_limit, 3), 1)
    ) x;
$$;


--
-- Name: mail_predict_event(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_predict_event(_user uuid, _action text, _prefix text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.mail_predict_events (user_id, action, prefix)
  select _user, _action, left(coalesce(_prefix, ''), 120)
   where _action in ('accept','dismiss','conflict');
$$;


--
-- Name: mail_predict_learn(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_predict_learn(_user uuid, _text text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  clean text;
  parts text[];
  i integer;
  n integer;
  learned integer := 0;
  pre text;
  nxt text;
begin
  clean := btrim(regexp_replace(coalesce(_text, ''), '\s+', ' ', 'g'));
  if length(clean) < 12 then return 0; end if;

  -- credentials / secrets / tokens / emails / long digit strings kabhi nahi seekhte
  if clean ~* '(password|passwd|secret|api[ _-]?key|token|bearer |otp|cvv|iban|sort code|account number)'
     or clean ~ '[0-9]{6,}'
     or clean ~ '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}'
     or clean ~ '(sk|pk|sb)[-_][A-Za-z0-9]{10,}'
  then
    return 0;
  end if;

  parts := string_to_array(lower(clean), ' ');
  n := coalesce(array_length(parts, 1), 0);
  if n < 4 then return 0; end if;

  i := 3;
  while i < n and learned < 40 loop
    pre := array_to_string(parts[greatest(i - 2, 1):i], ' ');
    nxt := array_to_string(parts[i + 1:least(i + 4, n)], ' ');
    if length(nxt) > 2 then
      insert into public.mail_predict_phrases (user_id, prefix, next_text, formality, weight)
      values (_user, pre, nxt, 'any', 1)
      on conflict (coalesce(user_id, '00000000-0000-0000-0000-000000000000'::uuid), prefix, next_text)
      do update set weight = public.mail_predict_phrases.weight + 1, updated_at = now();
      learned := learned + 1;
    end if;
    i := i + 2;
  end loop;

  return learned;
end $$;


--
-- Name: mail_recipient_known(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_recipient_known(p_addr text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  a   text := lower(btrim(coalesce(p_addr, '')));
  hit boolean := false;
begin
  if a = '' then return false; end if;
  if to_regclass('public.mail_accounts') is not null
     and exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'mail_accounts' and column_name = 'address') then
    execute 'select exists (select 1 from public.mail_accounts where lower(address) = $1)' into hit using a;
    if hit then return true; end if;
  end if;
  return exists (select 1 from public.mailboxes where lower(address) = a);
end $_$;


--
-- Name: mail_system_local_part(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_system_local_part(p_addr text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  select lower(btrim(coalesce(p_addr, ''))) ~ '^(root|admin|administrator|hostmaster|webmaster|security|mailer-daemon|cron|daemon|nobody|www-data|vmail)@(mail\.)?anexomail\.com$'
$_$;


--
-- Name: mail_threads; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.mail_threads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid,
    account_id uuid,
    subject text DEFAULT '(no subject)'::text NOT NULL,
    snippet text,
    from_name text,
    from_address text DEFAULT ''::text NOT NULL,
    folder public.mail_folder DEFAULT 'inbox'::public.mail_folder NOT NULL,
    status public.thread_status DEFAULT 'open'::public.thread_status NOT NULL,
    category public.thread_category DEFAULT 'primary'::public.thread_category,
    assignee uuid,
    unread boolean DEFAULT true NOT NULL,
    starred boolean DEFAULT false NOT NULL,
    has_attachments boolean DEFAULT false NOT NULL,
    message_count integer DEFAULT 0 NOT NULL,
    snoozed_until timestamp with time zone,
    last_message_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    mailbox_address text
);


--
-- Name: mail_thread_assign(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_assign(_thread_id uuid, _assignee uuid, _org_id uuid) RETURNS public.mail_threads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result public.mail_threads;
begin
  update public.mail_threads
  set assignee = _assignee
  where id = _thread_id
    and org_id = _org_id
  returning * into result;

  if result.id is null then
    raise exception 'thread_not_found_or_not_owned';
  end if;

  return result;
end;
$$;


--
-- Name: mail_thread_count_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_count_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.message_count is distinct from old.message_count then
    new.message_count := (select count(*) from public.mail_messages m where m.thread_id = new.id);
  end if;
  return new;
end $$;


--
-- Name: mail_thread_recount_del(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_recount_del() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.mail_threads t
     set message_count = (select count(*) from public.mail_messages m where m.thread_id = t.id)
   where t.id in (select distinct thread_id from old_rows where thread_id is not null);
  return null;
end $$;


--
-- Name: mail_thread_recount_ins(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_recount_ins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.mail_threads t
     set message_count = (select count(*) from public.mail_messages m where m.thread_id = t.id)
   where t.id in (select distinct thread_id from new_rows where thread_id is not null);
  return null;
end $$;


--
-- Name: mail_thread_recount_upd(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_recount_upd() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.mail_threads t
     set message_count = (select count(*) from public.mail_messages m where m.thread_id = t.id)
   where t.id in (select thread_id from new_rows where thread_id is not null
                  union select thread_id from old_rows where thread_id is not null);
  return null;
end $$;


--
-- Name: mail_thread_rollup(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_rollup() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.mail_threads t
     set message_count   = (select count(*) from public.mail_messages m
                            where m.thread_id = t.id and m.scheduled_at is null),
         last_message_at = greatest(t.last_message_at, coalesce(new.sent_at, now())),
         snippet         = coalesce(
                             left(regexp_replace(coalesce(new.body_text, new.subject, ''), '\s+', ' ', 'g'), 180),
                             t.snippet),
         has_attachments = t.has_attachments or exists (
                             select 1 from public.mail_attachments a where a.message_id = new.id)
   where t.id = new.thread_id;
  return new;
end $$;


--
-- Name: mail_thread_subject_safe(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mail_thread_subject_safe(_thread uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare v text;
begin
  if to_regclass('public.mail_threads') is null then return null; end if;
  begin
    execute 'select subject from public.mail_threads where id = $1' into v using _thread;
  exception when others then
    return null;
  end;
  return v;
end $_$;


--
-- Name: match_memories(extensions.vector, text, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_memories(query_embedding extensions.vector, agent_name text, match_count integer DEFAULT 10, min_similarity double precision DEFAULT 0.5) RETURNS TABLE(id uuid, content text, summary text, role text, importance double precision, similarity double precision, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    m.id, m.content, m.summary, m.role, m.importance,
    1 - (m.embedding <=> query_embedding) AS similarity,
    m.created_at
  FROM ai_memory_vectors m
  WHERE 
    m.agent = agent_name
    AND m.embedding IS NOT NULL
    AND 1 - (m.embedding <=> query_embedding) >= min_similarity
  ORDER BY m.embedding <=> query_embedding
  LIMIT match_count;
END;
$$;


--
-- Name: message_attach_file(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_attach_file(_user uuid, _message uuid, _version uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_conv uuid;
begin
  select conversation_id into v_conv from public.chat_messages where id = _message;
  if v_conv is null then return jsonb_build_object('ok', false, 'error', 'message_not_found'); end if;
  if not public.chat_in_conversation(v_conv, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;
  if not exists (select 1 from public.chat_file_versions where id = _version) then
    return jsonb_build_object('ok', false, 'error', 'version_not_found');
  end if;
  insert into public.chat_message_files (message_id, version_id, linked_by)
  values (_message, _version, _user)
  on conflict (message_id, version_id) do nothing;
  return jsonb_build_object('ok', true, 'message_id', _message, 'version_id', _version);
end $$;


--
-- Name: message_escalations(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_escalations(_message uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_conv uuid; v_rows jsonb;
begin
  select conversation_id into v_conv from public.chat_messages where id = _message;
  if v_conv is null then return jsonb_build_object('error', 'message_not_found'); end if;
  if not public.chat_in_conversation(v_conv, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'draft_id', e.draft_id, 'at', e.at, 'state', d.state,
           'subject', d.subject, 'mail_message_id', d.mail_message_id)
           order by e.at desc), '[]'::jsonb)
    into v_rows from public.chat_message_escalations e
    join public.chat_email_drafts d on d.id = e.draft_id
   where e.message_id = _message;

  return jsonb_build_object('message_id', _message, 'escalations', v_rows,
    'label', case when jsonb_array_length(v_rows) = 0 then null
                  else 'Escalated to email' end,
    'formal_record', 'ANEXOMAIL');
end $$;


--
-- Name: message_mark_important(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_mark_important(_message uuid, _user uuid, _reason text DEFAULT NULL::text, _important boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare m record; v_id uuid;
begin
  select * into m from public.chat_messages where id = _message;
  if m.id is null then return jsonb_build_object('ok', false, 'error', 'message_not_found'); end if;
  if not public.chat_in_conversation(m.conversation_id, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'conversation_timeline') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;

  if _important then
    insert into public.chat_message_important (message_id, conversation_id, marked_by, reason)
    values (_message, m.conversation_id, _user, nullif(btrim(coalesce(_reason,'')), ''))
    on conflict do nothing
    returning id into v_id;
    return jsonb_build_object('ok', true, 'important', true, 'id', v_id);
  end if;

  update public.chat_message_important
     set removed_at = now(), removed_by = _user
   where message_id = _message and removed_at is null;
  return jsonb_build_object('ok', true, 'important', false);
end $$;


--
-- Name: message_provenance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_provenance(_message uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare m record; p record; v_now text; v_recipients int; v_delivered int; v_read int;
begin
  select * into m from public.chat_messages where id = _message;
  if m.id is null then return jsonb_build_object('error', 'message_not_found'); end if;
  if not public.chat_in_conversation(m.conversation_id, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'message_provenance') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;

  select * into p from public.chat_message_provenance where message_id = _message;
  v_now := encode(digest(coalesce(m.body, ''), 'sha256'), 'hex');

  select count(*) into v_recipients from public.chat_participants
   where conversation_id = m.conversation_id and user_id <> m.sender_user_id;
  select count(*) into v_delivered from public.chat_message_receipts
   where message_id = _message and state = 'delivered';
  select count(*) into v_read from public.chat_message_receipts
   where message_id = _message and state = 'read';

  return jsonb_build_object(
    'message_id', m.id,
    'conversation_id', m.conversation_id,
    'seq', m.seq,
    'sent_by', (select u.email from auth.users u where u.id = m.sender_user_id),
    'sent_by_id', m.sender_user_id,
    'workspace', (select w.name from public.chat_workspaces w where w.id = m.workspace_id),
    -- millisecond-exact UTC (14:32:11.418 UTC)
    'sent_at_utc', to_char(m.created_at at time zone 'UTC', 'YYYY-MM-DD HH24:MI:SS.MS') || ' UTC',
    'sent_at', m.created_at,
    'transport', coalesce(m.transport, 'bun'),
    'transport_label', case coalesce(m.transport, 'bun')
      when 'wt' then 'WebTransport / QUIC (Rust engine)'
      when 'realtime' then 'Realtime channel'
      else 'HTTP fallback' end,
    'device_label', m.device_label,
    'recipients', v_recipients,
    'delivery_confirmed', (v_recipients > 0 and v_delivered >= v_recipients),
    'delivery_count', v_delivered,
    'read_count', v_read,
    'receipts', coalesce((
      select jsonb_agg(jsonb_build_object('user_id', r.user_id, 'state', r.state, 'at', r.at)
             order by r.at)
        from public.chat_message_receipts r where r.message_id = _message), '[]'::jsonb),
    'sealed', p.message_id is not null,
    'seal_hash', p.body_hash,
    'chain_hash', p.chain_hash,
    'prev_hash', p.prev_hash,
    'sealed_at', p.sealed_at,
    'current_hash', v_now,
    'integrity_verified', (p.message_id is not null and p.body_hash = v_now),
    'edited', m.edited_at is not null,
    'edited_at', m.edited_at,
    'visible', m.deleted_at is null,
    'integrity_note', case
      when p.message_id is null then 'Not sealed yet — this message was written before sealing began.'
      when p.body_hash = v_now then 'Integrity verified against the sealed record.'
      when m.edited_at is not null then 'Edited after sending. The original seal is still on record.'
      else 'Text no longer matches the sealed record.' end,
    'important', exists (select 1 from public.chat_message_important i
                          where i.message_id = _message and i.removed_at is null));
end $$;


--
-- Name: message_receipt_pack(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_receipt_pack(_message uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  m record; v_steps jsonb := '[]'::jsonb; v_negative jsonb := '[]'::jsonb;
  v_files jsonb := '[]'::jsonb; r record; v_recipients int; v_delivered int; v_read int;
begin
  select mm.*, c.workspace_id as ws into m
    from public.chat_messages mm
    join public.chat_conversations c on c.id = mm.conversation_id
   where mm.id = _message;
  if not found then return jsonb_build_object('error', 'message_not_found'); end if;
  if not public.chat_in_conversation(m.conversation_id, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'receipt_pack') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;

  select count(*) into v_recipients from public.chat_participants
   where conversation_id = m.conversation_id and user_id <> m.sender_user_id;
  select count(distinct user_id) into v_delivered from public.chat_message_receipts
   where message_id = _message and state = 'delivered';
  select count(distinct user_id) into v_read from public.chat_message_receipts
   where message_id = _message and state = 'read';

  -- ✓ Sent — asli row ka waqt (millisecond UTC)
  v_steps := v_steps || jsonb_build_object(
    'step', 'sent', 'recorded', true,
    'at', to_char(m.created_at at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
    'evidence', 'chat_messages.created_at');

  -- ✓ Delivered / ✓ Read — sirf receipts se
  v_steps := v_steps || jsonb_build_object(
    'step', 'delivered', 'recorded', v_delivered > 0,
    'at', (select to_char(min(at) at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
             from public.chat_message_receipts where message_id = _message and state = 'delivered'),
    'people', v_delivered, 'of', v_recipients, 'evidence', 'chat_message_receipts');

  v_steps := v_steps || jsonb_build_object(
    'step', 'read', 'recorded', v_read > 0,
    'at', (select to_char(min(at) at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
             from public.chat_message_receipts where message_id = _message and state = 'read'),
    'people', v_read, 'of', v_recipients, 'evidence', 'chat_message_receipts');

  -- NEGATIVE RECEIPTS — jo hua hi nahi, asli presence window ke saath
  for r in
    select p.user_id, u.email, pr.last_seen_at
      from public.chat_participants p
      join auth.users u on u.id = p.user_id
      left join public.chat_presence pr
             on pr.user_id = p.user_id and pr.workspace_id = m.ws
     where p.conversation_id = m.conversation_id
       and p.user_id <> m.sender_user_id
       and not exists (select 1 from public.chat_message_receipts x
                        where x.message_id = _message and x.user_id = p.user_id
                          and x.state = 'delivered')
  loop
    v_negative := v_negative || jsonb_build_object(
      'user_id', r.user_id, 'person', r.email, 'state', 'not_delivered',
      'window_from', to_char(m.created_at at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'window_to', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'last_seen_at', r.last_seen_at,
      'note', case when r.last_seen_at is null
                then 'No presence recorded for this person.'
                else 'Recipient was not present after this message was sent.' end,
      'evidence', 'chat_presence · chat_message_receipts (absent row)');
  end loop;

  -- read but no response (24h) — evidence, ilzaam nahi
  for r in
    select rr.user_id, u.email, rr.at
      from public.chat_message_receipts rr
      join auth.users u on u.id = rr.user_id
     where rr.message_id = _message and rr.state = 'read'
       and not exists (select 1 from public.chat_messages nm
                        where nm.conversation_id = m.conversation_id
                          and nm.sender_user_id = rr.user_id
                          and nm.created_at > rr.at)
       and rr.at < now() - interval '24 hours'
  loop
    v_negative := v_negative || jsonb_build_object(
      'user_id', r.user_id, 'person', r.email, 'state', 'read_without_response',
      'read_at', r.at, 'hours_since', round(extract(epoch from (now() - r.at)) / 3600.0, 1),
      'note', 'Read on record; no reply recorded in this conversation since.',
      'evidence', 'chat_message_receipts · chat_messages (absent reply)');
  end loop;

  -- ATTACHMENT CHAIN — file_evidence se, koi step guess nahi
  for r in
    select v.id as version_id, f.name, v.bytes, v.state as version_state
      from public.chat_message_files mf
      join public.chat_file_versions v on v.id = mf.version_id
      join public.chat_files f on f.id = v.file_id
     where mf.message_id = _message
  loop
    v_files := v_files || jsonb_build_object(
      'version_id', r.version_id, 'filename', r.name, 'bytes', r.bytes,
      'version_state', r.version_state,
      'steps', (
        select jsonb_agg(jsonb_build_object(
                 'step', s.state, 'recorded', e.at is not null, 'at', e.at,
                 'actor', e.actor, 'evidence', case when e.at is null then null else 'file_evidence' end)
                 order by s.ord)
          from (values ('uploaded',1),('scanning',2),('verified',3),('available',4),('downloaded',5)) as s(state, ord)
          left join public.file_evidence e
                 on e.version_id = r.version_id and e.state = s.state));
  end loop;

  return jsonb_build_object(
    'message_id', _message,
    'conversation_id', m.conversation_id,
    'recipients', v_recipients,
    'steps', v_steps,
    'negative_receipts', v_negative,
    'attachments', v_files,
    'engine_invents_nothing', true,
    'note', 'Steps without a record are shown as Not recorded.');
end $$;


--
-- Name: mig_chain_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mig_chain_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    raise exception 'mig_chain append-only hai: entry badal nahi sakti' using errcode = 'AX052';
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from public.mig_sessions s where s.id = old.session_id) then
      raise exception 'mig_chain append-only hai: entry hata nahi sakti' using errcode = 'AX052';
    end if;
    return old;
  end if;
  return new;
end $$;


--
-- Name: migration_cancel(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_cancel(_user uuid, _session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare s public.mig_sessions;
begin
  select * into s from public.mig_sessions where id = _session for update;
  if s.id is null or not (s.user_id = _user or public._mig_is_manager(_user, s.org_id)) then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if s.locked then return jsonb_build_object('ok', true, 'already', true, 'status', s.status); end if;
  if s.status = 'running' and s.heartbeat_at >= now() - interval '3 minutes' then
    update public.mig_sessions set cancel_requested = true where id = s.id;   -- worker zinda hai: agle batch par ruk kar khud band karega
    return jsonb_build_object('ok', true, 'requested', true);
  end if;
  return public._mig_finish(s, 'cancelled', 'cancelled_by_user');
end $$;


--
-- Name: migration_chain_export(uuid, uuid, bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_chain_export(_user uuid, _session uuid, _after bigint DEFAULT 0, _limit integer DEFAULT 2000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.mig_sessions;
begin
  select * into s from public.mig_sessions where id = _session;
  if s.id is null or not (s.user_id = _user or public._mig_is_manager(_user, s.org_id)) then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  return jsonb_build_object('ok', true, 'session_id', s.id, 'mailbox', s.mailbox, 'chain_len', s.chain_len,
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
        'seq', c.seq, 'outcome', c.outcome, 'folder', c.folder, 'uidvalidity', c.uidvalidity, 'uid', c.uid,
        'raw_sha256', c.raw_sha256, 'body_sha256', c.body_sha256, 'row_id', c.row_id, 'ts', c.ts,
        'copied', c.copied, 'duplicate', c.duplicate, 'skipped', c.skipped, 'failed', c.failed,
        'prev_hash', c.prev_hash, 'entry_hash', c.entry_hash) order by c.seq)
       from (select * from public.mig_chain where session_id = _session and seq > _after order by seq limit greatest(least(_limit, 5000), 1)) c), '[]'::jsonb));
end $$;


--
-- Name: migration_chain_verify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_chain_verify(_session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  s    public.mig_sessions;
  r    public.mig_chain;
  v_prev text;
  v_want bigint := 1;
  v_n  bigint := 0;
  v_seal boolean := false;
begin
  select * into s from public.mig_sessions where id = _session;
  if s.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  v_prev := public._mig_genesis(s.id, s.mailbox);
  for r in select * from public.mig_chain where session_id = _session order by seq loop
    if v_seal then return jsonb_build_object('ok', false, 'broken_at', r.seq, 'why', 'entries_after_seal'); end if;
    if r.seq <> v_want then return jsonb_build_object('ok', false, 'broken_at', r.seq, 'why', 'sequence_gap'); end if;
    if r.prev_hash <> v_prev then return jsonb_build_object('ok', false, 'broken_at', r.seq, 'why', 'prev_hash_mismatch'); end if;
    if r.entry_hash <> public._mig_entry_hash(v_prev, r.seq, r.outcome, r.folder, r.uidvalidity, r.uid, r.raw_sha256, r.body_sha256, r.row_id, r.ts,
                                              coalesce(r.copied, 0), coalesce(r.duplicate, 0), coalesce(r.skipped, 0), coalesce(r.failed, 0)) then
      return jsonb_build_object('ok', false, 'broken_at', r.seq, 'why', 'entry_hash_mismatch');
    end if;
    v_prev := r.entry_hash;
    v_want := v_want + 1;
    v_n := v_n + 1;
    v_seal := (r.outcome = 'seal');
  end loop;
  if v_n <> s.chain_len or coalesce(s.chain_head, public._mig_genesis(s.id, s.mailbox)) <> v_prev then
    return jsonb_build_object('ok', false, 'broken_at', v_n + 1, 'why', 'head_mismatch');
  end if;
  return jsonb_build_object('ok', true, 'entries', v_n, 'head', v_prev, 'sealed', v_seal);
end $$;


--
-- Name: migration_done(text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_done(_token text, _folder text, _uidv bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  s public.mig_sessions;
  v_r text;
begin
  s := public._mig_by_token(_token, true);
  if s.id is null then return jsonb_build_object('ok', false, 'error', 'gate_closed', 'why', public._mig_gate_why(_token)); end if;
  select string_agg(case when lo = hi then lo::text else lo || ':' || hi end, ',' order by lo) into v_r
    from (select min(uid) as lo, max(uid) as hi
            from (select uid, uid - row_number() over (order by uid) as g
                    from public.mig_items where session_id = s.id and folder = _folder and uidvalidity = _uidv) t
           group by g) x;
  return jsonb_build_object('ok', true, 'ranges', coalesce(v_r, ''));
end $$;


--
-- Name: migration_finish(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_finish(_token text, _status text, _error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare s public.mig_sessions;
begin
  if _status not in ('completed', 'failed', 'cancelled') then
    return jsonb_build_object('ok', false, 'error', 'bad_status');
  end if;
  s := public._mig_by_token(_token, false);
  if s.id is null then return jsonb_build_object('ok', false, 'error', 'gate_closed', 'why', public._mig_gate_why(_token)); end if;
  return public._mig_finish(s, _status, _error);
end $$;


--
-- Name: migration_get(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_get(_user uuid, _session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s public.mig_sessions;
begin
  select * into s from public.mig_sessions where id = _session;
  if s.id is null or not (s.user_id = _user or public._mig_is_manager(_user, s.org_id)) then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  return jsonb_build_object('ok', true, 'session', public._mig_summary(s), 'source_host', s.source_host);
end $$;


--
-- Name: migration_ingest(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_ingest(_token text, _items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  s        public.mig_sessions;
  it       jsonb;
  v_oc     text;
  v_folder text;
  v_uidv   bigint;
  v_uid    bigint;
  v_raw    text;
  v_size   bigint;
  v_msgid  text;
  v_reply  text;
  v_refs   text[];
  v_subj   text;
  v_norm   text;
  v_sent   timestamptz;
  v_dir    text;
  v_app    text;
  v_seen   boolean;
  v_to     text[];
  v_cc     text[];
  v_text   text;
  v_html   text;
  v_att    jsonb;
  v_thread uuid;
  v_msg    uuid;
  v_dup_id uuid;
  v_acct   uuid;
  v_c bigint := 0; v_d bigint := 0; v_k bigint := 0; v_f bigint := 0; v_b bigint := 0;
  v_body_sha text;
  v_from   text;
begin
  s := public._mig_by_token(_token, true);
  if s.id is null then
    return jsonb_build_object('ok', false, 'error', 'gate_closed', 'why', public._mig_gate_why(_token));
  end if;
  if jsonb_typeof(_items) is distinct from 'array' then
    return jsonb_build_object('ok', false, 'error', 'bad_input');
  end if;
  select a.id into v_acct from public.mail_accounts a where a.org_id = s.org_id and lower(a.address) = s.mailbox limit 1;
  if v_acct is null then
    return jsonb_build_object('ok', false, 'error', 'mailbox_not_found');
  end if;

  -- gate kholna: sirf is transaction mein, sirf is session ke liye
  perform set_config('anexomail.mig_gate', s.id::text, true);

  for it in select * from jsonb_array_elements(_items) loop
    v_oc     := coalesce(it->>'outcome', 'copy');
    v_folder := left(coalesce(it->>'folder', ''), 500);
    v_uidv   := (it->>'uidvalidity')::bigint;
    v_uid    := (it->>'uid')::bigint;
    v_raw    := coalesce(it->>'raw_sha256', '');
    v_size   := coalesce((it->>'raw_size')::bigint, 0);
    if v_folder = '' or v_uidv is null or v_uid is null or v_oc not in ('copy', 'too_large', 'failed') then
      continue;                                                     -- kharab item chain mein nahi aata, baqi chalte hain
    end if;
    if v_oc = 'copy' and v_raw !~ '^[0-9a-f]{64}$' then
      continue;
    end if;
    if exists (select 1 from public.mig_items i where i.session_id = s.id and i.folder = v_folder and i.uidvalidity = v_uidv and i.uid = v_uid) then
      continue;                                                     -- dobara aaya: kuch nahi (idempotent)
    end if;

    if v_oc = 'too_large' then
      insert into public.mig_items (session_id, org_id, mailbox, folder, uidvalidity, uid, outcome, reason, raw_size)
      values (s.id, s.org_id, s.mailbox, v_folder, v_uidv, v_uid, 'too_large', coalesce(it->>'reason', 'too_large'), v_size);
      s := (select t from public.mig_sessions t where t.id = s.id);
      perform public._mig_chain_add(s, 'too_large', v_folder, v_uidv, v_uid, '', '', null);
      v_k := v_k + 1;
      continue;
    elsif v_oc = 'failed' then
      insert into public.mig_items (session_id, org_id, mailbox, folder, uidvalidity, uid, outcome, reason)
      values (s.id, s.org_id, s.mailbox, v_folder, v_uidv, v_uid, 'failed', left(coalesce(it->>'reason', 'failed'), 60));
      s := (select t from public.mig_sessions t where t.id = s.id);
      perform public._mig_chain_add(s, 'failed', v_folder, v_uidv, v_uid, '', '', null);
      v_f := v_f + 1;
      continue;
    end if;

    -- ---- copy ----
    v_msgid := nullif(btrim(coalesce(it->>'message_id', '')), '');
    v_reply := nullif(btrim(coalesce(it->>'in_reply_to', '')), '');
    select coalesce(array_agg(x), '{}') into v_refs from jsonb_array_elements_text(
      case when jsonb_typeof(it->'references') = 'array' then it->'references' else '[]'::jsonb end) x;
    if v_reply is not null then v_refs := array_append(v_refs, v_reply); end if;
    v_subj := coalesce(nullif(btrim(coalesce(it->>'subject', '')), ''), '(no subject)');
    v_norm := regexp_replace(v_subj, '^((re|fwd|fw)\s*:\s*)+', '', 'i');
    v_app  := case when it->>'app_folder' in ('inbox', 'sent', 'drafts', 'archive', 'spam', 'trash') then it->>'app_folder' else 'archive' end;
    -- live mail_threads.folder enum (public.mail_folder) hai: jo label enum mein na ho uski jagah 'inbox'
    if not exists (select 1 from pg_enum en where en.enumtypid = 'public.mail_folder'::regtype and en.enumlabel = v_app) then v_app := 'inbox'; end if;
    v_dir  := case when it->>'direction' = 'out' then 'out' else 'in' end;
    v_seen := coalesce((it->>'seen')::boolean, false);
    begin
      v_sent := coalesce(nullif(it->>'sent_at', '')::timestamptz, now());
    exception when others then
      v_sent := now();
    end;
    if v_sent > now() + interval '1 day' then v_sent := now(); end if;
    v_text := left(coalesce(it->>'body_text', ''), 200000);
    v_html := left(it->>'body_html', 400000);
    v_att  := case when jsonb_typeof(it->'attachments') = 'array' then it->'attachments' else null end;
    v_from := lower(coalesce(nullif(btrim(it->>'from_address'), ''), 'unknown'));
    select coalesce(array_agg(lower(x)), '{}') into v_to from jsonb_array_elements_text(
      case when jsonb_typeof(it->'to') = 'array' then it->'to' else '[]'::jsonb end) x;
    select coalesce(array_agg(lower(x)), '{}') into v_cc from jsonb_array_elements_text(
      case when jsonb_typeof(it->'cc') = 'array' then it->'cc' else '[]'::jsonb end) x;
    if cardinality(v_to) = 0 then v_to := array[s.mailbox]; end if;
    v_body_sha := public._mig_sha(v_text);

    -- duplicate? (a) isi mailbox mein wohi Message-ID  (b) isi mailbox mein pehle copy hui wohi raw mail
    v_dup_id := null;
    if v_msgid is not null then
      select m.id into v_dup_id from public.mail_messages m join public.mail_threads t on t.id = m.thread_id
       where m.message_id = v_msgid and lower(t.mailbox_address) = s.mailbox limit 1;
    end if;
    if v_dup_id is null then
      select i.message_row_id into v_dup_id from public.mig_items i
       where i.mailbox = s.mailbox and i.raw_sha256 = v_raw and i.outcome = 'copied' limit 1;
      if v_dup_id is null and exists (select 1 from public.mig_items i where i.mailbox = s.mailbox and i.raw_sha256 = v_raw and i.outcome = 'copied') then
        v_dup_id := '00000000-0000-0000-0000-000000000000';
      end if;
    end if;
    if v_dup_id is not null then
      insert into public.mig_items (session_id, org_id, mailbox, folder, uidvalidity, uid, outcome, reason, raw_sha256, raw_size, message_row_id)
      values (s.id, s.org_id, s.mailbox, v_folder, v_uidv, v_uid, 'duplicate', 'already_in_mailbox', v_raw, v_size,
              nullif(v_dup_id, '00000000-0000-0000-0000-000000000000'::uuid));
      s := (select t from public.mig_sessions t where t.id = s.id);
      perform public._mig_chain_add(s, 'duplicate', v_folder, v_uidv, v_uid, v_raw, v_body_sha, nullif(v_dup_id, '00000000-0000-0000-0000-000000000000'::uuid));
      v_d := v_d + 1;
      continue;
    end if;

    -- Message-ID kisi AUR mailbox mein pehle se hai (unique index): yahan NULL ke saath rakho, mail phir bhi milti hai
    if v_msgid is not null and exists (select 1 from public.mail_messages m where m.message_id = v_msgid) then
      v_msgid := null;
    end if;

    -- thread: (1) jis mail ka jawab hai (2) wohi subject isi folder mein 30 din ke andar (3) naya
    v_thread := null;
    if cardinality(v_refs) > 0 then
      select t.id into v_thread from public.mail_messages m join public.mail_threads t on t.id = m.thread_id
       where m.message_id = any (v_refs) and lower(t.mailbox_address) = s.mailbox
       order by t.last_message_at desc limit 1;
    end if;
    if v_thread is null then
      select t.id into v_thread from public.mail_threads t
       where lower(t.mailbox_address) = s.mailbox and t.folder = v_app::public.mail_folder and t.subject = v_norm
         and abs(extract(epoch from (t.last_message_at - v_sent))) <= 30 * 86400
       order by t.last_message_at desc limit 1;
    end if;
    if v_thread is null then
      insert into public.mail_threads (org_id, account_id, mailbox_address, subject, snippet, from_name, from_address,
                                       message_count, unread, starred, has_attachments, folder, last_message_at)
      values (s.org_id, v_acct, s.mailbox, v_norm, left(v_text, 180), it->>'from_name', v_from, 0,
              (v_dir = 'in' and not v_seen), coalesce((it->>'flagged')::boolean, false),
              (v_att is not null and jsonb_array_length(v_att) > 0), v_app::public.mail_folder, v_sent)
      returning id into v_thread;
    end if;

    insert into public.mail_messages (org_id, thread_id, direction, message_id, in_reply_to, from_name, from_address,
                                      to_addresses, cc_addresses, to_addrs, cc_addrs, subject, body_text, body_html, sent_at, mig_session_id)
    values (s.org_id, v_thread, v_dir::public.mail_direction, v_msgid, v_reply, it->>'from_name', v_from, v_to, v_cc, v_to, v_cc, v_subj, v_text, v_html, v_sent, s.id)
    returning id into v_msg;

    update public.mail_threads
       set message_count = (select count(*) from public.mail_messages m2 where m2.thread_id = v_thread),  -- gina hua (live mein thread naya banne par ginti pehle se 1 thi => '+ 1' galat deta)
           unread = unread or (v_dir = 'in' and not v_seen),
           starred = starred or coalesce((it->>'flagged')::boolean, false),
           has_attachments = has_attachments or (v_att is not null and jsonb_array_length(v_att) > 0),
           snippet = case when v_sent >= last_message_at then left(v_text, 180) else snippet end,
           last_message_at = greatest(last_message_at, v_sent),
           org_id = coalesce(org_id, s.org_id), account_id = coalesce(account_id, v_acct)
     where id = v_thread;

    insert into public.mig_items (session_id, org_id, mailbox, folder, uidvalidity, uid, outcome, raw_sha256, raw_size, message_row_id, thread_id, attachments)
    values (s.id, s.org_id, s.mailbox, v_folder, v_uidv, v_uid, 'copied', v_raw, v_size, v_msg, v_thread, v_att);
    s := (select t from public.mig_sessions t where t.id = s.id);
    perform public._mig_chain_add(s, 'copied', v_folder, v_uidv, v_uid, v_raw, v_body_sha, v_msg);
    v_c := v_c + 1;
    v_b := v_b + v_size;
  end loop;

  update public.mig_sessions
     set status = 'running', started_at = coalesce(started_at, now()), heartbeat_at = now(), token_expires_at = [REDACTED] + interval '6 hours',
         copied = copied + v_c, duplicate = duplicate + v_d, skipped = skipped + v_k, failed = failed + v_f, bytes = bytes + v_b
   where id = s.id;
  select cancel_requested into v_seen from public.mig_sessions where id = s.id;
  return jsonb_build_object('ok', true, 'stop', coalesce(v_seen, false), 'copied', v_c, 'duplicate', v_d, 'skipped', v_k, 'failed', v_f);
end $_$;


--
-- Name: migration_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_list(_user uuid, _org uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return jsonb_build_object('ok', true, 'sessions', coalesce((
    select jsonb_agg(public._mig_summary(s) order by s.created_at desc)
      from (select * from public.mig_sessions x
             where x.org_id = _org and (x.user_id = _user or public._mig_is_manager(_user, _org))
             order by x.created_at desc limit 30) s), '[]'::jsonb));
end $$;


--
-- Name: migration_progress(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_progress(_token text, _p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare s public.mig_sessions;
begin
  s := public._mig_by_token(_token, true);
  if s.id is null then return jsonb_build_object('ok', false, 'error', 'gate_closed', 'why', public._mig_gate_why(_token)); end if;
  update public.mig_sessions
     set status = 'running', started_at = coalesce(started_at, now()),
         heartbeat_at = now(), token_expires_at = [REDACTED] + interval '6 hours',
         folders_total = coalesce((_p->>'folders_total')::integer, folders_total),
         folders_done  = coalesce((_p->>'folders_done')::integer, folders_done),
         current_folder = nullif(_p->>'folder', ''),
         last_error = coalesce(nullif(left(_p->>'last_error', 60), ''), last_error),
         found = greatest(public.mig_sessions.found, coalesce((_p->>'found')::bigint, 0)),
         skipped_folders = case when jsonb_typeof(_p->'skipped_folders') = 'array' then _p->'skipped_folders' else skipped_folders end
   where id = s.id;
  return jsonb_build_object('ok', true, 'stop', s.cancel_requested);
end $$;


--
-- Name: migration_release(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_release(_token text, _error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare s public.mig_sessions;
begin
  s := public._mig_by_token(_token, true);
  if s.id is null then return jsonb_build_object('ok', false, 'error', 'gate_closed', 'why', public._mig_gate_why(_token)); end if;
  update public.mig_sessions
     set token_hash = [REDACTED] token_expires_at = [REDACTED] heartbeat_at = now() - interval '1 hour',
         last_error = coalesce(nullif(left(_error, 60), ''), last_error), current_folder = null
   where id = s.id;
  return jsonb_build_object('ok', true, 'session_id', s.id);
end $$;


--
-- Name: migration_reopen(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_reopen(_user uuid, _session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  s public.mig_sessions;
  v_tok text;
begin
  select * into s from public.mig_sessions where id = _session for update;
  if s.id is null or not (s.user_id = _user or public._mig_is_manager(_user, s.org_id)) then
    return jsonb_build_object('ok', false, 'error', 'not_found');
  end if;
  if s.locked or s.status not in ('created', 'verified', 'running') then
    return jsonb_build_object('ok', false, 'error', 'session_locked');
  end if;
  if s.heartbeat_at >= now() - interval '3 minutes' then
    return jsonb_build_object('ok', false, 'error', 'still_running');
  end if;
  v_tok := encode(gen_random_bytes(32), 'hex');
  update public.mig_sessions
     set token_hash = [REDACTED] token_expires_at = [REDACTED] + interval '6 hours', heartbeat_at = now(),
         cancel_requested = false, status = case when status = 'created' then 'created' else 'verified' end
   where id = s.id;
  return jsonb_build_object('ok', true, 'token', v_tok, 'session_id', s.id, 'mailbox', s.mailbox, 'source_login', s.source_login,
                            'source_host', s.source_host, 'provider', s.provider, 'include_trash_spam', s.include_trash_spam);
end $$;


--
-- Name: migration_session_create(uuid, uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_session_create(_user uuid, _org uuid, _mailbox text, _provider text, _host text, _login text, _include_trash_spam boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_mb   text := lower(btrim(coalesce(_mailbox, '')));
  v_tok  text;
  v_id   uuid;
  v_old  public.mig_sessions;
  v_n    integer;
begin
  if v_mb = '' or _host is null or btrim(_host) = '' or _login is null or btrim(_login) = '' then
    return jsonb_build_object('ok', false, 'error', 'bad_input');
  end if;
  if not exists (select 1 from public.mail_accounts a where a.org_id = _org and lower(a.address) = v_mb) then
    return jsonb_build_object('ok', false, 'error', 'mailbox_not_found');
  end if;
  if not public._mig_can_use_mailbox(_user, _org, v_mb) then
    return jsonb_build_object('ok', false, 'error', 'not_allowed');
  end if;
  select count(*) into v_n from public.mig_sessions where user_id = _user and created_at > now() - interval '24 hours';
  if v_n >= 10 then
    return jsonb_build_object('ok', false, 'error', 'too_many_sessions');
  end if;

  -- shuru hi na hui purani koshish (login nahi hua / worker nahi chala) 15 minute baad khud band
  update public.mig_sessions set status = 'cancelled', locked = true, token_hash = [REDACTED] finished_at = now(), last_error = 'abandoned'
   where mailbox = v_mb and status in ('created', 'verified') and started_at is null and created_at < now() - interval '15 minutes';

  select * into v_old from public.mig_sessions where mailbox = v_mb and status in ('created', 'verified', 'running') limit 1;
  if v_old.id is not null then
    return jsonb_build_object('ok', false, 'error', 'session_active', 'session_id', v_old.id, 'status', v_old.status);
  end if;

  v_tok := encode(gen_random_bytes(32), 'hex');
  insert into public.mig_sessions (org_id, user_id, mailbox, provider, source_host, source_login, token_hash, token_expires_at, include_trash_spam, heartbeat_at)
  values (_org, _user, v_mb, left(coalesce(_provider, 'custom'), 24), left(lower(btrim(_host)), 253), left(btrim(_login), 320),
          public._mig_sha(v_tok), now() + interval '6 hours', coalesce(_include_trash_spam, false), now())
  returning id into v_id;
  return jsonb_build_object('ok', true, 'session_id', v_id, 'token', v_tok, 'mailbox', v_mb);
end $$;


--
-- Name: migration_verify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migration_verify(_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare s public.mig_sessions;
begin
  select * into s from public.mig_sessions where token_hash = [REDACTED] when _token ~ '^[0-9a-f]{64}$' then public._mig_sha(_token) end for update;
  if s.id is null then return jsonb_build_object('ok', false, 'error', 'invalid_token'); end if;
  if s.locked then return jsonb_build_object('ok', false, 'error', 'session_locked'); end if;
  if s.status not in ('created', 'verified', 'running') then return jsonb_build_object('ok', false, 'error', 'session_closed'); end if;
  update public.mig_sessions
     set status = case when status = 'created' then 'verified' else status end,
         verified_at = coalesce(verified_at, now()), heartbeat_at = now(), token_expires_at = [REDACTED] + interval '6 hours'
   where id = s.id;
  return jsonb_build_object('ok', true, 'session_id', s.id, 'mailbox', s.mailbox, 'include_trash_spam', s.include_trash_spam);
end $_$;


--
-- Name: movein_arm_cutover(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_arm_cutover(p_deal uuid, p_actor text DEFAULT 'founder'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not public.movein_cutover_ready(p_deal) then
    insert into public.movein_audit (deal_id, actor, action, reason)
      values (p_deal, p_actor, 'arm_blocked', 'runbook / dns / exceptions not clear');
    return jsonb_build_object('ok', false, 'error', 'not_ready');
  end if;
  if not exists (select 1 from public.movein_rollback_points where deal_id = p_deal and available) then
    return jsonb_build_object('ok', false, 'error', 'no_rollback_point');
  end if;
  update public.movein_deals set cutover_armed_at = now(), updated_at = now() where id = p_deal;
  insert into public.movein_audit (deal_id, actor, action, reason)
    values (p_deal, p_actor, 'cutover_armed', 'all required checks verified, rollback point recorded');
  return jsonb_build_object('ok', true, 'armed_at', now());
end $$;


--
-- Name: movein_attach_intent(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_attach_intent(p_deal uuid, p_leg text, p_intent uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d record; i record; v_expected numeric;
begin
  if p_leg not in ('deposit','final') then
    raise exception 'invalid_leg:%', p_leg using errcode = '22023';
  end if;

  select * into d from public.movein_deals where id = p_deal for update;
  if d is null then raise exception 'deal_not_found' using errcode = '22023'; end if;

  select * into i from public.billing_intents where id = p_intent for update;
  if i is null then raise exception 'intent_not_found' using errcode = '22023'; end if;

  if i.kind <> 'movein' then
    raise exception 'intent_kind_mismatch:%', i.kind using errcode = '22023';
  end if;
  if coalesce(i.currency,'') <> 'GBP' then
    raise exception 'intent_currency_mismatch:%', i.currency using errcode = '22023';
  end if;
  if d.user_id is null or i.user_id is distinct from d.user_id then
    raise exception 'intent_user_mismatch' using errcode = '42501';
  end if;

  -- HARD BIND: doosre deal/leg ka intent kabhi re-use nahi
  if i.movein_deal_id is not null and i.movein_deal_id <> p_deal then
    raise exception 'intent_bound_to_other_deal:%', i.movein_deal_id using errcode = '23505';
  end if;
  if i.movein_leg is not null and i.movein_leg <> p_leg then
    raise exception 'intent_bound_to_other_leg:%', i.movein_leg using errcode = '23505';
  end if;
  -- purana / already settled intent naye deal par attach nahi ho sakta
  if i.movein_deal_id is null and i.state in ('paid','entitled') then
    raise exception 'intent_already_settled_unbound' using errcode = '23505';
  end if;
  if i.created_at < d.created_at then
    raise exception 'intent_predates_deal' using errcode = '22023';
  end if;

  perform public.movein_sync_payments(p_deal);
  select amount_gbp into v_expected from public.movein_payments where deal_id = p_deal and leg = p_leg;
  if v_expected is null or coalesce(i.amount_expected, -1) <> v_expected then
    raise exception 'intent_amount_mismatch:expected=% got=%', v_expected, i.amount_expected
      using errcode = '22023';
  end if;

  if exists (select 1 from public.movein_payments p
              where p.intent_id = p_intent and not (p.deal_id = p_deal and p.leg = p_leg)) then
    raise exception 'intent_already_attached' using errcode = '23505';
  end if;

  -- bind pehle (unique index race ko rokta hai), phir payment row
  update public.billing_intents
     set movein_deal_id = p_deal, movein_leg = p_leg, updated_at = now()
   where id = p_intent;

  update public.movein_payments
     set intent_id = p_intent,
         state = case when state = 'due' then 'invoiced' else state end,
         invoiced_at = coalesce(invoiced_at, now()), updated_at = now()
   where deal_id = p_deal and leg = p_leg;

  if p_leg = 'deposit' then
    update public.movein_deals set deposit_intent_id = p_intent, updated_at = now() where id = p_deal;
  else
    update public.movein_deals set final_intent_id = p_intent, updated_at = now() where id = p_deal;
  end if;

  insert into public.movein_audit (deal_id, actor, action, reason, evidence, payload)
    values (p_deal, 'system', 'payment_invoiced', p_leg || ' invoice issued', p_intent::text,
            jsonb_build_object('leg', p_leg, 'intent_id', p_intent, 'amount_gbp', v_expected));
  perform public.movein_sync_payments(p_deal);
end $$;


--
-- Name: movein_audit_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_audit_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'movein_audit is append-only';
end $$;


--
-- Name: movein_band_for(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_band_for(p_mailboxes integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select case
    when coalesce(p_mailboxes,1) <= 5  then '1-5'
    when p_mailboxes <= 15 then '6-15'
    when p_mailboxes <= 29 then '16-29'
    else '30plus' end
$$;


--
-- Name: movein_book_slot(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_book_slot(p_deal uuid, p_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_month date := date_trunc('month', p_month)::date;
        v_total int; v_used int; v_pos int;
begin
  perform pg_advisory_xact_lock(hashtext('movein_capacity:' || v_month::text));
  insert into public.movein_capacity (month) values (v_month) on conflict (month) do nothing;
  select slots_total into v_total from public.movein_capacity where month = v_month;
  select count(*) into v_used from public.movein_deals
   where scheduled_month = v_month and waitlisted = false and state <> 'CANCELLED' and id <> p_deal;

  if v_used < v_total then
    update public.movein_deals
       set scheduled_month = v_month, waitlisted = false, updated_at = now()
     where id = p_deal;
    delete from public.movein_waitlist where deal_id = p_deal and month = v_month;
    insert into public.movein_audit (deal_id, actor, action, reason, payload)
      values (p_deal, 'system', 'capacity_booked', 'slot reserved', jsonb_build_object('month', v_month));
    return jsonb_build_object('booked', true, 'month', v_month, 'slots_used', v_used + 1, 'slots_total', v_total);
  end if;

  select coalesce(max(position), 0) + 1 into v_pos from public.movein_waitlist
   where month = v_month and released_at is null;
  insert into public.movein_waitlist (deal_id, month, position)
    values (p_deal, v_month, v_pos)
    on conflict (deal_id, month) do update set position = excluded.position;
  update public.movein_deals set scheduled_month = v_month, waitlisted = true, updated_at = now()
   where id = p_deal;
  insert into public.movein_audit (deal_id, actor, action, reason, payload)
    values (p_deal, 'system', 'waitlisted', 'month at capacity', jsonb_build_object('month', v_month, 'position', v_pos));
  return jsonb_build_object('booked', false, 'waitlisted', true, 'position', v_pos, 'month', v_month, 'slots_total', v_total);
end $$;


--
-- Name: movein_cockpit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_cockpit() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select jsonb_build_object(
    'active_moves', (select count(*) from public.movein_deals
       where state not in ('LEAD','QUALIFIED','CLOSED','CANCELLED')),
    'capacity', (select coalesce(to_jsonb(c), '{}'::jsonb) from public.movein_capacity_state c
       where c.month = date_trunc('month', now())::date),
    'waitlisted', (select count(*) from public.movein_waitlist where released_at is null),
    'cash', (select to_jsonb(x) from public.movein_cash_clock x),
    'cutovers_tonight', (select count(*) from public.movein_deals
       where cutover_window_start between now() and now() + interval '24 hours'),
    'blocked', (select count(*) from public.movein_exceptions
       where resolved_at is null and severity in ('BLOCKED','FAILED','ROLLBACK_REQUIRED')),
    'exceptions_open', (select count(*) from public.movein_exceptions where resolved_at is null),
    'dns_proof_pct', (select coalesce(round(100.0 * count(*) filter (where result='VERIFIED')
       / greatest(count(*),1)), 0) from public.movein_dns_proof),
    'mailbox_verification_pct', (select coalesce(round(100.0 * count(*) filter (where result='VERIFIED')
       / greatest(count(*),1)), 0) from public.movein_mailboxes),
    'attention', (select coalesce(jsonb_agg(to_jsonb(a)), '[]'::jsonb) from public.movein_attention a),
    'board', (select coalesce(jsonb_agg(jsonb_build_object(
         'id', d.id, 'reference', d.reference, 'company', d.company, 'state', d.state,
         'band', d.band, 'price_gbp', d.price_gbp, 'health', d.health_score,
         'waitlisted', d.waitlisted, 'mailboxes', d.mailbox_count,
         'deposit_paid', public.movein_leg_paid(d.id,'deposit'),
         'final_paid', public.movein_leg_paid(d.id,'final'),
         'cutover_window_start', d.cutover_window_start,
         'updated_at', d.updated_at) order by d.updated_at desc), '[]'::jsonb)
       from public.movein_deals d where d.state <> 'CLOSED'),
    'generated_at', now()
  )
$$;


--
-- Name: movein_customer_view(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_customer_view(p_deal uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select jsonb_build_object(
    'reference', d.reference,
    'company', d.company,
    'state', d.state,
    'progress', (select round(100.0 * count(distinct a.to_state) / 9.0)
                   from public.movein_audit a
                  where a.deal_id = d.id
                    and a.to_state::text = any (array['PLAN_ACCEPTED','DEPOSIT_PAID_50','MIGRATION_PREP',
                        'DATA_VERIFIED','CUTOVER_SCHEDULED','CUTOVER_EXECUTED',
                        'POST_CUTOVER_VERIFIED','FINAL_50_PAID','HANDOVER_COMPLETE'])),
    'cutover_window', jsonb_build_object('start', d.cutover_window_start, 'end', d.cutover_window_end),
    'cutover_note', 'Scheduled overnight cut-over designed to avoid interruption.',
    'payments', (select coalesce(jsonb_agg(jsonb_build_object('leg', leg, 'amount_gbp', amount_gbp,
                        'state', state) order by leg), '[]'::jsonb)
                   from public.movein_payments where deal_id = d.id),
    'dns_proof', (select coalesce(jsonb_agg(jsonb_build_object('phase', phase, 'record', record,
                        'result', result, 'checked_at', checked_at) order by phase, record), '[]'::jsonb)
                   from public.movein_dns_proof where deal_id = d.id),
    'mailboxes_verified', (select count(*) from public.movein_mailboxes where deal_id = d.id and result='VERIFIED'),
    'mailboxes_total', (select count(*) from public.movein_mailboxes where deal_id = d.id),
    'customer_action', (select coalesce(jsonb_agg(jsonb_build_object('reason', reason,
                        'required_action', required_action)), '[]'::jsonb)
                   from public.movein_exceptions
                  where deal_id = d.id and resolved_at is null
                    and severity = 'CUSTOMER_ACTION_REQUIRED'),
    'health', public.movein_health_calc(d.id)
  ) from public.movein_deals d where d.id = p_deal
$$;


--
-- Name: movein_cutover_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_cutover_ready(p_deal uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select coalesce(
    (select count(*) = 0 from public.movein_runbook
      where deal_id = p_deal and required and result <> 'VERIFIED'), false)
   and coalesce((select count(*) > 0 from public.movein_runbook where deal_id = p_deal), false)
   and public.movein_dns_green(p_deal, 'PRE')
   and coalesce((select count(*) = 0 from public.movein_exceptions
      where deal_id = p_deal and resolved_at is null
        and severity in ('BLOCKED','FAILED','ROLLBACK_REQUIRED','CUSTOMER_ACTION_REQUIRED')), true)
$$;


--
-- Name: movein_data_verified_ok(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_data_verified_ok(p_deal uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select (count(*) > 0)
       and (count(*) = greatest(coalesce(d.mailbox_count, 0), 1))
       and (count(*) filter (where m.result <> 'VERIFIED') = 0)
       and (count(*) filter (where m.messages_source <= 0) = 0)
       and (count(*) filter (where m.messages_verified < m.messages_source) = 0)
      from public.movein_mailboxes m where m.deal_id = d.id
  ), false)
  from public.movein_deals d where d.id = p_deal
$$;


--
-- Name: movein_dns_green(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_dns_green(p_deal uuid, p_phase text DEFAULT 'POST'::text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select coalesce(count(*) filter (where result = 'VERIFIED') = 4, false)
    from public.movein_dns_proof
   where deal_id = p_deal and phase = p_phase
     and record in ('MX','SPF','DKIM','DMARC')
$$;


--
-- Name: movein_dns_owner_fill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_dns_owner_fill() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.owner_id is null then
    select coalesce(d.owner_id, d.user_id) into new.owner_id
      from public.movein_deals d where d.id = new.deal_id;
  end if;
  return new;
end $$;


--
-- Name: movein_evidence_bundle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_evidence_bundle(p_deal uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select jsonb_build_object(
    'reference', d.reference,
    'company', d.company,
    'domain', d.domain,
    'band', d.band,
    'price_gbp', d.price_gbp,
    'state', d.state,
    'scope', jsonb_build_object('mailboxes', d.mailbox_count, 'source_provider', d.source_provider,
                                'cutover_window_start', d.cutover_window_start,
                                'cutover_window_end', d.cutover_window_end),
    'payments', (select coalesce(jsonb_agg(jsonb_build_object('leg', leg, 'amount_gbp', amount_gbp,
                        'state', state, 'paid_at', paid_at) order by leg), '[]'::jsonb)
                   from public.movein_payments where deal_id = d.id),
    'mailbox_ledger', (select coalesce(jsonb_agg(to_jsonb(m) order by m.address), '[]'::jsonb)
                   from public.movein_mailboxes m where m.deal_id = d.id),
    'dns_proof', (select coalesce(jsonb_agg(to_jsonb(p) order by p.phase, p.record), '[]'::jsonb)
                   from public.movein_dns_proof p where p.deal_id = d.id),
    'runbook', (select coalesce(jsonb_agg(jsonb_build_object('label', label, 'result', result,
                        'evidence', evidence, 'completed_at', completed_at) order by position), '[]'::jsonb)
                   from public.movein_runbook where deal_id = d.id),
    'exceptions', (select coalesce(jsonb_agg(jsonb_build_object('scope', scope, 'ref', ref,
                        'severity', severity, 'reason', reason, 'required_action', required_action,
                        'resolved_at', resolved_at) order by created_at), '[]'::jsonb)
                   from public.movein_exceptions where deal_id = d.id),
    'rollback', (select coalesce(jsonb_agg(jsonb_build_object('label', label, 'available', available,
                        'created_at', created_at) order by created_at desc), '[]'::jsonb)
                   from public.movein_rollback_points where deal_id = d.id),
    'audit', (select coalesce(jsonb_agg(jsonb_build_object('actor', actor, 'action', action,
                        'from_state', from_state, 'to_state', to_state, 'reason', reason,
                        'evidence', evidence, 'at', created_at) order by created_at), '[]'::jsonb)
                   from public.movein_audit where deal_id = d.id),
    'health', public.movein_health_calc(d.id),
    'cutover_note', 'Scheduled overnight cut-over designed to avoid interruption.',
    'generated_at', now()
  )
  from public.movein_deals d where d.id = p_deal
$$;


--
-- Name: movein_evidence_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_evidence_validate() RETURNS TABLE(constraint_name text, invalid_rows bigint, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_mail  bigint;
  v_phase bigint;
  v_rec   bigint;
begin
  select count(*) into v_mail  from public.movein_evidence_violations
   where source_table = 'movein_mailboxes';
  select count(*) into v_phase from public.movein_evidence_violations
   where source_table = 'movein_dns_checks' and violation = 'invalid_phase';
  select count(*) into v_rec   from public.movein_evidence_violations
   where source_table = 'movein_dns_checks' and violation = 'invalid_record';

  if v_mail = 0 then
    begin alter table public.movein_mailboxes validate constraint movein_mailboxes_counts_chk;
    exception when undefined_object then null; end;
  end if;
  if v_phase = 0 then
    begin alter table public.movein_dns_checks validate constraint movein_dns_phase_chk;
    exception when undefined_object then null; end;
  end if;
  if v_rec = 0 then
    begin alter table public.movein_dns_checks validate constraint movein_dns_record_chk;
    exception when undefined_object then null; end;
  end if;

  return query
  select c.conname::text,
         case c.conname
           when 'movein_mailboxes_counts_chk' then v_mail
           when 'movein_dns_phase_chk'        then v_phase
           else v_rec
         end,
         case when c.convalidated then 'VALIDATED (data clean)'
              else 'NOT VALID — future writes enforced, historical rows preserved for manual correction'
         end
    from pg_constraint c
   where c.conname in ('movein_mailboxes_counts_chk','movein_dns_phase_chk','movein_dns_record_chk')
   order by 1;
end $$;


--
-- Name: movein_exception_blocks_fill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_exception_blocks_fill() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.severity in ('BLOCKED','FAILED','ROLLBACK_REQUIRED') then
    new.blocks_cutover := true;
  end if;
  return new;
end $$;


--
-- Name: movein_health(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_health(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare v jsonb;
begin
  v := public.movein_health_calc(p_deal);
  update public.movein_deals
     set health_score = coalesce((v->>'overall')::numeric, 0)::int, updated_at = now()
   where id = p_deal;
  return v;
end $$;


--
-- Name: movein_health_calc(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_health_calc(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_mb_total int; v_mb_ok int; v_msg_src bigint; v_msg_ver bigint;
  v_dns int; v_run_total int; v_run_ok int;
  v_mailbox numeric := 0; v_data numeric := 0; v_dnsp numeric := 0;
  v_pay numeric := 0; v_cut numeric := 0; v_overall numeric := 0;
begin
  select count(*), count(*) filter (where result = 'VERIFIED'),
         coalesce(sum(messages_source),0), coalesce(sum(messages_verified),0)
    into v_mb_total, v_mb_ok, v_msg_src, v_msg_ver
    from public.movein_mailboxes where deal_id = p_deal;

  select count(*) filter (where result = 'VERIFIED') into v_dns
    from public.movein_dns_proof where deal_id = p_deal and phase = 'PRE'
      and record in ('MX','SPF','DKIM','DMARC');

  select count(*) filter (where required), count(*) filter (where required and result = 'VERIFIED')
    into v_run_total, v_run_ok from public.movein_runbook where deal_id = p_deal;

  v_mailbox := case when v_mb_total = 0 then 0 else round(100.0 * v_mb_ok / v_mb_total, 0) end;
  v_data    := case when v_msg_src = 0 then 0 else round(100.0 * least(v_msg_ver, v_msg_src) / v_msg_src, 0) end;
  v_dnsp    := round(100.0 * least(v_dns,4) / 4, 0);
  v_pay     := (case when public.movein_leg_paid(p_deal,'deposit') then 50 else 0 end)
             + (case when public.movein_leg_paid(p_deal,'final')   then 50 else 0 end);
  v_cut     := case when v_run_total = 0 then 0 else round(100.0 * v_run_ok / v_run_total, 0) end;
  v_overall := round((v_mailbox + v_data + v_dnsp + v_pay + v_cut) / 5.0, 0);

  return jsonb_build_object(
    'mailbox_verification', v_mailbox,
    'data_verification', v_data,
    'dns_readiness', v_dnsp,
    'payment_readiness', v_pay,
    'cutover_readiness', v_cut,
    'overall', v_overall,
    'mailboxes', v_mb_total,
    'messages_source', v_msg_src,
    'messages_verified', v_msg_ver
  );
end $$;


--
-- Name: movein_is_deal_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_is_deal_member(p_deal uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1 from public.movein_deals d
     where d.id = p_deal
       and auth.uid() is not null
       and (d.user_id = auth.uid() or d.owner_id = auth.uid())
  )
$$;


--
-- Name: movein_leg_paid(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_leg_paid(p_deal uuid, p_leg text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select coalesce((select state = 'paid' from public.movein_payments
                    where deal_id = p_deal and leg = p_leg), false)
$$;


--
-- Name: movein_next_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_next_reference() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare n int;
begin
  select count(*) + 1 into n from public.movein_deals
   where date_part('year', created_at) = date_part('year', now());
  return 'MOVE-IN-' || to_char(now(), 'YYYY') || '-' || lpad(n::text, 3, '0');
end $$;


--
-- Name: movein_open_deal(text, text, integer, text, text, text, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_open_deal(p_company text, p_email text, p_mailboxes integer DEFAULT 1, p_domain text DEFAULT NULL::text, p_provider text DEFAULT 'other'::text, p_contact text DEFAULT NULL::text, p_user uuid DEFAULT NULL::uuid, p_month date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid; v_band text; v_price numeric; v_book jsonb;
begin
  v_band  := public.movein_band_for(p_mailboxes);
  v_price := public.movein_price_for(v_band);

  insert into public.movein_deals
    (reference, user_id, company, contact_name, contact_email, domain, source_provider,
     mailbox_count, band, price_gbp, deposit_gbp, final_gbp)
  values
    (public.movein_next_reference(), p_user, p_company, p_contact, lower(p_email), lower(p_domain),
     p_provider, greatest(coalesce(p_mailboxes,1),1), v_band, v_price,
     round(v_price/2,2), v_price - round(v_price/2,2))
  returning id into v_id;

  perform public.movein_seed_runbook(v_id);
  perform public.movein_sync_payments(v_id);
  insert into public.movein_audit (deal_id, actor, action, to_state, reason, payload)
    values (v_id, 'system', 'deal_opened', 'LEAD', 'move-in request received',
            jsonb_build_object('band', v_band, 'price_gbp', v_price));

  if p_month is not null then
    v_book := public.movein_book_slot(v_id, p_month);
  end if;

  perform public.movein_health(v_id);
  return jsonb_build_object('deal_id', v_id, 'band', v_band, 'price_gbp', v_price,
                            'deposit_gbp', round(v_price/2,2), 'capacity', v_book,
                            'reference', (select reference from public.movein_deals where id = v_id));
end $$;


--
-- Name: movein_price_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_price_for(p_band text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select case p_band
    when '1-5'    then 568
    when '6-15'   then 1670
    when '16-29'  then 2210
    when '30plus' then 3350
    else 568 end::numeric
$$;


--
-- Name: movein_promote_waitlist(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_promote_waitlist(p_month date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_month date := date_trunc('month', p_month)::date;
        v_total int; v_used int; v_promoted jsonb := '[]'::jsonb;
        v_deal uuid; v_pos int; v_wid uuid;
begin
  perform pg_advisory_xact_lock(hashtext('movein_capacity:' || v_month::text));
  insert into public.movein_capacity (month) values (v_month) on conflict (month) do nothing;
  select slots_total into v_total from public.movein_capacity where month = v_month;

  loop
    select count(*) into v_used from public.movein_deals
     where scheduled_month = v_month and waitlisted = false and state <> 'CANCELLED';
    exit when v_used >= coalesce(v_total, 2);

    v_deal := null; v_pos := null; v_wid := null;
    select w2.id, w2.deal_id, w2.position into v_wid, v_deal, v_pos
      from public.movein_waitlist w2
      join public.movein_deals d on d.id = w2.deal_id
     where w2.month = v_month and w2.released_at is null and d.state <> 'CANCELLED'
     order by w2.position asc, w2.created_at asc
     limit 1;
    exit when v_deal is null;

    update public.movein_deals
       set scheduled_month = v_month, waitlisted = false, updated_at = now()
     where id = v_deal;
    update public.movein_waitlist set released_at = now() where id = v_wid;

    insert into public.movein_audit (deal_id, actor, action, reason, payload)
      values (v_deal, 'system', 'waitlist_promoted', 'slot released, promoted from waitlist',
              jsonb_build_object('month', v_month, 'position', v_pos));
    v_promoted := v_promoted || jsonb_build_object('deal_id', v_deal, 'position', v_pos);
  end loop;

  return jsonb_build_object('ok', true, 'month', v_month, 'promoted', v_promoted);
end $$;


--
-- Name: movein_rollback_create(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_rollback_create(p_deal uuid, p_label text DEFAULT 'pre-cutover'::text, p_operator text DEFAULT 'founder'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  if not exists (select 1 from public.movein_deals where id = p_deal) then
    return jsonb_build_object('ok', false, 'error', 'deal_not_found');
  end if;

  insert into public.movein_rollback_points (deal_id, label, operator,
    source_state, destination_state, dns_state, verification_state, available)
  values (p_deal, p_label, p_operator,
    (select coalesce(jsonb_agg(jsonb_build_object('address', address, 'source_provider', source_provider,
        'messages_source', messages_source)), '[]'::jsonb) from public.movein_mailboxes where deal_id = p_deal),
    (select coalesce(jsonb_agg(jsonb_build_object('address', address, 'destination', destination,
        'destination_status', destination_status)), '[]'::jsonb) from public.movein_mailboxes where deal_id = p_deal),
    (select coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb) from public.movein_dns_proof p where p.deal_id = p_deal),
    public.movein_health_calc(p_deal),
    true)
  returning id into v_id;

  insert into public.movein_audit (deal_id, actor, action, reason, evidence)
    values (p_deal, p_operator, 'rollback_point_created', p_label, v_id::text);
  return jsonb_build_object('ok', true, 'rollback_id', v_id);
end $$;


--
-- Name: movein_rollback_use(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_rollback_use(p_deal uuid, p_reason text DEFAULT 'cutover failed'::text, p_operator text DEFAULT 'founder'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; v jsonb;
begin
  v := public.movein_rollback_validate(p_deal);
  if coalesce((v->>'ok')::boolean, false) is not true then
    return jsonb_build_object('ok', false, 'error', 'rollback_invalid', 'detail', v);
  end if;

  select * into r from public.movein_rollback_points where id = (v->>'rollback_id')::uuid for update;
  update public.movein_rollback_points
     set available = false, used_at = now() where id = r.id;

  insert into public.movein_exceptions (deal_id, scope, ref, severity, reason, required_action, blocks_cutover)
    values (p_deal, 'cutover', r.id::text, 'ROLLBACK_REQUIRED', p_reason,
            'Rollback executed — re-verify data then re-arm cut-over', true);

  update public.movein_deals
     set cutover_armed_at = null, cutover_executed_at = null, updated_at = now()
   where id = p_deal;

  insert into public.movein_audit (deal_id, actor, action, reason, evidence, payload)
    values (p_deal, p_operator, 'rollback_used', p_reason, r.id::text, r.dns_state);

  -- enum mein ROLLBACK state nahi hai — deal ON_HOLD par jata hai (exception ledger mein ROLLBACK_REQUIRED)
  perform public.movein_transition(p_deal, 'ON_HOLD'::public.movein_state, p_operator, p_reason, r.id::text);
  return jsonb_build_object('ok', true, 'rollback_id', r.id, 'state', 'ON_HOLD');
end $$;


--
-- Name: movein_rollback_validate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_rollback_validate(p_deal uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record;
begin
  select * into r from public.movein_rollback_points
   where deal_id = p_deal and available and used_at is null
   order by created_at desc limit 1;
  if r is null then
    return jsonb_build_object('ok', false, 'error', 'no_rollback_point');
  end if;
  return jsonb_build_object('ok',
      jsonb_array_length(coalesce(r.source_state,'[]'::jsonb)) > 0
      and jsonb_array_length(coalesce(r.dns_state,'[]'::jsonb)) > 0,
    'rollback_id', r.id, 'label', r.label,
    'source_entries', jsonb_array_length(coalesce(r.source_state,'[]'::jsonb)),
    'dns_entries', jsonb_array_length(coalesce(r.dns_state,'[]'::jsonb)),
    'created_at', r.created_at);
end $$;


--
-- Name: movein_seed_runbook(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_seed_runbook(p_deal uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_n int := 0;
begin
  insert into public.movein_runbook (deal_id, step_key, label, position)
  select p_deal, s.k, s.l, s.p from (values
    ('mailboxes_created','All mailboxes created', 1),
    ('data_copy_complete','Source data copy complete', 2),
    ('counts_verified','Message counts verified', 3),
    ('dns_prepared','DNS records prepared', 4),
    ('mx_ttl','MX TTL checked and lowered', 5),
    ('spf_verified','SPF verified', 6),
    ('dkim_verified','DKIM verified', 7),
    ('dmarc_verified','DMARC verified', 8),
    ('test_mailbox','Test mailbox working', 9),
    ('test_inbound','Test inbound delivery', 10),
    ('test_outbound','Test outbound delivery', 11),
    ('rollback_point','Rollback point recorded', 12),
    ('customer_approval','Customer approval recorded', 13)
  ) as s(k,l,p)
  on conflict (deal_id, step_key) do nothing;
  select count(*) into v_n from public.movein_runbook where deal_id = p_deal;
  return v_n;
end $$;


--
-- Name: movein_sync_payments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_sync_payments(p_deal uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d record; v_dep numeric; v_fin numeric;
begin
  select * into d from public.movein_deals where id = p_deal;
  if d is null then return; end if;
  v_dep := coalesce(d.deposit_gbp, round(d.price_gbp / 2, 2));
  v_fin := coalesce(d.final_gbp, d.price_gbp - v_dep);

  insert into public.movein_payments (deal_id, leg, amount_gbp)
    values (p_deal, 'deposit', v_dep)
    on conflict (deal_id, leg) do update set amount_gbp = excluded.amount_gbp, updated_at = now();
  insert into public.movein_payments (deal_id, leg, amount_gbp)
    values (p_deal, 'final', v_fin)
    on conflict (deal_id, leg) do update set amount_gbp = excluded.amount_gbp, updated_at = now();

  -- Phase 36 truth: intent paid ho to leg paid (idempotent)
  update public.movein_payments p
     set state = 'paid', paid_at = coalesce(p.paid_at, i.paid_at, now()), updated_at = now()
    from public.billing_intents i
   where p.deal_id = p_deal and p.intent_id = i.id
     and i.state in ('paid','entitled') and p.state <> 'paid';

  update public.movein_deals set
      deposit_gbp = v_dep,
      final_gbp   = v_fin,
      deposit_paid_at = (select paid_at from public.movein_payments where deal_id = p_deal and leg='deposit' and state='paid'),
      final_paid_at   = (select paid_at from public.movein_payments where deal_id = p_deal and leg='final'   and state='paid'),
      updated_at = now()
   where id = p_deal;
end $$;


--
-- Name: movein_transition(uuid, public.movein_state, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.movein_transition(p_deal uuid, p_to public.movein_state, p_actor text DEFAULT 'founder'::text, p_reason text DEFAULT NULL::text, p_evidence text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare d record; v_gate text; v_ok boolean := true; v_why text;
begin
  select * into d from public.movein_deals where id = p_deal for update;
  if d is null then return jsonb_build_object('ok', false, 'error', 'deal_not_found'); end if;
  if d.state = p_to then
    return jsonb_build_object('ok', true, 'state', p_to, 'idempotent', true);
  end if;

  select gate into v_gate from public.movein_transitions
   where from_state = d.state and to_state = p_to;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'illegal_transition',
      'from', d.state, 'to', p_to,
      'allowed', (select coalesce(jsonb_agg(to_state), '[]'::jsonb)
                    from public.movein_transitions where from_state = d.state));
  end if;

  if v_gate = 'deposit_paid' and not public.movein_leg_paid(p_deal, 'deposit') then
    v_ok := false; v_why := 'deposit_50_not_paid';
  elsif v_gate = 'final_paid' and not public.movein_leg_paid(p_deal, 'final') then
    v_ok := false; v_why := 'final_50_not_paid';
  elsif v_gate = 'data_verified' and exists (
        select 1 from public.movein_mailboxes where deal_id = p_deal and result <> 'VERIFIED') then
    v_ok := false; v_why := 'mailbox_ledger_not_verified';
  elsif v_gate = 'cutover_ready' and not public.movein_cutover_ready(p_deal) then
    v_ok := false; v_why := 'runbook_or_dns_or_exception_open';
  elsif v_gate = 'cutover_armed' and d.cutover_armed_at is null then
    v_ok := false; v_why := 'cutover_not_armed';
  elsif v_gate = 'dns_green' and not public.movein_dns_green(p_deal, 'POST') then
    v_ok := false; v_why := 'post_cutover_dns_not_green';
  end if;

  if not v_ok then
    insert into public.movein_audit (deal_id, actor, actor_id, action, from_state, to_state, reason, payload)
      values (p_deal, p_actor, p_actor_id, 'transition_blocked', d.state, p_to, v_why,
              jsonb_build_object('gate', v_gate));
    return jsonb_build_object('ok', false, 'error', 'gate_blocked', 'gate', v_gate, 'reason', v_why);
  end if;

  update public.movein_deals set
      state = p_to,
      cutover_executed_at = case when p_to = 'CUTOVER_EXECUTED' then now() else cutover_executed_at end,
      closed_at = case when p_to in ('CLOSED','CANCELLED') then now() else closed_at end,
      updated_at = now()
   where id = p_deal;

  insert into public.movein_audit (deal_id, actor, actor_id, action, from_state, to_state, reason, evidence, payment_state, payload)
    values (p_deal, p_actor, p_actor_id, 'state_changed', d.state, p_to, p_reason, p_evidence,
            case when public.movein_leg_paid(p_deal,'final') then 'final_paid'
                 when public.movein_leg_paid(p_deal,'deposit') then 'deposit_paid'
                 else 'unpaid' end,
            jsonb_build_object('gate', v_gate));

  perform public.movein_health(p_deal);
  return jsonb_build_object('ok', true, 'from', d.state, 'state', p_to, 'gate', v_gate);
end $$;


--
-- Name: org_address_create(uuid, uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_address_create(_org uuid, _domain_id uuid, _local text, _kind text DEFAULT 'mailbox'::text, _owner uuid DEFAULT NULL::uuid, _alias_target text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare l text := lower(trim(coalesce(_local,''))); dom public.org_domains; addr text;
        plan text; cap integer; used integer; row_ public.org_addresses; k text := coalesce(_kind,'mailbox');
begin
  select * into dom from public.org_domains where id = _domain_id and org_id = _org and status <> 'removed';
  if dom.id is null then return jsonb_build_object('ok', false, 'error', 'domain_not_found'); end if;
  if dom.status <> 'verified' then return jsonb_build_object('ok', false, 'error', 'domain_not_verified'); end if;
  if k not in ('mailbox','shared','alias') then return jsonb_build_object('ok', false, 'error', 'invalid_kind'); end if;
  if l !~ '^[a-z0-9]([a-z0-9._-]{0,62}[a-z0-9])?$' then return jsonb_build_object('ok', false, 'error', 'invalid_local_part'); end if;
  if k = 'alias' and coalesce(trim(_alias_target),'') = '' then return jsonb_build_object('ok', false, 'error', 'alias_target_required'); end if;
  addr := l || '@' || dom.domain;
  if exists (select 1 from public.org_addresses a where a.address = addr and a.active)
     or exists (select 1 from public.mail_accounts m where lower(m.address) = addr and m.org_id <> _org) then
    return jsonb_build_object('ok', false, 'error', 'address_taken');
  end if;
  if k <> 'alias' then
    plan := public.org_plan_of(_org);
    cap  := public.org_mailbox_cap(plan);
    select count(*) into used from public.org_addresses where org_id = _org and active and kind in ('mailbox','shared');
    if cap is not null and used >= cap then
      return jsonb_build_object('ok', false, 'error', 'mailbox_limit', 'plan', plan, 'limit', cap, 'used', used);
    end if;
  end if;
  insert into public.org_addresses (org_id, domain_id, local_part, address, kind, owner_user_id, alias_target)
  values (_org, _domain_id, l, addr, k, _owner, lower(nullif(trim(_alias_target),''))) returning * into row_;
  if k <> 'alias' then   -- mail_ingest isi se owner org pehchanta hai
    insert into public.mail_accounts (org_id, address) values (_org, addr) on conflict do nothing;
  end if;
  return jsonb_build_object('ok', true, 'address', to_jsonb(row_));
end $_$;


--
-- Name: org_address_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_address_list(_org uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at), '[]'::jsonb)
    from public.org_addresses a where a.org_id = _org and a.active;
$$;


--
-- Name: org_address_remove(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_address_remove(_org uuid, _id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.org_addresses set active = false where id = _id and org_id = _org and active;
  return jsonb_build_object('ok', found);
end $$;


--
-- Name: org_audit_chain_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_audit_chain_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'org_audit_chain is append-only (% blocked)', tg_op using errcode = '42501';
end;
$$;


--
-- Name: org_chain_append(text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_chain_append(p_actor text, p_action text, p_target text DEFAULT NULL::text, p_ip text DEFAULT NULL::text, p_org uuid DEFAULT NULL::uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_seq bigint; v_prev text; v_at timestamptz := clock_timestamp();
begin
  if coalesce(trim(p_action), '') = '' then
    raise exception 'org_chain_append: action is required';
  end if;
  -- serialise appends per chain so seq / prev_hash can never fork
  perform pg_advisory_xact_lock(hashtextextended('org_audit_chain:' || coalesce(p_org::text, '-'), 0));
  select l.seq, l.hash into v_seq, v_prev
    from public.org_audit_chain l
   where l.org_id is not distinct from p_org
   order by l.seq desc limit 1;
  v_seq := coalesce(v_seq, 0) + 1;
  insert into public.org_audit_chain (org_id, seq, actor, action, target, ip, prev_hash, hash, created_at)
  values (p_org, v_seq, coalesce(p_actor, ''), p_action, p_target, p_ip, v_prev,
          public.org_chain_hash(v_prev, p_org, v_seq, coalesce(p_actor, ''), p_action, p_target, p_ip, v_at), v_at);
  return v_seq;
end;
$$;


--
-- Name: org_chain_hash(text, uuid, bigint, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_chain_hash(p_prev text, p_org uuid, p_seq bigint, p_actor text, p_action text, p_target text, p_ip text, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select encode(sha256(convert_to(
    coalesce(p_prev, 'genesis') || '|' || coalesce(p_org::text, '-') || '|' || p_seq::text || '|' ||
    coalesce(p_actor, '') || '|' || coalesce(p_action, '') || '|' || coalesce(p_target, '') || '|' ||
    coalesce(p_ip, '') || '|' || to_char(p_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
    'UTF8')), 'hex');
$$;


--
-- Name: org_chain_verify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_chain_verify(p_org uuid DEFAULT NULL::uuid) RETURNS TABLE(ok boolean, checked bigint, broken_at_seq bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record; v_prev text := null; v_n bigint := 0; v_expect bigint := 0;
begin
  for r in
    select * from public.org_audit_chain l where l.org_id is not distinct from p_org order by l.seq
  loop
    v_n := v_n + 1;
    v_expect := v_expect + 1;
    if r.seq <> v_expect
       or r.prev_hash is distinct from v_prev
       or r.hash <> public.org_chain_hash(v_prev, r.org_id, r.seq, r.actor, r.action, r.target, r.ip, r.created_at) then
      return query select false, v_n, r.seq;
      return;
    end if;
    v_prev := r.hash;
  end loop;
  return query select true, v_n, null::bigint;
end;
$$;


--
-- Name: org_domain_add(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_domain_add(_org uuid, _domain text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare d text := lower(trim(coalesce(_domain,''))); plan text; cap integer; used integer; row_ public.org_domains;
begin
  d := regexp_replace(d, '^(https?://)?(www\.)?', '');
  d := regexp_replace(d, '[/:].*$', '');
  if d !~ '^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_domain');
  end if;
  if d in ('anexomail.com') or d like '%.anexomail.com' then
    return jsonb_build_object('ok', false, 'error', 'reserved_domain');
  end if;
  if exists (select 1 from public.organisations o where o.id = _org and o.slug like 'personal-%') then
    return jsonb_build_object('ok', false, 'error', 'business_required');
  end if;
  if exists (select 1 from public.org_domains x where x.domain = d and x.status <> 'removed') then
    return jsonb_build_object('ok', false, 'error', 'domain_taken');
  end if;
  plan := public.org_plan_of(_org);
  cap  := public.org_domain_cap(plan);
  select count(*) into used from public.org_domains where org_id = _org and status <> 'removed';
  if cap is not null and used >= cap then
    return jsonb_build_object('ok', false, 'error', 'domain_limit_reached', 'plan', plan, 'limit', cap, 'used', used);
  end if;
  insert into public.org_domains (org_id, domain) values (_org, d) returning * into row_;
  return jsonb_build_object('ok', true, 'domain', to_jsonb(row_));
end $_$;


--
-- Name: org_domain_cap(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_domain_cap(_plan text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case _plan when 'basic' then 1 when 'pro' then 3 else null end;   -- NULL = unlimited
$$;


--
-- Name: org_domain_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_domain_list(_org uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at), '[]'::jsonb)
    from public.org_domains x where x.org_id = _org and x.status <> 'removed';
$$;


--
-- Name: org_domain_remove(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_domain_remove(_org uuid, _id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.org_addresses set active = false where domain_id = _id and org_id = _org;
  update public.org_domains set status = 'removed' where id = _id and org_id = _org and status <> 'removed';
  return jsonb_build_object('ok', found);
end $$;


--
-- Name: org_domain_set_checks(uuid, boolean, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_domain_set_checks(_id uuid, _txt boolean, _mx boolean, _spf boolean, _dkim boolean, _dmarc boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.org_domains; all_ok boolean;
begin
  all_ok := coalesce(_txt,false) and coalesce(_mx,false) and coalesce(_spf,false)
        and coalesce(_dkim,false) and coalesce(_dmarc,false);
  update public.org_domains
     set txt_ok = coalesce(_txt,false), mx_ok = coalesce(_mx,false), spf_ok = coalesce(_spf,false),
         dkim_ok = coalesce(_dkim,false), dmarc_ok = coalesce(_dmarc,false),
         last_checked_at = now(),
         status = case when all_ok then 'verified' else 'pending' end,
         verified_at = case when all_ok then coalesce(verified_at, now()) else null end
   where id = _id and status <> 'removed'
   returning * into r;
  if r.id is null then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  return jsonb_build_object('ok', true, 'domain', to_jsonb(r));
end $$;


--
-- Name: org_domain_set_dkim(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_domain_set_dkim(_id uuid, _public text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.org_domains set dkim_public = nullif(trim(_public), '') where id = _id and status <> 'removed';
  return jsonb_build_object('ok', found);
end $$;


--
-- Name: org_audit_ledger; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.org_audit_ledger (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organisation_id uuid NOT NULL,
    seq bigint NOT NULL,
    actor text NOT NULL,
    action text NOT NULL,
    target text,
    ip text,
    meta jsonb DEFAULT '{}'::jsonb NOT NULL,
    prev_hash text,
    hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: org_ledger_append(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_ledger_append(_org uuid, _actor text, _action text, _target text DEFAULT NULL::text, _ip text DEFAULT NULL::text, _meta jsonb DEFAULT '{}'::jsonb) RETURNS public.org_audit_ledger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _prev public.org_audit_ledger; _seq bigint; _prev_hash text; _hash text; _row public.org_audit_ledger;
begin
  select * into _prev from public.org_audit_ledger
   where organisation_id = _org order by seq desc limit 1;
  _seq := coalesce(_prev.seq, 0) + 1;
  _prev_hash := _prev.hash;
  _hash := encode(digest(
    coalesce(_prev_hash,'genesis') || '|' || _org::text || '|' || _seq::text || '|' ||
    _actor || '|' || _action || '|' || coalesce(_target,'') || '|' ||
    coalesce(_ip,'') || '|' || _meta::text, 'sha256'), 'hex');
  insert into public.org_audit_ledger
    (organisation_id, seq, actor, action, target, ip, meta, prev_hash, hash)
  values (_org, _seq, _actor, _action, _target, _ip, _meta, _prev_hash, _hash)
  returning * into _row;
  return _row;
end $$;


--
-- Name: org_ledger_verify(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_ledger_verify(_org uuid) RETURNS TABLE(ok boolean, checked bigint, broken_at_seq bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; _prev text := null; _calc text; _n bigint := 0; _broken bigint := null;
begin
  for r in select * from public.org_audit_ledger where organisation_id = _org order by seq asc loop
    _calc := encode(digest(
      coalesce(_prev,'genesis') || '|' || _org::text || '|' || r.seq::text || '|' ||
      r.actor || '|' || r.action || '|' || coalesce(r.target,'') || '|' ||
      coalesce(r.ip,'') || '|' || r.meta::text, 'sha256'), 'hex');
    _n := _n + 1;
    if _calc <> r.hash or coalesce(r.prev_hash,'') <> coalesce(_prev,'') then
      _broken := r.seq; exit;
    end if;
    _prev := r.hash;
  end loop;
  return query select (_broken is null), _n, _broken;
end $$;


--
-- Name: org_mail_sync_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.org_mail_sync_state() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'domains',   coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'domain', d.domain, 'selector', d.dkim_selector, 'has_dkim', d.dkim_public is not null))
                           from public.org_domains d where d.status = 'verified'), '[]'::jsonb),
    'pending_dkim', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'domain', d.domain, 'selector', d.dkim_selector))
                           from public.org_domains d where d.status <> 'removed' and d.dkim_public is null), '[]'::jsonb),
    'addresses', coalesce((select jsonb_agg(jsonb_build_object('address', a.address, 'kind', a.kind, 'alias_target', a.alias_target))
                           from public.org_addresses a join public.org_domains d on d.id = a.domain_id
                          where a.active and d.status = 'verified'), '[]'::jsonb));
$$;


