    AS $$
  select coalesce(
    (select e.plan from public.org_members m
       join public.entitlement_state e on e.user_id = m.user_id
      where m.org_id = _org and m.role = 'owner' limit 1),
    'basic');
$$;


--
-- Name: passkey_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.passkey_status(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  p      public.passkey_policy;
  n      int;
  codes  int;
  made   timestamptz;
  grace  timestamptz;
  hard   boolean;
begin
  select * into p from public.passkey_policy where id = 1;
  select count(*) into n from public.webauthn_credentials where user_id = _user;
  select count(*) into codes from public.account_recovery_codes where user_id = _user and used_at is null;
  select u.created_at into made from auth.users u where u.id = _user;
  grace := p.enforced_at + make_interval(days => p.grace_days);
  -- naya account (policy ke baad bana) ya grace khatam => hard
  hard := n = 0 and (made > p.enforced_at or now() > grace);
  return jsonb_build_object(
    'count', n, 'target', p.target, 'codes_remaining', codes,
    'required', n = 0, 'hard', hard,
    'grace_until', case when made > p.enforced_at then null else grace end);
end $$;


--
-- Name: password_reset_rate_ok(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.password_reset_rate_ok(_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_count int;
begin
  if _user_id is null then
    return jsonb_build_object('ok', true, 'count', 0);
  end if;
  select count(*) into v_count
    from public.account_recovery_tokens
   where user_id = _user_id
     and created_at > now() - interval '1 hour';
  if v_count >= 5 then
    return jsonb_build_object('ok', false, 'error', 'too_many_requests', 'count', v_count);
  end if;
  return jsonb_build_object('ok', true, 'count', v_count);
end $$;


--
-- Name: pending_plan_stale(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pending_plan_stale(_hours integer DEFAULT 72) RETURNS TABLE(user_id uuid, anexomail_address text, hours_pending numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select t.user_id, t.anexomail_address,
         round(extract(epoch from (now() - t.updated_at)) / 3600.0, 1) as hours_pending
  from public.trial_accounts t
  where t.status = 'pending_plan'
    and t.updated_at <= now() - (_hours || ' hours')::interval
  order by t.updated_at asc;
$$;


--
-- Name: FUNCTION pending_plan_stale(_hours integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.pending_plan_stale(_hours integer) IS 'E20: read-only — abandoned-checkout accounts stuck in pending_plan >_hours. Surfaces for a human win-back decision, never auto-acts.';


--
-- Name: personal_entitlement_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_entitlement_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  plan_id text;
begin
  if new.product_key is null
     or new.product_key not ilike 'POLAR_PRODUCT_PLAN_PERSONAL_%'
     or new.user_id is null then
    return new;
  end if;

  plan_id := case
    when new.product_key ilike '%PERSONAL_PREMIUM%' then 'business_pro'
    when new.product_key ilike '%PERSONAL_PRO%'     then 'pro'
    when new.product_key ilike '%PERSONAL_BASIC%'   then 'basic'
    else null
  end;

  if plan_id is null then
    return new;
  end if;

  if new.status in ('active','past_due','grace') then
    insert into public.entitlement_state (user_id, plan, seats, active_until, revision, updated_at)
    values (new.user_id, plan_id, 1, new.current_period_end, 1, now())
    on conflict (user_id) do update set
      plan         = plan_id,
      seats        = greatest(1, entitlement_state.seats),
      active_until = coalesce(new.current_period_end, entitlement_state.active_until),
      revision     = entitlement_state.revision + 1,
      updated_at   = now();
  end if;

  return new;
end;
$$;


--
-- Name: personal_name_for_polar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_name_for_polar(_plan text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select m.personal_name
  from public.personal_polar_map m
  where m.polar_sku = replace(lower(coalesce(nullif(btrim(_plan), ''), '')), '-', '_')
  limit 1;
$$;


--
-- Name: personal_workspace_label(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personal_workspace_label(_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  kind text;
  billed text;
  email text;
begin
  if _user_id is null then return null; end if;

  select lower(nullif(btrim(p.preferences->>'workspace_kind'), ''))
    into kind
  from public.account_profiles p
  where p.user_id = _user_id;

  select u.email into email from auth.users u where u.id = _user_id;

  if to_regclass('public.family_accounts') is not null and email is not null then
    execute $q$
      select plan from public.family_accounts
      where lower(email) = lower($1)
      limit 1
    $q$ into billed using email;
  end if;

  if (billed is null or btrim(billed) = '')
     and to_regclass('public.trial_accounts') is not null then
    execute 'select plan from public.trial_accounts where user_id = $1 limit 1'
      into billed using _user_id;
  end if;

  if (billed is null or btrim(billed) = '')
     and to_regclass('public.entitlement_state') is not null then
    execute $q$
      select plan from public.entitlement_state
      where user_id = $1
      order by updated_at desc nulls last
      limit 1
    $q$ into billed using _user_id;
  end if;

  -- E20: koi bhi real source se plan nahi mila to NULL — kabhi 'basic' mat
  -- fabricate karo. Frontend (plan-surface.ts surfaceFromSession) null ko
  -- "Choose your plan" dikhata hai.
  billed := replace(lower(coalesce(nullif(btrim(billed), ''), '')), '-', '_');
  if billed = '' then
    return null;
  end if;
  if billed = 'businesspro' then billed := 'business_pro'; end if;

  if kind is null then
    if billed in ('basic', 'pro') then
      kind := 'personal';
    else
      return null;
    end if;
  end if;

  if kind <> 'personal' then
    return null;
  end if;

  return public.personal_name_for_polar(billed);
end;
$_$;


--
-- Name: FUNCTION personal_workspace_label(_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.personal_workspace_label(_user_id uuid) IS 'E20: returns NULL (never fakes ''basic'') when no real plan exists anywhere for this user — frontend shows "Choose your plan".';


--
-- Name: polar_billing_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.polar_billing_state(_user uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select coalesce(
    (select jsonb_build_object(
       'plan',               s.product_key,
       'status',             s.status,
       'seats',              s.seats,
       'current_period_end', s.current_period_end,
       'grace_until',        s.grace_until,
       'grace_days_left',    greatest(0, ceil(extract(epoch from (s.grace_until - now())) / 86400))::int,
       'payment_due',        s.status in ('past_due','grace'),
       'service_blocked',    false
     )
     from public.polar_subscriptions s
     where s.user_id = _user
     order by (s.status in ('active','past_due','grace')) desc, s.updated_at desc
     limit 1),
    jsonb_build_object('plan', null, 'status', 'none', 'payment_due', false, 'service_blocked', false)
  )
$$;


--
-- Name: polar_inbox_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.polar_inbox_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  d           jsonb := coalesce(new.payload -> 'data', '{}'::jsonb);
  meta        jsonb := coalesce(d -> 'metadata', '{}'::jsonb);
  sub_id      text  := d ->> 'id';
  cust_id     text  := coalesce(d ->> 'customer_id', d #>> '{customer,id}');
  mail        text  := lower(coalesce(d #>> '{customer,email}', d ->> 'customer_email', meta ->> 'email'));
  ext_user    text  := coalesce(d ->> 'external_customer_id', d #>> '{customer,external_id}', meta ->> 'user_id');
  uid         uuid;
  pkey        text  := meta ->> 'product_key';
  pid         text  := coalesce(d ->> 'product_id', d #>> '{product,id}');
  period_end  timestamptz := nullif(d ->> 'current_period_end','')::timestamptz;
  new_status  text;
begin
  begin
    if ext_user ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      uid := ext_user::uuid;
    end if;
    if uid is null and mail is not null then
      select id into uid from auth.users where lower(email) = mail limit 1;
    end if;

    new_status := case
      when new.event_type in ('subscription.active','subscription.created','subscription.uncanceled','order.paid') then 'active'
      when new.event_type = 'subscription.past_due' then 'past_due'
      when new.event_type = 'subscription.canceled' then 'canceled'
      when new.event_type = 'subscription.revoked' then 'revoked'
      else null
    end;

    if new_status is not null and (sub_id is not null or mail is not null) then
      insert into public.polar_subscriptions as s
        (polar_subscription_id, polar_customer_id, user_id, email, product_key, product_id,
         status, current_period_end, grace_until, last_event_id)
      values
        (sub_id, cust_id, uid, mail, pkey, pid, new_status, period_end,
         case when new_status = 'past_due' then now() + interval '3 days' else null end,
         new.event_id)
      on conflict (polar_subscription_id) do update
        set polar_customer_id  = coalesce(excluded.polar_customer_id, s.polar_customer_id),
            user_id            = coalesce(excluded.user_id, s.user_id),
            email              = coalesce(excluded.email, s.email),
            product_key        = coalesce(excluded.product_key, s.product_key),
            product_id         = coalesce(excluded.product_id, s.product_id),
            status             = excluded.status,
            current_period_end = coalesce(excluded.current_period_end, s.current_period_end),
            grace_until        = case
                                   when excluded.status = 'past_due'
                                     then coalesce(s.grace_until, now() + interval '3 days')
                                   else null
                                 end,
            last_event_id      = excluded.last_event_id,
            updated_at         = now();
    end if;

    -- receipt (regular email par) + welcome (pehli active subscription par)
    if new.event_type = 'order.paid' and mail is not null then
      insert into public.polar_mail_outbox (kind, to_email, user_id, subject, data)
      values ('receipt', mail, uid, 'Your ANEXOMAIL payment receipt',
              jsonb_build_object('product_key', pkey, 'event_id', new.event_id,
                                 'amount', d ->> 'total_amount', 'currency', d ->> 'currency'))
      on conflict do nothing;
    end if;

    if new.event_type in ('subscription.active','subscription.created') and mail is not null then
      insert into public.polar_mail_outbox (kind, to_email, user_id, subject, data)
      values ('welcome', mail, uid, 'Welcome to ANEXOMAIL Workspace',
              jsonb_build_object('product_key', pkey, 'event_id', new.event_id))
      on conflict do nothing;
    end if;

    if new_status = 'past_due' and mail is not null then
      insert into public.polar_mail_outbox (kind, to_email, user_id, subject, data)
      values ('grace_warning', mail, uid, 'Action needed: payment due (3 day grace)',
              jsonb_build_object('product_key', pkey, 'event_id', new.event_id))
      on conflict do nothing;
    end if;

    update public.polar_webhook_inbox
       set processed = true, processed_at = now(), process_error = null
     where id = new.id;
  exception when others then
    -- FAIL-SAFE: event kabhi kho nahi sakta; error row par likha jata hai,
    -- reconcile isay dobara process kar sakta hai. Polar ko farq nahi padta.
    update public.polar_webhook_inbox
       set processed = false, process_error = sqlerrm
     where id = new.id;
  end;
  return null;
end $_$;


--
-- Name: polar_payment_pulse(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.polar_payment_pulse() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
  select jsonb_build_object(
    'inbox_total',        (select count(*) from public.polar_webhook_inbox),
    'inbox_pending',      (select count(*) from public.polar_webhook_inbox where not processed),
    'inbox_failed',       (select count(*) from public.polar_webhook_inbox where process_error is not null),
    'last_event_at',      (select max(received_at) from public.polar_webhook_inbox),
    'active_subs',        (select count(*) from public.polar_subscriptions where status = 'active'),
    'past_due_subs',      (select count(*) from public.polar_subscriptions where status in ('past_due','grace')),
    'rejects_24h',        (select count(*) from public.polar_signature_rejects where created_at > now() - interval '24 hours'),
    'reconcile_last_at',  (select max(created_at) from public.polar_reconcile_log),
    'reconcile_gap_24h',  (select count(*) from public.polar_reconcile_log
                            where verdict in ('missing','diverged') and created_at > now() - interval '24 hours'),
    'alerts_open',        (select count(*) from public.polar_payment_alerts where sent_at is null),
    'mail_outbox_pending',(select count(*) from public.polar_mail_outbox where sent_at is null)
  )
$$;


--
-- Name: promise_board(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promise_board(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_ws uuid;
begin
  select workspace_id into v_ws from public.chat_members where user_id = _user limit 1;
  if v_ws is null then
    return jsonb_build_object('plan', public.chat_feature_allowed(_user,'promise_recovery'),
                              'reassign', public.chat_feature_allowed(_user,'promise_reassign'),
                              'items', '[]'::jsonb, 'summary', '{}'::jsonb);
  end if;

  return jsonb_build_object(
    'plan',     public.chat_feature_allowed(_user, 'promise_recovery'),
    'reassign', public.chat_feature_allowed(_user, 'promise_reassign'),
    'summary', (
      select jsonb_build_object(
        'open',      count(*) filter (where w.state in ('open','blocked')),
        'overdue',   count(*) filter (where w.state in ('open','blocked')
                                        and w.due_at is not null and w.due_at < now()),
        'due_soon',  count(*) filter (where w.state in ('open','blocked') and w.due_at is not null
                                        and w.due_at >= now() and w.due_at < now() + interval '24 hours'),
        'kept',      count(*) filter (where w.state = 'done'),
        'kept_late', count(*) filter (where w.state = 'done' and w.original_due_at is not null
                                        and w.completed_at > w.original_due_at),
        'cancelled', count(*) filter (where w.state = 'cancelled'),
        'slipped',   count(*) filter (where w.deadline_changes > 0))
        from public.chat_work_items w
       where w.workspace_id = v_ws and w.kind = 'promise'),
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
          'id', w.id, 'title', w.title, 'state', w.state,
          'promise_state', public.promise_state_of(w.state, w.due_at, w.completed_at, w.original_due_at),
          'owner_user_id', w.owner_user_id, 'original_owner_id', w.original_owner_id,
          'due_at', w.due_at, 'original_due_at', w.original_due_at,
          'slipped_by_hours', case
              when w.due_at is not null and w.original_due_at is not null
              then round(extract(epoch from (w.due_at - w.original_due_at)) / 3600.0)::int
              else 0 end,
          'deadline_changes', w.deadline_changes,
          'reminders_sent', w.reminders_sent,
          'reassignments', w.reassignments,
          'downstream_impact', w.downstream_impact,
          'conversation_id', w.conversation_id, 'message_id', w.message_id,
          'created_at', w.created_at, 'completed_at', w.completed_at,
          'evidence_count', (select count(*) from public.chat_work_evidence e
                              where e.item_id = w.id and e.kind <> 'message'),
          'last_action', (select l.action from public.promise_recovery_log l
                           where l.item_id = w.id order by l.id desc limit 1))
        order by (w.state not in ('open','blocked')),
                 (w.due_at is null), w.due_at)
        from public.chat_work_items w
       where w.workspace_id = v_ws and w.kind = 'promise'
         and (w.state in ('open','blocked') or w.closed_at > now() - interval '30 days')),
      '[]'::jsonb));
end $$;


--
-- Name: promise_history(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promise_history(_item uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.chat_work_items;
begin
  select * into v_row from public.chat_work_items where id = _item;
  if not found then raise exception 'item_not_found'; end if;
  if not public.chat_in_conversation(v_row.conversation_id, _user) then raise exception 'not_participant'; end if;

  return jsonb_build_object(
    'item', jsonb_build_object(
      'id', v_row.id, 'title', v_row.title, 'state', v_row.state,
      'promise_state', public.promise_state_of(v_row.state, v_row.due_at,
                                               v_row.completed_at, v_row.original_due_at),
      'owner_user_id', v_row.owner_user_id, 'original_owner_id', v_row.original_owner_id,
      'due_at', v_row.due_at, 'original_due_at', v_row.original_due_at,
      'deadline_changes', v_row.deadline_changes, 'reminders_sent', v_row.reminders_sent,
      'reassignments', v_row.reassignments, 'downstream_impact', v_row.downstream_impact,
      'cancel_reason', v_row.cancel_reason, 'completed_at', v_row.completed_at),
    'provenance', v_row.provenance,
    'log', coalesce((select jsonb_agg(jsonb_build_object(
        'action', l.action, 'reason', l.reason, 'prev', l.prev, 'next', l.next,
        'actor_id', l.actor_id, 'at', l.at) order by l.id)
      from public.promise_recovery_log l where l.item_id = _item), '[]'::jsonb),
    'evidence', coalesce((select jsonb_agg(jsonb_build_object(
        'kind', e.kind, 'ref', e.ref, 'sha256', e.sha256, 'at', e.at) order by e.id)
      from public.chat_work_evidence e where e.item_id = _item), '[]'::jsonb),
    'append_only', true);
end $$;


--
-- Name: promise_keep(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promise_keep(_item uuid, _user uuid, _evidence jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_res jsonb; v_row public.chat_work_items;
begin
  select * into v_row from public.chat_work_items where id = _item;
  if not found then raise exception 'item_not_found'; end if;
  if v_row.kind <> 'promise' then return jsonb_build_object('ok', false, 'error', 'not_a_promise'); end if;

  v_res := public.chat_work_complete(_item, _user, _evidence);
  if coalesce((v_res->>'ok')::boolean, false) then
    insert into public.promise_recovery_log (item_id, actor_id, action, prev, next)
    values (_item, _user, 'kept',
            jsonb_build_object('state', v_row.state, 'original_due_at', v_row.original_due_at),
            jsonb_build_object('state', 'done', 'kept_at', now(),
              'late', v_row.original_due_at is not null and now() > v_row.original_due_at));
  end if;
  return v_res;
end $$;


--
-- Name: promise_recover(uuid, uuid, text, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promise_recover(_item uuid, _user uuid, _action text, _reason text DEFAULT NULL::text, _new_due timestamp with time zone DEFAULT NULL::timestamp with time zone, _new_owner uuid DEFAULT NULL::uuid, _impact text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_row public.chat_work_items;
  v_reason text := btrim(coalesce(_reason, ''));
  v_msg  record;
  v_body text;
  v_owner_name text;
begin
  select * into v_row from public.chat_work_items where id = _item;
  if not found then raise exception 'item_not_found'; end if;
  if v_row.kind <> 'promise' then return jsonb_build_object('ok', false, 'error', 'not_a_promise'); end if;
  if not public.chat_in_conversation(v_row.conversation_id, _user) then raise exception 'not_participant'; end if;

  if not coalesce((public.chat_feature_allowed(_user,'promise_recovery')->>'allowed')::boolean, false) then
    return jsonb_build_object('ok', false, 'error', 'not_entitled',
      'plan', public.chat_feature_allowed(_user,'promise_recovery')->>'plan');
  end if;

  if _action in ('deadline_change','reassign','cancelled') and length(v_reason) < 8 then
    return jsonb_build_object('ok', false, 'error', 'reason_required',
      'message', 'This action changes the record. Write at least 8 characters of reason.');
  end if;

  if _action = 'remind' then
    if v_row.state not in ('open','blocked') then
      return jsonb_build_object('ok', false, 'error', 'promise_closed');
    end if;
    select coalesce(p.display_name, 'the owner') into v_owner_name
      from public.chat_members p
     where p.user_id = coalesce(v_row.owner_user_id, v_row.created_by) limit 1;

    v_body := 'Promise reminder for ' || coalesce(v_owner_name, 'the owner')
              || ' — "' || v_row.title || '"'
              || case when v_row.due_at is not null
                      then ' · due ' || to_char(v_row.due_at, 'DD Mon YYYY HH24:MI') else '' end
              || case when v_reason <> '' then ' · ' || v_reason else '' end;

    select * into v_msg from public.chat_send(
      v_row.conversation_id, _user,
      'promise-remind-' || _item::text || '-' || extract(epoch from now())::bigint::text,
      v_body, 'promise-engine', v_row.message_id);

    update public.chat_work_items
       set reminders_sent = reminders_sent + 1 where id = _item;

    insert into public.promise_recovery_log (item_id, actor_id, action, reason, next)
    values (_item, _user, 'remind', nullif(v_reason,''),
            jsonb_build_object('message_id', v_msg.id, 'body', v_body));

    insert into public.chat_work_events (item_id, actor_id, action, detail)
    values (_item, _user, 'promise_reminded', jsonb_build_object('message_id', v_msg.id));

    return jsonb_build_object('ok', true, 'action', 'remind', 'message_id', v_msg.id, 'body', v_body);

  elsif _action = 'deadline_change' then
    if _new_due is null then return jsonb_build_object('ok', false, 'error', 'new_due_required'); end if;
    if v_row.state not in ('open','blocked') then
      return jsonb_build_object('ok', false, 'error', 'promise_closed');
    end if;

    update public.chat_work_items
       set due_at = _new_due,
           original_due_at = coalesce(original_due_at, v_row.due_at),
           deadline_changes = deadline_changes + 1
     where id = _item;

    insert into public.promise_recovery_log (item_id, actor_id, action, reason, prev, next)
    values (_item, _user, 'deadline_change', v_reason,
            jsonb_build_object('due_at', v_row.due_at),
            jsonb_build_object('due_at', _new_due));

    insert into public.chat_work_events (item_id, actor_id, action, detail)
    values (_item, _user, 'deadline_changed',
            jsonb_build_object('from', v_row.due_at, 'to', _new_due, 'reason', v_reason));

    return jsonb_build_object('ok', true, 'action', 'deadline_change',
      'from', v_row.due_at, 'to', _new_due,
      'original_due_at', coalesce(v_row.original_due_at, v_row.due_at));

  elsif _action = 'reassign' then
    if _new_owner is null then return jsonb_build_object('ok', false, 'error', 'new_owner_required'); end if;
    if not coalesce((public.chat_feature_allowed(_user,'promise_reassign')->>'allowed')::boolean, false) then
      return jsonb_build_object('ok', false, 'error', 'not_entitled_reassign',
        'plan', public.chat_feature_allowed(_user,'promise_reassign')->>'plan');
    end if;
    if not public.chat_in_conversation(v_row.conversation_id, _new_owner) then
      return jsonb_build_object('ok', false, 'error', 'new_owner_not_participant');
    end if;

    update public.chat_work_items
       set owner_user_id = _new_owner,
           original_owner_id = coalesce(original_owner_id, v_row.owner_user_id),
           reassignments = reassignments + 1
     where id = _item;

    insert into public.promise_recovery_log (item_id, actor_id, action, reason, prev, next)
    values (_item, _user, 'reassign', v_reason,
            jsonb_build_object('owner_user_id', v_row.owner_user_id),
            jsonb_build_object('owner_user_id', _new_owner));

    insert into public.chat_work_events (item_id, actor_id, action, detail)
    values (_item, _user, 'promise_reassigned',
            jsonb_build_object('from', v_row.owner_user_id, 'to', _new_owner, 'reason', v_reason));

    return jsonb_build_object('ok', true, 'action', 'reassign', 'owner_user_id', _new_owner);

  elsif _action = 'impact_set' then
    if btrim(coalesce(_impact,'')) = '' then
      return jsonb_build_object('ok', false, 'error', 'impact_required');
    end if;

    update public.chat_work_items set downstream_impact = btrim(_impact) where id = _item;

    insert into public.promise_recovery_log (item_id, actor_id, action, reason, prev, next)
    values (_item, _user, 'impact_set', nullif(v_reason,''),
            jsonb_build_object('downstream_impact', v_row.downstream_impact),
            jsonb_build_object('downstream_impact', btrim(_impact)));

    return jsonb_build_object('ok', true, 'action', 'impact_set', 'downstream_impact', btrim(_impact));

  elsif _action = 'cancelled' then
    if v_row.state = 'done' then return jsonb_build_object('ok', false, 'error', 'already_kept'); end if;

    update public.chat_work_items
       set state = 'cancelled', cancel_reason = v_reason, closed_at = now()
     where id = _item;

    update public.chat_work_items set state = 'open'
     where depends_on = _item and state = 'blocked';

    insert into public.promise_recovery_log (item_id, actor_id, action, reason, prev, next)
    values (_item, _user, 'cancelled', v_reason,
            jsonb_build_object('state', v_row.state),
            jsonb_build_object('state', 'cancelled'));

    insert into public.chat_work_events (item_id, actor_id, from_state, to_state, action, detail)
    values (_item, _user, v_row.state, 'cancelled', 'promise_cancelled',
            jsonb_build_object('reason', v_reason));

    return jsonb_build_object('ok', true, 'action', 'cancelled', 'state', 'cancelled');
  end if;

  return jsonb_build_object('ok', false, 'error', 'unknown_action');
end $$;


--
-- Name: promise_state_of(text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promise_state_of(_state text, _due timestamp with time zone, _completed timestamp with time zone, _original_due timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when _state = 'cancelled' then 'cancelled'
    when _state = 'done' and _completed is not null and _original_due is not null
         and _completed > _original_due then 'kept_late'
    when _state = 'done' then 'kept'
    when _due is not null and _due < now() then 'overdue'
    when _due is not null and _due < now() + interval '24 hours' then 'due_soon'
    else 'pending'
  end
$$;


--
-- Name: queue_inbound_support_reply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_inbound_support_reply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  j jsonb := to_jsonb(new);
  tj jsonb := '{}'::jsonb;
  v_thread_id uuid;
  v_message_id uuid;
  v_customer_email text;
  v_subject text;
  v_received_at timestamptz;
  v_recipient_text text;
  v_queue_id uuid;
begin
  if coalesce(j->>'direction', 'in') not in ('in','inbound') then return new; end if;

  begin v_thread_id := nullif(j->>'thread_id','')::uuid; exception when others then v_thread_id := null; end;
  begin v_message_id := nullif(j->>'id','')::uuid; exception when others then v_message_id := null; end;
  if v_thread_id is not null then
    select to_jsonb(t) into tj from public.mail_threads t where t.id = v_thread_id;
    tj := coalesce(tj, '{}'::jsonb);
  end if;

  v_recipient_text := lower(concat_ws(' ',
    j->>'to', j->>'to_address', j->>'to_addresses', j->>'recipient', j->>'recipient_address',
    tj->>'account_address', tj->>'to_address', tj->>'recipient_address'
  ));
  if position('hello@anexomail.com' in v_recipient_text) = 0 then return new; end if;

  v_customer_email := coalesce(nullif(j->>'from_address',''), nullif(j->>'sender',''), nullif(tj->>'from_address',''));
  if v_customer_email is null then return new; end if;
  v_subject := coalesce(nullif(j->>'subject',''), nullif(tj->>'subject',''), 'Support conversation');
  begin
    v_received_at := coalesce(nullif(j->>'sent_at','')::timestamptz, nullif(j->>'received_at','')::timestamptz, now());
  exception when others then
    v_received_at := now();
  end;

  if v_message_id is not null and exists (select 1 from public.founder_reply_queue where message_id = v_message_id) then
    return new;
  end if;

  v_queue_id := public.enqueue_founder_reply(null, v_customer_email, v_subject, v_thread_id, v_received_at);
  if v_message_id is not null then
    update public.founder_reply_queue set message_id = v_message_id where id = v_queue_id;
  end if;
  return new;
exception when others then
  raise warning 'queue_inbound_support_reply skipped: %', sqlerrm;
  return new;
end;
$$;


--
-- Name: read_without_response(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_without_response(_user uuid, _hours integer DEFAULT 24) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_rows jsonb; v_h int := greatest(coalesce(_hours, 24), 1);
begin
  if not public.chat_feature_ok(_user, 'receipt_pack') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;

  select coalesce(jsonb_agg(x order by x->>'read_at' desc), '[]'::jsonb) into v_rows from (
    select jsonb_build_object(
             'message_id', m.id, 'conversation_id', m.conversation_id,
             'title', coalesce(c.subject, 'Direct conversation'),
             'reader', u.email, 'reader_id', rr.user_id,
             'read_at', rr.at,
             'hours_since', round(extract(epoch from (now() - rr.at)) / 3600.0, 1),
             'evidence', 'chat_message_receipts · chat_messages (absent reply)') as x
      from public.chat_messages m
      join public.chat_conversations c on c.id = m.conversation_id
      join public.chat_message_receipts rr on rr.message_id = m.id and rr.state = 'read'
      join auth.users u on u.id = rr.user_id
     where m.sender_user_id = _user
       and rr.at < now() - make_interval(hours => v_h)
       and not exists (select 1 from public.chat_messages nm
                        where nm.conversation_id = m.conversation_id
                          and nm.sender_user_id = rr.user_id
                          and nm.created_at > rr.at)
     order by rr.at desc
     limit 200) t;

  return jsonb_build_object('hours', v_h, 'items', v_rows,
    'note', 'Measured silence, not intent. This is evidence for follow-up.');
end $$;


--
-- Name: receipt_certificate_issue(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receipt_certificate_issue(_conversation uuid, _user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_chain jsonb; v_ws uuid; v_from bigint; v_to bigint;
        v_msgs int; v_del int; v_read int; v_id uuid; v_hash text; v_token text; v_head text;
begin
  if not public.chat_in_conversation(_conversation, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'receipt_certificate') then
    return jsonb_build_object('ok', false, 'error', 'plan_not_allowed');
  end if;

  v_chain := public.conversation_chain_verify(_conversation, _user);
  if v_chain ? 'error' then return jsonb_build_object('ok', false, 'error', v_chain->>'error'); end if;
  if coalesce((v_chain->>'chain_intact')::boolean, false) is not true then
    return jsonb_build_object('ok', false, 'error', 'chain_not_intact', 'chain', v_chain);
  end if;
  v_head := v_chain->>'head_hash';
  if v_head is null then return jsonb_build_object('ok', false, 'error', 'nothing_sealed_yet'); end if;

  select workspace_id into v_ws from public.chat_conversations where id = _conversation;
  select min(seq), max(seq), count(*) into v_from, v_to, v_msgs
    from public.chat_messages where conversation_id = _conversation;
  select count(*) into v_del from public.chat_message_receipts rr
    join public.chat_messages m on m.id = rr.message_id
   where m.conversation_id = _conversation and rr.state = 'delivered';
  select count(*) into v_read from public.chat_message_receipts rr
    join public.chat_messages m on m.id = rr.message_id
   where m.conversation_id = _conversation and rr.state = 'read';

  v_hash := encode(digest(v_head || ':' || v_msgs::text || ':' || v_del::text || ':' ||
                          v_read::text || ':' || now()::text, 'sha256'), 'hex');

  insert into public.chat_receipt_certificates (
    conversation_id, workspace_id, issued_by, from_seq, to_seq,
    message_count, delivered_count, read_count, head_hash, certificate_hash)
  values (_conversation, v_ws, _user, coalesce(v_from, 0), coalesce(v_to, 0),
          v_msgs, v_del, v_read, v_head, v_hash)
  returning id, verify_token into v_id, v_token;

  return jsonb_build_object('ok', true, 'certificate_id', v_id, 'verify_token', v_token,
    'certificate_hash', v_hash, 'head_hash', v_head,
    'messages', v_msgs, 'delivered', v_del, 'read', v_read,
    'contains_message_bodies', false,
    'note', 'Anyone holding this token can verify the counts and hash without signing in.');
end $$;


--
-- Name: receipt_certificate_verify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receipt_certificate_verify(_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare c record; v_now jsonb; v_intact boolean; v_head text;
begin
  select * into c from public.chat_receipt_certificates
   where verify_token = [REDACTED] ''), '-', '');
  if not found then return jsonb_build_object('valid', false, 'error', 'certificate_not_found'); end if;

  -- chain aaj bhi wahi hai? (body dekhe bina, sirf seal)
  select coalesce(p.chain_hash = c.head_hash, false) into v_intact
    from public.chat_message_provenance p
   where p.conversation_id = c.conversation_id
   order by p.seq desc limit 1;

  return jsonb_build_object(
    'valid', true,
    'issued_at', c.issued_at,
    'messages', c.message_count,
    'delivered', c.delivered_count,
    'read', c.read_count,
    'from_seq', c.from_seq, 'to_seq', c.to_seq,
    'certificate_hash', c.certificate_hash,
    'head_hash', c.head_hash,
    'still_matches_live_chain', coalesce(v_intact, false),
    'contains_message_bodies', false,
    'note', case when coalesce(v_intact, false)
                 then 'The sealed chain head still matches this certificate.'
                 else 'Newer messages exist or the chain head changed since issue.' end);
end $$;


--
-- Name: receipt_device_record(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receipt_device_record(_user uuid, _message uuid, _state text, _platform_class text DEFAULT NULL::text, _tz_bucket text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_conv uuid;
begin
  if _state not in ('delivered','read') then
    return jsonb_build_object('ok', false, 'error', 'state_must_be_delivered_or_read');
  end if;
  select conversation_id into v_conv from public.chat_messages where id = _message;
  if v_conv is null then return jsonb_build_object('ok', false, 'error', 'message_not_found'); end if;
  if not public.chat_in_conversation(v_conv, _user) then
    return jsonb_build_object('ok', false, 'error', 'not_in_conversation');
  end if;

  insert into public.chat_message_receipts (message_id, user_id, state)
  values (_message, _user, _state)
  on conflict (message_id, user_id, state) do nothing;

  insert into public.chat_receipt_devices (message_id, user_id, state, platform_class, tz_bucket)
  values (_message, _user, _state,
          coalesce(nullif(lower(_platform_class), ''), 'unknown'),
          coalesce(nullif(_tz_bucket, ''), 'unknown'))
  on conflict (message_id, user_id, state) do nothing;

  return jsonb_build_object('ok', true, 'message_id', _message, 'state', _state,
    'signals_stored', jsonb_build_array('platform_class', 'timezone_bucket'),
    'fingerprinting', false);
end $$;


--
-- Name: receipt_replay(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.receipt_replay(_conversation uuid, _user uuid, _limit integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_limit int; v_frames jsonb;
begin
  if not public.chat_in_conversation(_conversation, _user) then
    return jsonb_build_object('error', 'not_in_conversation');
  end if;
  if not public.chat_feature_ok(_user, 'receipt_replay') then
    return jsonb_build_object('error', 'plan_not_allowed');
  end if;
  v_limit := least(coalesce(_limit,
    coalesce((public.chat_feature_allowed(_user, 'receipt_replay')->>'limit')::int, 400)), 5000);

  select coalesce(jsonb_agg(f order by f->>'at'), '[]'::jsonb) into v_frames from (
    select jsonb_build_object('at', m.created_at, 'kind', 'sent',
             'message_id', m.id, 'seq', m.seq, 'actor', u.email,
             'evidence', 'chat_messages') as f
      from public.chat_messages m join auth.users u on u.id = m.sender_user_id
     where m.conversation_id = _conversation
    union all
    select jsonb_build_object('at', rr.at, 'kind', rr.state,
             'message_id', rr.message_id, 'seq', m.seq, 'actor', u.email,
             'device', jsonb_build_object('platform_class', d.platform_class, 'timezone_bucket', d.tz_bucket),
             'evidence', 'chat_message_receipts')
      from public.chat_message_receipts rr
      join public.chat_messages m on m.id = rr.message_id
      join auth.users u on u.id = rr.user_id
      left join public.chat_receipt_devices d
             on d.message_id = rr.message_id and d.user_id = rr.user_id and d.state = rr.state
     where m.conversation_id = _conversation
    order by 1
    limit v_limit) t;

  return jsonb_build_object('conversation_id', _conversation, 'frames', v_frames,
    'engine_invents_nothing', true);
end $$;


--
-- Name: recompute_contact_stats(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_contact_stats(_org_id uuid) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  updated_count integer := 0;
begin
  with contact_addrs as (
    select
      c.id as contact_id,
      lower(c.primary_address) as primary_address,
      array(select lower(a) from unnest(coalesce(c.addresses, '{}')) a) as extra_addresses
    from public.contacts c
    where c.org_id = _org_id
  ),
  matched as (
    select ca.contact_id, m.direction, m.sent_at
    from contact_addrs ca
    join public.mail_messages m
      on m.org_id = _org_id
      and (
        lower(m.from_address) = ca.primary_address
        or lower(m.from_address) = any(ca.extra_addresses)
      )
  ),
  agg as (
    select
      contact_id,
      count(*) filter (where direction = 'in')::int as messages_in,
      count(*) filter (where direction = 'out')::int as messages_out,
      min(sent_at) as first_contact_at,
      max(sent_at) as last_contact_at
    from matched
    group by contact_id
  ),
  reply_gaps as (
    select contact_id, avg(gap_minutes) as avg_reply_minutes
    from (
      select
        m1.contact_id,
        extract(epoch from (m2.sent_at - m1.sent_at)) / 60.0 as gap_minutes
      from matched m1
      join lateral (
        select sent_at
        from matched m2b
        where m2b.contact_id = m1.contact_id
          and m2b.direction = 'out'
          and m2b.sent_at > m1.sent_at
        order by m2b.sent_at asc
        limit 1
      ) m2 on true
      where m1.direction = 'in'
    ) gaps
    group by contact_id
  ),
  scored as (
    select
      a.contact_id,
      a.messages_in,
      a.messages_out,
      a.first_contact_at,
      a.last_contact_at,
      rg.avg_reply_minutes,
      case
        when extract(epoch from (now() - a.last_contact_at)) / 86400 <= 14 then 'active'
        when extract(epoch from (now() - a.last_contact_at)) / 86400 <= 45 then 'cooling'
        else 'cold'
      end as relationship,
      greatest(0, least(100,
        round(
          50
          + least(a.messages_in + a.messages_out, 20) * 1.5
          - greatest(0, (extract(epoch from (now() - a.last_contact_at)) / 86400) - 14) * 0.8
        )
      ))::int as health_score
    from agg a
    left join reply_gaps rg on rg.contact_id = a.contact_id
  )
  insert into public.contact_stats (
    contact_id, messages_in, messages_out, first_contact_at, last_contact_at,
    avg_reply_minutes, open_threads, health_score, relationship, computed_at
  )
  select
    s.contact_id, s.messages_in, s.messages_out, s.first_contact_at, s.last_contact_at,
    s.avg_reply_minutes, 0, s.health_score, s.relationship, now()
  from scored s
  on conflict (contact_id) do update set
    messages_in = excluded.messages_in,
    messages_out = excluded.messages_out,
    first_contact_at = excluded.first_contact_at,
    last_contact_at = excluded.last_contact_at,
    avg_reply_minutes = excluded.avg_reply_minutes,
    health_score = excluded.health_score,
    relationship = excluded.relationship,
    computed_at = now();

  get diagnostics updated_count = row_count;
  return updated_count;
end;
$$;


--
-- Name: recovery_code_redeem(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recovery_code_redeem(_email text, _code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  uid    uuid;
  norm   text := upper(regexp_replace(coalesce(_code, ''), '[^A-Za-z0-9]', '', 'g'));
  r      record;
  recent int;
begin
  select u.id into uid from auth.users u where lower(u.email) = lower(btrim(coalesce(_email, ''))) limit 1;
  -- ek jaisa jawab: account hai ya nahi, yeh nahi batate
  if uid is null or length(norm) <> 12 then
    return jsonb_build_object('ok', false, 'error', 'invalid');
  end if;
  select count(*) into recent from public.account_recovery_code_attempts
   where user_id = uid and ok = false and at > now() - interval '15 minutes';
  if recent >= 5 then
    return jsonb_build_object('ok', false, 'error', 'too_many_attempts');
  end if;
  for r in select id, code_hash from public.account_recovery_codes where user_id = uid and used_at is null loop
    if crypt(norm, r.code_hash) = r.code_hash then
      update public.account_recovery_codes set used_at = now() where id = r.id and used_at is null;
      insert into public.account_recovery_code_attempts (user_id, ok) values (uid, true);
      return jsonb_build_object('ok', true, 'user_id', uid,
        'codes_left', (select count(*) from public.account_recovery_codes where user_id = uid and used_at is null));
    end if;
  end loop;
  insert into public.account_recovery_code_attempts (user_id, ok) values (uid, false);
  return jsonb_build_object('ok', false, 'error', 'invalid');
end $$;


--
-- Name: recovery_codes_regenerate(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recovery_codes_regenerate(_user uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  codes text[] := '{}';
  c text;
  b bytea;
  i int;
  j int;
begin
  if _user is null then raise exception 'user_required'; end if;
  delete from public.account_recovery_codes where user_id = _user and used_at is null;
  for i in 1..10 loop
    b := gen_random_bytes(12);
    c := '';
    for j in 0..11 loop
      c := c || substr(alphabet, (get_byte(b, j) % 32) + 1, 1);
      if j in (3, 7) then c := c || '-'; end if;
    end loop;
    codes := codes || c;
    insert into public.account_recovery_codes (user_id, code_hash)
    values (_user, crypt(replace(c, '-', ''), gen_salt('bf', 8)));
  end loop;
  return codes;
end $$;


--
-- Name: resolve_plan(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_plan(_user_id uuid, _email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  anexo text;
  family_plan text;
  family_ai text;
  trial_plan text;
  trial_addr text;
  addr text;
  workspace_plan text;
  ai_plan text;
  result text;
begin
  anexo := case when lower(_email) like '%@anexomail.com' then lower(_email) else null end;

  select f.plan, f.ai_plan into family_plan, family_ai
  from public.family_accounts f
  where f.email = anexo
  limit 1;

  select t.plan, t.anexomail_address into trial_plan, trial_addr
  from public.trial_accounts t
  where t.user_id = _user_id
  limit 1;

  addr := lower(coalesce(trial_addr, anexo, ''));

  if family_plan is null and addr <> '' then
    select f.plan, f.ai_plan into family_plan, family_ai
    from public.family_accounts f
    where f.email = addr
    limit 1;
  end if;

  workspace_plan := lower(coalesce(family_plan, trial_plan, 'basic'));
  workspace_plan := regexp_replace(workspace_plan, '[\s-]+', '_', 'g');
  if workspace_plan not in ('basic', 'pro', 'business', 'business_pro') then
    workspace_plan := 'basic';
  end if;

  ai_plan := lower(coalesce(family_ai, ''));

  result := workspace_plan;
  if ai_plan = 'ai_executive' then
    result := 'business_pro';
  elsif ai_plan in ('ai_business', 'ai_pro', 'ai') then
    if workspace_plan not in ('business', 'business_pro') then
      result := 'business';
    end if;
  end if;

  return result;
end;
$$;


--
-- Name: safety_can_review(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_can_review(_user uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare v boolean := false;
begin
  if to_regclass('public.founder_accounts') is not null then
    execute 'select exists(select 1 from public.founder_accounts where user_id = $1)'
      into v using _user;
    if v then return true; end if;
  end if;
  return coalesce((public.chat_feature_allowed(_user, 'safety_review')->>'allowed')::boolean, false);
end $_$;


--
-- Name: safety_my_standing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_my_standing(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  return jsonb_build_object(
    'reports_filed', (select count(*) from public.safety_reports where reporter_id = _user),
    'open_reports', (select count(*) from public.safety_reports
                      where reporter_id = _user and state <> 'resolved'),
    'enforcement', coalesce((select jsonb_agg(jsonb_build_object(
        'action', action, 'reason', reason, 'until', until, 'at', at) order by at desc)
      from public.safety_enforcement where subject_user = _user), '[]'::jsonb),
    'can_review', public.safety_can_review(_user));
end $$;


--
-- Name: safety_queue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_queue(_actor uuid, _state text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_rows jsonb;
begin
  if not public.safety_can_review(_actor) then
    return jsonb_build_object('ok', false, 'error', 'not_a_reviewer');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'subject_kind', r.subject_kind, 'reason', r.reason,
      'severity', r.severity, 'state', r.state,
      'conversation_id', r.conversation_id,
      'reporter', left(r.reporter_id::text, 8),
      'subject', left(coalesce(r.subject_user_id::text, r.subject_id), 8),
      'note', r.note,
      'evidence_sealed', r.sealed_evidence is not null,
      'evidence_hash', r.evidence_hash,
      'assigned_to', r.assigned_to,
      'created_at', r.created_at, 'updated_at', r.updated_at,
      'outcome', r.outcome
    ) order by r.severity desc, r.created_at), '[]'::jsonb)
    into v_rows
    from public.safety_reports r
   where (_state is null or r.state = _state);
  return jsonb_build_object('ok', true, 'reports', v_rows,
    'counts', (select jsonb_object_agg(state, c) from
                (select state, count(*) c from public.safety_reports group by state) s));
end $$;


--
-- Name: safety_report_advance(uuid, uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_report_advance(_actor uuid, _report uuid, _to text, _note text DEFAULT NULL::text, _action text DEFAULT NULL::text, _until timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.safety_reports; v_order text[] := array['new','under_review','action','resolved'];
        v_from int; v_next int;
begin
  if not public.safety_can_review(_actor) then raise exception 'not_a_reviewer'; end if;
  select * into v_row from public.safety_reports where id = _report;
  if not found then raise exception 'report_not_found'; end if;

  v_from := array_position(v_order, v_row.state);
  v_next := array_position(v_order, _to);
  if v_next is null then raise exception 'bad_state'; end if;
  if v_next <> v_from + 1 then
    raise exception 'step_skip_not_allowed: % -> %', v_row.state, _to;
  end if;

  update public.safety_reports
     set state = _to,
         assigned_to = coalesce(assigned_to, _actor),
         outcome = coalesce(_action, outcome),
         updated_at = now(),
         resolved_at = case when _to = 'resolved' then now() else resolved_at end
   where id = _report;

  insert into public.safety_report_events (report_id, actor_id, from_state, to_state, action, note)
  values (_report, _actor, v_row.state, _to, _action, _note);

  if _to = 'action' then
    insert into public.safety_enforcement (report_id, subject_user, action, reason, until, actor_id)
    values (_report, v_row.subject_user_id, coalesce(_action, 'warned'),
            coalesce(_note, v_row.reason), _until, _actor);

    if coalesce(_action,'') = 'device_banned' then
      insert into public.device_bans (device_hash, reason, banned_by)
      select d.device_hash, 'safety enforcement ' || _report::text, _actor
        from public.device_vault d
       where d.user_id = v_row.subject_user_id
      on conflict (device_hash) do nothing;
      update public.device_vault set state = 'banned' where user_id = v_row.subject_user_id;
    end if;
  end if;

  return jsonb_build_object('ok', true, 'report_id', _report, 'state', _to);
end $$;


--
-- Name: safety_report_create(uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_report_create(_user uuid, _kind text, _subject text, _reason text, _note text DEFAULT NULL::text, _key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_conv uuid; v_subject_user uuid; v_body text; v_ws uuid; v_id uuid;
  v_sev int := 2;
begin
  if _user is null then raise exception 'user_required'; end if;
  if not coalesce((public.chat_feature_allowed(_user,'safety_report')->>'allowed')::boolean,false) then
    return jsonb_build_object('ok', false, 'error', 'not_entitled');
  end if;

  if _kind = 'message' then
    select m.conversation_id, m.sender_user_id, m.body, c.workspace_id
      into v_conv, v_subject_user, v_body, v_ws
      from public.chat_messages m
      join public.chat_conversations c on c.id = m.conversation_id
     where m.id = _subject::uuid;
    if v_conv is null then raise exception 'message_not_found'; end if;
    if not public.chat_in_conversation(v_conv, _user) then raise exception 'not_participant'; end if;
  elsif _kind = 'conversation' then
    v_conv := _subject::uuid;
    if not public.chat_in_conversation(v_conv, _user) then raise exception 'not_participant'; end if;
    select workspace_id into v_ws from public.chat_conversations where id = v_conv;
  elsif _kind = 'person' then
    v_subject_user := _subject::uuid;
  end if;

  if _reason in ('threat','illegal_content','malware') then v_sev := 4;
  elsif _reason in ('harassment','impersonation') then v_sev := 3; end if;

  insert into public.safety_reports (
    workspace_id, reporter_id, subject_kind, subject_id, conversation_id,
    subject_user_id, reason, note, severity,
    sealed_evidence, evidence_hash)
  values (
    v_ws, _user, _kind, _subject, v_conv, v_subject_user, _reason, left(coalesce(_note,''), 1000), v_sev,
    case when v_body is null then null
         else pgp_sym_encrypt(v_body, coalesce(_key, 'no-pepper')) end,
    case when v_body is null then null
         else encode(digest(v_body, 'sha256'), 'hex') end)
  returning id into v_id;

  insert into public.safety_report_events (report_id, actor_id, from_state, to_state, action, note)
  values (v_id, _user, null, 'new', 'reported', _reason);

  return jsonb_build_object('ok', true, 'report_id', v_id, 'state', 'new', 'severity', v_sev,
    'evidence_sealed', v_body is not null,
    'notice', 'Reviewers see metadata only. Opening the sealed evidence is logged.');
end $$;


--
-- Name: safety_report_reveal(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safety_report_reveal(_actor uuid, _report uuid, _justification text, _key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_row public.safety_reports; v_text text;
begin
  if not public.safety_can_review(_actor) then raise exception 'not_a_reviewer'; end if;
  if coalesce(length(trim(_justification)), 0) < 12 then
    raise exception 'justification_required';
  end if;
  select * into v_row from public.safety_reports where id = _report;
  if not found then raise exception 'report_not_found'; end if;
  if v_row.state = 'new' then raise exception 'open_review_first'; end if;
  if v_row.sealed_evidence is null then
    return jsonb_build_object('ok', true, 'evidence', null, 'note', 'nothing sealed for this report');
  end if;

  v_text := pgp_sym_decrypt(v_row.sealed_evidence::bytea, coalesce(_key, 'no-pepper'));

  insert into public.safety_reveal_log (report_id, actor_id, justification)
  values (_report, _actor, _justification);

  return jsonb_build_object('ok', true, 'evidence', v_text,
    'evidence_hash', v_row.evidence_hash, 'logged', true);
end $$;


--
-- Name: sec_dashboard(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sec_dashboard(_user uuid, _current uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v jsonb;
begin
  select jsonb_build_object(
    'sessions', public.sec_sessions(_user, _current),
    'devices_trusted', (select count(*) from public.device_vault d where d.user_id = _user and d.state = 'trusted'),
    'devices_pending', (select count(*) from public.device_vault d where d.user_id = _user and d.state in ('pending', 'suspicious')),
    'devices_total', (select count(*) from public.device_vault d where d.user_id = _user),
    'failed_logins_24h', (select count(*) from public.security_login_events e
                           where e.user_id = _user and e.outcome in ('failed', 'blocked') and e.at > now() - interval '24 hours'),
    'anomalies', coalesce((select jsonb_agg(jsonb_build_object('kind', a.kind, 'severity', a.severity, 'detail', a.detail))
                             from public.security_anomalies a where a.user_id = _user and a.state = 'open'), '[]'::jsonb),
    'last_proof', (select jsonb_build_object('domain', p.domain, 'ran_at', p.ran_at, 'passed', p.passed, 'failed', p.failed)
                     from public.security_proofs p where p.user_id = _user order by p.ran_at desc limit 1),
    'ledger', coalesce((select jsonb_agg(jsonb_build_object('at', l.at, 'action', l.action, 'actor', l.actor,
                                                            'hash', l.hash, 'prev_hash', l.prev_hash) order by l.at desc)
                          from (select * from public.security_ledger where user_id = _user order by at desc limit 12) l), '[]'::jsonb)
  ) into v;
  return v;
end $$;


--
-- Name: sec_kill_switch(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sec_kill_switch(_user uuid, _current uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n int; v_hash text;
begin
  if _current is null then raise exception 'current_session_unknown'; end if;
  delete from auth.sessions where user_id = _user and id <> _current;
  get diagnostics v_n = row_count;
  v_hash := public.sec_ledger_add(_user, 'kill_switch',
              jsonb_build_object('reason', left(coalesce(_reason, 'kill switch'), 300), 'sessions_killed', v_n));
  insert into public.security_kill_switches (user_id, reason, sessions_killed, devices_blocked, hash)
  values (_user, left(coalesce(_reason, 'kill switch'), 300), v_n, 0, v_hash);
  return jsonb_build_object('ok', true, 'sessions_killed', v_n, 'devices_blocked', 0, 'hash', v_hash);
end $$;


--
-- Name: sec_ledger_add(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sec_ledger_add(_user uuid, _action text, _payload jsonb, _actor text DEFAULT 'owner'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_prev text; v_at timestamptz := clock_timestamp(); v_hash text;
begin
  perform pg_advisory_xact_lock(hashtext('sec_ledger:' || _user::text));
  select hash into v_prev from public.security_ledger where user_id = _user order by at desc, id desc limit 1;
  v_hash := encode(digest(concat_ws('|', _user::text, _action, _actor, coalesce(_payload, '{}'::jsonb)::text,
                                     coalesce(v_prev, ''), to_char(v_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')), 'sha256'), 'hex');
  insert into public.security_ledger (user_id, action, actor, payload, prev_hash, hash, at)
  values (_user, _action, _actor, coalesce(_payload, '{}'::jsonb), v_prev, v_hash, v_at);
  return v_hash;
end $$;


--
-- Name: sec_logins(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sec_logins(_user uuid, _limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(x order by x->>'at' desc), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'id', e.id, 'at', e.created_at, 'action', e.action, 'email', e.email, 'provider', e.provider, 'ip', e.ip,
      -- is network (ip) se is user ka pehle bhi login hua tha?
      'seen_before', coalesce(e.ip is not null and count(*) filter (where e.action = 'login') over (
                        partition by e.ip order by e.created_at rows between unbounded preceding and 1 preceding) > 0, false)
    ) as x, e.created_at
    from (
      select a.id, a.created_at, a.payload->>'action' as action, coalesce(a.payload->>'actor_username', '') as email,
             coalesce(a.payload->'traits'->>'provider', a.payload->>'provider', 'email') as provider,
             nullif(to_jsonb(a)->>'ip_address', '') as ip
      from auth.audit_log_entries a
      where a.created_at > now() - interval '90 days'
        and a.payload->>'actor_id' = _user::text
        and a.payload->>'action' in ('login', 'logout', 'token_revoked', 'user_recovery_requested',
                                     'user_reauthenticate', 'user_updated_password', 'user_modified')
    ) e
    order by e.created_at desc
    limit greatest(1, least(coalesce(_limit, 50), 200))
  ) q;
$$;


--
-- Name: sec_session_kill(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sec_session_kill(_user uuid, _session uuid, _current uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_n int; v_hash text;
begin
  if _session is null then raise exception 'session_id_required'; end if;
  if _session = _current then raise exception 'this_session_use_sign_out'; end if;
  delete from auth.sessions where id = _session and user_id = _user;
  get diagnostics v_n = row_count;
  if v_n = 0 then raise exception 'session_not_found'; end if;
  v_hash := public.sec_ledger_add(_user, 'session_killed', jsonb_build_object('session_id', _session));
  return jsonb_build_object('ok', true, 'sessions_killed', v_n, 'hash', v_hash);
end $$;


--
-- Name: sec_sessions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sec_sessions(_user uuid, _current uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(x order by (x->>'current')::boolean desc, x->>'last_seen_at' desc), '[]'::jsonb)
  from (
    select jsonb_build_object(
      'id', s.id,
      'user_agent', j->>'user_agent',
      'ip', nullif(split_part(coalesce(j->>'ip', ''), '/', 1), ''),
      'started_at', s.created_at,
      'last_seen_at', coalesce((j->>'refreshed_at')::timestamptz, (j->>'updated_at')::timestamptz, s.created_at),
      'expires_at', (j->>'not_after')::timestamptz,
      'aal', j->>'aal',
      'idle_days', floor(extract(epoch from (now() - coalesce((j->>'refreshed_at')::timestamptz, (j->>'updated_at')::timestamptz, s.created_at))) / 86400)::int,
      'current', coalesce(s.id = _current, false)
    ) as x
    from auth.sessions s, lateral (select to_jsonb(s) as j) t
    where s.user_id = _user
      and ((j->>'not_after') is null or (j->>'not_after')::timestamptz > now())
  ) q;
$$;


--
-- Name: set_user_pref(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_user_pref(_user_id uuid, _key text, _value jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result jsonb;
begin
  update public.account_profiles
  set preferences = coalesce(preferences, '{}'::jsonb) || jsonb_build_object(_key, _value)
  where user_id = _user_id
  returning preferences into result;
  return result;
end;
$$;


--
-- Name: signup_device_gate(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.signup_device_gate(_signals jsonb, _key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_ua       text := coalesce(_signals->>'ua', '');
  v_platform text;
  v_browser  text;
  v_tz       int;
  v_screen   text;
  v_lang     text;
  v_canon    text;
  v_h1       text;
  v_h2       text;
  v_banned   boolean := false;
begin
  if to_regclass('public.device_vault') is null then
    return jsonb_build_object('ok', true, 'device_hash', null, 'skipped', true);
  end if;
  v_platform := coalesce(nullif(_signals->>'platform_class',''), public.device_signal_class(v_ua,'platform'));
  v_browser  := coalesce(nullif(_signals->>'browser_class',''), public.device_signal_class(v_ua,'browser'));
  v_tz       := coalesce((_signals->>'tz_offset_minutes')::int, 0) / 60;
  v_screen   := coalesce(_signals->>'screen_bucket', 'unknown');
  v_lang     := lower(left(coalesce(_signals->>'language','xx'), 2));
  v_canon    := concat_ws('|', v_platform, v_browser, v_tz::text, v_screen, v_lang);
  v_h1       := public.device_hash_v1(v_canon, _key);
  v_h2       := public.device_hash_v2(v_canon, _key);

  if to_regclass('public.device_bans') is not null then
    select exists (
      select 1 from public.device_bans b
       where b.device_hash in (v_h1, v_h2) and (b.expires_at is null or b.expires_at > now())
    ) into v_banned;
  end if;
  if v_banned then
    return jsonb_build_object('ok', false, 'error', 'device_banned', 'device_hash', v_h2);
  end if;

  return jsonb_build_object('ok', true, 'device_hash', v_h2);
end $$;


--
-- Name: silent_thread_rescue(uuid, uuid, text, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.silent_thread_rescue(_user uuid, _mail_thread uuid, _title text, _owner uuid, _due timestamp with time zone, _mail_message uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare v_open jsonb; v_conv uuid; v_ws uuid; v_item uuid;
begin
  if coalesce(length(trim(coalesce(_title, ''))), 0) < 3 then
    return jsonb_build_object('ok', false, 'error', 'title_required');
  end if;
  if _owner is null or _due is null then
    return jsonb_build_object('ok', false, 'error', 'owner_and_due_required',
      'note', 'Engine never picks an owner or a deadline.');
  end if;

  v_open := public.email_discuss_in_chat(_user, _mail_thread, _mail_message, null, _title);
  if coalesce((v_open->>'ok')::boolean, false) is not true then return v_open; end if;
  v_conv := (v_open->>'conversation_id')::uuid;
  select workspace_id into v_ws from public.chat_conversations where id = v_conv;

  insert into public.chat_participants (conversation_id, user_id)
  values (v_conv, _owner) on conflict do nothing;

  insert into public.chat_work_items (workspace_id, conversation_id, kind, title,
    owner_user_id, due_at, created_by)
  values (v_ws, v_conv, 'task', trim(_title), _owner, _due, _user)
  returning id into v_item;

  update public.chat_email_links set work_item_id = v_item
   where mail_thread_id = _mail_thread and conversation_id = v_conv and removed_at is null
     and work_item_id is null;

  return jsonb_build_object('ok', true, 'conversation_id', v_conv, 'work_item_id', v_item,
    'owner', _owner, 'due_at', _due, 'confirmed_by_human', true,
    'formal_record', 'ANEXOMAIL');
end $$;


--
-- Name: sla_public(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sla_public(_days integer DEFAULT 30) RETURNS TABLE(avg_first_reply_seconds numeric, resolved_count bigint, window_days integer, resolution_rate numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select avg(first_reply_seconds)::numeric,
         count(*)::bigint,
         _days,
         case when count(*) = 0 then null
              else (sum(case when resolved_on_first_reply then 1 else 0 end)::numeric / count(*)) end
  from public.resolution_log
  where created_at > now() - (_days || ' days')::interval
    and first_reply_seconds is not null
$$;


--
-- Name: storage_can_accept(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_can_accept(_workspace uuid, _mailbox text, _bytes bigint, _kind text DEFAULT 'attachment'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _plan text; _p record; _used bigint; _quota bigint; _pool_used bigint;
begin
  _plan := public.storage_plan_of(_workspace);
  select * into _p from public.storage_plans where plan_id = _plan;
  if _p is null then select * into _p from public.storage_plans where plan_id='trial'; end if;

  if _kind <> 'email' and _bytes > _p.max_send_bytes then
    return jsonb_build_object('allowed', false, 'code', 'file_too_large',
      'reason', 'This file is larger than your plan allows for a single transfer.',
      'limit_bytes', _p.max_send_bytes);
  end if;

  select coalesce(used_emails_bytes + used_attachments_bytes + used_files_bytes + reserved_bytes, 0),
         coalesce(quota_override_bytes, _p.per_mailbox_bytes, _p.pooled_bytes)
    into _used, _quota
  from public.mailbox_storage
  where workspace_id = _workspace and mailbox = _mailbox;

  if _used is null then _used := 0; end if;
  if _quota is null then _quota := coalesce(_p.per_mailbox_bytes, _p.pooled_bytes); end if;

  if _p.pooled_bytes is not null then
    select coalesce(sum(used_emails_bytes + used_attachments_bytes + used_files_bytes + reserved_bytes), 0)
      into _pool_used from public.mailbox_storage where workspace_id = _workspace;
    if _pool_used + _bytes > _p.pooled_bytes then
      return jsonb_build_object('allowed', false, 'code', 'pool_full',
        'reason', 'Your workspace storage pool is full. Free up space or add capacity.',
        'used_bytes', _pool_used, 'quota_bytes', _p.pooled_bytes);
    end if;
    return jsonb_build_object('allowed', true, 'code', 'ok',
      'used_bytes', _pool_used, 'quota_bytes', _p.pooled_bytes);
  end if;

  if _used + _bytes > _quota then
    return jsonb_build_object('allowed', false, 'code', 'mailbox_full',
      'reason', format('Mailbox %s is full (%s of %s used). Existing email stays readable; new items are held until space is freed.',
                       _mailbox, pg_size_pretty(_used), pg_size_pretty(_quota)),
      'used_bytes', _used, 'quota_bytes', _quota,
      'remaining_bytes', greatest(_quota - _used, 0));
  end if;

  return jsonb_build_object('allowed', true, 'code', 'ok',
    'used_bytes', _used, 'quota_bytes', _quota,
    'remaining_bytes', greatest(_quota - _used - _bytes, 0));
end $$;


--
-- Name: storage_capacity_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_capacity_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _drained int := 0;
begin
  update public.storage_volumes
     set accepts_new = false
   where accepts_new
     and used_bytes::numeric >= capacity_bytes * 0.85;
  _drained := coalesce((select count(*) from public.storage_volumes where not accepts_new), 0);
  return jsonb_build_object(
    'drained_volumes', _drained,
    'writable', (select count(*) from public.storage_volumes where accepts_new),
    'health', (select jsonb_agg(to_jsonb(h)) from public.storage_capacity_health h));
end $$;


--
-- Name: storage_commit(uuid, text, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_commit(_workspace uuid, _mailbox text, _bytes bigint, _kind text, _was_reserved boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.mailbox_storage (workspace_id, mailbox) values (_workspace, _mailbox)
  on conflict (workspace_id, mailbox) do nothing;

  update public.mailbox_storage set
    used_emails_bytes      = used_emails_bytes      + case when _kind='email' then _bytes else 0 end,
    used_attachments_bytes = used_attachments_bytes + case when _kind='attachment' then _bytes else 0 end,
    used_files_bytes       = used_files_bytes       + case when _kind='file' then _bytes else 0 end,
    reserved_bytes = greatest(reserved_bytes - case when _was_reserved then _bytes else 0 end, 0),
    updated_at = now()
  where workspace_id = _workspace and mailbox = _mailbox;

  update public.storage_volumes v set used_bytes = v.used_bytes + _bytes
   where v.id = (select volume_id from public.mailbox_storage
                  where workspace_id=_workspace and mailbox=_mailbox);

  insert into public.storage_events (workspace_id, mailbox, kind, delta_bytes, reason)
  values (_workspace, _mailbox, _kind, _bytes, 'commit');

  return public.storage_can_accept(_workspace, _mailbox, 0, _kind);
end $$;


--
-- Name: storage_plan_of(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_plan_of(_workspace uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare _owner uuid; _plan text; _is_founder boolean := false;
begin
  if _workspace is null then return 'trial'; end if;

  if to_regclass('public.chat_workspaces') is not null then
    execute 'select owner_user_id from public.chat_workspaces where id = $1'
      into _owner using _workspace;
  end if;
  if _owner is null then return 'trial'; end if;

  if to_regclass('public.founder_accounts') is not null then
    execute 'select exists(select 1 from public.founder_accounts where user_id = $1)'
      into _is_founder using _owner;
    if _is_founder then return 'business_pro'; end if;
  end if;

  if to_regclass('public.entitlement_state') is not null then
    execute 'select plan from public.entitlement_state
              where user_id = $1
                and (active_until is null or active_until > now())
              limit 1'
      into _plan using _owner;
  end if;

  -- AI plans ko pooled (business_pro) storage milti hai.
  if coalesce(_plan,'') in ('ai_pro','ai_business','ai_executive') then
    return 'business_pro';
  end if;
  if _plan is not null and exists (select 1 from public.storage_plans where plan_id = _plan) then
    return _plan;
  end if;
  return 'trial';
end $_$;


--
-- Name: storage_purge(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_purge(_workspace uuid, _mailbox text, _bytes bigint, _kind text DEFAULT 'attachment'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.mailbox_storage set
    used_emails_bytes      = greatest(used_emails_bytes      - case when _kind='email' then _bytes else 0 end, 0),
    used_attachments_bytes = greatest(used_attachments_bytes - case when _kind='attachment' then _bytes else 0 end, 0),
    used_files_bytes       = greatest(used_files_bytes       - case when _kind='file' then _bytes else 0 end, 0),
    updated_at = now()
  where workspace_id = _workspace and mailbox = _mailbox;

  insert into public.storage_events (workspace_id, mailbox, kind, delta_bytes, reason)
  values (_workspace, _mailbox, 'purge', -_bytes, _kind);

  return public.storage_can_accept(_workspace, _mailbox, 0, _kind);
end $$;


--
-- Name: storage_release(uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_release(_workspace uuid, _mailbox text, _bytes bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.mailbox_storage
     set reserved_bytes = greatest(reserved_bytes - _bytes, 0), updated_at = now()
   where workspace_id = _workspace and mailbox = _mailbox;
  insert into public.storage_events (workspace_id, mailbox, kind, delta_bytes, reason)
  values (_workspace, _mailbox, 'release', -_bytes, 'cancelled');
end $$;


--
-- Name: storage_reserve(uuid, text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_reserve(_workspace uuid, _mailbox text, _bytes bigint, _kind text DEFAULT 'attachment'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _check jsonb; _vol uuid;
begin
  _check := public.storage_can_accept(_workspace, _mailbox, _bytes, _kind);
  if not (_check->>'allowed')::boolean then return _check; end if;

  select id into _vol from public.storage_volumes
   where accepts_new and capacity_bytes - used_bytes > _bytes
   order by capacity_bytes - used_bytes desc limit 1;

  insert into public.mailbox_storage (workspace_id, mailbox, volume_id, reserved_bytes)
  values (_workspace, _mailbox, _vol, _bytes)
  on conflict (workspace_id, mailbox) do update
    set reserved_bytes = public.mailbox_storage.reserved_bytes + _bytes,
        volume_id = coalesce(public.mailbox_storage.volume_id, _vol),
        updated_at = now();

  insert into public.storage_events (workspace_id, mailbox, kind, delta_bytes, reason)
  values (_workspace, _mailbox, 'reserve', _bytes, _kind);

  return jsonb_build_object('allowed', true, 'code', 'reserved', 'bytes', _bytes);
end $$;


--
-- Name: storage_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_state(_workspace uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  _plan text; _p record; _pool_used bigint; _out jsonb;
begin
  _plan := public.storage_plan_of(_workspace);
  select * into _p from public.storage_plans where plan_id = _plan;
  if _p is null then
    select * into _p from public.storage_plans where plan_id = 'trial';
  end if;

  select coalesce(sum(used_emails_bytes + used_attachments_bytes + used_files_bytes), 0)
    into _pool_used from public.mailbox_storage where workspace_id = _workspace;

  select jsonb_build_object(
    'plan', _plan,
    'model', case when _p.pooled_bytes is not null then 'pooled' else 'per_mailbox' end,
    'mailbox_limit', _p.mailbox_limit,
    'max_send_bytes', _p.max_send_bytes,
    'pool', case when _p.pooled_bytes is null then null else jsonb_build_object(
        'quota_bytes', _p.pooled_bytes,
        'used_bytes', _pool_used,
        'remaining_bytes', greatest(_p.pooled_bytes - _pool_used, 0),
        'percent', round((_pool_used::numeric / nullif(_p.pooled_bytes,0)) * 100, 1)
      ) end,
    'mailboxes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'mailbox', m.mailbox,
        'quota_bytes', q.quota,
        'used_bytes', q.used,
        'remaining_bytes', greatest(q.quota - q.used, 0),
        'percent', round((q.used::numeric / nullif(q.quota,0)) * 100, 1),
        'level', case
                   when q.used >= q.quota then 'full'
                   when q.used::numeric >= q.quota * 0.9 then 'critical'
                   when q.used::numeric >= q.quota * 0.8 then 'warning'
                   else 'ok' end,
        'breakdown', jsonb_build_object(
          'emails_bytes', m.used_emails_bytes,
          'attachments_bytes', m.used_attachments_bytes,
          'files_bytes', m.used_files_bytes),
        'reserved_bytes', m.reserved_bytes,
        'updated_at', m.updated_at
      ) order by q.used desc)
      from public.mailbox_storage m
      cross join lateral (
        select coalesce(m.quota_override_bytes, _p.per_mailbox_bytes, _p.pooled_bytes) as quota,
               m.used_emails_bytes + m.used_attachments_bytes + m.used_files_bytes as used
      ) q
      where m.workspace_id = _workspace
    ), '[]'::jsonb)
  ) into _out;

  return _out;
end $$;


--
-- Name: storage_volume_register(text, text, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.storage_volume_register(_name text, _kind text, _capacity_bytes bigint, _endpoint text DEFAULT NULL::text, _drain_others boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare _id uuid;
begin
  insert into public.storage_volumes (name, kind, capacity_bytes, endpoint, accepts_new)
  values (_name, _kind, _capacity_bytes, _endpoint, true)
  on conflict (name) do update
    set kind = excluded.kind,
        capacity_bytes = excluded.capacity_bytes,
        endpoint = excluded.endpoint,
        accepts_new = true
  returning id into _id;

  if _drain_others then
    update public.storage_volumes set accepts_new = false where id <> _id;
  end if;
  return _id;
end $$;


--
-- Name: team_audit(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_audit(p_org uuid, p_actor text, p_action text, p_target text DEFAULT NULL::text, p_detail jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_seq   bigint;
  v_chain boolean := false;
begin
  insert into public.org_people_log (org_id, actor, action, target, detail)
  values (p_org, coalesce(p_actor, ''), p_action, p_target, coalesce(p_detail, '{}'::jsonb));
  if to_regprocedure('public.org_chain_append(text,text,text,text,uuid)') is not null then
    begin
      v_seq := public.org_chain_append(
        coalesce(p_actor, ''), 'team.' || p_action,
        left(coalesce(p_target, '') || case when p_detail is null or p_detail = '{}'::jsonb then '' else ' ' || p_detail::text end, 500),
        null, p_org);
      v_chain := true;
    exception when others then
      v_chain := false;      -- chain optional: jis action ko yeh likhta hai use kabhi nahi rokta
    end;
  end if;
  return jsonb_build_object('log', true, 'chain', v_chain, 'seq', v_seq);
end $$;


--
-- Name: team_col_type(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_col_type(p_col text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select format('%I.%I', n.nspname, t.typname)
    from pg_attribute a
    join pg_type t      on t.oid = a.atttypid
    join pg_namespace n on n.oid = t.typnamespace
   where a.attrelid = 'public.org_members'::regclass
     and a.attname = p_col and a.attnum > 0 and not a.attisdropped
$$;


--
-- Name: team_invite_accept(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_invite_accept(p_token uuid, p_user_id uuid, p_email text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  inv      record;
  v_name   text;
  v_role   text;
  v_status text;
  v_found  boolean;
  v_new    text;
  v_email  text := lower(btrim(coalesce(p_email, '')));
  t_role   text := public.team_col_type('role');
  t_status text := public.team_col_type('status');
  v_acct   boolean := false;
  v_seats  jsonb;
  v_dom    record;
  v_mb     jsonb;
  v_r      jsonb;
begin
  select * into inv from public.org_invitations where token = [REDACTED] for update;
  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;
  select name into v_name from public.organisations where id = inv.org_id;

  if inv.status = 'revoked' then
    return jsonb_build_object('error', 'revoked');
  end if;
  if inv.status = 'accepted' then
    if inv.accepted_by = p_user_id then
      return jsonb_build_object('ok', true, 'already', true, 'org_id', inv.org_id, 'org_name', v_name, 'role', inv.role,
                                'mailbox', coalesce(inv.mailbox_result, jsonb_build_object('status', 'pending')));
    end if;
    return jsonb_build_object('error', 'used');
  end if;
  if inv.expires_at < now() then
    update public.org_invitations set status = 'expired' where id = inv.id;
    return jsonb_build_object('error', 'expired');
  end if;

  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'E33: user % auth.users mein nahi', p_user_id using errcode = 'AX035';
  end if;
  if exists (select 1 from pg_type ty where ty.oid = t_role::regtype and ty.typtype = 'e')
     and not exists (select 1 from pg_enum en where en.enumtypid = t_role::regtype and en.enumlabel = inv.role) then
    raise exception 'E33: role "%" live org_members.role (%) mein nahi', inv.role, t_role using errcode = 'AX036';
  end if;

  -- do log ek saath aakhri seat na le sakein: org-wise lock, ginti uske ANDAR
  perform pg_advisory_xact_lock(hashtextextended('team_seats:' || inv.org_id::text, 0));

  select m.role::text, m.status::text into v_role, v_status
    from public.org_members m where m.org_id = inv.org_id and m.user_id = p_user_id limit 1;
  v_found := found;

  if not v_found or v_status = 'revoked' then          -- naya seat (pehle se active member ka role badalna seat nahi leta)
    v_seats := public.team_seat_state(inv.org_id);
    if coalesce((v_seats->>'enforced')::boolean, false)
       and (v_seats->>'used')::integer >= (v_seats->>'seats')::integer then
      return jsonb_build_object('error', 'seats_full', 'org_name', v_name,
                                'seats', (v_seats->>'seats')::integer, 'used', (v_seats->>'used')::integer);
    end if;
  end if;

  if v_found then
    v_new := case
               when v_status = 'revoked' then inv.role
               when public.team_role_rank(inv.role) > public.team_role_rank(v_role) then inv.role
               else v_role
             end;
    execute format(
      'update public.org_members set status = %L::%s, email = coalesce(nullif(email, %L), $3), role = $4::%s where org_id = $1 and user_id = $2',
      'active', t_status, '', t_role)
      using inv.org_id, p_user_id, v_email, v_new;
  else
    v_new := inv.role;
    execute format(
      'insert into public.org_members (org_id, user_id, role, status, email) values ($1, $2, $3::%s, %L::%s, $4)',
      t_role, 'active', t_status)
      using inv.org_id, p_user_id, v_new, v_email;
  end if;

  begin
    insert into public.account_org_members (org_id, user_id, role)
    select inv.org_id, p_user_id, case when v_new in ('owner', 'admin') then v_new else 'member' end
     where not exists (select 1 from public.account_org_members a where a.org_id = inv.org_id and a.user_id = p_user_id);
    v_acct := true;
  exception when others then
    v_acct := false;
  end;

  -- mailbox: manga gaya ho to banao, warna "pending" (admin banayega). Kuch bhi ho, join nahi rukta.
  if coalesce(inv.mailbox_local, '') <> '' then
    begin
      select d.id, d.domain into v_dom from public.team_invite_domain(inv.org_id, inv.mailbox_domain_id) d;
      if v_dom.id is null then
        v_mb := jsonb_build_object('status', 'failed', 'error', 'domain_not_verified');
      else
        v_r := public.org_address_create(inv.org_id, v_dom.id, inv.mailbox_local, 'mailbox', p_user_id, null);
        if coalesce((v_r->>'ok')::boolean, false) then
          v_mb := jsonb_build_object('status', 'created', 'address', coalesce(v_r->'address'->>'address', inv.mailbox_local || '@' || v_dom.domain));
        else
          v_mb := jsonb_build_object('status', 'failed', 'error', coalesce(v_r->>'error', 'unknown'));
        end if;
      end if;
    exception when others then
      v_mb := jsonb_build_object('status', 'failed', 'error', 'mailbox_failed');
    end;
  else
    v_mb := jsonb_build_object('status', 'pending');
  end if;

  update public.org_invitations
     set status = 'accepted', accepted_at = now(), accepted_by = p_user_id, mailbox_result = v_mb
   where id = inv.id;

  perform public.team_audit(inv.org_id, v_email, 'invite.accepted', inv.email,
          jsonb_build_object('role', v_new, 'invited_role', inv.role, 'user_id', p_user_id,
                             'rejoin', coalesce(v_status = 'revoked', false), 'mailbox', v_mb->>'status'));

  return jsonb_build_object('ok', true, 'org_id', inv.org_id, 'org_name', v_name, 'role', v_new, 'account_layer', v_acct, 'mailbox', v_mb);
end $_$;


--
-- Name: team_invite_domain(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_invite_domain(p_org uuid, p_domain_id uuid) RETURNS TABLE(id uuid, domain text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
begin
  if to_regclass('public.org_domains') is null then
    return;
  end if;
  return query execute
    'select d.id, d.domain::text from public.org_domains d
      where d.org_id = $1 and d.status = ''verified'' and ($2 is null or d.id = $2)
      order by d.domain limit 1'
    using p_org, p_domain_id;
end $_$;


--
-- Name: team_invite_lookup(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_invite_lookup(p_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r    record;
  v_d  record;
  v_mb text := null;
begin
  select i.org_id, i.email, i.role, i.status, i.expires_at, i.invited_by_email, i.mailbox_local, i.mailbox_domain_id, o.name as org_name
    into r
    from public.org_invitations i
    join public.organisations o on o.id = i.org_id
   where i.token = [REDACTED]
  if not found then
    return jsonb_build_object('error', 'not_found');
  end if;
  if coalesce(r.mailbox_local, '') <> '' then
    begin
      select d.id, d.domain into v_d from public.team_invite_domain(r.org_id, r.mailbox_domain_id) d;
      if v_d.id is not null then v_mb := r.mailbox_local || '@' || v_d.domain; end if;
    exception when others then
      v_mb := null;
    end;
  end if;
  return jsonb_build_object(
    'org_name',   r.org_name,
    'role',       r.role,
    'email',      r.email,
    'invited_by', r.invited_by_email,
    'expires_at', r.expires_at,
    'mailbox',    v_mb,
    'status',     case when r.status = 'pending' and r.expires_at < now() then 'expired' else r.status end
  );
end $$;


--
-- Name: team_role_rank(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_role_rank(p_role text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case p_role when 'owner' then 5 when 'admin' then 4 when 'manager' then 3 when 'member' then 2 when 'viewer' then 1 else 0 end
$$;


--
-- Name: team_seat_calc(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_seat_calc(p_plan text, p_seats integer, p_used integer, p_pending integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
  select jsonb_build_object(
    'plan',      p_plan,
    'unlimited', coalesce(p_plan, '') = 'business_pro',
    'known',     coalesce(p_seats, 0) > 0,
    'enforced',  coalesce(p_plan, '') <> 'business_pro' and coalesce(p_seats, 0) > 0,
    'seats',     case when coalesce(p_plan, '') <> 'business_pro' and coalesce(p_seats, 0) > 0 then p_seats else null end,
    'used',      greatest(coalesce(p_used, 0), 0),
    'pending',   greatest(coalesce(p_pending, 0), 0),
    'free',      case when coalesce(p_plan, '') <> 'business_pro' and coalesce(p_seats, 0) > 0
                      then greatest(p_seats - greatest(coalesce(p_used, 0), 0) - greatest(coalesce(p_pending, 0), 0), 0)
                      else null end
  )
$$;


--
-- Name: team_seat_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_seat_state(p_org uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_plan    text;
  v_seats   integer := 0;
  v_seats2  integer := 0;
  v_used    integer;
  v_pending integer;
begin
  begin
    v_plan := public.org_plan_of(p_org);
  exception when undefined_function then
    v_plan := null;
  end;
  select coalesce(max(e.seats), 0) into v_seats
    from public.entitlement_state e
   where e.user_id in (select m.user_id from public.org_members m where m.org_id = p_org and m.role::text = 'owner');
  if to_regclass('public.workspace_subscriptions') is not null then
    begin
      execute 'select coalesce(max(s.seats), 0) from public.workspace_subscriptions s
                where s.user_id in (select m.user_id from public.org_members m where m.org_id = $1 and m.role::text = ''owner'')'
        into v_seats2 using p_org;
    exception when others then
      v_seats2 := 0;
    end;
  end if;
  select count(*) into v_used from public.org_members m
   where m.org_id = p_org and coalesce(m.status::text, 'active') <> 'revoked';
  select count(*) into v_pending from public.org_invitations i
   where i.org_id = p_org and i.status = 'pending' and i.expires_at > now();
  return public.team_seat_calc(v_plan, greatest(v_seats, v_seats2), v_used, v_pending);
end $_$;


--
-- Name: trg_entitlement_activates_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_entitlement_activates_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  begin
    perform public.activate_paid_account(
      new.user_id, new.plan, 'entitlement:' || coalesce(new.source_intent::text, ''));
  exception when others then
    raise warning 'E23 activate_paid_account failed for %: %', new.user_id, sqlerrm;
  end;
  return null;
end $$;


--
-- Name: trial_activate_if_paid(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_activate_if_paid(_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare p text;
begin
  select e.plan into p
    from public.entitlement_state e
   where e.user_id = _user
     and e.plan is not null
     and (e.active_until is null or e.active_until > now())
   limit 1;
  if p is null then
    return jsonb_build_object('ok', false, 'error', 'no_verified_payment');
  end if;
  perform public.activate_paid_account(_user, p, 'entitlement:poke');
  return jsonb_build_object('ok', true, 'state', public.account_state(_user));
end $$;


--
-- Name: trial_claim_address(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_claim_address(_user_id uuid, _handle text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare h text := lower(trim(_handle));
begin
  if h !~ '^[a-z0-9]([a-z0-9.-]{1,28})[a-z0-9]$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_handle');
  end if;
  if exists (select 1 from public.reserved_handles where handle = h) then
    return jsonb_build_object('ok', false, 'error', 'reserved_handle');
  end if;
  if exists (select 1 from public.trial_accounts
             where lower(anexomail_handle) = h and user_id <> _user_id
               and (status <> 'released')) then
    return jsonb_build_object('ok', false, 'error', 'taken');
  end if;
  update public.trial_accounts
     set anexomail_handle = h, anexomail_address = h || '@anexomail.com', updated_at = now()
   where user_id = _user_id;
  insert into public.trial_events (user_id, event_type, detail)
  values (_user_id, 'claim', jsonb_build_object('address', h || '@anexomail.com'))
  on conflict do nothing;
  return jsonb_build_object('ok', true, 'state', public.account_state(_user_id));
end $_$;


--
-- Name: trial_events_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_events_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  raise exception 'trial_events is append-only (immutable audit ledger)';
end $$;


--
-- Name: trial_provision_workspace(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_provision_workspace(_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  a public.trial_accounts;
  existing_org uuid;
  new_org uuid;
  ws_name text;
  ws_slug text;
begin
  select * into a from public.trial_accounts where user_id = _user_id;
  if a.user_id is null then
    return jsonb_build_object('ok', false, 'error', 'no_trial_account');
  end if;
  if a.anexomail_address is null then
    return jsonb_build_object('ok', false, 'error', 'address_not_claimed');
  end if;

  select org_id into existing_org from public.org_members where user_id = _user_id limit 1;
  if existing_org is not null then
    return jsonb_build_object('ok', true, 'already_provisioned', true, 'org_id', existing_org,
                               'address', a.anexomail_address);
  end if;

  ws_name := initcap(a.anexomail_handle) || ' workspace';
  ws_slug := a.anexomail_handle || '-' || substr(_user_id::text, 1, 8);

  insert into public.organisations (id, name, slug, owner_id, created_at, storage_limit_bytes)
  values (gen_random_uuid(), ws_name, ws_slug, _user_id, now(), 32212254720)
  returning id into new_org;

  insert into public.mail_accounts (id, org_id, address, kind, accepts_replies, auto_reply, created_at)
  values (gen_random_uuid(), new_org, a.anexomail_address, 'personal', true, false, now());

  insert into public.org_members (id, org_id, user_id, role, created_at, email, status)
  values (gen_random_uuid(), new_org, _user_id, 'owner', now(), a.anexomail_address, 'active');

  insert into public.trial_events (user_id, event_type, detail)
  values (_user_id, 'workspace_provisioned',
          jsonb_build_object('org_id', new_org, 'address', a.anexomail_address))
  on conflict do nothing;

  return jsonb_build_object('ok', true, 'already_provisioned', false, 'org_id', new_org,
                             'address', a.anexomail_address);
end $$;


--
-- Name: trial_set_security(uuid, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_set_security(_user_id uuid, _passkey boolean, _recovery_kind text, _recovery_hint text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.trial_accounts
     set passkey_set = [REDACTED] or coalesce(_passkey, false),
         recovery_set = recovery_set or (_recovery_kind is not null),
         recovery_kind = coalesce(_recovery_kind, recovery_kind),
         recovery_hint = coalesce(_recovery_hint, recovery_hint),
         updated_at = now()
   where user_id = _user_id;
  if coalesce(_passkey, false) then
    insert into public.trial_events (user_id, event_type) values (_user_id, 'passkey_set')
    on conflict do nothing;
  end if;
  if _recovery_kind is not null then
    insert into public.trial_events (user_id, event_type, detail)
    values (_user_id, 'recovery_set', jsonb_build_object('kind', _recovery_kind, 'hint', _recovery_hint))
    on conflict do nothing;
  end if;
  return public.account_state(_user_id);
end $$;


--
-- Name: trial_start(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_start(_user_id uuid, _social_email text, _provider text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a public.trial_accounts;
begin
  insert into public.trial_accounts (user_id, social_email, social_provider)
  values (_user_id, _social_email, _provider)
  on conflict (user_id) do update set social_email = coalesce(excluded.social_email, trial_accounts.social_email),
                                      updated_at = now()
  returning * into a;
  insert into public.trial_events (user_id, event_type, detail)
  values (_user_id, 'signup', jsonb_build_object('provider', _provider, 'email', _social_email))
  on conflict do nothing;
  return public.account_state(_user_id);
end $$;


--
-- Name: trial_subscribe(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_subscribe(_user_id uuid, _plan text, _payment_ref text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if _plan not in ('basic','pro','business','business_pro') then
    return jsonb_build_object('ok', false, 'error', 'invalid_plan');
  end if;
  update public.trial_accounts
     set status = 'active', plan = _plan, converted_at = coalesce(converted_at, now()),
         expired_at = null, frozen_at = null, address_reserved_until = null, updated_at = now()
   where user_id = _user_id;
  insert into public.trial_events (user_id, event_type, detail)
  values (_user_id, 'subscribed', jsonb_build_object('plan', _plan, 'payment_ref', _payment_ref))
  on conflict do nothing;
  return jsonb_build_object('ok', true, 'state', public.account_state(_user_id));
end $$;


--
-- Name: trial_sweep(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_sweep() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare warned24 int := 0; warned2 int := 0; expired int := 0; frozen int := 0; released int := 0;
begin
  -- 24h warning (once — unique index guarantees it)
  with c as (
    select user_id from public.trial_accounts
     where status = 'trial' and trial_ends_at between now() and now() + interval '24 hours'
  ), i as (
    insert into public.trial_events (user_id, event_type)
    select user_id, 'warn_24h' from c on conflict do nothing returning 1
  ) select count(*) into warned24 from i;

  with c as (
    select user_id from public.trial_accounts
     where status = 'trial' and trial_ends_at between now() and now() + interval '2 hours'
  ), i as (
    insert into public.trial_events (user_id, event_type)
    select user_id, 'warn_2h' from c on conflict do nothing returning 1
  ) select count(*) into warned2 from i;

  -- trial -> expired (social login band, recovery khula, address 30 din reserved)
  with u as (
    update public.trial_accounts
       set status = 'expired', expired_at = now(),
           address_reserved_until = now() + interval '30 days', updated_at = now()
     where status = 'trial' and trial_ends_at <= now()
     returning user_id
  ), i as (
    insert into public.trial_events (user_id, event_type) select user_id, 'expired' from u
    on conflict do nothing returning 1
  ) select count(*) into expired from i;

  -- expired -> frozen (mailbox inaccessible, mail held/rejected — kabhi discard nahi)
  with u as (
    update public.trial_accounts set status = 'frozen', frozen_at = now(), updated_at = now()
     where status = 'expired' and expired_at <= now() - interval '24 hours'
     returning user_id
  ), i as (
    insert into public.trial_events (user_id, event_type) select user_id, 'frozen' from u
    on conflict do nothing returning 1
  ) select count(*) into frozen from i;

  -- 30 din baad address release
  with u as (
    update public.trial_accounts
       set status = 'released', anexomail_handle = null, address_reserved_until = null, updated_at = now()
     where status in ('expired','frozen') and address_reserved_until is not null
       and address_reserved_until <= now()
     returning user_id
  ), i as (
    insert into public.trial_events (user_id, event_type) select user_id, 'released' from u
    on conflict do nothing returning 1
  ) select count(*) into released from i;

  return jsonb_build_object('warn_24h', warned24, 'warn_2h', warned2,
    'expired', expired, 'frozen', frozen, 'released', released, 'ran_at', now());
end $$;


--
-- Name: ui_copy_bundle(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ui_copy_bundle(p_tag text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions'
    AS $$
  select coalesce(jsonb_object_agg(c.english_key, c.text), '{}'::jsonb)
    from public.ui_copy c
   where c.locale_tag = p_tag
     and c.text is not null
     and length(btrim(c.text)) > 0
     and not (p_tag <> 'en-GB' and c.text = c.english_key);
$$;


--
-- Name: ui_copy_register(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ui_copy_register(p_english text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
begin
  if p_english is null or length(btrim(p_english)) = 0 then
    return;
  end if;
  insert into public.ui_copy (english_key, locale_tag, text)
  values (btrim(p_english), 'en-GB', btrim(p_english))
  on conflict (english_key, locale_tag) do nothing;
end;
$$;


--
-- Name: update_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: webhook_capture_raw(text, text, jsonb, boolean, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_capture_raw(p_event_id text, p_type text, p_body jsonb, p_verified boolean, p_reason text DEFAULT NULL::text, p_headers jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_id uuid;
begin
  insert into public.polar_webhook_raw
    (polar_event_id, event_type, verified, reject_reason, headers, body)
  values (p_event_id, p_type, p_verified, p_reason, p_headers, p_body)
  returning id into v_id;

  if not p_verified then
    insert into public.payment_alerts (severity, kind, polar_event_id, message)
    values ('critical', 'webhook_rejected', p_event_id,
            coalesce(p_reason, 'unverified webhook') || ' — raw payload saved, manual replay possible');
  end if;
  return v_id;
end;
$$;


--
-- Name: webhook_claim_retries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_claim_retries(p_limit integer DEFAULT 20) RETURNS TABLE(polar_event_id text, type text, payload jsonb, attempts integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.polar_event_id, e.type, e.payload, e.attempts
    from public.polar_webhook_events e
   where e.processed_at is null
     and e.state in ('pending', 'retry')
     and coalesce(e.next_retry_at, e.first_seen_at) <= now()
   order by e.first_seen_at asc
   limit greatest(1, least(p_limit, 100));
$$;


--
-- Name: webhook_mark_failed(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_mark_failed(p_event_id text, p_error text) RETURNS TABLE(attempts integer, next_retry_at timestamp with time zone, state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_attempts int;
begin
  update public.polar_webhook_events e
     set attempts = e.attempts + 1,
         last_error = p_error,
         state = case when e.attempts + 1 >= 8 then 'dead' else 'retry' end,
         -- backoff: 1m, 2m, 4m, 8m ... capped at 6h
         next_retry_at = now() + least(interval '6 hours',
                                       (interval '1 minute') * power(2, least(e.attempts, 9)))
   where e.polar_event_id = p_event_id
  returning e.attempts into v_attempts;

  if coalesce(v_attempts, 0) >= 3 then
    insert into public.payment_alerts (severity, kind, polar_event_id, message)
    values ('critical', 'webhook_processing_failed', p_event_id,
            'attempt ' || v_attempts || ' failed: ' || coalesce(p_error, 'unknown'));
  end if;

  return query
    select e.attempts, e.next_retry_at, e.state
      from public.polar_webhook_events e
     where e.polar_event_id = p_event_id;
end;
$$;


--
-- Name: webhook_mark_processed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.webhook_mark_processed(p_event_id text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update public.polar_webhook_events
     set processed_at = now(), state = 'processed', last_error = null, next_retry_at = null
   where polar_event_id = p_event_id;
$$;


--
-- Name: work_task_update(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.work_task_update(_org_id uuid, _id uuid, _status text DEFAULT NULL::text, _due timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare r public.work_tasks;
begin
  if _status is not null and _status not in ('todo','doing','waiting','done') then
    raise exception 'invalid_status';
  end if;
  update public.work_tasks t
     set status = coalesce(_status, t.status),
         due_at = coalesce(_due, t.due_at),
         completed_at = case
           when _status is null then t.completed_at
           when _status = 'done' then coalesce(t.completed_at, now())
           else null
         end
   where t.id = _id and t.org_id = _org_id
   returning * into r;
  if not found then return null; end if;
  return to_jsonb(r);
end;
$$;


