--
-- Name: billing_reconcile_queue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_reconcile_queue WITH (security_invoker='on') AS
 SELECT i.id AS intent_id,
    i.user_id,
    (i.guest_token IS NOT NULL) AS guest,
    i.polar_checkout_id,
    i.state,
    i.fsm_state,
    i.state_version,
    i.amount_expected,
    i.amount_paid,
    i.created_at,
        CASE
            WHEN ((i.state = 'paid'::text) AND (e.user_id IS NULL)) THEN 'P0'::text
            WHEN ((i.state = 'paid'::text) AND (i.fsm_state <> 'SUBSCRIPTION_ACTIVE'::text)) THEN 'P1'::text
            WHEN ((i.state = 'open'::text) AND (i.created_at > (now() - '00:10:00'::interval))) THEN 'P1'::text
            WHEN ((i.state = 'open'::text) AND (i.created_at > (now() - '24:00:00'::interval))) THEN 'P2'::text
            WHEN (i.state = 'stuck'::text) THEN 'P2'::text
            ELSE 'P4'::text
        END AS priority,
        CASE
            WHEN (i.created_at > (now() - '00:02:00'::interval)) THEN 5
            WHEN (i.created_at > (now() - '00:10:00'::interval)) THEN 15
            WHEN (i.created_at > (now() - '01:00:00'::interval)) THEN 120
            WHEN (i.created_at > (now() - '24:00:00'::interval)) THEN 900
            ELSE 3600
        END AS poll_seconds
   FROM (public.billing_intents i
     LEFT JOIN public.entitlement_state e ON ((e.user_id = i.user_id)))
  WHERE ((i.state = ANY (ARRAY['open'::text, 'paid'::text, 'stuck'::text])) OR (i.fsm_state = ANY (ARRAY['CHECKOUT_OPEN'::text, 'PAYMENT_PENDING'::text, 'PAYMENT_CONFIRMED'::text])));


--
-- Name: billing_reconciliation_runs; Type: TABLE; Schema: public; Owner: -
