CREATE TABLE public.billing_reconciliation_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    scope text DEFAULT 'hot'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    checked integer DEFAULT 0 NOT NULL,
    repaired integer DEFAULT 0 NOT NULL,
    failed integer DEFAULT 0 NOT NULL,
    lease_until timestamp with time zone,
    note text,
    CONSTRAINT billing_reconciliation_runs_scope_check CHECK ((scope = ANY (ARRAY['hot'::text, 'warm'::text, 'cold'::text, 'daily'::text])))
);


--
-- Name: billing_mesh_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_mesh_health WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM public.billing_reconcile_queue
          WHERE (billing_reconcile_queue.priority = 'P0'::text)) AS p0_paid_without_entitlement,
    ( SELECT count(*) AS count
           FROM public.billing_reconcile_queue
          WHERE (billing_reconcile_queue.priority = 'P1'::text)) AS p1_urgent,
    ( SELECT count(*) AS count
           FROM public.billing_outbox
          WHERE (billing_outbox.acked_at IS NULL)) AS outbox_pending,
    ( SELECT count(*) AS count
           FROM public.billing_inbox
          WHERE ((billing_inbox.applied = false) AND (billing_inbox.stale = false))) AS inbox_unapplied,
    ( SELECT count(*) AS count
           FROM public.billing_observations
          WHERE ((billing_observations.signature_ok = false) AND (billing_observations.observed_at > (now() - '24:00:00'::interval)))) AS bad_signatures_24h,
    ( SELECT count(*) AS count
           FROM public.billing_failures
          WHERE (billing_failures.resolved = false)) AS open_failures,
    ( SELECT max(billing_reconciliation_runs.finished_at) AS max
           FROM public.billing_reconciliation_runs) AS last_run_at;


