    CONSTRAINT billing_price_book_billing_cycle_check CHECK ((billing_cycle = ANY (ARRAY['monthly'::text, 'yearly'::text]))),
    CONSTRAINT billing_price_book_kind_check CHECK ((kind = ANY (ARRAY['plan'::text, 'ai_plan'::text, 'support'::text, 'movein'::text]))),
    CONSTRAINT billing_price_book_required_account_kind_check CHECK (((required_account_kind IS NULL) OR (required_account_kind = ANY (ARRAY['personal'::text, 'business'::text]))))
);


