   FROM public.billing_price_book
  WHERE (active AND polar_listed AND (COALESCE(polar_product_id, ''::text) = ''::text));


--
-- Name: billing_price_audit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_price_audit WITH (security_invoker='on') AS
 SELECT i.id AS intent_id,
    i.user_id,
    i.product_key,
    i.billing_cycle,
    i.seats,
    i.amount_expected,
    i.amount_paid,
    (pb.amount_gbp * (
        CASE
            WHEN pb.per_seat THEN GREATEST(1, i.seats)
            ELSE 1
        END)::numeric) AS book_amount,
    (i.amount_expected IS DISTINCT FROM (pb.amount_gbp * (
        CASE
            WHEN pb.per_seat THEN GREATEST(1, i.seats)
            ELSE 1
        END)::numeric)) AS mismatch,
    i.state,
    i.created_at
   FROM (public.billing_intents i
     LEFT JOIN public.billing_price_book pb ON ((pb.product_key = i.product_key)))
  ORDER BY i.created_at DESC;


