--
-- Name: billing_truth_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_truth_gaps WITH (security_invoker='on') AS
 SELECT 'paid_without_entitlement'::text AS gap,
    (i.id)::text AS ref,
    i.user_id,
    i.state,
    i.paid_at AS at,
    i.last_error AS detail
   FROM (public.billing_intents i
     LEFT JOIN public.entitlement_state e ON ((e.user_id = i.user_id)))
  WHERE ((i.paid_at IS NOT NULL) AND ((e.user_id IS NULL) OR (e.source_intent IS DISTINCT FROM i.id)) AND (i.state <> 'entitled'::text))
UNION ALL
 SELECT 'stuck_intent'::text AS gap,
    (i.id)::text AS ref,
    i.user_id,
    i.state,
    i.updated_at AS at,
    i.last_error AS detail
   FROM public.billing_intents i
  WHERE (i.state = 'stuck'::text)
UNION ALL
 SELECT 'unverified_webhook'::text AS gap,
    (r.id)::text AS ref,
    NULL::uuid AS user_id,
    'raw'::text AS state,
    r.received_at AS at,
    r.reject_reason AS detail
   FROM public.polar_webhook_raw r
  WHERE ((r.verified = false) AND (r.received_at > (now() - '30 days'::interval)));


