--
-- Name: billing_state_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.billing_state_health WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM public.billing_intents
          WHERE (billing_intents.state = 'open'::text)) AS open_intents,
    ( SELECT count(*) AS count
           FROM public.billing_intents
          WHERE (billing_intents.state = 'paid'::text)) AS paid_pending,
    ( SELECT count(*) AS count
           FROM public.billing_intents
          WHERE (billing_intents.state = 'stuck'::text)) AS stuck_intents,
    ( SELECT count(*) AS count
           FROM public.billing_intents
          WHERE (billing_intents.state = 'entitled'::text)) AS entitled_total,
    ( SELECT count(*) AS count
           FROM public.billing_truth_gaps) AS open_gaps,
    ( SELECT count(*) AS count
           FROM public.payment_alerts
          WHERE (payment_alerts.resolved_at IS NULL)) AS open_alerts,
    ( SELECT max(billing_intents.updated_at) AS max
           FROM public.billing_intents) AS last_sync_at;


