    workspace_id uuid,
    caller_id uuid NOT NULL,
    peer_id uuid,
    role text DEFAULT 'caller'::text NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    connected_at timestamp with time zone,
    ended_at timestamp with time zone,
    setup_ms integer,
    path text,
    video_codec text,
    audio_codec text DEFAULT 'opus'::text,
    ice_restarts integer DEFAULT 0 NOT NULL,
    end_reason text,
    signaling text,
    capture_width integer,
    capture_height integer,
    capture_native_8k boolean DEFAULT false NOT NULL,
    max_encoded_width integer,
    max_encoded_height integer,
    max_decoded_width integer,
    max_decoded_height integer,
    top_rung text,
    hw_accelerated boolean,
    downgrades integer DEFAULT 0 NOT NULL,
    upgrades integer DEFAULT 0 NOT NULL,
    CONSTRAINT chat_call_sessions_path_check CHECK ((path = ANY (ARRAY['p2p'::text, 'relay'::text, 'unknown'::text]))),
    CONSTRAINT chat_call_sessions_role_check CHECK ((role = ANY (ARRAY['caller'::text, 'callee'::text]))),
    CONSTRAINT chat_call_sessions_signaling_check CHECK ((signaling = ANY (ARRAY['webtransport'::text, 'realtime'::text, 'rows'::text])))
);


--
-- Name: chat_call_resolution_truth; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.chat_call_resolution_truth WITH (security_invoker='on') AS
 SELECT date_trunc('day'::text, started_at) AS day,
    count(*) AS calls,
    count(*) FILTER (WHERE capture_native_8k) AS native_8k_capture,
    count(*) FILTER (WHERE (COALESCE(max_encoded_width, 0) >= 7680)) AS encoded_8k,
    count(*) FILTER (WHERE (COALESCE(max_decoded_width, 0) >= 7680)) AS decoded_8k,
    count(*) FILTER (WHERE ((COALESCE(max_encoded_width, 0) >= 3840) AND (COALESCE(max_encoded_width, 0) < 7680))) AS encoded_4k,
    count(*) FILTER (WHERE (video_codec ~~* 'av1%'::text)) AS av1_calls,
    count(*) FILTER (WHERE (video_codec ~~* 'vp9%'::text)) AS vp9_calls,
    count(*) FILTER (WHERE (video_codec ~~* 'h264%'::text)) AS h264_calls,
    sum(downgrades) AS downgrades,
    sum(upgrades) AS upgrades
   FROM public.chat_call_sessions s
  GROUP BY (date_trunc('day'::text, started_at))
  ORDER BY (date_trunc('day'::text, started_at)) DESC;


