--
-- Name: follow_through_scores; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.follow_through_scores WITH (security_invoker='on') AS
 SELECT p.org_id,
    COALESCE(p.promised_by, 'unknown'::text) AS subject,
    count(*) FILTER (WHERE (p.state = 'committed'::text)) AS promises_made,
    count(*) FILTER (WHERE ((t.status = 'done'::text) AND ((t.due_at IS NULL) OR (t.completed_at <= t.due_at)))) AS kept_on_time,
    count(*) FILTER (WHERE ((t.status = 'done'::text) AND (t.due_at IS NOT NULL) AND (t.completed_at > t.due_at))) AS kept_late,
    count(*) FILTER (WHERE ((t.status <> 'done'::text) AND (t.due_at IS NOT NULL) AND (t.due_at < now()))) AS broken
   FROM (public.work_promises p
     LEFT JOIN public.work_tasks t ON ((t.id = p.task_id)))
  GROUP BY p.org_id, COALESCE(p.promised_by, 'unknown'::text);


