--
-- Name: mail_counterparties; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.mail_counterparties WITH (security_invoker='on') AS
 SELECT m.id AS message_id,
    t.id AS thread_id,
    t.org_id,
    m.direction,
    m.sent_at,
    lower(TRIM(BOTH '<> '::text FROM
        CASE
            WHEN (m.direction = 'in'::public.mail_direction) THEN m.from_address
            ELSE COALESCE((to_jsonb(m.*) ->> 'to_address'::text), ((to_jsonb(m.*) -> 'to_addresses'::text) ->> 0), ((to_jsonb(m.*) -> 'to'::text) ->> 0), ((to_jsonb(m.*) -> 'recipients'::text) ->> 0))
        END)) AS address,
        CASE
            WHEN (m.direction = 'in'::public.mail_direction) THEN m.from_name
            ELSE NULL::text
        END AS name
   FROM (public.mail_messages m
     JOIN public.mail_threads t ON ((t.id = m.thread_id)));


