    CONSTRAINT movein_payments_leg_check CHECK ((leg = ANY (ARRAY['deposit'::text, 'final'::text]))),
    CONSTRAINT movein_payments_state_check CHECK ((state = ANY (ARRAY['due'::text, 'invoiced'::text, 'paid'::text, 'void'::text])))
);


--
-- Name: movein_attention; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_attention WITH (security_invoker='on') AS
 SELECT d.id AS deal_id,
    d.reference,
    'final_payment_overdue'::text AS kind,
    'Final 50% overdue'::text AS message,
    (d.state)::text AS state
   FROM (public.movein_deals d
     JOIN public.movein_payments p ON ((p.deal_id = d.id)))
  WHERE ((p.leg = 'final'::text) AND (p.state = ANY (ARRAY['due'::text, 'invoiced'::text])) AND (p.due_at IS NOT NULL) AND (p.due_at < now()))
UNION ALL
 SELECT d.id AS deal_id,
    d.reference,
    'deposit_overdue'::text AS kind,
    'Deposit 50% overdue'::text AS message,
    (d.state)::text AS state
   FROM (public.movein_deals d
     JOIN public.movein_payments p ON ((p.deal_id = d.id)))
  WHERE ((p.leg = 'deposit'::text) AND (p.state = ANY (ARRAY['due'::text, 'invoiced'::text])) AND (p.due_at IS NOT NULL) AND (p.due_at < now()))
UNION ALL
 SELECT d.id AS deal_id,
    d.reference,
    ('exception_'::text || lower((e.severity)::text)) AS kind,
    e.reason AS message,
    (d.state)::text AS state
   FROM (public.movein_deals d
     JOIN public.movein_exceptions e ON ((e.deal_id = d.id)))
  WHERE ((e.resolved_at IS NULL) AND (e.severity = ANY (ARRAY['BLOCKED'::public.movein_result, 'FAILED'::public.movein_result, 'ROLLBACK_REQUIRED'::public.movein_result, 'CUSTOMER_ACTION_REQUIRED'::public.movein_result])))
UNION ALL
 SELECT d.id AS deal_id,
    d.reference,
    'cutover_not_ready'::text AS kind,
    'Cut-over scheduled but checks not clear'::text AS message,
    (d.state)::text AS state
   FROM public.movein_deals d
  WHERE ((d.state = 'CUTOVER_SCHEDULED'::public.movein_state) AND (NOT public.movein_cutover_ready(d.id)));


