);


--
-- Name: movein_waitlist; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movein_waitlist (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    deal_id uuid NOT NULL,
    month date NOT NULL,
    "position" integer NOT NULL,
    released_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: movein_capacity_state; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_capacity_state WITH (security_invoker='on') AS
 SELECT month,
    slots_total,
    ( SELECT count(*) AS count
           FROM public.movein_deals d
          WHERE ((d.scheduled_month = c.month) AND (d.waitlisted = false) AND (d.state <> 'CANCELLED'::public.movein_state))) AS slots_booked,
    GREATEST((slots_total - ( SELECT count(*) AS count
           FROM public.movein_deals d
          WHERE ((d.scheduled_month = c.month) AND (d.waitlisted = false) AND (d.state <> 'CANCELLED'::public.movein_state)))), (0)::bigint) AS slots_free,
    ( SELECT count(*) AS count
           FROM public.movein_waitlist w
          WHERE ((w.month = c.month) AND (w.released_at IS NULL))) AS waitlisted
   FROM public.movein_capacity c;


--
-- Name: movein_cash_clock; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_cash_clock WITH (security_invoker='on') AS
 SELECT ( SELECT COALESCE(sum(movein_deals.price_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_deals
          WHERE (movein_deals.state <> ALL (ARRAY['LEAD'::public.movein_state, 'QUALIFIED'::public.movein_state, 'CANCELLED'::public.movein_state]))) AS booked_gbp,
    ( SELECT COALESCE(sum(movein_payments.amount_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_payments
          WHERE ((movein_payments.leg = 'deposit'::text) AND (movein_payments.state <> 'void'::text))) AS deposits_expected_gbp,
    ( SELECT COALESCE(sum(movein_payments.amount_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_payments
          WHERE ((movein_payments.leg = 'deposit'::text) AND (movein_payments.state = 'paid'::text))) AS deposits_paid_gbp,
    ( SELECT COALESCE(sum(movein_payments.amount_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_payments
          WHERE ((movein_payments.leg = 'final'::text) AND (movein_payments.state <> 'void'::text))) AS final_expected_gbp,
    ( SELECT COALESCE(sum(movein_payments.amount_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_payments
          WHERE ((movein_payments.leg = 'final'::text) AND (movein_payments.state = 'paid'::text))) AS final_paid_gbp,
    ( SELECT COALESCE(sum(movein_payments.amount_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_payments
          WHERE (movein_payments.state = ANY (ARRAY['due'::text, 'invoiced'::text]))) AS outstanding_gbp,
    ( SELECT COALESCE(sum(movein_payments.amount_gbp), (0)::numeric) AS "coalesce"
           FROM public.movein_payments
          WHERE ((movein_payments.state = ANY (ARRAY['due'::text, 'invoiced'::text])) AND (movein_payments.due_at IS NOT NULL) AND (movein_payments.due_at < now()))) AS overdue_gbp;


--
-- Name: movein_dns_checks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movein_dns_checks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    deal_id uuid NOT NULL,
    verification_id text DEFAULT encode(extensions.gen_random_bytes(8), 'hex'::text) NOT NULL,
    phase text DEFAULT 'PRE'::text NOT NULL,
    domain text NOT NULL,
    record text NOT NULL,
    hostname text,
    resolver text,
    expected text,
    observed text,
    result public.movein_result DEFAULT 'PENDING'::public.movein_result NOT NULL,
    reason text,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    owner_id uuid,
    CONSTRAINT movein_dns_phase_chk CHECK ((phase = ANY (ARRAY['PRE'::text, 'POST'::text]))),
    CONSTRAINT movein_dns_record_chk CHECK ((record = ANY (ARRAY['MX'::text, 'SPF'::text, 'DKIM'::text, 'DMARC'::text])))
);


--
-- Name: movein_dns_proof; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_dns_proof WITH (security_invoker='on') AS
 SELECT deal_id,
    phase,
    record,
    (array_agg(result ORDER BY movein_dns_checks.checked_at DESC))[1] AS result,
    (array_agg(observed ORDER BY movein_dns_checks.checked_at DESC))[1] AS observed,
    (array_agg(resolver ORDER BY movein_dns_checks.checked_at DESC))[1] AS resolver,
    (array_agg(verification_id ORDER BY movein_dns_checks.checked_at DESC))[1] AS verification_id,
    max(checked_at) AS checked_at
   FROM public.movein_dns_checks
  GROUP BY deal_id, phase, record;


--
-- Name: movein_mailboxes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.movein_mailboxes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    deal_id uuid NOT NULL,
    address text NOT NULL,
    destination text,
    source_provider text,
    size_mb numeric(14,2),
    messages_source integer DEFAULT 0 NOT NULL,
    messages_copied integer DEFAULT 0 NOT NULL,
    messages_verified integer DEFAULT 0 NOT NULL,
    folders_found integer DEFAULT 0 NOT NULL,
    contacts_count integer DEFAULT 0 NOT NULL,
    calendar_events integer DEFAULT 0 NOT NULL,
    aliases_count integer DEFAULT 0 NOT NULL,
    signatures_count integer DEFAULT 0 NOT NULL,
    source_credentials text DEFAULT 'PENDING'::text NOT NULL,
    destination_status text DEFAULT 'PENDING'::text NOT NULL,
    result public.movein_result DEFAULT 'PENDING'::public.movein_result NOT NULL,
    exceptions integer DEFAULT 0 NOT NULL,
    operator text,
    verified_at timestamp with time zone,
    last_checked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT movein_mailboxes_counts_chk CHECK (((messages_source >= 0) AND (messages_copied >= 0) AND (messages_verified >= 0) AND (folders_found >= 0) AND (contacts_count >= 0) AND (calendar_events >= 0) AND (aliases_count >= 0) AND (signatures_count >= 0) AND (exceptions >= 0) AND (messages_copied <= messages_source) AND (messages_verified <= messages_copied)))
);


--
-- Name: movein_evidence_violations; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_evidence_violations WITH (security_invoker='on') AS
 SELECT 'movein_mailboxes'::text AS source_table,
    m.id AS row_id,
    m.deal_id,
        CASE
            WHEN ((COALESCE(m.messages_source, 0) < 0) OR (COALESCE(m.messages_copied, 0) < 0) OR (COALESCE(m.messages_verified, 0) < 0)) THEN 'negative_counts'::text
            WHEN (COALESCE(m.messages_copied, 0) > COALESCE(m.messages_source, 0)) THEN 'copied_gt_source'::text
            ELSE 'verified_gt_copied'::text
        END AS violation,
    jsonb_build_object('messages_source', m.messages_source, 'messages_copied', m.messages_copied, 'messages_verified', m.messages_verified) AS observed,
    m.created_at AS observed_at
   FROM public.movein_mailboxes m
  WHERE ((COALESCE(m.messages_source, 0) < 0) OR (COALESCE(m.messages_copied, 0) < 0) OR (COALESCE(m.messages_verified, 0) < 0) OR (COALESCE(m.messages_copied, 0) > COALESCE(m.messages_source, 0)) OR (COALESCE(m.messages_verified, 0) > COALESCE(m.messages_copied, 0)))
UNION ALL
 SELECT 'movein_dns_checks'::text AS source_table,
    d.id AS row_id,
    d.deal_id,
        CASE
            WHEN ((d.phase IS NULL) OR (d.phase <> ALL (ARRAY['PRE'::text, 'POST'::text]))) THEN 'invalid_phase'::text
            ELSE 'invalid_record'::text
        END AS violation,
    jsonb_build_object('phase', d.phase, 'record', d.record) AS observed,
    d.checked_at AS observed_at
   FROM public.movein_dns_checks d
  WHERE ((d.phase IS NULL) OR (d.phase <> ALL (ARRAY['PRE'::text, 'POST'::text])) OR (d.record IS NULL) OR (d.record <> ALL (ARRAY['MX'::text, 'SPF'::text, 'DKIM'::text, 'DMARC'::text])));


--
-- Name: movein_mailbox_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_mailbox_gaps WITH (security_invoker='on') AS
 SELECT m.deal_id,
    d.reference,
    m.address,
    m.messages_source,
    m.messages_copied,
    m.messages_verified,
    GREATEST((m.messages_source - m.messages_verified), 0) AS missing,
    m.result
   FROM (public.movein_mailboxes m
     JOIN public.movein_deals d ON ((d.id = m.deal_id)))
  WHERE ((m.messages_verified < m.messages_source) OR (m.result <> 'VERIFIED'::public.movein_result));


--
-- Name: movein_my_dns_proof; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_my_dns_proof WITH (security_invoker='on') AS
 SELECT deal_id,
    phase,
    record,
    result,
    observed,
    resolver,
    verification_id,
    checked_at
   FROM public.movein_dns_proof p
  WHERE (EXISTS ( SELECT 1
           FROM public.movein_deals d
          WHERE ((d.id = p.deal_id) AND ((d.user_id = auth.uid()) OR (d.owner_id = auth.uid())))));


--
-- Name: movein_my_mailbox_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.movein_my_mailbox_gaps WITH (security_invoker='on') AS
 SELECT deal_id,
    reference,
    address,
    messages_source,
    messages_copied,
    messages_verified,
    missing,
    result
   FROM public.movein_mailbox_gaps g
  WHERE (EXISTS ( SELECT 1
           FROM public.movein_deals d
          WHERE ((d.id = g.deal_id) AND ((d.user_id = auth.uid()) OR (d.owner_id = auth.uid())))));


