--
-- Name: payment_reconciliation_gaps; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.payment_reconciliation_gaps WITH (security_invoker='on') AS
 SELECT r.polar_event_id,
    r.polar_order_id,
    r.user_id,
    r.customer_email,
    r.plan,
    r.amount_gbp,
    r.created_at,
    (i.id IS NULL) AS invoice_missing,
    ((r.plan IS NOT NULL) AND (s.user_id IS NULL)) AS subscription_missing
   FROM ((public.billing_event_receipts r
     LEFT JOIN public.workspace_invoices_legacy_20260912134209 i ON (((i.user_id = r.user_id) AND (i.total = r.amount_gbp))))
     LEFT JOIN public.workspace_subscriptions s ON ((s.user_id = r.user_id)))
  WHERE ((i.id IS NULL) OR ((r.plan IS NOT NULL) AND (s.user_id IS NULL)));


