    last_error text,
    next_retry_at timestamp with time zone,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: payment_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.payment_health WITH (security_invoker='on') AS
 SELECT ( SELECT count(*) AS count
           FROM public.polar_webhook_events
          WHERE ((polar_webhook_events.processed_at IS NULL) AND (polar_webhook_events.state = ANY (ARRAY['pending'::text, 'retry'::text])))) AS awaiting_retry,
    ( SELECT count(*) AS count
           FROM public.polar_webhook_events
          WHERE (polar_webhook_events.state = 'dead'::text)) AS dead_letters,
    ( SELECT count(*) AS count
           FROM public.polar_webhook_raw
          WHERE (polar_webhook_raw.verified = false)) AS unverified_hits,
    ( SELECT count(*) AS count
           FROM public.payment_reconciliation_gaps) AS reconciliation_gaps,
    ( SELECT count(*) AS count
           FROM public.payment_alerts
          WHERE (payment_alerts.resolved_at IS NULL)) AS open_alerts,
    ( SELECT max(polar_webhook_raw.received_at) AS max
           FROM public.polar_webhook_raw) AS last_webhook_at;


