    used_bytes bigint DEFAULT 0 NOT NULL,
    accepts_new boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT storage_volumes_kind_check CHECK ((kind = ANY (ARRAY['local'::text, 'storage_box'::text, 'object'::text, 'external'::text])))
);


--
-- Name: storage_capacity_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.storage_capacity_health WITH (security_invoker='on') AS
 SELECT id,
    name,
    kind,
    accepts_new,
    capacity_bytes,
    used_bytes,
    GREATEST((capacity_bytes - used_bytes), (0)::bigint) AS free_bytes,
    round((((used_bytes)::numeric / (NULLIF(capacity_bytes, 0))::numeric) * (100)::numeric), 1) AS percent,
        CASE
            WHEN ((used_bytes)::numeric >= ((capacity_bytes)::numeric * 0.85)) THEN 'critical'::text
            WHEN ((used_bytes)::numeric >= ((capacity_bytes)::numeric * 0.70)) THEN 'warning'::text
            ELSE 'ok'::text
        END AS level
   FROM public.storage_volumes v;


