    status text DEFAULT 'trial'::text NOT NULL,
    plan text,
    passkey_set boolean DEFAULT false NOT NULL,
    recovery_set boolean DEFAULT false NOT NULL,
    recovery_kind text,
    recovery_hint text,
    expired_at timestamp with time zone,
    frozen_at timestamp with time zone,
    address_reserved_until timestamp with time zone,
    converted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recovery_email text,
    CONSTRAINT trial_accounts_pending_plan_no_plan_check CHECK (((status <> 'pending_plan'::text) OR (plan IS NULL))),
    CONSTRAINT trial_accounts_plan_check CHECK (((plan IS NULL) OR (plan = ANY (ARRAY['basic'::text, 'pro'::text, 'business'::text, 'business_pro'::text])))),
    CONSTRAINT trial_accounts_status_check CHECK ((status = ANY (ARRAY['trial'::text, 'active'::text, 'expired'::text, 'frozen'::text, 'released'::text, 'pending_plan'::text])))
);


--
