--
-- Name: v_signup_plan_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_signup_plan_funnel AS
 SELECT status,
    count(*) AS accounts,
    count(*) FILTER (WHERE (created_at > (now() - '7 days'::interval))) AS last_7_days,
    count(*) FILTER (WHERE (created_at > (now() - '30 days'::interval))) AS last_30_days,
    round(avg((EXTRACT(epoch FROM (COALESCE(converted_at, now()) - trial_started_at)) / 3600.0)), 1) AS avg_hours_in_state
   FROM public.trial_accounts
  GROUP BY status
  ORDER BY status;


--
-- Name: VIEW v_signup_plan_funnel; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_signup_plan_funnel IS 'E20: signup->payment funnel by trial_accounts.status. service_role only.';


